GimCorpus.put(122,0,[[1,1,"אִישׁ הָיָה בְאֶרֶץ עוּץ. פֵּירוּשׁוֹ: בְּאֶרֶץ אֲרָם, כְּמָה דִכְתִיב ״אֶת עוּץ בְּכֹרוֹ״ מִבְּנֵי נָחוֹר (בראשית כב:כא):",1,0],[1,1,"וְהָיָה הָאִישׁ. אַף עַל פִּי שֶׁהוּא לְשׁוֹן עָתִיד, כֵּן דֶּרֶךְ לָשׁוֹן עִבְרִית; וּלְשׁוֹן מְלִיצָתוֹ: וְהוֹוֶה הָאִישׁ הַהוּא גָּדוֹל מִכָּל בְּנֵי קֶדֶם – בְּנֵי אֶרֶץ הַמִּזְרָחִי; שֶׁאֲרָם בְּמִזְרָחוֹ שֶׁל עוֹלָם הוּא, שֶׁנֶּאֱמַר ״מִן אֲרָם יַנְחֵנִי בָלָק מֵהַרְרֵי קֶדֶם״ (במדבר כג:ז). דָּבָר אַחֵר: עוּץ – זֶה אִיּוֹב; בּוּז – זֶה אֱלִיהוּא בֶּן בַּרַכְאֵל הַבּוּזִי; וַהֲרֵי הוּא שֶׁאָמַר אִיּוֹב: ״וּבוּז מִשְׁפָּחוֹת יְחִתֵּנִי״ (איוב לא:לד) – זֶה הוּא מִמִּשְׁפַּחְתִּי שֶׁמִּחְתָּה דְבָרַי; וְהַיְנוּ דְּאָמְרֵי אִינְשֵׁי (סנהדרין לט:): מִינֵּהּ וּבֵהּ אַבָּא לֵיזִיל בֵּהּ נַרְגָּא. דָּבָר אַחֵר: בְּאֶרֶץ עוּץ. בְּאֶרֶץ שֶׁנּוֹטְלִין מִמֶּנּוּ עֵצוֹת רָעוֹת עַל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנֶּאֱמַר ״מִן הָאָרֶץ הַהִיא יָצָא אַשּׁוּר״ (בראשית י:יא); וּמָה עֵצָה נָטְלוּ? שֶׁהָיוּ אוֹמְרִים: לֹא כָּל הֵימֶנּוּ לִטּוֹל אֶת הָעֶלְיוֹנִים וְלִתֵּן לָנוּ אֶת הַתַּחְתּוֹנִים! אֶלָּא בּוֹאוּ לְאֶרֶץ שִׁנְעָר שֶׁשָּׁם אֱלוֹהוֹת הַרְבֵּה, שֶׁנֶּאֱמַר בָּהּ ״אֶרֶץ פְּסִילִים הִיא״ (ירמיהו נ:לח). ״וְנַעֲשֶׂה מִגְדָּל וְרֹאשׁוֹ בַשָּׁמַיִם וְנַעֲשֶׂה לָּנוּ שֵׁם״ (בראשית יא:ד), וְאֵין שֵׁם הָאָמוּר כָּאן אֶלָּא עֲבוֹדַת כּוֹכָבִים, שֶׁנֶּאֱמַר ״וְשֵׁם אֱלֹהִים אֲחֵרִים לֹא תַזְכִּירוּ״ (שמות כג:יג). מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? יָשַׁב עֲלֵיהֶם בְּדִין וְהֶעֱמִיד עֲלֵיהֶם עֵדִים, שֶׁנֶּאֱמַר ״וַיֵּרֶד ה׳ לִרְאֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל״ (בראשית יא:ה) – וְכִי צָרִיךְ יְרִידָה לִפְנֵי הַמָּקוֹם לִרְאוֹת? וְהַכְּתִיב ״עֵינֵי ה׳ מְשׁוֹטְטוֹת בְּכָל הָאָרֶץ״ (זכריה ד:י)! אֶלָּא לְלַמֵּד הֲלָכָה לְדוֹרוֹת, שֶׁאֵין דָּנִין אֶלָּא עַל פִּי עֵדֵי רְאִיָּה, שֶׁנֶּאֱמַר ״אוֹ רָאָה אוֹ יָדָע״ (ויקרא ה:א):",2,0],[1,1,"וְהָיָה. פְּשׁוּטוֹ כְּמוֹ וַיְהִי, וּמַשְׁמָעוֹ לְעָבָר וּלְהַבָּא:",3,0],[1,1,"תָּם וְיָשָׁר. אֲבָל בִּדְבָרִים שֶׁבֵּין קוֹנוֹ וּבֵינוֹ לֹא הָיָה צַדִּיק? לְכָךְ נֶאֱמַר: וִירֵא אֱלֹהִים וְסָר מֵרָע:",4,0],[1,3,"שִׁבְעַת אַלְפֵי צֹאן. הָרוֹב מָנָה תְּחִלָּה:",1,0],[1,3,"גָּדוֹל מִכָּל בְּנֵי קֶדֶם. מִדּוֹר הַפְּלַגָּה, דִּכְתִיב ״וַיְהִי בְּנָסְעָם מִקֶּדֶם״ (בראשית יא:ב). אֲבָל מֵאַבְרָהָם אֵינוֹ כֵּן, שֶׁהֲרֵי בְּאַבְרָהָם כְּתִיב בּוֹ ׳הַגָּדוֹל׳, שֶׁנֶּאֱמַר ״וְשֵׁם חֶבְרוֹן לְפָנִים קִרְיַת אַרְבַּע הָאָדָם הַגָּדוֹל בָּעֲנָקִים הוּא״ (יהושע יד:טו). הָיָה לוֹ לִכְתֹּב ׳אָדָם גָּדוֹל׳, וְלָמָּה כָּתַב ״הָאָדָם הַגָּדוֹל״? אֶלָּא רֶמֶז שֶׁהוּא אָדָם גָּדוֹל, שֶׁעָמַד בְּעֶשֶׂר נִסְיוֹנוֹת. לְפִיכָךְ כּוֹתְבִין אוֹתוֹ שְׁנֵי הֵהִי״ן. וְאִיּוֹב שֶׁנֶּאֱמַר בּוֹ גָּדוֹל – לֹא עָמַד אֶלָּא בְּאַחַת, שֶׁנֶּאֱמַר ״תָּם וְיָשָׁר וְגוֹ׳״ – מִכָּל אוֹתוֹ הַדּוֹר, שֶׁלֹּא נִתְפַּס עַל אוֹתוֹ עָוֹן (סא״א):",2,0],[1,4,"וְהָלְכוּ בָנָיו וְעָשׂוּ מִשְׁתֶּה בֵּית אִישׁ יוֹמוֹ. בְּבֵית כָּל אֶחָד וְאֶחָד יוֹמוֹ:",1,0],[1,4,"וְשָׁלְחוּ וְקָרְאוּ. כְּמוֹ וְשׁוֹלְחִים וְקוֹרְאִים, שֶׁהָיוּ עוֹשִׂין כֵּן תָּמִיד:",2,0],[1,5,"וַיְהִי כִּי הִקִּיפוּ. כַּאֲשֶׁר כָּלוּ יְמֵי הַמִּשְׁתֶּה, נוֹהֵג הָיָה אִיּוֹב בְּכָל סוֹף שִׁבְעַת הַיָּמִים, שֶׁחָזְרוּ יְמֵי חֲלִילָתָם, הָיָה שׁוֹלֵחַ וּמְקַדְּשָׁם, כְּלוֹמַר: מְזַמְּנָם וְקוֹרְאָם; כְּמוֹ ״הִתְקַדְּשׁוּ לְמָחָר״ (במדבר יא:יח):",1,0],[1,5,"וְהִשְׁכִּים בַּבֹּקֶר וְהֶעֱלָה. מְלִיצָתוֹ, שֶׁהָיָה מַשְׁכִּים וּמַעֲלֶה עוֹלוֹת. לָכֵן כָּתַב בִּלְשׁוֹן עָתִיד, שֶׁהָיָה נוֹהֵג לַעֲשׂוֹת כֵּן תָּמִיד, לְסוֹף כָּל שִׁבְעַת הַיָּמִים:",2,0],[1,5,"מִסְפַּר כֻּלָּם. הַבָּנִים וְהַבָּנוֹת:",3,0],[1,5,"וּבֵרְכוּ. לְשׁוֹן כִּנּוּי כְּלַפֵּי מַעְלָה:",4,0],[1,5,"כָּכָה יַעֲשֶׂה אִיּוֹב. כְּמוֹ הָיָה עוֹשֶׂה מָחָר; כְּשֶׁכָּתַב בְּדָבָר הַהוֹוֶה וְתָדִיר, פְּעָמִים שֶׁכָּתַב בּוֹ לְשׁוֹן עָבָר וּפְעָמִים לְשׁוֹן עָתִיד:",5,0],[1,6,"וַיְהִי הַיּוֹם. אוֹתוֹ יוֹם שֶׁהָיָה רֹאשׁ הַשָּׁנָה (ראש השנה טז.), שֶׁהוּא יוֹם תְּרוּעָה, וְצִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לַשָּׂטָן לְהָבִיא זְכוּת וְחוֹבָה שֶׁל כָּל הַבְּרִיּוֹת. הֲדָא הוּא דִּכְתִיב מִשּׁוּט בָּאָרֶץ:",1,0],[1,6,"וַיָּבֹאוּ בְּנֵי הָאֱלֹהִים לְהִתְיַצֵּב עַל־ה׳. לָרִיב עִמּוֹ, שֶׁאֵין לְהִתְיַצֵּב אֶלָּא עַל־דִּין, שֶׁנֶּאֱמַר: ״נִצָּב לָרִיב ה׳״ (ישעיהו ג:יג):",2,0],[1,6,"וַיָּבֹא גַם הַשָּׂטָן בְּתוֹכָם. לְקַטְרֵג הַבְּרִיּוֹת:",3,0],[1,7,"מֵאַיִן תָּבֹא. דִּבֵּר הַכָּתוּב דֶּרֶךְ אֶרֶץ, שֶׁהַגָּדוֹל מְדַבֵּר תְּחִלָּה וּמַרְשֶׁה הַקָּטָן לַעֲנוֹת:",1,0],[1,7,"מִשּׁוּט בָּאָרֶץ. כַּאֲשֶׁר מְפֹרָשׁ לְמַעְלָה, וּבַהַגָּדָה דְּהַשּׁוּתָּפִין הוּא (בבא בתרא טז.):",2,0],[1,7,"מִשּׁוּט בָּאָרֶץ וּמֵהִתְהַלֵּךְ בָּהּ. כֵּן דַּרְכִּי, לָשׁוּט וְלִרְאוֹת רָעִים וְטוֹבִים; וְשׁוֹטַטְתִּי בְּכָל הָאָרֶץ וְלֹא מָצָאתִי כְּאַבְרָהָם, שֶׁנֶּאֱמַר בּוֹ ״קוּם הִתְהַלֵּךְ בָּאָרֶץ״ (בראשית יג:יז). וְאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (בבא בתרא טז.): שָׂטָן לְשֵׁם שָׁמַיִם נִתְכַּוֵּן, כְּדֵי שֶׁלֹּא יְהֵא נִשְׁכָּח לִפְנֵי אֱלֹהֵינוּ זְכוּתוֹ שֶׁל אַבְרָהָם:",3,0],[1,8,"הֲשַׂמְתָּ לִבְּךָ עַל עַבְדִּי אִיּוֹב. שֶׁתִּרְצֶה לְקַטְרְגוֹ:",1,0],[1,8,"הֲשַׂמְתָּ. לְשׁוֹן תֵּימַהּ הוּא:",2,0],[1,8,"תָּם וְיָשָׁר. שָׁלֵם בְּמַעֲשָׂיו:",3,0],[1,9,"הֶחִנָּם יָרֵא אִיּוֹב. בִּתְמִיהַּ:",1,0],[1,10,"הֲלֹא. אַתָּה שַׂכְתָּ בַּעֲדוֹ לְפִי שֶׁהוּא יוֹדֵעַ שֶׁאַתָּה רָגִיל אֶצְלוֹ לַעֲשׂוֹת לוֹ נִסִּים, וּפָרֶה וְרָבֶה, לְפִיכָךְ עוֹשֶׂה צְדָקוֹת הַלָּלוּ; אֲבָל לֹא נִסִּיתָ אוֹתוֹ:",1,0],[1,10,"שַׂכְתָּ בַעֲדוֹ. הִגַּנְתָּ בַּעֲדוֹ, כִּמְחִיצָּה זוֹ; כְּמוֹ ״הָסֵר מְשׂוּכָתוֹ״ (ישעיהו ה:ה) – מְחִיצָתוֹ. וְכָל ׳בְּעַד׳ הָאָמוּר בִּלְשׁוֹן עִבְרִי אֵינוֹ אֶלָּא לְשׁוֹן ׳כְּנֶגְדּוֹ וּבְפָנָיו׳; כְּמוֹ ״וְכַפֵּר בַּעַדְךָ״ (ויקרא ט:ז) – קַנַּח הֶעָוֹן כְּנֶגְדְּךָ וּבְפָנֶיךָ, לִהְיוֹת הַכַּפָּרָה מָגֵן בַּעַדְךָ; וְכֵן ״ה׳ מָגֵן בַּעֲדִי״ (תהלים ג:ד):",2,0],[1,10,"פָּרַץ בָּאָרֶץ. נִתְחַזְּקוּ, כְּמוֹ ״וְכֵן יִפְרֹץ״ (שמות א:יב), וּמְתַרְגְּמִינָן: ״יִתְקוֹף״. זֶהוּ פְּשׁוּטוֹ. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה אָמְרוּ בַּהַגָּדָה (בבא בתרא טו:; טז.): פָּרַץ גְּדֵרוֹ שֶׁל עוֹלָם, שֶׁהָעִזִּים הוֹרְגִים הַזְּאֵבִים:",3,0],[1,11,"וְאוּלָם. לוּ הָיִיתָ נוֹגֵעַ בְּכָל אֲשֶׁר לוֹ, אִם לֹא עַל פָּנֶיךָ יְבָרְכֶךָּ. מִיָּד; בִּתְמִיהַּ. וְאָז:",1,0],[1,12,"וַיֹּאמֶר ה׳ אֶל הַשָּׂטָן הִנֵּה כָל אֲשֶׁר לוֹ בְּיָדֶךָ. (דָּבָר אַחֵר:) וַיְהִי הַיּוֹם, אוֹתוֹ הַיּוֹם שֶׁחָזְרוּ חֲלִילָה לֶאֱכוֹל בְּבֵית אֲחִיהֶם הַבְּכוֹר:",1,0],[1,12,"בְּנֵי הָאֱלֹהִים. צְבָא הַשָּׁמַיִם הַקְּרוֹבִים לַשְּׁכִינָה, לִהְיוֹת בְּנֵי בֵיתוֹ; וְעַל שֵׁם כָּךְ נִקְרְאוּ בָּנָיו:",2,0],[1,12,"לְהִתְיַצֵּב עַל ה׳. סְבִיבוֹתָיו, כְּמוֹ ״לְכָל הַנִּצָּבִים עָלָיו״ (בראשית מה:א):",3,0],[1,14,"עַל יְדֵיהֶם. כְּמוֹ ״אִישׁ עַל יָדוֹ״ (במדבר ב:יז). וְאֵינוֹ לְשׁוֹן ׳מָקוֹם׳, אֶלָּא עַל שֵׁם שֶׁהוּא מוּכָן וּמְזֻמָּן לְיָדוֹ. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה אָמְרוּ בַּהַגָּדָה (בבא בתרא טו:; טז.) שֶׁהִטְעִימָם הַקָּדוֹשׁ בָּרוּךְ הוּא מֵעֵין עוֹלָם הַבָּא, שֶׁלְּאַחַר חֲרִישַׁת הָאֲתוֹנוֹת הָיוּ זוֹרְעִים עִם הַחֲרִישָׁה וְרוֹעוֹת הָאֲתוֹנוֹת מִיָּד חָזִיז מִן הַתֶּלֶם:",1,0],[1,15,"וַתִּפֹּל שְׁבָא. נִתְנַפְּלָה וְחָנְתָה מַלְכוּת שְׁבָא עֲלֵיהֶם, כְּמוֹ (בראשית כ״ה:י״ח) ״עַל פְּנֵי כָל אֶחָיו נָפָל״:",1,0],[1,15,"וְאֶת־הַנְּעָרִים. מְשָׁרְתֶיךָ, הַשּׁוֹמְרִים אוֹתָם:",2,0],[1,15,"וָאִמָּלְטָה. אֵין מְלִיטָה אֶלָּא לְשׁוֹן הַשְׁמָטָה, שֶׁנִּשְׁמַט מִן הַצָּרָה, (וּבָאתִי לְהַגִּיד לָךְ. וְכֵיוָן שֶׁהִגִּיד, מִיָּד מֵת כן הוא בס״א):",3,0],[1,16,"וּבַנְּעָרִים. בַּמְשָׁרְתִים שׁוֹמְרֵי הַצֹּאן מְדַבֵּר הַכָּתוּב:",1,0],[1,17,"וַיִּפְשְׁטוּ עַל הַגְּמַלִּים. זֶה לְשׁוֹן ״בָּזְזוּ בַּז״ (ישעיה לג:כג) – לְפִי מִנְהָגָם. כָּל זְמַן שֶׁהֵם מְהַלְּכִים, נִדְבָּקִים יַחַד וְהוֹלְכִים בְּמַאֲרָב, שֶׁלֹּא יָבִינוּ בָּהֶם וְיַבְרִיחוּ אֶת הַמִּקְנֶה; וּכְשֶׁמַּגִּיעִים לִמְקוֹם הַמִּקְנֶה, פּוֹשְׁטִים בְּמֶרְחַב הַמִּקְנֶה זֶה לְכָאן וְזֶה לְכָאן, לֶאֱסֹף הַמִּקְנֶה. וְהַמַּלְאָכִים הַלָּלוּ – שְׁלוּחֵי שָׂטָן הָיוּ; וּכְדֵי לְהַקְנִיטוֹ וּלְהַחֲטִיאוֹ בִּשְּׂרוּהוּ תְּחִלָּה בְּהֶפְסֵד מוּעָט, וְאַחַר כָּךְ בְּגָדוֹל הֵימֶנּוּ, וְכֵן כֻּלָּם:",1,0],[1,19,"מֵעֵבֶר הַמִּדְבָּר. מִצַּד שֵׁנִי שֶׁל מִדְבָּר, וְהָיָה הַבַּיִת מִצַּד זֶה; וְזֶהוּ לְשׁוֹן ׳עֵבֶר׳ בַּמִּקְרָא:",1,0],[1,19,"עַל הַנְּעָרִים. בָּנִים, אֲבָל אֵין צָרִיךְ לְהַזְכִּיר הַבָּנוֹת:",2,0],[1,19,"(לְהַגִּיד לָךְ. שֶׁהָיָה לוֹ רְשׁוּת לְהַגִּיד, וְהָיָה מֵת בְּאוֹתוֹ רֶגַע ס״א אינו):",3,0],[1,20,"וַיָּגָז. תָּלַשׁ, כְּמוֹ ״גָּזִּי נִזְרֵךְ״ (ירמיה ז:כט), וּמְתַרְגְּמִינָן: ״תְּלִישָׁה״, וּכְמוֹ ״מִמְּעֵי אִמִּי אַתָּה גוֹזִי״ (תהלים עא:ו) – מוֹשְׁכִי:",1,0],[1,21,"מִבֶּטֶן אִמִּי. הָאֲדָמָה אֲשֶׁר לוּקַחְתִּי מִשָּׁם (בראשית ג:כג), אוֹ אִמִּי מַמָּשׁ:",1,0],[1,21,"וְעָרוֹם אָשׁוּב שָׁמָּה. לֹא בַּבֶּטֶן הוּא מְדַבֵּר. וּמַה שָׁמָּה? אֶל מְקוֹם תְּשׁוּבָתוֹ. וְעַל שֶׁהוּא מוּכָן לְכָךְ, וְלֹא יַחֲלִיף הַחֹק לָשׁוּב כִּי אִם אֶל הֶעָפָר, לְפִיכָךְ לֹא הֻצְרַךְ לְהַזְכִּירוֹ:",2,0],[1,22,"תִּפְלָה. לֹא שׁוּם שֶׁמֶץ וְתִפְלוּת נָתַן עַל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ (ירמיהו כג:יג) ״וּבִנְבִיאֵי שׁוֹמְרוֹן רָאִיתִי תִפְלָה״:",1,0],[1,22,"וְלֹא נָתַן. לְהַטִּיל תִּפְלָה וְעוֹל אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ ״נָתְנוּ לְדָוִד רְבָבוֹת וְלִי נָתְנוּ הָאֲלָפִים״ (שמואל א יח:ח):",2,0],[2,2,"אֵי מִזֶּה תָּבוֹא. אַיֵּה מָקוֹם שֶׁתּוּכַל לוֹמַר: מִזֶּה אֲנִי בָּא?",1,0],[2,3,"מַחֲזִיק. אוֹחֵז, כְּמוֹ ״וַיִּשְׁלַח יָדוֹ וַיַּחֲזֶק בּוֹ״ (שמות ד:ד), ״מַחֲזִיק בְּאָזְנֵי כֶלֶב״ (משלי כו:יז):",1,0],[2,3,"וַתְּסִיתֵנִי בוֹ. הֲסִיתַנִי לְבָלְעוֹ. כָּל לְשׁוֹן הֲסָתָה אֵינוֹ אֶלָּא לְשׁוֹן הַמְשָׁכָה, שֶׁמַּמְשִׁיךְ אֶת הָאָדָם לַעֲצָתוֹ:",2,0],[2,4,"עוֹר בְּעַד עוֹר. אֵבֶר בִּפְנֵי אֵבֶר. כֵּן דֶּרֶךְ בְּנֵי אָדָם: כְּשֶׁרוֹאֶה הַחֶרֶב בָּאָה עַל רֹאשׁוֹ, מֵגִין בִּזְרוֹעוֹ לְפָנָיו. וְכָל שֶׁכֵּן – כֹּל אֲשֶׁר לָאִישׁ בְּמָמוֹן יִתֵּן:",1,0],[2,4,"בְּעַד נַפְשׁוֹ. בִּפְנֵי נַפְשׁוֹ, לְהָגִין. לְפִי שֶׁזֶּה יוֹדֵעַ בְּנַפְשׁוֹ שֶׁנִּתְחַיֵּב, לְפִיכָךְ אֵינוֹ מִצְטַעֵר עַל מָמוֹנוֹ:",2,0],[2,5,"אוּלָם. אֲבָל:",1,0],[2,5,"אִם לֹא. תִּרְאֶה בּוֹ מִיָּד, שֶׁעַל פָּנֶיךָ יְבָרֲכֶךָּ:",2,0],[2,6,"אַךְ אֶת נַפְשׁוֹ שְׁמֹר. שֶׁלֹּא תֵצֵא. מִכָּאן אָמְרוּ חֲכָמִים (בבא בתרא טז.): קָשֶׁה הָיָה צַעֲרוֹ שֶׁל שָׂטָן יוֹתֵר מִשֶּׁל אִיּוֹב; כְּאוֹמֵר לַחֲבֵירוֹ: שְׁבֹר חָבִית זוֹ וּשְׁמֹר יֵינָהּ:",1,0],[2,8,"לְהִתְגָּרֵד בּוֹ. בְּדָלֶ״ת כָּתוּב, וּלְשׁוֹן מִשְׁנָה הִיא: גּוֹרְדוֹ וּמַעֲמִידוֹ עַל גִּלְדּוֹ (ראש השנה כז:). אֲבָל גּוֹרֵר בְּרֵי״שׁ אֵינוֹ אֶלָּא לְשׁוֹן סְחִיבָה, כְּמוֹ גּוֹרֵר אָדָם מִטָּה וְסַפְסָל (שבת כב.):",1,0],[2,9,"מַחֲזִיק. אוֹחֵז:",1,0],[2,9,"וָמֻת: לְשׁוֹן צִוּוּי, כְּמוֹ ״וּמֻת בָּהָר״ (דברים לב:נ):",2,0],[2,10,"גַּם. לֹא דַי שֶׁבְּרָאָנוּ, אֶלָּא גַּם אֶת הַטּוֹב נְקַבֵּל וְאֶת הָרָע לֹא נְקַבֵּל?! בִּתְמִיהַּ:",1,0],[2,10,"בִּשְׂפָתָיו. אֲבָל בְּלִבּוֹ חָטָא:",2,0],[2,11,"רֵעֵי אִיּוֹב. אוֹהֲבָיו:",1,0],[2,11,"לָנוּד. כְּמוֹ ״מִי יָנוּד לָךְ״ (ישעיהו נא:יט), ״לֹא תָנֻדוּ לוֹ״ (ירמיהו כב:י):",2,0],[2,12,"וְלֹא הִכִּירוּהוּ. כִּי נִשְׁתַּנּוּ פָנָיו מֵחֲמַת הַיִּסּוּרִין:",1,0],[2,12,"הַשָּׁמָיְמָה. כְּלוֹמַר: לְמַעְלָה מֵרָאשֵׁיהֶם (הַרְבֵּה), וְהוּא הָיָה לָהֶם מִנְהַג אֵבֶל:",2,0],[2,13,"לָאָרֶץ. עַל הָאָרֶץ, לְצַעֵר בְּצַעֲרוֹ:",1,0],[3,2,"(מענה איוב) וַיַּעַן. וַיִּצְעַק, שֶׁכָּל עֲנִיָּה הָאֲמוּרָה בַּתּוֹרָה אֵינָהּ אֶלָּא לְשׁוֹן הֲרָמַת קוֹל, וְאָב לְכֻלָּם: ״וְעָנוּ הַלְוִיִּם קוֹל רָם״ (דברים כז:יד):",1,0],[3,3,"אִוָּלֶד בּוֹ. לְשׁוֹן עָתִיד, שֶׁהָיָה אוֹמֵר: הַלְוַאי וְיֹאבַד הַיּוֹם שֶׁהָיִיתִי עָתִיד לְהִוָּלֵד בּוֹ, וְאָז לֹא הָיִיתִי נוֹלָד:",1,0],[3,3,"וְהַלַּיְלָה. אַף הִיא תֹּאבַד:",2,0],[3,3,"אָמַר. שֶׁיֹּאמַר הַמְבַשֵּׂר אֲשֶׁר עָלָיו הַדָּבָר מֻטָּל:",3,0],[3,3,"הוֹרָה גָבֶר. שֶׁעִיבֵּר אָבִי אֶת אִמִּי. בִּנְקֵבָה נוֹהֵג לוֹמַר ׳הוֹרָתָה׳, וּבְזָכָר נוֹהֵג לוֹמַר ׳הוֹרָה אֶת הַנְּקֵבָה׳:",4,0],[3,3,"וְהַלַּיְלָה אָמַר. זֶה אֶחָד מִן הַמְּקוֹמוֹת שֶׁחִסֵּר הַמִּקְרָא אֶת דְּבָרָיו, מִפְּנֵי שֶׁלֹּא הֻצְרַךְ לְפָרֵשׁ מִי הוּא; וּמְלִיצָתוֹ: אָמַר הָאוֹמֵר. (וְדוֹמֶה לוֹ ״הֲיָרֻצוּן בַּסֶּלַע סוּסִים אִם יַחֲרוֹשׁ בַּבְּקָרִים״ (עמוס ו:יב)) – הָיָה לוֹ לוֹמַר: אִם יַחֲרוֹשׁ אָדָם בַּבְּקָרִים. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה אָמְרוּ (נדה טז:): מַלְאָךְ הַמְמֻנֶּה עַל הַהֵרָיוֹן, ׳לַיְלָה׳ שְׁמוֹ:",5,0],[3,4,"הַיּוֹם הַהוּא יְהִי חֹשֶׁךְ. תָּמִיד בְּכָל שָׁנָה, כְּשֶׁיַּגִּיעַ אוֹתוֹ יוֹם:",1,0],[3,4,"אַל יִדְרְשֵׁהוּ אֱלוֹהַּ מִמָּעַל. לְטוֹבָה:",2,0],[3,4,"וְאַל תּוֹפַע עָלָיו נְהָרָה. אוֹרָה, כְּמוֹ ״צֹהַר״ (בראשית ו:טז), וּמְתַרְגְּמִינָן ״נִיהוֹר״ (תרגום אונקלוס):",3,0],[3,5,"יִגְאָלֻהוּ. כְּמוֹ ״לֶחֶם מְגֹאָל״ (מלאכי א:ז), ״בַּמֶּה גֵאַלְנוּךָ״ (מלאכי א:ז), וְהוּא לְשׁוֹן לִכְלוּךְ:",1,0],[3,5,"צַלְמָוֶת. צֵל שֶׁל מָוֶת (חֹשֶׁךְ), שֶׁאֵינוֹ מֵאִיר לְעוֹלָם:",2,0],[3,5,"עֲנָנָה. אֲפֵלָה:",3,0],[3,5,"כְּמְרִירֵי יוֹם. שֵׁדִים הַמּוֹשְׁלִים בַּצָּהֳרַיִם, כְּמוֹ ״קֶטֶב מְרִירִי״ (דברים לב:כד), וְהוּא מוֹשֵׁל בַּצָּהֳרַיִם, שֶׁנֶּאֱמַר ״וּמִקֶּטֶב יָשׁוּד צָהֳרָיִם״ (תהלים צא:ו):",4,0],[3,6,"אַל יִחַדְּ. אַל יִשְׂמַח, כְּמוֹ ״וַיִּחַדְּ יִתְרוֹ״ (שמות יח:ט). פֵּרוּשׁ אַחֵר: אַל יִתְאַחֵד (סא״א):",1,0],[3,7,"גַּלְמוּד. יָחִיד, וְחָסֵר מֵאָדָם וּמִכָּל בְּרִיָּה:",1,0],[3,8,"יִקְּבֻהוּ. יְקַלְלוּהוּ, כְּמוֹ ״קָבָה לִי״ (במדבר כב:יז):",1,0],[3,8,"אוֹרְרֵי יוֹם. הַמְקַלְּלִים אֶת יְמֵיהֶם, לְפִי שֶׁהֵם מְכַוְּנִים לְקַלֵּל קְלָלָה מִתּוֹךְ צַעֲרָם:",2,0],[3,8,"הָעֲתִידִים עוֹרֵר לִוְיָתָן. לִהְיוֹת עֲרִירִים בְּמַחְבַּרְתָּם, לְיַחֵד לִוּוּי שֶׁלָּהֶם מֵחֶבְרַת אִישׁ וְאִשְׁתּוֹ, מֵאֵין בָּנִים. וּבַגְּמָרָא יְרוּשַׁלְמִי רָאִיתִי (מועד קטן א,ה): עוֹרֵר לִוְיָתָן. לְקוֹנֵן עַל לִוּוּי שֶׁלָּהֶם כְּשֶׁיָּמוּת, כְּמוֹ (מועד קטן ח.): לֹא יְעַרְעֵר עַל מֵתוֹ:",3,0],[3,9,"נִשְׁפּוֹ. חֹשֶׁךְ אִישׁוֹנוֹ:",1,0],[3,9,"בְּעַפְעַפֵּי. בְּזָהֳרוּרֵי, כְּמוֹ ״וְעַפְעַפֵּינוּ יִזְּלוּ מָיִם״ (ירמיהו ט:יז):",2,0],[3,10,"כִּי לֹא סָגַר. מִי שֶׁיְּכֹלֶת בְּיָדוֹ לִסְגּוֹר. וְגַם זֶה מִן הַמִּקְרָאוֹת דּוֹמִין לְ״הַלַּיְלָה אָמַר״ (לעיל ג:ג):",1,0],[3,10,"דַּלְתֵי בִטְנִי. שֶׁיָּצָאתִי מִמֶּנּוּ, שֶׁאִם עָשָׂה כֵּן, וַיַּסְתֵּר עָמָל מֵעֵינָי:",2,0],[3,11,"לָמָּה לֹא מֵרֶחֶם אָמוּת. מִיצִיאָתִי מֵרֶחֶם (הָיִיתִי) מוּכָן לָמוּת מִיָּד. וּמְדַבֵּר בִּלְשׁוֹן עָתִיד, כְּאִלּוּ עוֹמֵד עַכְשָׁיו בְּיוֹם יְצִיאַת הָרֶחֶם, וְאוֹמֵר: (לָמָּה) לֹא אָמוּת עַתָּה, וְלָמָּה לֹא מִבֶּטֶן יָצָאתִי וְאֶגְוָע. לָמָּה לֹא הָיְתָה לִי גְּוִיעָה מוּכֶנֶת:",1,0],[3,12,"מַדּוּעַ קִדְּמוּנִי. בִּרְכֵּי אִמִּי קוֹדֶם לְמִיתָה:",1,0],[3,12,"כִּי אִינָק. נִגְזַר עָלַי לִינֹק מֵהֶם. לְפִי שֶׁהוּא מְדַבֵּר בְּיוֹם לֵידָה, הוּא מַזְכִּיר דְּבָרִים שֶׁל אַחֲרָיו בִּלְשׁוֹן עָתִיד:",2,0],[3,13,"שָׁכַבְתִּי. הָיִיתִי שׁוֹכֵב בַּקֶּבֶר:",1,0],[3,14,"הַבּוֹנִים חֳרָבוֹת לָמוֹ. זֶהוּ דֶּרֶךְ לְמַעֲמִידֵי שֵׁם, לִבְנוֹת עָרִים נֶחֱרָבוֹת לְזִכָּרוֹן לָהֶם; כְּמוֹ ״וּבָנוּ מִמְּךָ חָרְבוֹת עוֹלָם וְקֹרֵא לְךָ גֹּדֵר פֶּרֶץ״ (ישעיה נח:יב). כְּלוֹמַר: עִם שָׂרִים וּבַעֲלֵי שֵׁם. אוֹ הַלְוַאי שֶׁלֹּא נוֹדַעְתִּי וְאֶהְיֶה כְּנֵפֶל. וּמַה שֶּׁכָּתַב לֹא אֶהְיֶה כְנֵפֶל טָמוּן – מִפְּנֵי שֶׁעוֹמֵד עַל לָשׁוֹן שֶׁהִתְחִיל לְדַבֵּר, בִּלְשׁוֹן תֵּימַהּ; וּמוּסָב עַל לָמָּה לֹּא, מַדּוּעַ קִדְּמוּנִי בִרְכָּיִם, אוֹ מַדּוּעַ לֹא אֶהְיֶה כְנֵפֶל טָמוּן:",1,0],[3,16,"כְּעוֹלְלִים. תִּינוֹקוֹת. וּלְכָךְ קוֹרֵא אוֹתָם עוֹלְלִים, שֶׁכֻּלָּם שְׂחוֹק וְלִכְלוּךְ; כְּמוֹ ״וְעֹלַלְתִּי בֶעָפָר״ (איוב טז:טו), וּכְמוֹ ״וַיִּתְעַלְּלוּ בָהּ כָּל הַלָּיְלָה״ (שופטים יט:כה):",1,0],[3,17,"חָדְלוּ רֹגֶז. נִמְנָעִים מֵרוּגְזָם, שֶׁהָיוּ נוֹהֲגִים וּרְגִילִים לְהַרְגִּיז בָּאָרֶץ:",1,0],[3,17,"וְשָׁם יָנוּחוּ. וְשָׁם נָחוּ, דָּבָר הַהוֹוֶה כְּתָבוֹ בִּלְשׁוֹן עָתִיד:",2,0],[3,19,"קָטֹן וְגָדוֹל שָׁם. שָׁם נִכָּר מִי חָשׁוּב וּמִי שָׁפָל, וּלְפִי שֶׁאוֹתָהּ גְּדֻלָּה גְּדֻלַּת עוֹלָם הוּא, וְאוֹתוֹ שִׁפְלוּת שִׁפְלוּת עוֹלָם הִיא:",1,0],[3,20,"לָמָּה יִתֵּן. הַנּוֹתֵן, וְהוּא הַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[3,20,"לְעָמֵל אוֹר. לְמִי שֶׁגָּדַל בְּעָמָל וְצָרָה, לָמָּה נוֹתֵן לוֹ אוֹר עוֹלָם, וְלֹא הֱמִיתוֹ בְּהִוָּלְדוֹ?",2,0],[3,21,"הַמְחַכִּים לַמָּוֶת. לְמָרֵי נֶפֶשׁ הַתְּאֵבִים וּמִתְאַוִּים לַמָּוֶת, וְקוֹבְלִים לֵאמֹר: אֵינֶנּוּ:",1,0],[3,21,"וַיַּחְפְּרֻהוּ. מְרַגְּלִים אַחֲרָיו:",2,0],[3,21,"מִמַּטְמוֹנִים. יוֹתֵר מִשֶּׁמְּרַגְּלִים אַחַר מַטְמוֹנֵי אוֹצָרוֹת. וְהָיוּ:",3,0],[3,22,"שְׂמֵחִים אֱלֵי גִיל. וְיָשִׂישׂוּ אִם הָיוּ מוֹצְאִים קָבֶר:",1,0],[3,22,"אֱלֵי גִיל. בִּשְׁבִיל הַגִּילָה וְהַשָּׂשׂוֹן שֶׁל מְצִיאַת קָבֶר:",2,0],[3,23,"לְגֶבֶר אֲשֶׁר דַּרְכּוֹ נִסְתָּרָה. כָּל טוֹבוֹת אֲשֶׁר פָּעַל, נִסְתְּרוּ מֵאֵת בַּעַל הַגְּמוּל, וְלֹא הִבִּיט בָּהֶם:",1,0],[3,23,"וַיָּסֶךְ אֱלוֹהַּ בַּעֲדוֹ. עָשָׂה מְחִיצָּה לְפָנָיו, לְסוֹגְרוֹ בְּמַסְגֵּר. כְּמוֹ ״הִנְנִי שָׂךְ אֶת דַּרְכֵּךְ״ (הושע ב:ח):",2,0],[3,24,"תָּבֹא. בָּאָה:",1,0],[3,24,"וַיִּתְּכוּ. לְשׁוֹן ״נִתַּךְ אַרְצָה״ (שמות ט:לג), נִגָּרִים וְיוֹרְדִים כַּמַּיִם. וְיֵשׁ לְפָרֵשׁ ׳נְתִיכָה׳ לְשׁוֹן ׳רִבְּיָה׳:",2,0],[3,25,"פַּחַד פָּחַדְתִּי. כָּל יָמַי עָמַדְתִּי בְּפַחַד עַל זֶה, כְּמוֹ שֶׁאָמַרְנוּ ״וַיְהִי כִּי הִקִּיפוּ וְגוֹ׳״ (איוב א:ה):",1,0],[3,25,"וַאֲשֶׁר יָגֹרְתִּי. הֵן עַתָּה הוּעְתַּד וְנִגְזַר שֶׁיָּבֹא לִי:",2,0],[3,26,"לֹא שָׁלַוְתִּי. מִדְּאָגָה זוֹ, וְהִנֵּה וַיָּבֹא רֹגֶז:",1,0],[4,1,"(מענה אליפז) אֱלִיפַז בֶּן עֵשָׂו הָיָה (בראשית לו:ד), וְעַל יְדֵי שֶׁנִּתְגַּדֵּל בְּחֵיקוֹ שֶׁל יִצְחָק, זָכָה שֶׁתִּשְׁרֶה עָלָיו שְׁכִינָה:",1,0],[4,1,"הַתֵּימָנִי. מֵאֶרֶץ תֵּימָן, מֵאַרְצוֹ שֶׁל עֵשָׂו (בראשית לו:לד) (סא״א):",2,0],[4,2,"הֲנִסָּה. לְשׁוֹן תֵּימַהּ: הֲבַּעֲבוּר שֶׁנִּסָּה דָבָר אֵלֶיךָ תִּלְאֶה? בְּנִסָּיוֹן אֶחָד שֶׁנִּסְּךָ בּוֹרַאֲךָ וּבָא אֵלֶיךָ, אַתָּה נִלְאֶה?! וּמֵעַתָּה, עֲצֹר בְּמִלִּין מִי יוּכַל. מִלְּהַשִׁיבְךָ?",1,0],[4,3,"הִנֵּה יִסַּרְתָּ רַבִּים. שֶׁהִרְבּוּ דְבָרִים, הוֹכַחְתָּם וְיִסַּרְתָּם:",1,0],[4,3,"וְיָדַיִם רָפוֹת. וִיגוּרוֹת מִפּוּרְעָנוּת הַבָּא עֲלֵיהֶם, אַתָּה הָיִיתָ רָגִיל לְחַזְּקָם, וְלוֹמַר: אַל תִּירָא, שֶׁכָּךְ הוּא מִדַּת הַדִּין:",2,0],[4,4,"יְקִימוּן. רְגִילוֹת הֵם מִלֶּיךָ לְהָקִים אֶת הַכּוֹשֵׁל:",1,0],[4,6,"הֲלֹא. עַתָּה סוֹפְךָ מוֹכִיחַ עַל תְּחִלָּתְךָ, שֶׁיִּרְאָתְךָ, שֶׁהָיִיתָ יְרֵא שָׁמַיִם:",1,0],[4,6,"כִּסְלָתֶךָ. הִיא (בבא מציעא נח.) מֵחֲמַת כְּסִילוּת הִיא, וְלֹא מִדַּעַת שְׁלֵימָה. וְכֵן תִּקְוָתְךָ וְתֹם דְּרָכֶיךָ הַכֹּל כְּסִילוּת:",2,0],[4,7,"נִכְחָדוּ. נֶעֶלְמוּ וְנֶאֶבְדוּ, כְּמוֹ ״וַתִּכָּחֵד מִן הָאָרֶץ״ (שמות ט:טו):",1,0],[4,8,"כַּאֲשֶׁר רָאִיתִי. אֲשֶׁר (כֵּן) נִכְחֲדוּ חוֹרְשֵׁי אָוֶן וּמְכִינִים אֶת הָאָוֶן בְּמַחֲשַׁבְתָּם, כְּחוֹרֵשׁ זֶה שֶׁמֵּכִין לִפְנֵי הַזְּרִיעָה, וְאַחֲרֵי כֵן זוֹרְעִים בְּמַעֲשֵׂיהֶם אֶת הֶעָמָל; וְרָאִיתִי, שֶׁהֵם יִקְצְרֻהוּ. כְּלוֹמַר: רָעָתָם שֶׁבָּאָה עֲלֵיהֶם. וְרָאִיתִי, כִּי:",1,0],[4,9,"מִנִּשְׁמַת אֱלוֹהַּ יֹאבֵדוּ. מִנְּשִׁיבַת סַעֲרָתוֹ וְכַעֲסוֹ:",1,0],[4,9,"וּמֵרוּחַ אַפּוֹ יִכְלוּ. כָּלִים תָּמִיד, וְעַל דּוֹר הַמַּבּוּל דִּבֵּר (בראשית ו:יג):",2,0],[4,10,"שַׁאֲגַת אַרְיֵה וְקוֹל שָׁחַל וְגוֹ׳. הָאֲרִי גָּדוֹל, וְהַשַּׁחַל בֵּינוֹנִי, וְהַכְּפִיר קָטָן; כֻּלָּם נִתָּעוּ. כְּלוֹמַר: הַמְּלָכִים וְהַשָּׂרִים וְהָעֲבָדִים. וְכָל שֵׁמוֹת הַלָּלוּ שְׁמוֹת אַרְיֵה הֵם:",1,0],[4,11,"לַיִשׁ אוֹבֵד מִבְּלִי טָרֶף. הַשָּׂרִים אָבְדוּ כְּלַיִשׁ זֶה הָאוֹבֵד מִבְּלִי מָזוֹן, כָּךְ אָבַד כֹּחָם מֵעֲשׂוֹת חָמָס. אוֹבֵד אֵינוֹ לְשׁוֹן אָדָם הָאוֹבֵד דָּבָר מִמֶּנּוּ, אֶלָּא הוּא עַצְמוֹ הוֹלֵךְ לְאִבּוּד, כְּמוֹ ״תָּעִיתִי כְּשֶׂה אֹבֵד״ (תהילים קיט:קעו), וּכְמוֹ ״הָיִיתִי כִּכְלִי אֹבֵד״ (תהילים לא:יג):",1,0],[4,11,"וּבְנֵי לָבִיא יִתְפָּרָדוּ. מְדַבֵּר בְּדוֹר הַפְּלַגָּה, אֲשֶׁר נָפוֹצוּ מִשָּׁם עַל פְּנֵי כָל הָאָרֶץ (בראשית יא:ט):",2,0],[4,12,"וְאֵלַי דָּבָר יְגֻנָּב. חוֹזֵר עַל תּוֹכַחְתּוֹ שֶׁהוֹכִיחוֹ עַד הֵנָּה: מַה תִּזְעַק? זְכָר נָא מִי הוּא נָקִי אָבַד וְגוֹ׳כַּאֲשֶׁר רָאִיתִי וְגוֹ׳, וְעַל אוֹדוֹתֶיךָ אֵלַי דָּבָר נְבוּאָה יְגֻנָּב. מִן הַסִּגְנוֹן, כְּדָבָר גָּנוּב; לְפִי שֶׁאֵין רוּחַ הַקֹּדֶשׁ נִגְלֶה עַל נְבִיאֵי עוֹבְדֵי כּוֹכָבִים בְּפַרְהֶסְיָא. מָשָׁל לְמֶלֶךְ, שֶׁהָיְתָה לוֹ אִשָּׁה וּפִילֶגֶשׁ; כְּשֶׁבָּא אֵצֶל אִשְׁתּוֹ בָּא בְּגָלוּי, וְאֵצֶל פִּילַגְשׁוֹ בָּא בְּסֵתֶר וּבִגְנֵבָה. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לִנְבִיאֵי עוֹבְדֵי כּוֹכָבִים: ״וַיָּבֹא אֱלֹהִים אֶל אֲבִימֶלֶךְ בַּחֲלוֹם הַלָּיְלָה״ (בראשית כ:ג); וְכֵן ״וַיָּבֹא אֱלֹהִים אֶל לָבָן וְגוֹ׳״ (בראשית לא:כד); לְבִלְעָם: ״נֹפֵל וּגְלוּי עֵינָיִם״ (במדבר כד:ד); לֶאֱלִיפַז: בַּחֶזְיוֹנוֹת הַלַּיְלָה. אֲבָל בִּנְבִיאֵי יִשְׂרָאֵל כְּתִיב ״פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ בְּמַרְאֶה וְלֹא בְחִידוֹת״ (במדבר יב:ח). בְּמִדְרַשׁ תַּנְחוּמָא מָצָאתִי מֻגֶּה וְל״שׁ:",1,0],[4,12,"וַתִּקַּח אָזְנִי שֵׁמֶץ מֶנְהוּ. שֶׁמֶץ מִקְצָת רוּחַ הֲבָנָה:",2,0],[4,13,"בִּשְׂעִפִּים. בְּמַחֲשָׁבוֹת:",1,0],[4,14,"פַּחַד קְרָאַנִי. מִן הָרוּחַ שֶׁבָּא אֵלַי. וְרוּחַ הוּא מַלְאָךְ, שֶׁנֶּאֱמַר (תהילים קד:ד) ״עֹשֶׂה מַלְאָכָיו רוּחוֹת״:",1,0],[4,15,"תְּסַמֵּר. הָרוּחַ שַׂעֲרַת בְּשָׂרִי:",1,0],[4,15,"תְּסַמֵּר. הוּא לְשׁוֹן אָדָם שֶׁעָמְדוּ שַׂעֲרוֹתָיו:",2,0],[4,16,"יַעֲמֹד. עוֹמֵד הָיָה בְּפָנַי, וְלֹא הָיִיתִי מַכִּיר מַרְאֵהוּ:",1,0],[4,16,"דְּמָמָה וָקוֹל. קוֹל דָּבָר חֲשַׁאי הָיִיתִי שׁוֹמֵעַ. דָּבָר אַחֵר: דְּמָמָה וָקוֹל אֶשְׁמַע – קוֹל שָׁמַעְתִּי מִדְּמָמָה, אֲבָל דְּמָמָה לֹא שָׁמַעְתִּי. דְּמָמָה – אֵלּוּ הַמַּלְאָכִים שֶׁאוֹמְרִים שִׁירָה, כְּדִמְתַרְגֵּם ״וְאַחַר הָרַעַשׁ קוֹל דְּמָמָה דַקָּה״ (מלכים א יט:יב): ״קָל דִּמְשַׁבְּחִין בַּחֲשַׁאי״. מֹשֶׁה – דְּמָמָה שָׁמַע; מִכָּאן, שֶׁהָרִאשׁוֹנִים נִשְׁתַּמְּשׁוּ בְּקוֹל, וְהָאַחֲרוֹנִים – בְּבַת קוֹל. כְּאָדָם הַמַּכֶּה בְּפַטִּישׁ, וְקוֹל הַהֲבָרָה נִשְׁמַע לְמֵרָחוֹק; כָּךְ הוּא אוֹמֵר:",2,0],[4,17,"הַאֱנוֹשׁ מֵאֱלוֹהַ יִצְדָּק. בִּתְמִיהַּ:",1,0],[4,17,"וְאִם מֵעֹשֵׂהוּ יִטְהַר גָּבֶר. וְאִם יוֹתֵר מֵעוֹשֵׂהוּ יִטְהַר גָּבֶר? וּמָה זֶּה חֲבֵירְךָ יִצְעַק?!",2,0],[4,18,"הֵן בַּעֲבָדָיו. הַצַּדִּיקִים לֹא יַאֲמִין שֶׁלֹּא יֶחֶטְאוּ לוֹ, וּמְסַלְּקָם מִן הָעוֹלָם לִפְנֵי זְמַנָּם:",1,0],[4,18,"תָּהֳלָה. לְשׁוֹן ״הוֹלְלוּת״ (קהלת י:יג):",2,0],[4,19,"אַף. כָּל שֶׁכֵּן:",1,0],[4,19,"שׁוֹכְנֵי בָתֵּי חֹמֶר אֲשֶׁר בֶּעָפָר יְסוֹדָם. קִבְרָם:",2,0],[4,19,"יְדַכְּאוּם לִפְנֵי עָשׁ. מִן הַשָּׁמַיִם מְתִישִׁין אֶת כֹּחָם, עַד שֶׁהֵן שְׁפָלִים וְנִדְכָּאִים לִפְנֵי הָרִמָּה הָאוֹכַלְתָּן בְּמוֹתָן:",3,0],[4,20,"מִבֹּקֶר לָעֶרֶב יֻכַּתּוּ. בְּיוֹם אֶחָד הֵם כְּתוּתִים וְנִדְכָּאִים:",1,0],[4,20,"מִבְּלִי מֵשִׂים. עַל לֵב לָשׁוּב לְקוֹנָם:",2,0],[4,20,"לָנֶצַח יֹאבֵֽדוּ. וְגַם זֶה הוּא מִקְרָא חָסֵר:",3,0],[4,21,"הֲלֹא נִסַּע יִתְרָם בָּם. כְּמוֹ ״יִתְרָה עָשָׂה וְגוֹ׳״ (ישעיהו טו:ז): גַּאֲוָתָם וְחָכְמָתָם תִּתְבַּלַּע בְּגוּפָן (תהלים קז:כז), וְהִנֵּה נוֹסַעַת וְנִסַּחַת, כְּמוֹ ״בַּל יִסַּע יְתֵדוֹתָיו״ (ישעיהו לג:כ):",1,0],[5,1,"קְרָא נָא. עַד כָּאן דִּבֵּר הַנְּבוּאָה, מִכָּאן וָאֵילָךְ חוֹזֵר לְתוֹכַחְתּוֹ: צְעַק הַרְבֵּה, מִי יַעַנְךָ?",1,0],[5,1,"וְאֶל מִי מִקְּדֹשִׁים. הַגּוֹזְרִים זֹאת עָלֶיךָ תִּפְנֶה. לְהִלָּחֵם אִתּוֹ:",2,0],[5,2,"כִּי לֶאֱוִיל וְגוֹ׳. לֶאֱוִיל כְּמוֹתְךָ יַהֲרֹג כַּעֲסוֹ, שֶׁאִלּוּ הָיִיתָ שׁוֹתֵק, שֶׁמָּא תָּשׁוּב מִדַּת הָרַחֲמִים עָלֶיךָ:",1,0],[5,2,"קִנְאָה. הִיא כַּעַס וְחֵמָה, כְּמוֹ ״הֵם קִנְאוּנִי״ (דברים לב:כא):",2,0],[5,4,"יִרְחֲקוּ בָנָיו. זוֹ הִיא קְלָלָה שֶׁקִּלַּלְתִּיו:",1,0],[5,4,"וְיִדַּכְּאוּ. בְּדָגֵשׁ הוּא יְדֻכְּאוּ, וְאִם הוּא נָקוּד רָפֵי מְשַׁמֵּשׁ יְדַכְּאוּ אֲחֵרִים:",2,0],[5,5,"אֲשֶׁר קְצִירוֹ. שֶׁל רָשָׁע:",1,0],[5,5,"רָעֵב יֹאכֵל. כִּי יָמוּת רָשָׁע, יָבוֹאוּ הָרְעֵבִים שֶׁקִּצֵּץ בְּחַיָּיו, וְיִשְׁתַּלְּמוּ גְזֵלוֹתָיו מִנְּכָסָיו:",2,0],[5,5,"וְאֶל מִצִּנִּים יִקָּחֵהוּ. כְּמוֹ ״וְיִקְחוּ אֵלֶיךָ״ (שמות כז:כ), כְּלוֹמַר: לְצֹרֶךְ הֶעָנִי הַנּוֹשָׁע מִצִּנִּים וּכְלֵי זַיִן שֶׁל רָשָׁע זֶה, יִקָּחֵהוּ הַשּׁוֹפֵט הַמְּמֻנֶּה לְכָךְ:",3,0],[5,5,"וְשָׁאַף. וּבָלַע אִישׁ אִישׁ מִן הַצַּמִּים שֶׁגָּזַל בְּחַיָּיו:",4,0],[5,5,"חֵילָם. מָמוֹנָם, שֶׁגָּזַל זֶה בְּחַיָּיו:",5,0],[5,6,"כִּי לֹא יֵצֵא מֵעָפָר. מַכָּה הַבָּאָה עַל הָאָדָם, לֹא לְחִנָּם הוּא, וְלֹא מִן הֶעָפָר תִּצְמַח לוֹ:",1,0],[5,6,"אָוֶן. הוּא לְשׁוֹן שֶׁבֶר:",2,0],[5,7,"כִּי אָדָם לְעָמָל יוּלָּד. כִּי אִי אֶפְשָׁר שֶׁלֹּא יֶחֱטָא וִיקַבֵּל עָמָל בְּחֶטְאוֹ, לְקַבֵּל פּוּרְעָנוּתוֹ. וְאֵינוֹ כִּבְנֵי רֶשֶׁף, שֶׁהֵם מַלְאָכִים וְרוּחוֹת, שֶׁהֵם יַגְבִּיהוּ עוּף, וְאֵינָם מִן הַתַּחְתּוֹנִים (יַגְבִּיהוּ לָעוּף וְלִהְיוֹת מִן הַתַּחְתּוֹנִים (סא״א)), לִשְׁלוֹט בָּם שָׂטָן וְיֵצֶר הָרָע:",1,0],[5,7,"רֶשֶׁף. כְּמוֹ ״רִשְׁפֵּי קֶשֶׁת״ (תהילים עו:ד), כְּשֶׁהַחֵץ מְעוֹפֶפֶת נִקְרָא רִשְׁפֵּי, לְשׁוֹן עוּף (סא״א):",2,0],[5,8,"אוּלָם אֲנִי אֶדְרֹשׁ. אִם הָיוּ בָּאִים עָלַי יִסּוּרִים הַלָּלוּ, הָיִיתִי דּוֹרֵשׁ אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא בִּתְפִלָּה וּבִתְחִנָּה; וְאִלּוּ הָיִיתִי שָׂם, דִּבְרָתִי בְּבַקָּשָׁה:",1,0],[5,10,"הַנּוֹתֵן מָטָר עַל פְּנֵי אָרֶץ. אֶרֶץ יִשְׂרָאֵל:",1,0],[5,10,"וְשׁוֹלֵחַ מַיִם עַל פְּנֵי חוּצוֹת. עַל יְדֵי שָׁלִיחַ, לִשְׁאָר אֲרָצוֹת:",2,0],[5,11,"לָשׂוּם שְׁפָלִים לְמָרוֹם. הוּא נוֹתֵן אֶת הַמָּטָר, וְהוּא מֵפֵר מַחֲשְׁבוֹת עֲרוּמִים, שֶׁמְּדַמִּין לְהַפְקִיעַ שְׁעָרִים וְלִקְנוֹת שְׂדוֹת הָעֲנִיִּים בִּמְעַט תְּבוּאָה:",1,0],[5,11,"קוֹדְרִים. שֶׁקּוֹמְטִים פָּנִים בָּרָעָב:",2,0],[5,12,"וְלֹא תַעֲשֶׂנָה יְדֵיהֶם תּוּשִׁיָּה. אוֹתָהּ עֵצָה שֶׁדִּמּוּ לַעֲשׂוֹת:",1,0],[5,13,"נִמְהָרָה. כָּל הָעֵצָה הָעֲשׂוּיָה בִּמְהִירוּת הִיא סִכְלוּת:",1,0],[5,14,"יוֹמָם יְפַגְּשׁוּ חֹשֶׁךְ. שֶׁאֵין עֲצָתָם מִתְקַיֶּמֶת וְנַעֲשֵׂית, וְאוֹר חָכְמָתָם נֶהְפַּךְ לְחֹשֶׁךְ:",1,0],[5,15,"וַיּוֹשַׁע. אֶת הַנִּכְשָׁלִים:",1,0],[5,15,"מֵחֶרֶב. וּמֵאֵיזֶה חֶרֶב? מִפִּיהֶם; שֶׁהָיוּ סְבוּרִים לְבוֹלְעָם, וּמִתְאַוִּים לְהַשְׁמִידָם:",2,0],[5,15,"וּמִיַּד חָזָק. יוֹשִׁיעַ אֶבְיוֹן:",3,0],[5,16,"וְעוֹלָתָהּ. הָעֲלִילָה וְהָרִשְׁעָה, כְּמוֹ (תהילים סד:ז) ״יַחְפְּשׂוּ עוֹלוֹת״ – עֲלִילוֹת:",1,0],[5,16,"קָפְצָה. סָגְרָה, כְּמוֹ ״לֹא תִקְפֹּץ״ (דברים טו:ז):",2,0],[5,17,"הִנֵּה אַשְׁרֵי אֱנוֹשׁ וְגוֹ׳. בְּיִסּוּרִין. וּכְשֵׁם שֶׁהוּא (מְרַפֵּא) מַכְאוֹבִים שֶׁל אֵלּוּ, כָּךְ אֲנִי אֶדְרוֹשׁ אֵלָיו עַל יִסּוּרִין אֵלּוּ שֶׁיָּבוֹאוּנִי; וְהָיָה לְךָ לְקַבְּלָם וְלֹא לְמָאֳסָם:",1,0],[5,19,"בְּשֵׁשׁ צָרוֹת. כְּשֶׁיָּבֹאוּ לָעוֹלָם יַצִּילְךָ עַל יְדֵי יִסּוּרִין שֶׁנִּתְיַסַּרְתָּ בָּהֶם, וְגַם בַּשְּׁבִיעִית כְּשֶׁתָּבֹא לֹא יִגַּע בְּךָ. וְעַכְשָׁיו הוּא מוֹנֶה אוֹתָן:",1,0],[5,21,"בְּשׁוֹט לָשׁוֹן. שֶׁל שָׂטָן תֵּחָבֵא אוֹתְךָ. אֵלּוּ הֵן הַשֶּׁבַע צָרוֹת: רָעָב וְחֶרֶב, לָשׁוֹן וְשׁוֹד וְגוֹ׳, וְחַיַּת הָאָרֶץ – הֵם לִיסְטִים:",1,0],[5,23,"אַבְנֵי הַשָּׂדֶה. מִין אָדָם הֵן:",1,0],[5,23,"וְחַיַּת הַשָּׂדֶה. הוּא שֶׁנִּקְרָא גְּרוּשׁ״ה בְּלַעַ״ז, וְזוֹ הִיא חַיַּת הַשָּׂדֶה מַמָּשׁ. וּבִלְשׁוֹן מִשְׁנָה תּוֹרַת כֹּהֲנִים נִקְרָאִים אַדְנֵי הַשָּׂדֶה (כלאים ח,ה):",2,0],[5,23,"הָשְׁלְמָה לָךְ. יִהְיֶה לָהּ שָׁלוֹם עִמָּךְ:",3,0],[5,24,"וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךָ. וְאָז בְּכָל מָקוֹם תִּהְיֶה בָּטוּחַ, כִּי שָׁלוֹם אָהֳלֶךָ:",1,0],[5,24,"וּפָקַדְתָּ נָוְךָ וְלֹא תֶחֱטָא. כְּמוֹ ״אֶל הַשַּׂעֲרָה וְלֹא יַחֲטִא״ (שופטים כ:טז), וְזוֹ הִיא הַשְּׁבִיעִית שֶׁמָּנִינוּ לְמַעְלָה (איוב ה:יט):",2,0],[5,26,"תָּבוֹא בְכֶלַח אֱלֵי קָבֶר. שֶׁתִּנָּצֵל מִן הַדֶּבֶר. וּבְכֶלַח – אֵין סֶמֶךְ בַּמִּקְרָא לְהָבִין מְלִיצָתוֹ. וּלְפִי עִנְיַן הַמְּלִיצָה יִפָּתֵר וְיִלָּמֵד מֵעִנְיָנוֹ, שֶׁהוּא לְשׁוֹן גְּמַר בִּשּׁוּל הַתְּבוּאָה, כְּשֶׁבִּשְּׁלָה כָּל צָרְכָּהּ. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה פֵּרְשׁוּ (מועד קטן כח.) בְּכֶלַח – בְּגִימַטְרִיָּא: שִׁשִּׁים שָׁנָה:",1,0],[5,26,"כַּעֲלוֹת גָּדִישׁ. כַּאֲשֶׁר נִסְתַּלֵּק הַגָּדִישׁ מִן הַקַּרְקַע בְּעִתּוֹ:",2,0],[6,1,"(מענה איוב):",1,0],[6,2,"וְהַוָּתִי. שִׁבְרִי:",1,0],[6,2,"יִשְׂאוּ יָחַד. עִם מִשְׁקָל שֶׁכְּנֶגְדָּם, וַאֲפִלּוּ הֵם חוֹל יַמִּים, יִכְבַּד מִמֶּנּוּ:",2,0],[6,3,"לָעוּ. מְגֻמְגָּמִין, כְּאָדָם שֶׁאֵין בּוֹ כֹּחַ לְהוֹצִיא דָּבָר מִפִּיו כְּתִקּוּנוֹ; וְכֵן ״וְשָׁתוּ וְלָעוּ״ (עובדיה א:טז), שֶׁכֵּן דֶּרֶךְ שִׁכּוֹר לְגַמְגֵּם בִּדְבָרָיו:",1,0],[6,4,"חֲמָתָם. אֶרֶס שֶׁלָּהֶם. דֶּרֶךְ פַּרְסִיִּים לָתֵת אֶרֶס שֶׁל נָחָשׁ בְּחִצֵּיהֶם:",1,0],[6,5,"הֲיִנְהַק פֶּרֶא וְגוֹ׳. כְּלוֹמַר: וְכִי לְחִנָּם אֲנִי צוֹעֵק? וַהֲלֹא בְּהֵמָה שׁוֹטָה אֵינָהּ נוֹהֶקֶת בִּזְמַן שֶׁיֵּשׁ לָהּ דֶּשֶׁא, וְכֵן שׁוֹר לֹא יִגְעֶה אֶלָּא אִם כֵּן אֵין לוֹ בְּלִיל תְּבוּאָה. בְּפֶרֶא נוֹהֵג לְשׁוֹן ׳נְהַק׳, וּבְשׁוֹר – לְשׁוֹן ׳גְּעִיָּה׳:",1,0],[6,6,"הֲיֵאָכֵל תָּפֵל. דָּבָר שֶׁהוּא בְּלִי מֶלַח וְצָרִיךְ לְהַמְלִיחוֹ, וְלֹא נִמְלַח, קָרוּי תָּפֵל בִּלְשׁוֹן מִשְׁנָה (שבת קכח.; חלין קיג.; נדרים נא.):",1,0],[6,6,"אִם יֶשׁ טַעַם בְּרִיר. הַבָּא מֵחֲמַת הַחֲלָמוֹת כְּשֶׁאוֹכֵל דָּבָר חָזָק שֶׁמַּרְבֶּה רִיר וְרוֹק, כְּגוֹן שׁוּם. כְּלוֹמַר: וְכִי סְבוּרִים אַתֶּם שֶׁיִּהְיוּ מִתְקַבְּלוֹת תְּשׁוּבוֹת שֶׁאֵין בָּהֶם מַמָּשׁ? רִיר, כְּמוֹ ״וַיּוֹרֶד רִירוֹ עַל זְקָנוֹ״ (שמואל א כא:יד):",2,0],[6,6,"חַלָּמוּת. כְּמוֹ ״יֶחֶלְמוּ בְנֵיהֶם״ (איוב לט:ד), לְשׁוֹן חוֹזֶק. וְיֵשׁ פּוֹתְרִים לְשׁוֹן חֲלוֹם, וְאֵין נִרְאֶה בְּעֵינַי, מִפְּנֵי דַּגְשׁוּת הַלָּמֶ״ד:",3,0],[6,7,"מֵאֲנָה לִנְגּוֹעַ נַפְשִׁי. כְּלוֹמַר: הַרְבֵּה יֵשׁ לִי לִזְעוֹק, כִּי דְבָרִים שֶׁהָיְתָה נַפְשִׁי מְמָאֶנֶת וְקָצָה לִנְגּוֹעַ בָּהֶן, לְשׁוֹן נְגִיעָה:",1,0],[6,7,"הֵמָּה כִּדְוֵי לַחְמִי. הֵמָּה לִי עַתָּה נְכוֹנִים לְמַשְׁמֵשׁ בָּהֶם כִּמְפוֹת שֻׁלְחָנִי, שֶׁלַּחְמִי נָתוּן בָּהֶם. כִּדְוֵי לְשׁוֹן ״וַיִּכְרֹת אֶת מִדְוֵיהֶם״ (שמואל ב י:ד). כָּךְ שָׁמַעְתִּי מִפִּי רַבִּי מְשֻׁלָּם רוֹפֵא. עִנְיָן אַחֵר: כִּמְפוֹת שֶׁמְּסַנְּנִין בָּהֶן אֶת הַתַּבְשִׁיל וּמַאֲכָל זָב מֵהֶם, דְּוֵי לְשׁוֹן דָּוָה זָבָה (ויקרא טו:לג, יט):",2,0],[6,7,"לַחְמִי. כָּל מַאֲכָל קָרוּי לֶחֶם, כְּמוֹ ״עֲבַד לְחֶם רַב״ (דניאל ה:א), וּכְמוֹ ״נַשְׁחִיתָה עֵץ בְּלַחְמוֹ״ (ירמיהו יא:יט), וְתִרְגֵּם יוֹנָתָן: ״סַמָּא דְמוֹתָא בְּמֵיכְלֵיהּ״. לָשׁוֹן אַחֵר: הֵמָּה כְּמַבָּטֵי מַאֲכָלִי, כְּלוֹמַר: גַּס לִבִּי לְהִסְתַּכֵּל בָּהֶם בְּרִמָּה, כַּאֲשֶׁר אֲנִי מִסְתַּכֵּל בְּמַאֲכָלִי. וּלְשׁוֹן מִשְׁנָה הוּא: ״וּמְסַגּוֹ כִּי דָווּ״, בְּמַסֶּכֶת שַׁבָּת (שבת נג:):",3,0],[6,9,"וְיוֹאֵל. וְיִרְצֶה:",1,0],[6,9,"וִידַכְּאֵנִי. לְשׁוֹן מִיתָה:",2,0],[6,9,"יַתֵּר יָדוֹ. יְגַדֵּל יָדוֹ בְּמַכָּתוֹ, כְּמוֹ ״הִנֵּה יַד ה׳ הוֹיָה״ (שמות ט:ג):",3,0],[6,9,"וִיבַצְּעֵנִי. וִיכַלֵּנִי, כְּמוֹ ״בִּצַּע אֶמְרָתוֹ״ (איכה ב:יז), ״יָדָיו תְּבַצַּעְנָה״ (זכריה ד:ט):",4,0],[6,10,"וּתְהִי עוֹד נֶחָמָתִי. וּתְהִי עוֹד זֹאת לִי לְנֶחָמָה:",1,0],[6,10,"וַאֲסַלְּדָה בְחִילָה וְלֹא יַחְמוֹל. וַאֲבַקֵּשׁ מִמֶּנּוּ סְלִיחָה שֶׁלֹּא יַחְמוֹל מִלְּבַצְּעֵנִי, וַאֲנִי אֵינִי מוֹצֵא לוֹ דִּמְיוֹן בַּמִּקְרָא, זוּלָתִי שֶׁבִּלְשׁוֹן מִשְׁנָה הוּא לְשׁוֹן יָרֵא וְדוֹאֵג (חולין קה:): שֶׁהַיָּד סוֹלֶדֶת בָּהֶן מִלִּכָּווֹת בָּרוֹתְחִין; כְּלוֹמַר: אֶתְחוֹלֵל בִּדְאָגָה וּבְחִילָה בַּקָּשָׁה זוֹ:",2,0],[6,10,"כִּי לֹא כִחַדְתִּי. וְלֹא חָסַרְתִּי אֲמָרָיו מִלְּקַיְּמָן:",3,0],[6,11,"מַה כֹּחִי. חָזָק לִסְבּוֹל:",1,0],[6,11,"כִּי אֲיַחֵל. כִּי אֲמְתִּין עַד יוֹם רְפוּאָה אוֹ עַד יוֹם מִיתָה:",2,0],[6,11,"אֲיַחֵל. כְּמוֹ ״וַיָּחֶל עוֹד״ דְּנֹחַ (בראשית ח:י):",3,0],[6,11,"וּמַה קִּצִּי. וּמָה חָשׁוּב קִצִּי וְחָזָק כִּי אֲיַחֵל, כִּי לֹא אוּכַל לְהַאֲרִיךְ קִצִּי מִלִּסְבּוֹל:",4,0],[6,11,"נַפְשִׁי. הוּא יֵצֶר תַּאֲוַת אָדָם, בְּכַמָּה מְקוֹמוֹת, כְּמוֹ ״אִם יֵשׁ אֶת נַפְשְׁכֶם״ (בראשית כג:ח):",5,0],[6,13,"הַאִם אֵין עֶזְרָתִי בִי. לְשׁוֹן תֵּימָא: הֲגַם זֹאת תָּבֹא עָלַי, שֶׁאֵין עֶזְרָתִי בִּי – אוֹתָם רֵיעִים שֶׁהָיוּ לִי לְעָזְרֵנִי, אֵינָם בְּעֶזְרָתִי?!",1,0],[6,13,"וְתוּשִׁיָּה נִדְּחָה. עֵצָה שֶׁל יוֹעֲצִים נִדְּחָה מִמֶּנִּי, שֶׁקָּמָה עָלַי לְהַקְנִיט וְלִדְחוֹת:",2,0],[6,14,"לַמָּס מֵרֵעֵהוּ חָסֶד. לְמִי שֶׁמּוֹנֵעַ חֶסֶד מֵחֲבֵירוֹ. וְהַלָּמֶ״ד – מְשַׁמֶּשֶׁת, כְּמוֹ ״לָרָב״ (במדבר כו:נד), ״לָצָו״ (ישעיהו כח:י), לָשָׁב. מָס גַּם הוּא לְשׁוֹן פּוֹעֵל, כְּמוֹ בָּא, שָׁב, נָד, גַּם אֵלֶּה לְשׁוֹן עוֹשֶׂה:",1,0],[6,14,"לַמָּס הַחֶסֶד. מְכַלֶּה אוֹתוֹ, כְּמוֹ ״וְחַם הַשֶּׁמֶשׁ וְנָמָס״ (שמות טז:כא):",2,0],[6,15,"אַחַי. בְּנֵי מְלִיצָתִי:",1,0],[6,15,"בָּגְדוּ. בִּי, כְּמוֹ הַנַּחַל הַבּוֹגֵד בְּגִידוֹת כְּמוֹ שֶׁמְּפָרֵשׁ בָּעִנְיָן:",2,0],[6,15,"כַּאֲפִיק נְחָלִים. מוֹצָא נְחָלִים יַעַבְרוּ מִמִּדָּה נְכוֹחָה וְרֵיעוּת. וּמַה הִיא בְּגִידוּתוֹ שֶׁל נַחַל?",3,0],[6,16,"הַקּוֹדְרִים מִנִּי קָרַח. אִם בָּא עֲלֵיהֶם קֶרַח נִקְמָטִים וְנַעֲשִׂים קְרִים (קרשים קרים):",1,0],[6,16,"וְעָלֵימוֹ יִתְעַלֶּם. מִתְכַּסֶּה הַשֶּׁלֶג שֶׁנּוֹפֵל עַל הַקֶּרַח. הֲרֵי בְּגִידָה אַחַת: שֶׁנִּתְכַּסָּה מִן הָעַיִן, וְאֵין הַצָּמֵא מוֹצֵא מַיִם לִשְׁתּוֹת:",2,0],[6,17,"בְּעֵת יְזֹרְבוּ. לְשׁוֹן יְצֹרְבוּ, כְּחוֹם הַשֶּׁמֶשׁ:",1,0],[6,17,"נִצְמָתוּ. רֶטְרִי״שׁ בְּלַעַ״ז, כְּמוֹ ״וְחֹמֶץ צוֹמְתָן״ בִּלְשׁוֹן גְּמָרָא (פסחים מ:). צָדִ״י מִתְחַלֶּפֶת בְּזַיִ״ן, כְּמוֹ צְעָקָה זְעָקָה (בראשית כז:לד; ישעיהו סה:יט):",2,0],[6,17,"יְזֹרְבוּ. לְשׁוֹן ״וְנִצְרְבוּ בָהּ כָּל פָּנִים״ (יחזקאל כא:ג), וּכְמוֹ ״אֵשׁ צָרֶבֶת״ (משלי טז:כז):",3,0],[6,17,"נִדְעֲכוּ. נִקְפְּצוּ מִמְּקוֹמָם:",4,0],[6,18,"יִלָּפְתוּ. יֵאָחֲזוּ אָרְחוֹת דַּרְכָּם, כְּמוֹ ״וַיִּלְפֹּת שִׁמְשׁוֹן״ (שופטים טז:כט), וְכֵן ״וַיֶּחֱרַד הָאִישׁ וַיִּלָּפֵת״ (רות ג:ח) – שֶׁחִבְּקַתּוּ הָאִשָּׁה:",1,0],[6,19,"תֵּימָא. אֶרֶץ יִשְׁמָעֵאל שֶׁהִיא נְמוּכָה, וְהַמַּיִם נִגָּרִים שָׁם:",1,0],[6,19,"קִוּוּ. לְשׁוֹן קַו נָטוּי (ישעיהו לד:יא). דָּבָר אַחֵר: לְשׁוֹן ״יִקָּווּ הַמַּיִם״ (בראשית א:ט):",2,0],[6,20,"בֹּשׁוּ כִּי בָטָח בָּאוּ עָדֶיהָ. יֵבוֹשׁוּ שׁוֹתֶיהָ, כִּי בָטַח כָּל אִישׁ וְאִישׁ לִשְׁתּוֹת מֵהֶם:",1,0],[6,21,"כִּי עַתָּה הֱיִיתֶם לוֹ. הֱיִיתֶם נִמְשָׁלִים לְאוֹתוֹ נַחַל:",1,0],[6,21,"תִּירְאוּ חֲתַת. וּפַחַד הַמַּכָּה, וַתִּירְאוּ לוֹמַר הָאֱמֶת; וּמַחֲנִיפִים אֶת בַּעַל רִיבִי:",2,0],[6,22,"וּמִכֹּחֲכֶם שִׁחֲדוּ בַעֲדִי. וּמִמָּמוֹנְכֶם:",1,0],[6,25,"מַה נִּמְרְצוּ. כְּמוֹ ״קְלָלָה נִמְרֶצֶת״ (מלכים א ב:ח), לְשׁוֹן ״דָּבָר דָּבוּר עַל אָפְנָיו״ (משלי כה:יא). וְכֵן ״נִמְלְצוּ לְחִכִּי״ (תהלים קיט:קג) – כֻּלָּן לְשׁוֹן מְלִיצָה הֵם, וְלָמֶ״ד מִתְחַלֶּפֶת בְּרֵי״שׁ:",1,0],[6,25,"אִמְרֵי יֹשֶׁר. אִם אִמְרֵי יֹשֶׁר הֱיִיתֶם אוֹמְרִים, הָיוּ מְקֻבָּלִים; אֲבָל עַתָּה, מַה יּוֹכִיחַ הוֹכֵחַ מִכֶּם? כָּל תּוֹכָחָה שֶׁבְּאִיּוֹב – בֵּרוּר הַדְּבָרִים הֵם, וּמַעֲמִידִים עַל הָאֱמֶת:",2,0],[6,26,"הֲלְהוֹכַח מִלִּים תַּחְשֹׁבוּ. הֲלְבָרֵר דְּבָרִים תַּחְשֹׁבוּ?",1,0],[6,26,"וּלְרוּחַ. הֵם מְשׁוּלִים:",2,0],[6,26,"אִמְרֵי נוֹאָשׁ. שֶׁאֵין בָּהֶם מַמָּשׁ, כְּמוֹ ״וַתֹּאמְרִי נוֹאָשׁ״ (ירמיה ב:כה) – אֵינִי חוֹשֵׁשׁ לְדִבְרֵי הַנְּבִיאִים:",3,0],[6,27,"תַּפִּילוּ. בְּדִינְכֶם אַתֶּם מַפִּילִים. הַאַף עַל עָנִי כָּמוֹנִי בְּקַו מִשְׁפָּט? וְתִכְרוּ שׁוּחָה עַל רֵיעֲכֶם לְהַפִּילוֹ?",1,0],[6,28,"הוֹאִילוּ. הִתְרַצּוּ לִפְנוֹת אֵלַי וְלִשְׁמֹעַ דְּבָרַי, וְתִרְאוּ אִם עַל פְּנֵיכֶם אֲכַזֵּב:",1,0],[6,29,"שׁוּבוּ נָא. לִבְחוֹן, וְתִבְחֲנוּ, שֶׁלֹּא תְהֵא עוֹד עַוְלָה וְשׁוּבוּ לַחֲקוֹר, וַהֲרֵי צִדְקִי יִמָּצֵא בָהּ:",1,0],[6,30,"אִם חִכִּי לֹא יָבִין הַוּוֹת. לֹא יָבִין כְּשֶׁאֲנִי מְדַבֵּר הַוּוֹת?",1,0],[7,1,"הֲלֹא צָבָא וְגוֹ׳. זֶה הַדָּבָר אֲשֶׁר אָמַרְתִּי לָכֶם הוֹאִילוּ פְּנוּ בִי, כִּי אֵיךְ אַחֲרִישׁ מִלִּזְעוֹק עַל הַוָּתִי? הֲלֹא יְדַעְתֶּם כִּי יֵשׁ צָבָא וּזְמַן לֶאֱנוֹשׁ, כַּמָּה יִחְיֶה:",1,0],[7,1,"וְכִימֵי שָׂכִיר. שֶׁנִּשְׂכַּר לְשָׁנָה, וְיוֹדֵעַ שֶׁיִּכְלוּ יְמֵי שְׂכִירוּתוֹ, כֵּן זֶה יוֹדֵעַ שֶׁיִּכְלוּ שָׁנִים הַקְּצוּבוֹת לוֹ. וַאֲנִי – אוֹתוֹ צָבָא הַנִּתָּן לִי:",2,0],[7,2,"כְּעֶבֶד יִשְׁאַף צֵל. כְּעֶבֶד שֶׁהוּא יָגֵעַ כָּל הַיּוֹם, וְיִשְׁאַף וְיִתְאַוֶּה מָתַי יִהְיֶה צֵל הָעֶרֶב; וּכְשָׂכִיר אֲשֶׁר יְקַוֶּה פָעֳלוֹ לָעֶרֶב, לְפִי שֶׁהָיָה לוֹ כָּל הַיּוֹם לְעָמָל, וְיִתְאַוֶּה לְבִיאַת הַשֶּׁמֶשׁ:",1,0],[7,3,"כֵּן הָנְחַלְתִּי לִי. מִשָּׁמַיִם יַרְחֵי שָׁוְא וְיִסּוּרִין, אוֹתוֹ ״צָבָא הַנִּתָּן לֶאֱנוֹשׁ עֲלֵי אָרֶץ״ (איוב ז:א):",1,0],[7,3,"וְלֵילוֹת עָמָל מִנּוּ לִי. (מִן הַשָּׁמַיִם):",2,0],[7,4,"אִם שָׁכַבְתִּי. בַּלַּיְלָה, צָפִיתִי וְאָמַרְתִּי וְגוֹ׳:",1,0],[7,4,"וּמִדַּד עָרֶב. מָתַי יָאִיר, וְיָבֹא עֵת קִימָה וְעֵת מִידוּד הַנֶּשֶׁף – לְשׁוֹן ״וַתִּדַּד שְׁנָתִי״ (בראשית לא:מ), וְהַמֵּ״ם הוּא עִקָּר נוֹפֵל, כְּמוֹ ״מַאֲמַר״ (אסתר א:טו), ״מִשְׁמָר״ (בראשית מב:יז):",2,0],[7,4,"וְשָׂבַעְתִּי נְדוּדִים. וְאֶשְׂבַּע נְדוּדִים עַל מִטָּתִי בַּיּוֹם עַד נָשֶׁף, לְפִי שֶׁלֹּא הָיִיתִי יָכוֹל לִישֹׁן מִפְּנֵי יִסּוּרִים עַד נֶשֶׁף שֶׁל יוֹם, לְפִי שֶׁלָּבַשׁ בְּשָׂרִי רִמָּה:",3,0],[7,5,"וְגוּשׁ עָפָר. גּוּשַׁת עָפָר, וְהִיא הֶעֶלְתָה חֲלוּדָּה; שֶׁדֶּרֶךְ גּוּשׁ עָפָר לְלַחְלֵחַ וּלְהַעֲלוֹת חֲלוּדָּה:",1,0],[7,5,"רָגַע. נִקְמַט, כְּמוֹ ״רֹגַע הַיָּם״ (ישעיה נא:טו). פֵּרוּשׁ אַחֵר: עוֹרִי רָגַע. לְשׁוֹן נוֹחַ, גַּל אַחַר גַּל, כַּקְּמָטִים הַלָּלוּ:",2,0],[7,6,"יָמַי קַלּוּ. יְמֵי טוֹבָתִי מִהֲרוּ לָלֶכֶת:",1,0],[7,6,"מִנִּי אָרֶג. מִנִּי אֲרִיגָה הַנַּעֲשֵׂית מְהֵרָה, וְכֵן אָמַר חִזְקִיָּה: ״קִפַּדְתִּי כָאֹרֵג חַיַּי״ (ישעיה לח:יב):",2,0],[7,6,"בְּאֶפֶס תִּקְוָה. אֵינִי מְקַוֶּה עוֹד לְטוֹבָה:",3,0],[7,7,"לֹא תָשׁוּב עֵינִי. לְאַחַר מִיתָה. וְכָאן כָּפַר אִיּוֹב בִּתְחִיַּת הַמֵּתִים:",1,0],[7,8,"לֹא תְשׁוּרֵנִי. לֹא יִרְאֵנִי עוֹד עַיִן שֶׁתַּחְפֹּץ לִרְאוֹתִי אַחַר שֶׁאָמוּת:",1,0],[7,8,"עֵינֶיךָ בִּי וְאֵינֶנִּי. לְהַקָּדוֹשׁ בָּרוּךְ הוּא מְדַבֵּר: לָמָּה הֻצְרַכְתָּ לְפַצְּעֵנִי וּלְדַכְּאֵנִי בְּיִסּוּרִים? בִּרְאִיָּה אַחַת, שֶׁתָּשִׂים עֵינֶיךָ עָלַי, וְאֵינֶנִּי בָּעוֹלָם!",2,0],[7,11,"גַּם אֲנִי לֹא אֶחֱשָׂךְ פִּי. הוֹאִיל וְאֵינְךָ חָדֵל מִמֶּנִּי, גַּם אֲנִי לֹא אֶמְנַע דִּבּוּר מִלִּצְעֹק עַל מִדּוֹתֶיךָ:",1,0],[7,12,"הֲיָם אָנִי. שֶׁשַּׂמְתָּ עָלַי חוֹל לְמִשְׁמָר?!",1,0],[7,12,"אִם תַּנִּין. דָּג גָּדוֹל שֶׁחֲבַשְׁתּוֹ בְּנִבְכֵי יָם, כִּי תָשִׂים עָלַי מִשְׁמָר. הַשָּׂטָן הַזֶּה, לְשׁוֹמְרֵנִי, שֶׁלֹּא תֵצֵא נַפְשִׁי?!",2,0],[7,13,"יִשָּׂא בְשִׂיחִי מִשְׁכָּבִי. מִשְׁכַּב הַלַּיְלָה יִסְבֹּל בְּצָרָתִי מְעַט, וְאוּכַל לִמְנֹעַ שִׂיחִי:",1,0],[7,15,"מָוֶת מֵעַצְמוֹתָי. מָוֶת אֲנִי בּוֹחֵר יוֹתֵר מֵאֵיבָרִים הַלָּלוּ שֶׁבִּי:",1,0],[7,16,"מָאַסְתִּי. בְּחַיַּי, כִּי סוֹף סוֹף לֹא לְעוֹלָם אֶחְיֶה:",1,0],[7,16,"חֲדַל מִמֶּנִּי. מִלְּהָרַע לִי, כִּי הֶבֶל וּמְעַט יָמָי:",2,0],[7,17,"כִּי תְגַדְּלֶנּוּ. לָשִׂית אֵלָיו לִבְּךָ, לִפְקֹד מַעֲשָׂיו בְּכָל בֹּקֶר, וְלִבְחֹן לְכָל רֶגַע:",1,0],[7,19,"כַּמָּה. עֵת אָרֹךְ אֲשֶׁר לֹא תִשְׁעֶה מִמֶּנִּי, כְּמוֹ (שמות ה:ט) ״וְאַל יִשְׁעוּ בְּדִבְרֵי שָׁקֶר״, וְכֵן (איוב יד:ו) ״שְׁעֵה מֵעָלַי וַחֲדָל״:",1,0],[7,19,"בִּלְעִי רֻקִּי. כְּדֵי בְּלִיעַת רֻקִּי:",2,0],[7,20,"לְמִפְגָּע לָךְ. כְּפוֹגֵעַ הָאָדָם בְּעֵת חֲמָתוֹ, וּמְעוֹרֵר עָלָיו כָּל מַעֲשֵׂה אֵיבָתוֹ (ס״א חוֹבָתוֹ):",1,0],[7,20,"וָאֶהְיֶה עָלַי לְמַשָּׂא. זֶה אֶחָד מִן תֵּיבוֹת שֶׁכִּינָּה הַכָּתוּב, וְהֵן תִּיקּוּן סוֹפְרִים:",2,0],[7,21,"וּמֶה לֹא תִשָּׂא פִשְׁעִי. וּמָה הַדָּבָר הַזֶּה, שֶׁאֵינְךָ נוֹשֵׂא לְפִשְׁעִי?",1,0],[7,21,"וְשִׁחַרְתַּנִי. תְּבַקְּשֵׁנִי וְלֹא תִמְצָאֵנִי:",2,0],[8,2,"(מענה בלדד): וְרוּחַ כַּבִּיר. רוּחַ דְּבָרִים:",1,0],[8,2,"כַּבִּיר. לְשׁוֹן רוֹב:",2,0],[8,3,"הַאֵל יְעַוֵּת מִשְׁפָּט. הַהֵ״א נָקוּד פַּתָּח, וּמְלִיצָתוֹ לְשׁוֹן תֵּימַהּ:",1,0],[8,4,"וַיְשַׁלְּחֵם בְּיַד פִּשְׁעָם. עַל יְדֵי פִּשְׁעָם, (הַפֶּשַׁע) הוּא נַעֲשָׂה שָׁלִיחַ לְהוֹבִילָם:",1,0],[8,5,"אִם אַתָּה תְשַׁחֵר וְגוֹ׳. יָעִיר עָלֶיךָ אֶת זְכוּתְךָ:",1,0],[8,6,"וְשִׁלַּם נְוַת צִדְקֶךָ. וְיַעֲשֶׂה אֶת נְוַת צִדְקְךָ שָׁלֵם וְתָמִים:",1,0],[8,7,"וְהָיָה רֵאשִׁיתְךָ מִצְעָר. רֵאשִׁיתְךָ שֶׁעָבְרָה מִצְעָר, לְפִי אַחֲרִיתְךָ, שֶׁיִּשְׂגֶּה מְאֹד:",1,0],[8,8,"לְדוֹר רִישׁוֹן. עַל דּוֹר רִאשׁוֹן, כְּמוֹ ״כִּי שְׁאַל נָא לְיָמִים רִאשׁוֹנִים״ (דברים ד:לב):",1,0],[8,8,"וְכוֹנֵן. הָכֵן וְהִזְדַּמֵּן לַעֲמֹד עַל חֶקְרֵי אֲבוֹתָם:",2,0],[8,11,"הֲיִגְאֶה גֹּמֶא. זֹאת יֹאמְרוּ: אֵין הַגֹּמֶא גָּדֵל אֶלָּא בְּעוֹד שֶׁהַבִּצָּה לַחָה בְּמֵימֶיהָ וּבְלִחְלוּחֶיהָ. בִּצָּה מָרִישְׁ״ק בְּלַעַ״ז:",1,0],[8,12,"בְּאִבּוֹ. בְּלִחְלוּחוֹ וּבְפִרְיוֹ:",1,0],[8,12,"לֹא יִקָּטֵף. לֹא יִשָּׁבֵר וְלֹא יִנָּתֵק, כְּמוֹ ״וְקָטַפְתָּ מְלִילֹת״ (דברים כג:כו):",2,0],[8,12,"וְלִפְנֵי כָל חָצִיר יִיבָשׁ. קוֹדֶם כָּל חָצִיר יִיבַשׁ, כְּשֶׁהַמַּיִם כָּלִים וְהַבִּיצָּה חֲרֵבָה:",3,0],[8,13,"כֵּן אָרְחוֹת כָּל שֹׁכְחֵי אֵל. לְהַצְלִיחַ בְּעֵת שֶׁשָּׁעָתוֹ מְשַׂחֶקֶת לוֹ, עַד שֶׁתִּתְמַלֵּא סְאָתוֹ:",1,0],[8,13,"וְתִקְוַת. סוֹפוֹ שֶׁל חָנֵף יֹאבַד:",2,0],[8,14,"אֲשֶׁר יָקוֹט. יִקְצוֹר וְיִכְרוֹת כִּסְלָתוֹ וְהַבְטָחָתוֹ:",1,0],[8,14,"כִּסְלוֹ. הִיא מַחֲשֶׁבֶת מִבְטַחוֹ, כְּמוֹ (איוב לא:כד) ״אִם שַׂמְתִּי זָהָב כִּסְלִי״. יָקוֹט, לְשׁוֹן קָצִיר, כְּמוֹ (יחזקאל טז:מז) ״כִּמְעַט קָט״:",2,0],[8,14,"וּבֵית עַכָּבִישׁ. שֶׁאֵינוֹ קַיָּם, יִהְיֶה מִבְטַחוֹ:",3,0],[8,16,"רָטֹב הוּא. לַח וְחָזָק מַזָּלוֹ טֶרֶם בָּא אֵלָיו עֵת פְּקֻדַּת מַכַּת חוּמוֹ, הַמְיַיבַּשְׁתּוֹ. וּלְפִי שֶׁדִּמָּהוּ בְּגֹמֶא (לעיל ח:יא), מְדַבֵּר לְפִי הָעִנְיָן:",1,0],[8,16,"וְעַל גַּנָּתוֹ יוֹנַקְתּוֹ תֵצֵא. יוֹנַקְתּוֹ שֹׁרֶשׁ הַיּוֹנֵק, אוֹ עָנָף הַיַּלְדָּה הַגָּדֵל בְּשָׁנָה זוֹ, כְּמוֹ ״מֵרֹאשׁ יֹנְקוֹתָיו קָטֹף״ (יחזקאל יז:כב):",2,0],[8,17,"יְסֻבָּכוּ. יִתְאַחֲזוּ בֶּעָנָף וּבְסוֹבֶךְ:",1,0],[8,17,"בֵּית אֲבָנִים. יֶחֱזֶה מָקוֹם אֵיתָן רוֹאֶה וּבוֹנֶה לוֹ לִמְצוּדָה. וּמְנַחֵם פֵּרֵשׁ יֶחֱזֶה לְשׁוֹן גְּבוּל: יִגְבּוֹל אוֹתוֹ, יִבְנֶנּוּ עַד גְּבוּלוֹ, וְכֵן ״מְחוֹז חֶפְצָם״ (תהילים קז:ל), וְכֵן ״מֶחֱזָה אֶל מֶחֱזָה״ (מלכים א ז:ד). כָּל אֵלֶּה לִפְנֵי מַכָּתוֹ:",2,0],[8,18,"וּכְשֶׁיְּבַלְּעֶנּוּ. מִמְּקוֹמוֹ – הַנִּפְרָע מִמֶּנּוּ. וּמִקְרָא חָסֵר הוּא זֶה:",1,0],[8,18,"וְכִחֶשׁ בּוֹ. מְקוֹמוֹ:",2,0],[8,18,"לֹא רְאִיתִיךָ. שֶׁאֵין נִשְׁאָר מִמֶּנּוּ לֹא שֹׁרֶשׁ וְלֹא עָנָף, וַהֲרֵי הוּא כְּלֹא הָיָה. שֶׁאֵין נְפִילָתוֹ כְּמַפֶּלֶת צַדִּיקִים; כִּי הַצַּדִּיק יִפּוֹל וְיָקוּם (משלי כד:טז), וְזֶה יִפּוֹל בְּלֹא תְקוּמָה:",3,0],[8,19,"הֵן הוּא מְשׂוֹשׂ דַּרְכּוֹ. שֶׁל רָשָׁע, שֶׁכָּל מְשׂוֹשׂוֹ וְגַם הַצְלָחָתוֹ, לְלֹא תִּקְוָה תָּשׁוּב:",1,0],[8,19,"וּמֵעָפָר אַחֵר יִצְמָחוּ. בְּנֵי אָדָם שֶׁהָיוּ עַד הֵנָּה שָׁחִים עַד עָפָר, יִצְמָחוּ:",2,0],[8,19,"אַחֵר. אָדָם אַחֵר יִצְמַח לְקַבֵּל גְּדֻלָּתוֹ שֶׁל זֶה, כְּשֵׁם שֶׁמָּצִינוּ ״וְלַחוֹטֵא נָתַן עִנְיָן וְגוֹ׳״ (קהלת ב:כו). עַל כֵּן דַּע עַל עַצְמְךָ: אִם רָשָׁע הָיִיתָ, אֵין תְּקוּמָה לְמַפַּלְתְּךָ, וְאִם תָּם הָיִיתָ וְכוּ׳:",3,0],[8,20,"הֵן אֵל לֹא יִמְאַס תָּם. וְלֹא יַחֲזִיק בְּיַד מְשַׂנְאֶיךָ הַמְּרֵעִים לְךָ, עַד אֲשֶׁר יָשׁוּב לְרַחֵם עָלֶיךָ וִימַלֵּא שְׂחוֹק פִּיךָ:",1,0],[9,3,"(מענה איוב): לָרִיב עִמּוֹ. לְהִתְוַכֵּחַ עִמּוֹ:",1,0],[9,4,"חֲכַם לֵבָב. הוּא לָרִיב:",1,0],[9,4,"וְאַמִּיץ כֹּחַ. לְהִפָּרַע:",2,0],[9,4,"מִי הִקְשָׁה. לִבּוֹ וְהָלַךְ שָׁלֵם?! פַּרְעֹה הִקְשָׁה וְנֶחְסַר (שמות ז:יג, ח:טו, ט:יב), וְכֵן כָּל הַמַּקְשִׁים:",3,0],[9,5,"הַמַּעְתִּיק הָרִים. הַמְּסַלְּקָם, כְּהָפְכוֹ סְדוֹם (בראשית יט:כה):",1,0],[9,5,"וְלֹא יָדָעוּ. עַד שֶׁנֶּהֶפְכוּ:",2,0],[9,6,"הַמַּרְגִּיז אֶרֶץ. בְּהַבִּיטוֹ אֵלֶיהָ וְתִרְעָד (תהלים קד:לב):",1,0],[9,7,"הָאוֹמֵר לַחֶרֶס. לַשֶּׁמֶשׁ: דּוֹם (יהושע י:יב)! וְהוּא שָׁמַר אִמְרַת מֶלֶךְ וְלֹא יִזְרָח:",1,0],[9,7,"וּבְעַד. וּכְנֶגֶד הַכּוֹכָבִים יִסְגֹּר מְחִיצָה, וְלֹא יָאִירוּ:",2,0],[9,8,"נוֹטֶה שָׁמַיִם לְבַדּוֹ. וּמַלְאָכִים נִבְרְאוּ בַּיּוֹם שֵׁנִי, שֶׁלֹּא תֹּאמַר: מִיכָאֵל מָתַח בַּצָּפוֹן, וְגַבְרִיאֵל בַּדָּרוֹם:",1,0],[9,8,"עַל בָּמֳתֵי יָם. עַל גָּבְהֵי יָם. וְעַל מַעֲשֵׂה בְרֵאשִׁית נֶאֱמַר, שֶׁגָּבְהוּ הַמַּיִם הַתַּחְתּוֹנִים לָרוּם לְמַעְלָה, וּדְרָכָם:",2,0],[9,9,"כְּסִיל וְכִימָה. מַזָּלוֹת הֵם:",1,0],[9,9,"וְחַדְרֵי תֵימָן. לְהַכְנִיס שָׁם סוּפָה, כְּמוֹ שֶׁאָמַר ״מִן הַחֶדֶר תָּבוֹא סוּפָה״ (איוב לז:ט):",2,0],[9,11,"הֵן יַעֲבֹר וְגוֹ׳. יָדַעְתִּי כִּי כָּל אֲשֶׁר יַחְפֹּץ יַעֲשֶׂה:",1,0],[9,11,"יַעֲבֹר עָלַי. לְפָנַי, וְלֹא אֶרְאֶנּוּ:",2,0],[9,12,"יַחְתֹּף. יַכֶּה פִּתְאוֹם, כְּמוֹ ״הִיא כְחָתֶף תֶּאֱרֹב״ (משלי כג:כח). לְשׁוֹן ׳פִּתְאוֹם׳ הוּא:",1,0],[9,13,"לֹא יָשִׁיב אַפּוֹ. מִפְּנֵי יִרְאַת (וְצִדְקַת ס״א) אִישׁ:",1,0],[9,13,"תַּחְתָּו שָׁחֲחוּ. צְבָא מָרוֹם שֶׁבָּאוּ לַעֲזוֹר אֶת מִצְרַיִם. מִצְרַיִם נִקְרָא רַהַב, שֶׁנֶּאֱמַר ״לָכֵן קָרָאתִי לָזֹאת רַהַב הֵם שָׁבֶת״ (ישעיהו ל:ז) – עַל שֵׁם גַּאֲוָתָם, אֲשֶׁר אָמְרוּ ״מִי ה׳ וְגוֹ׳״ (שמות ה:ב):",2,0],[9,14,"אַף. כָּל שֶׁכֵּן:",1,0],[9,15,"לֹא אֶעֱנֶה. אִירָא לְהָרִים קוֹל לְפָנָיו:",1,0],[9,15,"לִמְשׁוֹפְטִי. כְּמוֹ לְשׁוֹפְטִי:",2,0],[9,16,"לֹא אַאֲמִין. לֹא אוּכַל לְהַאֲמִין מִיִּרְאָתִי אוֹתוֹ, כִּי אֵיךְ לֹא אִירָאֶנּוּ?",1,0],[9,17,"אֲשֶׁר בִּשְׂעָרָה. נִתְחַלְּפָה צוּרָתִי (ס״א שׁוּרָתִי) לְפָנָיו:",1,0],[9,17,"יְשׁוּפֵנִי. יְכַתְּתֵנִי, וְ״אָכֹת אֹתוֹ טָחוֹן״ (דברים ט:כא) מְתַרְגְּמִינָן ״וְשָׁפֵית יָתֵיהּ״ (תרגום אונקלוס):",2,0],[9,17,"פְּצָעַי. מַכָּה הַמּוֹצִיאָה דָּם וְלֵחָה:",3,0],[9,18,"לֹא יִתְּנֵנִי. אֵינוֹ מַנִּיחֵנִי לְהָשִׁיב רוּחִי אֵלַי:",1,0],[9,19,"אִם לְכֹחַ. אֵיךְ אָרִיב עִמּוֹ? אִם לְכֹחַ הוּא בָּא – אַמִּיץ הִנֵּה הוּא:",1,0],[9,19,"וְאִם לְמִשְׁפָּט. מִי יוּכַל לְהוֹעִידֵנִי לְפָנָיו וּלְהַחֲזִיק דְּבַר מִשְׁפָּטִי?",2,0],[9,20,"הֲלֹא אִם אֶצְדָּק פִּי יַרְשִׁיעֵנִי. כִּי יִסָּתְמוּ דְבָרַי מִיִּרְאָה, וְיַעְקְשֵׁנִי פִּי:",1,0],[9,21,"תָּם אָנִי. יוֹדֵעַ אֲנִי בְּעַצְמִי שֶׁאֲנִי תָּם, וְאַף עַל פִּי כֵן לֹא אֵדַע נַפְשִׁי. בַּמֶּה אֶמְצָא נוֹפֶשׁ:",1,0],[9,22,"אַחַת הִיא. בָּעוֹלָם, וְעָלֶיהָ אָמַרְתִּי שֶׁתָּם וְרָשָׁע הוּא מְכַלֶּה בַּעֲבוּרָהּ; וּמַה הִיא?",1,0],[9,23,"אִם שׁוֹט. לָשׁוֹן שֶׁל שָׂטָן יָמִית פִּתְאוֹם אֶת הַצַּדִּיק:",1,0],[9,23,"לְמַסַּת נְקִיִּים. שֶׁהֵמִית, יִלְעָג:",2,0],[9,24,"בְּיַד רָשָׁע. כְּלַפֵּי שָׂטָן:",1,0],[9,24,"פְּנֵי שׁוֹפְטֶיהָ יְכַסֶּה. מֵהַבְחִין בְּדָבָר אֱמֶת:",2,0],[9,24,"וְאִם לֹא אֵפוֹא. דָּבָר אֱמֶת דָּבָר זֶה, מִי הוּא הַמְכַלֶּה אֶת הַתְּמִימִים?",3,0],[9,25,"וְיָמַי. עִם כִּלְיוֹן שְׁאָר הַתְּמִימִים, קַלּוּ מִנִּי רָץ:",1,0],[9,26,"אֵבֶה. שֵׁם נָהָר שׁוֹטֵף:",1,0],[9,26,"יָטוּשׂ. יִפְרַח:",2,0],[9,27,"שִׂיחִי. דִּבְרֵי צַעֲרִי:",1,0],[9,27,"פָּנַי. חֲמָתִי:",2,0],[9,27,"וְאַבְלִיגָה. אֶתְחַזֵּק, כְּמוֹ ״הַמַּבְלִיג שֹׁד עַל עָז״ (עמוס ה:ט):",3,0],[9,28,"יָגֹרְתִּי כָל עַצְּבוֹתָי. שֶׁלֹּא יַנִּיחוּנִי מִלִּצְעוֹק:",1,0],[9,28,"יָדַעְתִּי כִּי לֹא תְנַקֵּנִי. מֵעֲוֹנִי, מִלְּהִפָּרַע מִמֶּנִּי:",2,0],[9,29,"לָמָּה זֶּה הֶבֶל אִיגָע. לָבוֹא בְּמִשְׁפָּט:",1,0],[9,30,"בְּבוֹר. נִקָּיוֹן:",1,0],[9,31,"בַּשַּׁחַת תִּטְבְּלֵנִי. לִהְיוֹת צָחוֹן וּמְגֹאָל, כְּלוֹמַר: אָז תִּמְצָא לִי עָוֹן רַב:",1,0],[9,32,"בַּמִּשְׁפָּט. בְּדִבְרֵי תוֹכָחוֹת. מִשְׁפָּט מְשַׁמֵּשׁ שָׁלֹשׁ לְשׁוֹנוֹת: תְּחִלָּתוֹ הוֹכָחַת דְּבָרִים, אֶמְצָעִיתוֹ פְּסַק דִּין, וְסוֹפוֹ מִשְׁטַר יִסּוּרִין וְגִבּוּי חוֹב. וּפְעָמִים שֶׁהַמִּקְרָא כּוֹתְבוֹ עַל שֵׁם תְּחִלָּתוֹ, וּפְעָמִים עַל שֵׁם אֶמְצָעִיתוֹ, וּפְעָמִים עַל שֵׁם אַחֲרִיתוֹ:",1,0],[9,33,"מוֹכִיחַ. דְּרַשְׁנִי״ר בְּלַעַ״ז, מַרְאֶה לְכָל אֶחָד חוֹבָתוֹ וּזְכוּתוֹ:",1,0],[9,33,"יָשֵׁת יָדוֹ. מִשְׁטַר אֵימָתוֹ וְנִיגוּשׁוֹ:",2,0],[9,33,"עַל שְׁנֵינוּ. שֶׁלֹּא יְחַזֵּק הֶחָזָק אֶת הָרָפֶה:",3,0],[9,35,"כִּי לֹא כֵן אָנֹכִי. עַל כֵּן שֶׁאָנֹכִי יָרֵא, אֲנִי מֻחְזָק בִּי שֶׁלֹּא אֶתְחַיֵּב בַּדִּין:",1,0],[10,1,"נָקְטָה נַפְשִׁי. נַפְשִׁי מִתְקוֹטֶטֶת עַל שֶׁאֲנִי חַי, וְהוּא לְשׁוֹן ״וּנְקֹטֹתֶם בִּפְנֵיכֶם״ (יחזקאל כ:מג):",1,0],[10,1,"אֶעֶזְבָה עָלַי שִׂיחִי. צָרָתִי, לִזְעוֹק וְלִקְבּוֹל, וְלֹא אוּכַל לְשַׁבְּחוֹ וּלְהַבְלִיגוֹ:",2,0],[10,3,"הֲטוֹב. בִּתְמִיהַּ, כִּי תַעֲשֹׁק וְתִגְזֹל מִן הַצַּדִּיק אֶת צִדְקוֹ, וְעַל עֲצַת רְשָׁעִים וּמַקְנִיטִים הוֹפָעְתָּ זִיוְךָ, לְהַרְאוֹת לָהֶם פָּנִים שׂוֹחֲקוֹת?",1,0],[10,5,"הֲכִימֵי אֱנוֹשׁ יָמֶיךָ. לְהִתְגָּרוֹת בּוֹ וְלִרְדֹּף?",1,0],[10,7,"עַל דַּעְתְּךָ. יוֹדֵעַ אַתָּה:",1,0],[10,8,"עִצְּבוּנִי. עֲשָׂאוּנִי, עֶצֶב דְּפוּס כְּמוֹ אֵין מְעַצְּבִין אֶת הַקָּטָן (שבת קמו:). וְעַתָּה חֵילוֹתֶיךָ יַחַד סָבִיב:",1,0],[10,8,"וַתְּבַלְּעֵנִי. הֵם הַתּוֹלָעִים:",2,0],[10,9,"תְּשִׁיבֵנִי. לְבַסּוֹף:",1,0],[10,10,"כֶּחָלָב תַּתִּיכֵנִי. כְּטִפַּת תּוֹלְדוֹתַי:",1,0],[10,12,"וּפְקֻדָּתְךָ. פְּקֻדַּת מִשְׁמַרְתְּךָ, שֶׁמִּנִּיתָ לִי שׁוֹמְרִים:",1,0],[10,12,"שָׁמְרָה רוּחִי. בְּבֶטֶן אִמִּי, וְאַחַר כָּךְ:",2,0],[10,13,"וְאֵלֶּה צָפַנְתָּ בִלְבָבֶךָ. לְבַלְּעֵנִי, כְּאִלּוּ אֵין (אַתָּה) זוֹכְרָם:",1,0],[10,13,"יָדַעְתִּי כִּי זֹאת עִמָּךְ. הַכֹּל כַּמְפֹרָשׁ, וְלֹא שָׁכַחְתָּ:",2,0],[10,14,"אִם חָטָאתִי וּשְׁמַרְתָּנִי. נָתַתָּ עֵינֶיךָ בִּי מִלְּהַעְלִים וְלַעֲבוֹר עַל מִדּוֹתֶיךָ. (וּמֵעַתָּה) וּמֵעֲוֺנִי אֵין אַתָּה מְנַקֵּנִי, אֶלָּא עַל הַכֹּל אַתָּה פּוֹרֵעַ:",1,0],[10,15,"שְׂבַע קָלוֹן. אֲנִי:",1,0],[10,15,"וּרְאֵה עָנְיִי. אֵין זֶה צִוּוּי, אֶלָּא שֵׁם דָּבָר: רְאֵה עָנְיִי. בֶּדְנַ״ץ בְּלַעַ״ז; שֶׁכָּל שָׁעָה אֲנִי רוֹאֵהוּ. כְּמוֹ שֶׁאַתָּה אוֹמֵר ״וּשְׂבַע יָמִים״ (איוב מב:יז) – כְּמוֹ וְשָׂבֵעַ יָמִים, כֵּן תֹּאמַר וּרְאֵה – כְּמוֹ ׳וְרוֹאֶה עָנְיִי׳:",2,0],[10,16,"וְיִגְאֶה כַּשַּׁחַל תְּצוּדֵנִי. וְיִגְדַּל בְּעֵינֶיךָ לִהְיוֹת לְךָ לְמַשָּׂא וּלְפַח נֶפֶשׁ, אֶת אֲשֶׁר כַּשַּׁחַל תְּצוּדֵנִי אֲשֶׁר תִּפְרֹשׂ לִי מְצוּדָה, כְּאִלּוּ אֲנִי גִּבּוֹר כַּשַּׁחַל:",1,0],[10,16,"וְתָשֹׁב. מִיּוֹם אֶל יוֹם:",2,0],[10,16,"תִּתְפַּלָּא בִי. לְדַקְדֵּק וּלְהַפְלִיא בַּמִּשְׁפָּט, לְשׁוֹן ״כִּי יַפְלִא״ (במדבר ו:ב):",3,0],[10,17,"עֵדֶיךָ. לְהָעִיד עַל חֲלִיפַת הֶחֳלָאִים וּמַכְאוֹבִים:",1,0],[10,17,"וְצָבָא עִמִּי. זְמַנִּים קְצוּבִים לְיִסּוּרַי; אֵלּוּ מְשַׁמְּשִׁים (צבא א׳), וְחוֹזְרִים וּמִתְחַלְּפִים שִׁנּוּיִים מְשֻׁנִּים מֵאֵלֶּה, וּמְשַׁמְּשִׁין זְמַן אַחֵר:",2,0],[10,18,"אֶגְוַע וְעַיִן לֹא תִרְאֵנִי. הַלְוַאי אֶגְוַע מֵרֶחֶם:",1,0],[10,19,"אוּבָל. הַלְוַאי הָיִיתִי מוּבָל:",1,0],[10,20,"וְשִׁית מִמֶּנִּי. תָּשִׁית עַצְמְךָ מִמֶּנִּי וּמֵעָלַי, כְּמוֹ ״קְרַב אֵלֶיךָ״ (ישעיה סה:ה) – קְרַב לְעַצְמְךָ וּרְחַק מִמֶּנִּי:",1,0],[10,21,"בְּטֶרֶם אֵלֵךְ. בְּעוֹדֶנִּי חַי וְלֹא הִגִּיעַ עֵת מוֹתִי, הַנַּח לִי וְאַרְגִּיעַ:",1,0],[10,22,"עֵיפָתָה. שֵׁם דָּבָר, חֲשֵׁיכָה, כְּמוֹ ״שַׁחַר וְעֵיפָה״ (עמוס ד:יג):",1,0],[10,22,"צַלְמָוֶת. הִיא וְלֹא סְדָרִים בָּהּ (שֶׁאֵין שָׁם סִדְרֵי אָדָם כְּלוֹמַר מִנְהָגִים שֶׁאֵין שָׁם יִשּׁוּב וְאוֹר שֶׁלָּהּ כְּמוֹ אֹפֶל הוּא):",2,0],[10,22,"וַתֹּפַע כְּמוֹ אֹפֶל. מָקוֹם מוּפָע שֶׁבָּהּ, כְּמוֹ אֹפֶל הוּא:",3,0],[11,2,"(מענה צופר:) לֹא יֵעָנֶה. מֵאֲחֵרִים, מִפְּנֵי רֹב דְּבָרָיו:",1,0],[11,3,"בַּדֶּיךָ. שֶׁאַתָּה בּוֹדֶה מִלִּבְּךָ:",1,0],[11,3,"מְתִים יַחֲרִישׁוּ. בְּנֵי אָדָם:",2,0],[11,4,"וַתֹּאמֶר. לְהַקָּדוֹשׁ בָּרוּךְ הוּא: זַךְ לִקְחִי וּבַר הָיִיתִי בְעֵינֶיךָ:",1,0],[11,6,"תַּעֲלוּמוֹת חָכְמָה. וְתֵדַע, כִּי כִפְלַיִם לְתוּשִׁיָּה יֵשׁ לַתּוֹרָה, שֶׁלֹּא קִיַּמְתָּ:",1,0],[11,6,"כִּי יַשֶּׁה. כְּמוֹ ״כִּי תַשֶּׁה בְרֵעֲךָ״ (דברים כד:י), (כְּלוֹמַר) הַרְבֵּה יֵשׁ לוֹ עוֹד חוֹב עָלֶיךָ בְּדִבְרֵי עֲוֹנֶיךָ:",2,0],[11,7,"הַחֵקֶר אֱלוֹהַּ תִּמְצָא. שֶׁאַתָּה סָבוּר שֶׁקִּיַּמְתָּ הַכֹּל?",1,0],[11,8,"גָּבְהֵי שָׁמַיִם. דָּבָר שֶׁהוּא גָּבוֹהַּ כְּגָבְהֵי שָׁמַיִם, מַה תִּפְעָל עַתָּה? וַעֲמֻקָּה הִיא הַחָכְמָה מִשְּׁאוֹל:",1,0],[11,9,"מִדָּה. מִדּוּד שֶׁלָּהּ (ס״א מִדָּה שֶׁלָּהּ), וְכָאן הִזְכִּיר מִדּוּד בְּלָשׁוֹן זָכָר (שֶׁלֹּא אָמַר מִדָּתָהּ):",1,0],[11,10,"אִם יַחֲלֹף וְיַסְגִּיר. בְּיִסּוּרִין אֶת מִי שֶׁיִּרְצֶה:",1,0],[11,10,"וְיַקְהִיל. כָּל פַּמַלְיָאוֹת שֶׁלּוֹ, לְוַכֵּחַ עַל שֶׁהִסְגִּיר:",2,0],[11,10,"וּמִי. בָּהֶן יְשִׁיבֶנּוּ בִּדְבָרִים, לִמְצֹא עָוֶל בְּפָעֳלוֹ? וְאִם מִפְּנֵי שֶׁהַנִּדּוֹן שָׁלֵו וְשָׁקֵט יָמִים רַבִּים, כֵּן דַּרְכּוֹ:",3,0],[11,11,"כִּי הוּא יָדַע מְתֵי שָׁוְא וַיַּרְא אָוֶן וְלֹא יִתְבּוֹנָן. שֶׁהֵם עוֹשִׂים יָמִים וְשָׁנִים, וְדוֹמֶה כְּמִי שֶׁלֹּא יִתְבּוֹנֵן (יִתְבּוֹנְנוּ), כִּי מַאֲרִיךְ אַפּוֹ:",1,0],[11,12,"וְאִישׁ נָבוּב. חָלוּל, בְּלֹא לֵב, אֲשֶׁר לֹא הֵבִין דַּרְכּוֹ:",1,0],[11,12,"יִלָּבֵב. יִקְנֶה לוֹ לֵב, לָשׁוּב לְבוֹרְאוֹ וּלְפַשְׁפֵּשׁ בְּמַעֲשָׂיו. אוֹ אָדָם אֲשֶׁר הָיָה כְּעַיִר פֶּרֶא ״לִמֻּד מִדְבָּר״ (ירמיה ב:כד), קַל בְּלֹא דַעַת:",2,0],[11,12,"אָדָם יִוָּלֵד. יְלַמֵּד עַצְמוֹ לִהְיוֹת אָדָם חָדָשׁ, כְּסֵדֶר בְּנֵי אָדָם, וִיכַוֵּן דַּרְכּוֹ:",3,0],[11,13,"אִם אַתָּה. הָיִיתָ מְכַוֵּן לִבְּךָ אַחַר יִסּוּרִין:",1,0],[11,13,"וּפָרַשְׂתָּ אֵלָיו כַּפֶּיךָ. בִּתְחִנָּה:",2,0],[11,14,"וְתַרְחֵק אָוֶן מִיָּדְךָ, וְאַל תַּשְׁכֵּן בְּאֹהָלֶיךָ עַוְלָה:",1,0],[11,15,"כִּי אָז. אִם אַתָּה הָיִיתָ בָּטוּחַ שֶׁתִּשָּׂא פָנֶיךָ מִמּוּם שֶׁתִּגְרֹם לְעַצְמְךָ לָשֵׂאת פָנֶיךָ מִכָּל מוּם (מִתּוֹךְ כָּךְ):",1,0],[11,15,"וְהָיִיתָ מֻצָּק. חָזָק, כְּמוֹ ״מְצוּקֵי אֶרֶץ״ (שמואל א ב:ח):",2,0],[11,16,"עָמָל תִּשְׁכָּח. וְכָל עָמָל הָיִיתָ שׁוֹכֵחַ:",1,0],[11,16,"וּכְּמַיִם עָבְרוּ. וְחָלְפוּ, כֵּן יִהְיֶה לְךָ כָּל זִכְרוֹן עָמָל:",2,0],[11,17,"וּמִצָּהֳרַיִם יָקוּם חָלֶד. יוֹתֵר מֵאוֹר צָהֳרַיִם יָקוּם לְךָ חֶלֶד – מַזָּל וּזְמַן, כְּמוֹ ״וְחֶלְדִּי כְאַיִן נֶגְדֶּךָ״ (תהילים לט:ו). דָּבָר אַחֵר: יָקוּם חָלֶד כְּמוֹ יָקוּם אוֹר חֲלוּדָה שֶׁלְּךָ, כְּלוֹמַר: שֶׁיִּהְיֶה מְקוֹם אֲפֵלָה מֵאִיר יוֹתֵר מֵאוֹר צָהֳרַיִם. זוֹ שָׁמַעְתִּי, אֲבָל הָרִאשׁוֹן לֹא נִרְאֶה (סא״א):",1,0],[11,17,"תָּעֻפָה. אֲפֵלָה שֶׁלְּךָ כַּבֹּקֶר תִּהְיֶה. עִנְיָן אַחֵר: תָּעֻפָה לְשׁוֹן ״עַפְעַפֵּי שַׁחַר״ (איוב ג:ט), שֶׁאִם הוּא לְשׁוֹן אֹפֶל, הָיָה לוֹ לוֹמַר: ׳תְּעוּפָה׳, נָקוּד בִּשְׁוָ״א, כְּמוֹ ״תְּנוּפָה״ (שמות כט:כד), ״תְּקוּמָה״ (ויקרא כו:לז), ״תְּרוּמָה״ (שמות כה:ב), ״תְּנוּמָה״ (תהלים קלב:ד):",2,0],[11,20,"וְעֵינֵי רְשָׁעִים. שׂוֹנְאֶיךָ:",1,0],[11,20,"תִּכְלֶינָה. בִּפְנוֹתָם בְּרָעָתְךָ לִרְאוֹת, וְלֹא יַשִּׂיגוּ (תַּאֲוָתָם). וְכָל ׳כִּלְיוֹן עֵינַיִם׳ שֶׁבִּלְשׁוֹן קֹדֶשׁ, זֶהוּ הַמְּצַפֶּה לִרְאוֹת וְאֵינוֹ מַשִּׂיג, וּכְמוֹ ״וְעֵינֶיךָ רֹאוֹת וְכָלוֹת אֲלֵיהֶם וְגוֹ׳״ (דברים כח:לב):",2,0],[11,20,"וּמָנוֹס. הוּא מִבְטָח:",3,0],[11,20,"וְתִקְוָתָם. מַה שֶּׁהֵם מְקַוִּים לִרְאוֹת בְּךָ, לְמַפַּח נֶפֶשׁ יִהְיֶה לָהֶם:",4,0],[12,2,"(מענה איוב:) תָּמוּת חָכְמָה. כְּשֶׁתָּמוּתוּ, תָּמוּת עִמָּכֶם כָּל חָכְמָה, כִּי כָל חָכְמָה בָּכֶם. אֲבָל:",1,0],[12,3,"גַּם לִי לֵבָב כְּמוֹכֶם. וְאֶת מִי אֵין כְּמוֹ אֵלֶּה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שַׁלִּיט לַעֲשׂוֹת רְצוֹנוֹ וּלְהַאֲרִיךְ שַׁלְוַת רְשָׁעִים? אֵינְכֶם אֶלָּא כִּמְשַׂחֲקִים בִּי, וַאֲנִי הוּא (הַהוֹוֶה) שְׂחוֹק לְרֵעֵהוּ:",1,0],[12,4,"אֶהְיֶה קוֹרֵא לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וַיַּעֲנֵהוּ מִצַּעַר הַקְנָטַתְכֶם. וּמָה יַעֲנֵהוּ? לָתֵת לוֹ שְׂחוֹק לְצַדִּיק וְתָמִים. שָׁלֵם:",1,0],[12,4,"שְׂחוֹק צַדִּיק תָּמִים. הִיא הָעֲנִיָּה אֲשֶׁר יַעֲנֵהוּ. יָדַעְתִּי אֲנִי כַּאֲשֶׁר אֲמַרְתֶּם, כִּי:",2,0],[12,5,"לַפִּיד בּוּז. אֵשׁ שֶׁל גֵּיהִנֹּם עוֹמֵד לְמִי שֶׁשַּׁאֲנָן בְּעַשְׁתּוּתוֹ, לוֹמַר: ״שָׁלוֹם יִהְיֶה לִי״ (דברים כט:יח):",1,0],[12,5,"נָכוֹן. מְזֻמָּן הוּא הָעַשְׁתּוֹת שַׁאֲנָן, לִהְיוֹת בְּמוֹעֲדֵי רֶגֶל – שֶׁרַגְלָם מוֹעֶדֶת:",2,0],[12,6,"יִשְׁלָיוּ. יָדַעְתִּי אֲנִי, כִּי יְמֵי יִשְׁלָיוּ אֹהָלִים לִבְנֵי קֵדָר הַשּׁוֹכְנִים בָּאֹהָלִים הַמִּדְבָּרָה, וְהֵם שׁוֹדְדִים, שֶׁנֶּאֱמַר ״פֶּרֶא אָדָם יָדוֹ בַכֹּל״ (בראשית טז:יב):",1,0],[12,6,"וּבַטֻּחוֹת. שְׁלֵמוּת יֵשׁ לְמַרְגִּיזֵי אֵל, לְכָל אֲשֶׁר הֵבִיא לוֹ הַצּוּר הַשָּׁלוֹם בְּיָדוֹ, אִם טוֹב וְאִם רַע:",2,0],[12,11,"הֲלֹא אֹזֶן מִלִּין תִּבְחָן. וְלָמָּה לֹא יָדְעוּ זֹאת הַשּׁוֹמְעִים פָּעֳלוֹ, כַּאֲשֶׁר הַחֵךְ יִטְעַם לֶאֱכֹל?",1,0],[12,12,"בִּישִׁישִׁים חָכְמָה וְגוֹ׳. לָדַעַת כִּי עִמּוֹ חָכְמָה וְגוֹ׳:",1,0],[12,15,"וִישַׁלְּחֵם וְיַהַפְכוּ אָרֶץ. בִּשְׁלִיחוּתוֹ, כַּאֲשֶׁר עָשָׂה לְדוֹר אֱנוֹשׁ, שֶׁהֵצִיף שְׁלִישׁוֹ שֶׁל עוֹלָם (מכילתא דרבי ישמעאל יתרו ו):",1,0],[12,16,"לוֹ שׁוֹגֵג. הָאָדָם הַשּׁוֹגֵג:",1,0],[12,16,"וּמַשְׁגֶּה. שָׂטָן הַמַּשְׁגֵּהוּ:",2,0],[12,17,"שׁוֹלָל. שֵׁם דָּבָר הוּא שְׁטוּת, מוֹלִיכָם בִּשְׁטוּת כְּשֶׁהוּא רוֹצֶה לְעַרְבֵּב וּלְבַלֵּעַ חָכְמָתָם, כְּמוֹ ״וְסָר מֵרָע מִשְׁתּוֹלֵל״ (ישעיהו נט:טו), ״אֶשְׁתּוֹלְלוּ אַבִּירֵי לֵב״ (תהלים עו:ו). וְתָ״ו אֲשֶׁר בְּ״מִשְׁתּוֹלֵל״ וְ״אֶשְׁתּוֹלְלוּ״ – כֵּן דֶּרֶךְ לְשׁוֹן עִבְרִית בְּתֵיבָה שֶׁיְּסוֹדָהּ שִׁי״ן אוֹ סָמֶ״ךְ, וְהוּא בָּא לְדַבֵּר בִּלְשׁוֹן נַעֲשָׂה וְנִפְעַל אוֹ מִתְפַּעֵל, נוֹתֵן תָּ״ו אַחַר אוֹת רִאשׁוֹנָה שֶׁל יְסוֹד, כְּמוֹ ״וְיִשְׁתַּכְּחוּ בָעִיר״ (קהלת ח:י), ״וְיִשְׁתַּמֵּר חֻקּוֹת עָמְרִי״ (מיכה ו:טז), ״מִסְתּוֹלֵל בְּעַמִּי״ (שמות ט:יז), ״וְיִסְתַּבֵּל הֶחָגָב״ (קהלת יב:ה):",1,0],[12,17,"יְהוֹלֵל. יְשׁוּטֶה, לְשׁוֹן ״הוֹלְלוּת וְסִכְלוּת״ (קהלת ב:יב):",2,0],[12,18,"מוּסַר מְלָכִים פִּתֵּחַ. לְהָסִיר מוּסַר סִבְלָם מֵעַל אֲחֵרִים, וּמַעֲבִירָם מִמְּלוּכָה:",1,0],[12,18,"וַיֶּאְסֹר אֵזוֹר בְּמָתְנֵיהֶם. בִּתְחִלָּתָם, כְּשֶׁהוּא חָפֵץ בָּהֶם, חוֹגֵר חֲלָצֵיהֶם וּמְזָרְזָם כֹּחַ לַמְּלוּכָה:",2,0],[12,19,"כֹּהֲנִים. שָׂרִים, כְּמוֹ ״כֹּהֵן מִדְיָן״ (שמות ג:א), ״כֹּהֵן אוֹן״ (בראשית מא:מה):",1,0],[12,20,"לְנֶאֱמָנִים. אַף לְנֶאֱמָנִים, כִּי פְּעָמִים שְׂפָתָיו נִבְלָלִים לְדַבֵּר סָרָה, כְּגוֹן אַבְרָהָם: ״וְהֶאֱמִין בַּה׳״ (בראשית טו:ו), וְסוֹף נִכְשַׁל: ״בַּמָּה אֵדַע״ (בראשית טו:ח):",1,0],[12,21,"וּמְזִיחַ אֲפִיקִים רִפָּה. וַחֲגוֹר הַחֲזָקִים מְרַפֶּה, וּמְפַתֵּחַ חֲגוֹרָם לְהָתִישׁ כֹּחָם, כְּמוֹ (תהלים קט:יט) ״וּלְמֵזַח תָּמִיד יַחְגְּרֶהָ״:",1,0],[12,21,"אֲפִיקִים. חֲזָקִים, כְּמוֹ ״אֲפִיקֵי נְחוּשָׁה״ (איוב מ:יח); ״אֲפִיקֵי מָגִנִּים״ (איוב מא:ז):",2,0],[12,23,"מַשְׂגִּיא לַגּוֹיִם וַיְאַבְּדֵם. יֵשׁ אוֹמְרִים: כַּאֲשֶׁר עָשָׂה לְמִצְרַיִם, בְּהַשִּׂיגָם אֶת יִשְׂרָאֵל ״לִפְנֵי בַּעַל צְפוֹן״ (שמות יד:ט), שָׁגוּ וְאָמְרוּ: תֵּדְעוּ, שֶׁהִסְכִּים עִמָּנוּ לְטַבְּעָם בַּיָּם, כַּאֲשֶׁר גָּזַרְנוּ ״כָּל הַבֵּן הַיִּלּוֹד הַיְאֹרָה תַּשְׁלִיכֻהוּ״ (שמות א:כב); וְקָשָׁה יִרְאָתוֹ שֶׁל בַּעַל צְפוֹן, שֶׁלֹּא נַעֲשׂוּ בּוֹ שְׁפָטִים כְּכָל אֱלֹהֵי מִצְרַיִם. וְגָרַם הַמָּקוֹם לְהַשְׁגּוֹתָם, כְּדֵי לְטַבְּעָם. וְזֶה הַלָּשׁוֹן אֵינוֹ עִקָּר; דְּאִם כֵּן הָיָה לוֹ לוֹמַר בְּצַד יָמִין ׳מַשְׁגִּיא׳, כְּמוֹ ״שׁוֹגֶה״ (משלי כ:א). אֲבָל זֶה עִקָּר ׳מַגְדִּיל׳, לְשׁוֹן ״שַׂגִּיא כֹחַ״ (איוב לז:כג): מַשְׂגִּיא אֶת הַגּוֹיִם וּמַצְלִיחָם, וְלִבָּם מִתְגָּאֶה בְּהַצְלָחָתָם, וְהוּא הָיָה אָבְדָן שֶׁלָּהֶן – מַה שֶּׁהִצְלִיחוּ:",1,0],[12,23,"שׁוֹטֵחַ. מַרְבֶּה אוֹתָם, לְהַשְׁטִיחַ בָּאָרֶץ וּלְכַסּוֹתָם:",2,0],[12,24,"בְּתֹהוּ לֹא דָרֶךְ. בְּתֹהוּ שֶׁאֵינוֹ דֶרֶךְ:",1,0],[13,3,"אוּלָם אֲנִי. אֵינִי מְבַקֵּשׁ אֶלָּא לְדַבֵּר אֵלָיו, וּלְהִתְוַכֵּחַ עִמּוֹ אֶחְפָּץ:",1,0],[13,4,"טוֹפְלֵי שָׁקֶר. מְחַבְּרֵי דִּבְרֵי שֶׁקֶר:",1,0],[13,4,"רוֹפְאֵי אֱלִיל כֻּלְּכֶם. כָּל אֱלִיל שֶׁבַּמִּקְרָא לְשׁוֹן אַל. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (חולין קכא.): זֶה גִּיד הַצַּוָּאר, שֶׁאֵין לוֹ רְפוּאָה, וּשְׁמוֹ אֱלָל:",2,0],[13,6,"וְרִיבוֹת. הוֹכָחוֹת:",1,0],[13,7,"הֲלָאֵל תְּדַבְּרוּ עַוְלָה. אַחֲרֵי אֲשֶׁר תַּחַת אֵל בָּאתֶם לָרִיב, לֹא טוֹב שֶׁתְּדַבְּרוּ עַוְלָה:",1,0],[13,7,"וְלוֹ תְּדַבְּרוּ רְמִיָּה. בַּעֲבוּרוֹ תְּדַבְּרוּ רְמִיָּה, כְּמוֹ ״הֵן אֲנִי כְפִיךָ לָאֵל״ (איוב לג:ו), וּכְמוֹ ״אֶל הָאָרֶץ אֲשֶׁר דִּבֶּר לָהֶם״ (דברים ט:כח) – לְצָרְכָם, וּכְמוֹ ״יִלָּחֵם לָכֶם״ (שמות יד:יד); ״הַאַתֶּם תְּרִיבוּן לַבַּעַל״ (שופטים ו:לא). הֻקְשָׁה בְּעֵינַי לְדַמּוֹתוֹ כָּאן, וְהוּא דֻּגְמַת ״בְּיַד מֹשֶׁה לוֹ״ – עַל קֹרַח (במדבר יז:ה):",2,0],[13,8,"הֲפָנָיו תִּשָּׂאוּן. וְכִי לְהַחֲנִיף לוֹ בִּשְׂאֵת פָּנִים בָּאתֶם?",1,0],[13,8,"אִם לָאֵל. בִּשְׁבִילוֹ תִּתְוַוּכְחוּן עַל רְמִיָּה?",2,0],[13,9,"הֲטוֹב כִּי יַחְקֹר אֶתְכֶם. וְתִמָּצְאוּ שְׁקָרִים?",1,0],[13,9,"אִם כְּהָתֵל בֶּאֱנוֹשׁ תְּהָתֵלּוּ בוֹ. לוֹמַר: לִכְבוֹדְךָ עָשִׂינוּ עַצְמֵינוּ שְׁקָרִים?",2,0],[13,10,"הוֹכֵחַ יוֹכִיחַ אֶתְכֶם. הֲלֹא יוֹדִיעַ לָכֶם דִּבַּתְכֶם?",1,0],[13,10,"אִם בַּסֵּתֶר. וְכִי בַּסֵּתֶר שֶׁתַּעַמְדוּ לְפָנָיו בַּדִּין, פָּנִים תִּשָּׂאוּ לוֹ, לוֹמַר: שָׁם נָשָׂאנוּ פָנֶיךָ?!",2,0],[13,11,"הֲלֹא שְׂאֵתוֹ. גָּבְהוֹ וְאֵימָתוֹ תְּבַעֵת אֶתְכֶם. וְיֵשׁ אוֹמְרִים: שְׂאֵתוֹ שְׂרֵפַת אֵשׁוֹ, כְּמוֹ ״וַיִּשָּׂאֵם דָּוִד וַאֲנָשָׁיו״ (שמואל ב ה:כא), וּכְמוֹ ״מַשְׂאַת הָעִיר״ (שופטים כ:לח):",1,0],[13,12,"זִכְרֹנֵיכֶם. נִמְשַׁל מִשְׁלֵי אֵפֶר זִכְרֹנֵיכֶם נִמְשַׁל לְאֵפֶר, אַתֶּם סְבוּרִים לְהִתְמַשֵּׁל לְאַבְרָהָם שֶׁאָמַר ״אָנֹכִי עָפָר וָאֵפֶר״ (בראשית יח:כז):",1,0],[13,12,"לְגַבֵּי חֹמֶר. שָׁוֶה לֶעָפָר יְהִי גַבֵּיכֶם אֶצְלוֹ. גַּבֵּיכֶם. גֹּבַהּ שֶׁלָּכֶם, כְּמוֹ ״וַתִּבְנִי לָךְ גָּב״ (יחזקאל טז:כד):",2,0],[13,13,"וְיַעֲבֹר עָלַי מָה. מַה שֶּׁיַּעֲבֹר עָלַי בַּעֲוֹן צַעֲקָתִי יַעֲבֹר עָלַי, וְאַל תָּחוּשׁוּ עַל מָה אֲנִי צָרִיךְ לָשֵׂאת וְלֶאֱחֹז:",1,0],[13,14,"בְּשָׂרִי בְשִׁנָּי. לְיַסְּרֵנִי וּלְכוֹפֵנִי אֶל הַשְּׁתִיקָה:",1,0],[13,14,"וְנַפְשִׁי אָשִׂים בְּכַפִּי. לְהַגִּישׁ נַפְשִׁי לַמָּוֶת בְּיִסּוּרֵי שְׁתִיקָה:",2,0],[13,15,"הֵן יִקְטְלֵנִי. הֲלֹא אִם יִקְטְלֵנִי, אֵינִי נִפְרָד מִמֶּנּוּ, וְתָמִיד לוֹ אֲיַיחֵל; עַל כֵּן אֵין מֶרֶד וָפֶשַׁע בִּדְבָרַי:",1,0],[13,15,"אַךְ דְּרָכַי. וּמִדּוֹתַי שֶׁנָּהַגְתִּי בָּהֶם:",2,0],[13,15,"אֶל פָּנָיו אוֹכִיחַ. לָדַעַת מַה יַּפְשִׁיעֵנִי:",3,0],[13,16,"גַּם הוּא. וְכַאֲשֶׁר אֲנִי שָׁלֵם עִמּוֹ, כֵּן הוּא גַּם הוּא לִי לִישׁוּעָה. וְלֹא תִמְצְאוּ אַתֶּם חֵן בְּעֵינָיו:",1,0],[13,16,"כִּי לֹא לְפָנָיו חָנֵף יָבוֹא. וְזֶה שֶׁנֶּאֱמַר לָהֶם: ״כִּי לֹא דִבַּרְתֶּם אֵלַי נְכוֹנָה״ (איוב מב:ז):",2,0],[13,18,"עָרַכְתִּי מִשְׁפָּט. הוֹכָחַת דְּבָרִים; סִדַּרְתִּי טַעֲנוֹתַי בְּלִבִּי, מַה לְהָשִׁיב:",1,0],[13,19,"אַחֲרִישׁ וְאֶגְוָע. אִם לֹא אָרִיב, אַחֲרִישׁ וְאֶגְוָע:",1,0],[13,20,"אַךְ שְׁתַּיִם אַל תַּעַשׂ עִמָּדִי. דִּין שֶׁל מַעְלָה וְדִין שֶׁל מַטָּה. וְאִם בְּאַחַת תָּבוֹא לְמִשְׁפָּט, אָז מִפָּנֶיךָ לֹא אֶסָּתֵר. אִם בְּדִין שֶׁל מַעְלָה, אֲנִי אוֹמֵר: חָטָאתִי, ״מְכַסֶּה פְשָׁעָיו לֹא יַצְלִיחַ וְגוֹ׳״ (משלי כח:יג); וְאִם בְּדִין שֶׁל מַטָּה, אַף אָנֹכִי לֹא אוֹדֶה: כִּסּוּי חֲטָאָה לָשׁוֹן שֶׁקֶר (תהלים לב:א; קט:ב) (סא״א):",1,0],[13,21,"כַּפְּךָ מֵעָלַי הַרְחַק. כְּפִיָּתְךָ, כְּמוֹ שֶׁהֵשִׁיבוֹ אֱלִיהוּא ״וְאַכְפִּי עָלֶיךָ לֹא יִכְבָּד״ (איוב לג:ז). וְיֵשׁ פּוֹתְרִים כַּפְּךָ – כְּלוֹמַר: יָדְךָ, וְקָשֶׁה לִי לְאוֹמְרוֹ, כִּי לֹא מָצִינוּ ׳כַּף׳ לְרָעָה, כִּי אִם לְהָגֵן, כְּמוֹ ״וְשַׂכֹּתִי כַפִּי״ (שמות לג:כב):",1,0],[13,24,"פָּנֶיךָ תַסְתִּיר. לִרְאוֹת אֶת דַּרְכֵי יָשְׁרִי:",1,0],[13,25,"תַּעֲרוֹץ. תְּפַחִיד:",1,0],[13,26,"מְרוֹרוֹת. סַרְבָנִיּוֹת אֲשֶׁר מָרִיתִי פִּיךָ אַתָּה כּוֹתֵב, וְלֹא הַטּוֹבוֹת שֶׁפָּעַלְתִּי:",1,0],[13,27,"בַּסַּד. בִּלְשׁוֹן אֲרַמִּי ״סַדְנָא בְּסַדְנֵיהּ יָתִיב״ (פסחים כח.) – עֵץ גָּדוֹל שֶׁנּוֹתְנִין בּוֹ רַגְלֵי הָאֲסוּרִים, וּבִלְשׁוֹן יְוָנִי ״אַשְׁתּוֹ״ק״:",1,0],[13,27,"תִּתְחַקֶּה. אַתָּה עַצְמְךָ מִתְחַקֶּה עַל פְּסִיעוֹתַי: כֵּן פָּסַע זֶה, וְכֹה פָּעַל. וּכְמוֹ ״מֵחֵיק הָאָרֶץ״ (יחזקאל מג:יד); ״וְחֵיק הָאַמָּה״ (יחזקאל מג:יג). זֶה הַיְסוֹד אפיקיו״ל בְּלַעַ״ז; ״הֵן עַל כַּפַּיִם חַקֹּתִיךְ״ (ישעיהו מט:טז):",2,0],[13,28,"וְהוּא כְּרָקָב יִבְלֶה. הַגּוּף הַזֶּה אֲשֶׁר תִּרְדֹּף, יֵרָקֵב וְיִבְלֶה, וְאֵין כְּבוֹדְךָ בִּרְדִיפָתְךָ:",1,0],[14,3,"אַף עַל זֶה. הַהֶבֶל וְהַנִּרְקָב:",1,0],[14,3,"פָּקַחְתָּ עֵינֶיךָ. לְדַקְדֵּק בַּחֲטָאָיו:",2,0],[14,3,"וְאוֹתִי. אַתָּה מֵבִיא בְמִשְׁפָּט עַל עֲווֹנוֹתַי:",3,0],[14,4,"מִי יִתֵּן טָהוֹר. מִדְּבַר טִפָּה סְרוּחָה וְשִׁכְבַת זֶרַע שֶׁהוּא טָמֵא. לֹא אֶחָד בָּהֶם טָהוֹר, שֶׁלֹּא יֶחֱטָא:",1,0],[14,5,"אִם חֲרוּצִים יָמָיו. אִם גְּמוּל זֶה הוּא מִשְׁתַּלֵּם, שֶׁחֲרוּצִים וּקְצוּבִים לְיוֹם קָבוּעַ וּמְיֻעָד לְמִיתָה:",1,0],[14,5,"וּמִסְפַּר חֳדָשָׁיו אִתָּךְ. קְצוּבִים, וְחֹק זֶה עָשִׂיתָ לוֹ וְלֹא יִתְקַיֵּם עוֹד יוֹתֵר בָּעוֹלָם – דַּי לְךָ בַּתַּשְׁלוּמִין הַלָּלוּ:",2,0],[14,6,"שְׁעֵה מֵעָלָיו. בְּאוֹתוֹ מִעוּט חָרַץ הַיָּמִים, וְיֶחְדַּל לוֹ מִמַּכְאוֹב, עַד יִרְצֶה בְּזִקְנוּתוֹ וְתַשּׁוּת כֹּחוֹ אֶת יוֹם מוֹתוֹ כְּשָׂכִיר הָרוֹצֶה לְהַשְׁלָמַת עֲבוֹדַת יוֹמוֹ. כִּי עֲבִירָתוֹ מִן הָעוֹלָם חֲלוּטָה וְנִצְמֶתֶת מִשְּׁאָר כָּל הָעוֹבְרִים:",1,0],[14,7,"כִּי יֵשׁ לָעֵץ תִּקְוָה. שֶׁיַּחֲלֹף:",1,0],[14,7,"וְיֹנַקְתּוֹ. אֲשֶׁר מִגִּזְעוֹ לֹא תֶחְדָּל מִהְיוֹת עָנָף:",2,0],[14,9,"וְעָשָׂה קָצִיר. הִיא יוֹנֶקֶת, כְּמוֹ ״תְּשַׁלַּח קְצִירֶיהָ עַד יָם״ (תהילים פ:יב):",1,0],[14,9,"נָטַע. שֵׁם דָּבָר הוּא, וְטַעַם הֲבָרָתוֹ לְמַעְלָה בַּנּוּ״ן, וְנִנְקַד כֻּלּוֹ קָמַץ מִפְּנֵי שֶׁהוּא סוֹף פָּסוּק. אַף מִגִּזְרַת ״נָטַע״ (ישעיה מד:יד) הוּא:",2,0],[14,11,"אָזְלוּ מַיִם מִנִּי יָם. מִמָּקוֹם שֶׁנָּהָר בָּא וְיוֹצֵא מִמְּקוֹרוֹ, הַבָּא מֵאֵלָיו מִן הַיָּם:",1,0],[14,11,"וְהַנָּהָר. הַבָּא מִשָּׁם יֶחֱרַב וְיִיבַשׁ לְעוֹלָם, כֵּן אִישׁ שָׁכַב וְלֹא יָקוּם:",2,0],[14,14,"כָּל־יְמֵי צְבָאִי אֲיַחֵל. לִתְחִיָּה:",1,0],[14,15,"תִּקְרָא. תְּחִנָּה הִיא: קְרָא אֵלַי וְאָנֹכִי אֶעֱנֶךָּ לְהוֹכִיחַ דְּבָרַי:",1,0],[14,15,"תִּכְסֹף. תַּחְמֹד:",2,0],[14,16,"כִּי עַתָּה. אַתָּה מֵרֵיעַ לִי:",1,0],[14,16,"צְעָדַי. אַתָּה סוֹפֵר:",2,0],[14,16,"לֹא תִשְׁמוֹר. אֵינְךָ מַמְתִּין עַל חַטָּאתִי מִלְּהִפָּרַע, כְּמוֹ ״וְאָבִיו שָׁמַר אֶת הַדָּבָר״ (בראשית לז:יא) – הִמְתִּין שֶׁתִּתְקַיֵּם. וּבִלְשׁוֹן מִשְׁנָה (סנהדרין סג:): לֹא יֹאמַר אָדָם לַחֲבֵרוֹ שְׁמוֹר לִי בְּצַד עֲבוֹדַת כּוֹכָבִים פְּלוֹנִית – לְשׁוֹן ״הַמְתֵּן״:",3,0],[14,17,"חָתוּם בִּצְרוֹר. חָתוּם וּמְשֻׁמָּר בִּצְרוֹר בֶּגֶד, כְּכֶסֶף וּמַרְגָּלִיּוֹת, שֶׁלֹּא תֹּאבַד:",1,0],[14,17,"וַתִּטְפֹּל עַל עֲוֺנִי. נִתְחַבַּרְתָּ עַל עֲוֺנִי:",2,0],[14,18,"וְאוּלָם הַר נוֹפֵל. הַר הַנּוֹפֵל גָּבְהוֹ יִבּוֹל וְיֵעָשֶׂה עָפָר, וּתְהֵא לוֹ תִּקְוָה לֵיהָנוֹת מִמֶּנּוּ. וְצוּר אֲשֶׁר נֶעְתַּק מִמְּקוֹמוֹ גַּם הוּא, יִבּוֹל לְשׁוֹן תְּבוּאָה. אוֹ:",1,0],[14,19,"אֲבָנִים. אֲשֶׁר שָׁחֲקוּ מַיִם בְּעָבְרָם עֲלֵיהֶם תָּמִיד:",1,0],[14,19,"תִּשְׁטֹף. הִשְׁטִיפוּ סְפִיחֶיהָ שֶׁל אֶבֶן לֵיהָפֵךְ לְעָפָר וְלִצְמֹחַ בּוֹ דָּבָר, כַּאֲשֶׁר יִצְמַח סְפִיחַ הַקָּצִיר שֶׁעָבַר – כֵּן יִתְהַפֵּךְ עָפָר זֶה סְפִיחֶיהָ לְאֶבֶן:",2,0],[14,19,"וְתִקְוַת אֱנוֹשׁ. אֵינָהּ כֵּן, אֲשֶׁר מִשֶּׁיָּמוּת – אָבְדָה סֶלָה:",3,0],[14,20,"תִּתְקְפֵהוּ. תֶּחֱזַק מִמֶּנּוּ וְתֶאֱנְסֵהוּ בְּתָקְפְּךָ, וַיַּהֲלֹךְ מִן הָעוֹלָם:",1,0],[14,21,"יִכְבְּדוּ. יִהְיוּ כְבֵדִים בְּכֶסֶף וּבְזָהָב, וְהוּא לֹא יֵדָע:",1,0],[14,21,"וְיִצְעֲרוּ. וְיִמְעֲטוּ מִכָּל טוֹב, וְהוּא לֹא יָבִין:",2,0],[14,22,"אַךְ בְּשָׂרוֹ עָלָיו יִכְאָב. קָשָׁה רִמָּה לַמֵּת כְּמַחַט בַּבָּשָׂר הֶחָי (שבת יג:):",1,0],[15,2,"(מענה אליפז): הֶחָכָם יַעֲנֶה דַעַת רוּחַ. תָּמוּהַּ הוּא, וְכִי מִי שֶׁהוּא חָכָם יַעֲנֶה וְיָרִים קוֹל בְּדַעַת שֶׁל רוּחַ וְהֶבֶל?",1,0],[15,3,"הוֹכֵחַ בְּדָבָר לֹא יִסְכּוֹן. לְהִתְוַכֵּחַ בְּדָבָר שֶׁלֹּא תְּהֵא לוֹ מֵהֶן הֲנָאָה, כְּמוֹ ״וַתְּהִי לוֹ סֹכֶנֶת״ (מלכים א א:ב), וּכְמוֹ ״יִסָּכֵן בָּם״ (קהלת י:ט) – יֵהָנֶה בָּם:",1,0],[15,4,"אַף אַתָּה. כָּל שֶׁכֵּן אַתָּה, שֶׁחָכָם מְאֹד, אַתָּה תָּפֵר יִרְאָה בְּמַרְבִּית דְּבָרֶיךָ:",1,0],[15,4,"וְתִגְרַע שִׂיחָה. כְּמוֹ ״כִּי יְגָרַע נִטְפֵי מָיִם״ (איוב לו:כז), וּכְמוֹ ״וְתִגְרַע אֵלֶיךָ חָכְמָה״ (איוב טו:ח):",2,0],[15,5,"כִּי יְאַלֵּף עֲוֺנְךָ. יִצְרְךָ הָרָע אֶת פִּיךָ לְדַבֵּר כַּדְּבָרִים הָאֵלֶּה, וְהָיָה לְךָ לִבְחֹר לְשׁוֹן עֲרוּמִים:",1,0],[15,6,"יַרְשִׁיעֲךָ פִיךָ וְלֹא אָנִי. כְּלוֹמַר: הֲשִׁיבֵנִי עַל שְׁאֵלָתִי, וְנִמְצָא פִיךָ הִרְשִׁיעֲךָ; כִּי טוֹב לִי שֶׁיַּרְשִׁיעֲךָ פִיךָ וְלֹא אָנִי. וְזוֹ הִיא שְׁאֵלָתִי:",1,0],[15,7,"הֲרִאשׁוֹן אָדָם תִּוָּלֵד. הֲבְטֶרֶם אָדָם תִּוָּלֵד? הֵ״א הַזֹּאת מְשַׁמֶּשֶׁת לְשׁוֹן תֵּימַהּ, לְפִיכָךְ נְקוּדָה בַּחֲטַף פַּתָּח. וּמְלִיצָתוֹ: הֲרִאשׁוֹן לְאָדָם הַנּוֹצָר מֵאֲדָמָה נוֹלַדְתָּ, שֶׁיָּדַעְתָּ לְקַיֵּם כָּל חָכְמַת מִצְווֹת הַבּוֹרֵא?!",1,0],[15,8,"וְתִגְרַע. וְתַרְבֶּה מִלְמַעְלָה לְמַטָּה לָרֶדֶת עָלֶיךָ:",1,0],[15,10,"כַּבִּיר. מְרֻבֶּה יָמִים מֵאָבִיךָ:",1,0],[15,11,"הַמְעַט מִמְּךָ תַּנְחוּמוֹת אֵל. אֲשֶׁר הֵיטִיב לְךָ הַצּוּר עַד עַתָּה יָמִים רַבִּים, וּדְבָרוֹ הַטּוֹב אֲשֶׁר לָאַט עִמָּךְ בְּלַאט וְנַחַת דִּשְּׁנוֹ:",1,0],[15,11,"לָאַט. הַנָּעִים. וּלְשׁוֹן פָּעַל הוּא, וְלֹא שֵׁם דָּבָר; וְלָכֵן הוּא נָקוּד חֶצְיוֹ קָמַץ וְחֶצְיוֹ פַּתַּח:",2,0],[15,12,"יִקָּחֲךָ. יְלַמֶּדְךָ, כְּמוֹ ״יַעֲרֹף כַּמָּטָר לִקְחִי״ (דברים לב:ב):",1,0],[15,12,"יִרְזְמוּן. כְּמוֹ יִרְמְזוּן, כְּמוֹ שִׂמְלָה שַׂלְמָה (שמות כב:ח, כו):",2,0],[15,14,"מָה אֱנוֹשׁ כִּי יִזְכֶּה. מַה כֹּחוֹ, שֶׁיּוּכַל לִהְיוֹת זַכַּאי נֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[15,15,"וְשָׁמַיִם. צְבָא הַשָּׁמַיִם:",1,0],[15,15,"זַכּוּ. יִצְהָרוּ. כָּל לְשׁוֹן זַךְ הוּא צֹהַר:",2,0],[15,16,"אַף. כָּל שֶׁכֵּן:",1,0],[15,16,"וְנֶאֱלָח. נִתְעָב וּמְעֹרְבָּב, וְכֵן ״כֻּלּוֹ סָג יַחְדָּו נֶאֱלָחוּ״ (תהילים נג:ד):",2,0],[15,18,"אֲשֶׁר חֲכָמִים יַגִּידוּ. וְיִתְוַדּוּ פִּשְׁעָם וְלֹא כִחֲדוּ עֲוֹנָם מֵאֲבוֹתָם. זֶהוּ אֲשֶׁר רָאִיתִי, וְהִנְנִי אֲסַפֵּר לְךָ. וְהֵיכָן רָאִיתִי? יְהוּדָה הוֹדָה וְלֹא בוֹשׁ בְּמַעֲשֵׂה תָמָר (בראשית לח), רְאוּבֵן הוֹדָה וְלֹא בוֹשׁ בְּמַעֲשֵׂה בִּלְהָה (בראשית לה:כב). וּמֶה הָיָה שְׂכָרָם?",1,0],[15,19,"לָהֶם לְבַדָּם נִתְּנָה הָאָרֶץ. בִּשְׂכַר זֶה זָכָה יְהוּדָה לְמַלְכוּת נֶצַח, וְנָטְלוּ שְׁנֵיהֶם מִן הַנַּחֲלָה חֶלְקָם, וְלֹא גֹרְשׁוּ מִן נַחֲלָתָם בַּעֲוֹנָם, מֵאַחַר שֶׁהוֹדוּ:",1,0],[15,19,"וְלֹא עָבַר זָר בְּתוֹכָם. כְּשֶׁבָּא מֹשֶׁה לְבָרְכָם שֶׁנֶּאֱמַר (דברים לג:ו-ז) ״יְחִי רְאוּבֵן וְאַל יָמֹת וְזֹאת לִיהוּדָה״. דָּבָר אַחֵר וְלֹא עָבַר זָר בְּתוֹכָם בְּנַחֲלָה שֶׁל עָתִיד לָבֹא הַחֲלוּקָה בְּסֵפֶר (יחזקאל מח):",2,0],[15,20,"כָּל יְמֵי. הָרָשָׁע שֶׁאֵינוֹ שָׁב מֵחֶטְאוֹ וְאֵינוֹ מוֹדֶה פְּשָׁעָיו כָּל יָמָיו:",1,0],[15,20,"הוּא מִתְחוֹלֵל. וּמִתְאוֹנֵן עַל הַבְטָחָתוֹ, שֶׁיְּשַׁלֵּם רָעָתוֹ אֲשֶׁר פָּעַל. כָּל מִסְפַּר שָׁנִים אֲשֶׁר נִצְפְּנוּ לֶעָרִיץ. הוּא מִתְחוֹלֵל:",2,0],[15,20,"מִתְחוֹלֵל. לְשׁוֹן אֲנִינוּת, וְלֹא שָׁמַעְתִּי:",3,0],[15,21,"קוֹל פְּחָדִים בְּאָזְנָיו. לֵאמֹר: הִגִּיעַ עֵת תַּשְׁלוּמֵי:",1,0],[15,21,"בַּשָּׁלוֹם. וּכְשֶׁהוּא שָׁרוּי בְּשָׁלוֹם, אָז הַשּׁוֹדֵד יְבוֹאֶנּוּ:",2,0],[15,22,"וְצָפוּי הוּא אֱלֵי חָרֶב. וְעָתִיד הוּא אֱלֵי חֶרֶב וְעֹנִי, לָנוּד לַלֶּחֶם אַיֵּה יִמְצָאֶנּוּ:",1,0],[15,23,"נוֹדֵד הוּא. כְּלוֹמַר: מֻבְטָח הוּא לָנוּד:",1,0],[15,23,"יָדַע. לוֹ בֶּאֱמֶת:",2,0],[15,23,"כִּי נָכוֹן. וּמְזֻמָּן לָבוֹא בְּיָדוֹ כְּלוֹמַר: אֵלָיו וְעִמּוֹ יוֹם חֹשֶׁךְ. כְּמוֹ ״מִן הַבָּא בְיָדוֹ״ (בראשית לב:יד):",3,0],[15,24,"תִּתְקְפֵהוּ. תֶּחֱזַק הַמְּצוּקָה מִמֶּנּוּ וְתֶאֱנְסֵהוּ:",1,0],[15,24,"כְּמֶלֶךְ עָתִיד לַכִּידוֹר. לֹא מָצָאתִי דִּמְיוֹנוֹ. וְיֵשׁ לְפוֹתְרוֹ בָּאוֹתִיּוֹת הַמִּתְחַלְּפוֹת רֵי״שׁ בְּדָלֵי״ת כְּמוֹ אַשְׁכְּנַז וְרִיפַת שֶׁבַּתּוֹרָה (בראשית י:ג) – אַשְׁכְּנַז וְדִיפַת (דברי הימים א א:ו); וְכֵן כִּתִּים וְדוֹדָנִים (בראשית י:ד). אַף כָּאן לַכִּידוֹר – כְּמוֹ לַכִּידוֹד, כְּאוֹתוֹ הַמֶּלֶךְ שֶׁהוּא עָתִיד לִיקוֹד בָּאֵשׁ שֶׁל גֵּיהִנֹּם; וְהוּא סַנְחֵרִיב, שֶׁנִּתְנַבֵּא הַנָּבִיא עָלָיו ״כִּי עָרוּךְ מֵאֶתְמוּל תָּפְתֶּה גַּם הִיא לַמֶּלֶךְ הוּכָן״ (ישעיהו ל:לג) – לִשְׂרֹף חֵילָיו יְקַד יְקוֹד (ישעיהו י:טז); וְדוֹמֶה לוֹ ״כִּידוּדֵי אֵשׁ יִתְמַלָּטוּ״ (איוב מא:יא) – אִם (ס״א אֵשׁ) ״לַפִּידִים״ (איוב מא:יא), אִם לֶהָבוֹת (איוב מא:יג):",2,0],[15,26,"יָרוּץ אֵלָיו. הָיָה רָץ אֶל הַבּוֹרֵא בְּגֹבַהּ וּזְקִיפַת צַוָּאר לְהַכְעִיסוֹ:",1,0],[15,26,"בַּעֲבִי גַּבֵּי מָגִנָּיו. בְּחָזְקַת כֹּחוֹ, גַּבֵּי לְשׁוֹן גּוֹבַהּ, כְּמוֹ ״וַתִּבְנִי לָךְ גָּב״ (יחזקאל טז:כד):",2,0],[15,27,"פִּימָה עֲלֵי כָסֶל. עָשָׂה פֶה עַל חֲלָצַיִם, שֶׁחֶלְבּוֹ וְעֹבִי שׁוּמָנוֹ כָּפוּל עַל כְּסָלָיו, וְנִרְאִין כְּמִין פֶּה:",1,0],[15,27,"פִּימָה. מִגִּזְרַת ״וְהָיְתָה הַפְּצִירָה פִים״ (שמואל א יג:כא), זוֹ הִיא לִימָ״א שֶׁל נַפָּחִים, שֶׁיֵּשׁ לוֹ פִּיּוֹת הַרְבֵּה, וְנִקְרֵאת הֶפְצֵר פִּיּוֹת:",2,0],[15,28,"וַיִּשְׁכּוֹן עָרִים נִכְחָדוֹת. כֵּן דֶּרֶךְ בַּעֲלֵי גַּאֲוָה: בּוֹנִים חֳרָבוֹת לְשֵׁם:",1,0],[15,29,"וְלֹא יָקוּם חֵילוֹ. לֹא יִתְקַיֵּם לְיָמִים רַבִּים:",1,0],[15,29,"וְלֹא יִטֶּה. לֹא יִנְטֶה מְלִיצָתוֹ; כְּמוֹ ״וַיִּטּוּ אַחֲרֵי הַבָּצַע״ (שמואל א ח:ג), שֶׁפֵּירוּשׁוֹ: ׳וַיִּנְטוּ׳ הֵם עַצְמָם; אַף כָּאן לֹא יִנְטֶה מִן הַשָּׁמַיִם לָאָרֶץ. מִנְלָם. מַתַּת תַּאֲוָתָם וְזִמּוּן מַחֲשַׁבְתָּם, וְהוּא כִּשְׁתֵּי תֵיבוֹת: מִן לָהֶם:",2,0],[15,29,"מִן. הֲכָנָתָם, כְּמוֹ ״וַיְמַן לָהֶם הַמֶּלֶךְ״ (דניאל א:ה). וְדוֹמֶה לוֹ ״הַפְּצִירָה פִים״ בִּשְׁתֵּי תֵיבוֹת (שמואל א יג:כא), וְכֵן ״אֶרְאֶלָּם״ (ישעיה לג:ז) – תַּרְגּוּם יוֹנָתָן: ״אִתְגְּלִי לְהוֹן״. זֶה נִרְאֶה בְּעֵינַי, וּמְנַחֵם מְסַיְּעֵנִי. דָּבָר אַחֵר: מִנְלָם. לְשׁוֹן ״כַּנְּלֹתְךָ לִבְגֹּד״ (ישעיה לג:א), וְהַנּוּ״ן שֶׁבּוֹ יְסוֹד נוֹפֵל. לְשׁוֹן תַּכְלִית: לֹא יִטֶּה לָאָרֶץ. לִהְיוֹת בְּטֵלָה, גְּזֵרַת חָרוּץ:",3,0],[15,30,"וְיָסוּר. מִן הָעוֹלָם:",1,0],[15,30,"בְּרוּחַ פִּיו. שֶׁל שַׁלִּיט בָּעוֹלָם, וְזֶה מִקְרָא חָסֵר. וְיֵשׁ פּוֹתְרִים: בִּשְׁבִיל רוּחַ פִּיו – שֶׁהֵרַע לְדַבֵּר סָרָה:",2,0],[15,31,"אַל יַאֲמֵן. אוֹתוֹ אֲשֶׁר בְּשָׁוְא נִתְעָה, כִּי שָׁוְא יִהְיֶה תְמוּרָתוֹ וִיגִיעוֹ, כְּמוֹ ״וְעַל הַתְּמוּרָה״ (רות ד:ז):",1,0],[15,32,"בְּלֹא יוֹמוֹ. תַּעֲמֹד תְּמוּרָתוֹ עַל מְלִיאָתָהּ מִלִּגְדֹּל וּמִלְּהַצְלִיחַ עוֹד, כְּמוֹ ״וַיִּמָּלְאוּ לוֹ אַרְבָּעִים יוֹם״ (בראשית נ:ג). פֵּירוּשׁוֹ: ״וְאַשְׁלִימוּ״ (תרגום אונקלוס):",1,0],[15,32,"וְכִפָּתוֹ. כְּפִיַּת עֲנָפָיו, כָּל עַנְפֵי אִילָן דּוֹמִין לְכִפָּה:",2,0],[15,35,"הָרֹה עָמָל וְיָלֹד אָוֶן. עָשָׂה רָעָה, וְיִשְׁתַּלְּמוּ שְׂכַר הַלֵּידָה לְפִי הַהֵרָיוֹן:",1,0],[15,35,"תָּכִין. תַּזְמִין:",2,0],[15,35,"מִרְמָה. לְמִרְמָה תֵּהָפֵךְ לָהֶם תַּאֲוָתָם:",3,0],[16,3,"(מענה איוב): יַמְרִיצְךָ. יְשַׁעֶרְךָ פִּיךָ לַחֲשֹׁב דְּבָרִים נִמְרָצִים עַל אוֹפְנֵיהֶם:",1,0],[16,4,"כָּכֶם אֲדַבֵּרָה. כָּכֶם אֲנִי יוֹדֵעַ לְקַנְתֵּר:",1,0],[16,4,"לוּ יֵשׁ נַפְשְׁכֶם. בְּיִסּוּרִין תַּחַת נַפְשִׁי, גַּם אֲנִי הָיִיתִי מְחַבֵּר עֲלֵיכֶם בְּמִלִּין וּמֵנִיעַ עֲלֵיכֶם רֹאשִׁי בְּצַעֲקַתְכֶם, וּמְאַמֵּץ אֶתְכֶם בְּמוֹ פִי לֵאמֹר: הַחֲרִישׁוּ, הִתְאַמְּצוּ וְעִמְדוּ בְּיִסּוּרֵיכֶם, כַּאֲשֶׁר אַתֶּם תֹּאמְרוּ אֵלַי:",2,0],[16,5,"וְנִיד שְׂפָתַי. שֶׁאֲנִי נָד וְקוֹבֵל עַתָּה וְצוֹעֵק, אָז יַחְשׂוֹךְ וְלֹא אֶזְעוֹק וְלֹא אָנוּד עוֹד, אֲבָל עַתָּה:",1,0],[16,6,"אִם אֲדַבְּרָה וְגוֹ׳:",1,0],[16,7,"הֲשִׁמּוֹתָ. לְשׁוֹן שְׁתִיקָה, כְּמוֹ ״אֶשְׁתּוֹמֵם״ (ישעיהו סג:ה), וּכְמוֹ ״שֹׁמּוּ שָׁמַיִם״ (ירמיהו ב:יב) – שָׁתְקוּ וְהִתְמָהוּ:",1,0],[16,8,"וַתִּקְמְטֵנִי לְעֵד הָיָה. הִקְמַטְתַּנִי וְהִקְדַּרְתַּנִי בִּשְׁבִיל עֵד, שֶׁהָיָה לְעֵד עַל עֲוֹנִי לְהַשְׂטִינֵנִי:",1,0],[16,9,"צָרִי. הַשָּׂטָן הוּא הַצָּר:",1,0],[16,9,"יִלְטוֹשׁ. יְחַדֵּד, כְּמוֹ ״לוֹטֵשׁ כָּל חֹרֵשׁ וְגוֹמֵר״ (בראשית ד:כב):",2,0],[16,10,"פָּעֲרוּ עָלַי בְּפִיהֶם. פָּתְחוּ, כְּמוֹ ״וּפָעֲרָה פִיהָ״ (ישעיה ה:יד):",1,0],[16,10,"יִתְמַלָּאוּן. יִתְאַסְּפוּן, וְהַרְבֵּה לוֹ דּוֹמִין בַּמִּקְרָא: ״קָרְאוּ אַחֲרֶיךָ מָלֵא״ (ירמיה יב:ו), ״אֲשֶׁר יִקָּרֵא עָלָיו מְלֹא רֹעִים״ (ישעיה לא:ד). וְאֵינוֹ מִשְׁתַּנֶּה מִלְּשׁוֹנוֹ, כִּי כָל ׳מִלּוּי׳ – ׳נֶאֱסָף׳ הוּא:",2,0],[16,11,"יַסְגִּירֵנִי אֵל אֶל עֲוִיל. הִסְגִּירַנִי הַקָּדוֹשׁ בָּרוּךְ הוּא אֶל אֱוִיל לֵץ עוֹלֵל, לָלוּץ בִּי:",1,0],[16,11,"וְעַל יְדֵי רְשָׁעִים יִרְטֵנִי. רְטִיַּת תַּנְחוּמָיו וּרְפוּאָתִי מָסַר לָרְשָׁעִים, שֶׁאֵינָן אֶלָּא מַקְנִיטִים. דָּבָר אַחֵר: יִרְטֵנִי כְּמוֹ יְרַצֵּנִי, לְשׁוֹן רִצּוּי וְתַנְחוּמִים:",2,0],[16,12,"וַיְפַרְפְּרֵנִי. אוֹתוֹ עֲוִיל, לְשׁוֹן פֵּרוּרִין:",1,0],[16,12,"וַיְפַצְפְּצֵנִי. לְשׁוֹן נִשְׁבָּר לִשְׁבָרִים הַרְבֵּה בַּחֲבָטָה רַבָּה, כְּמוֹ ״וְנִפַּצְתִּים אִישׁ אֶל אָחִיו״ (ירמיה יג:יד), ״וְנִפֵּץ עֹלָלַיִךְ אֶל הַסָּלַע״ (תהלים קלז:ט):",2,0],[16,13,"רַבָּיו. מוֹרֶה חִצָּיו, כְּמוֹ ״רֹבֶה קֶשֶׁת״ (בראשית כא:כ):",1,0],[16,13,"מְרֵרָתִי. מָרָה שֶׁלִּי:",2,0],[16,15,"גִּלְדִּי. מַכָּה יְבֵשָׁה וְהַעֲלָאַת גֶּלֶד, וּלְשׁוֹן מִשְׁנָה (ראש השנה כז:): וְהֶעֱמִידוֹ עַל גִּלְדּוֹ:",1,0],[16,15,"וְעוֹלַלְתִּי. וְלִכְלַכְתִּי וְגִנִּיתִי, כְּמוֹ ״וַיִּתְעַלְּלוּ בָהּ״ (שופטים יט:כה) – לְשׁוֹן בִּזָּיוֹן וּגְנַאי, וּכְמוֹ ״עוֹלְלָה לְנַפְשִׁי״ (איכה ג:נא):",2,0],[16,15,"קַרְנִי. זִיוִי, לָשׁוֹן ״וְקַרְנַיִם מִיָּדוֹ לוֹ״ (חבקוק ג:ד):",3,0],[16,16,"חֳמַרְמְרוּ. נִקְמְטוּ, כְּמוֹ ״נֶחְמְרוּ בְּנֵי מֵעֶיהָ״ בִּלְשׁוֹן מִשְׁנָה (חולין נו:); וְכֵן ״מֵעַי חֳמַרְמָרוּ״ (איכה א:כ):",1,0],[16,16,"צַלְמָוֶת. שֶׁחָשְׁכוּ מֵחֲמַת בֶּכִי וְדֶמְעָה:",2,0],[16,17,"וּתְפִלָּתִי זַכָּה. לֹא קִלַּלְתִּי חֲבֵרִי, וְלֹא פִלַּלְתִּי לוֹ רָעָה:",1,0],[16,18,"וְאַל יְהִי מָקוֹם. בָּאָרֶץ לְהַבְלִיעַ בּוֹ צַעֲקָתִי, כִּי לַשָּׁמַיִם תַּעֲלֶה:",1,0],[16,19,"הִנֵּה בַשָּׁמַיִם עֵדִי. יוֹצְרִי הַיּוֹדֵעַ דְּרָכִי:",1,0],[16,20,"דָּלְפָה. דּוֹמַעַת וְזוֹלֶפֶת דִּמְעָה, לְשׁוֹן דִּלּוּף:",1,0],[16,21,"וְיוֹכַח לְגֶבֶר. וְהַלְוַאי יַעֲשֶׂה לִי זֹאת, שֶׁיִּתֵּן לִי מָקוֹם לְהִתְוַכֵּחַ גֶּבֶר עִם אֱלוֹהַּ, לְהַשְׁווֹת שְׁנֵי הָרִיבִים: רִיב גֶּבֶר עִם קוֹנוֹ וְרִיב בֵּין אָדָם לְרֵעֵהוּ:",1,0],[16,22,"כִּי שְׁנוֹת וְגוֹ׳. הַקְּצוּבִים מִסְפָּר לִימֵי חַיַּי:",1,0],[16,22,"יֶאֱתָיוּ. יַגִּיעוּ, וְאָז אֹרַח לֹא אָשׁוּב אֶהֱלֹךְ:",2,0],[17,1,"נִזְעָכוּ. נִקְפְּצוּ, כְּמוֹ ״נִדְעָכוּ״ (איוב ו:יז):",1,0],[17,1,"קְבָרִים לִי. מוּכָן אֲנִי לַקֶּבֶר:",2,0],[17,2,"אִם לֹא. אִם לֹא זֹאת בָּאַתְנִי, שֶׁבְּנֵי אָדָם הַתּוּלִים נוֹעֲדוּ עִמִּי בְּתַנְחוּמַי, לְהָתֵל בִּי:",1,0],[17,2,"וּבְהַמְּרוֹתָם. כְּמוֹ ״וַיַּמְרוּ בִי״ (יחזקאל כ:ח), ״מַמְרִים הֱיִיתֶם״ (דברים ט:ז) – לְשׁוֹן בְּהַקְנָטַתְכֶם:",2,0],[17,2,"תָּלַן עֵינִי. עֵינִי וְלִבִּי וּמַחֲשַׁבְתִּי לָנוּחַ בָּהֶן:",3,0],[17,3,"שִׂימָה נָּא. הַבּוֹרֵא:",1,0],[17,3,"עָרְבֵנִי. בְּתֵקַע כַּף, לְהִתְוַכֵּחַ יַחַד. כְּמוֹ מִי הוּא מֵאֵלֶּה לְיָדִי יִתָּקֵעַ וְיִיטַב לוֹ:",2,0],[17,4,"כִּי לִבָּם צָפַנְתָּ מִשָּׂכֶל. וְעַל כֵּן לֹא תְרוֹמֵם תִּפְאַרְתְּךָ עַל יְדֵיהֶם:",1,0],[17,5,"לְחֵלֶק יַגִּיד. לַחֲלַקְלַקּוּת יַגִּיד כָּל אֶחָד מֵהֶם אֶת רֵעוֹ, וְזֹאת תָּבֹא לָהֶם: עֵינֵי בָנָיו תִּכְלֶינָה:",1,0],[17,6,"וְתֹפֶת. כְּמוֹ ״תֹּף״ (ישעיהו ה:יב):",1,0],[17,6,"לְפָנִים. שֶׁל בְּרִיּוֹת אֲנִי:",2,0],[17,7,"וִיצוּרַי. אֵיבָרִים שֶׁאֲנִי נוֹצָר בָּהֶם:",1,0],[17,8,"יָשֹׁמּוּ. יִתְמְהוּ:",1,0],[17,8,"וְנָקִי. אִם יֵשׁ צַדִּיק שׁוֹמֵעַ בְּהַתּוּלוֹת הַחֲנֵפִים הָאֵלֶּה:",2,0],[17,8,"יִתְעוֹרָר. לָרִיב בָּכֶם:",3,0],[17,9,"וְיֹאחֵז. כָּל צַדִּיק דַּרְכּוֹ לַעֲמֹד כְּנֶגֶד כַּת חֲנֵפִים:",1,0],[17,10,"וְאוּלָם כֻּלָּם. אֲנִי אוֹמֵר לָכֶם תָּשׁוּבוּ נָא וּבֹאוּ נָא:",1,0],[17,10,"וְלֹא אֶמְצָא בָכֶם חָכָם. בְּמַה שֶּׁאַתֶּם מַלְעִיגִים עַל קַבָּלָתִי:",2,0],[17,11,"יָמַי וְגוֹ׳. הִנֵּה יְמֵי טוֹבָתִי שֶׁהֻרְגַּלְתִּי בָּהֶם, עָבְרוּ:",1,0],[17,11,"זִמּוֹתַי. שֶׁזָּמוֹתִי לְהַאֲרִיךְ בְּטוֹבָה:",2,0],[17,11,"נִתְּקוּ מוֹרָשֵׁי לְבָבִי. מַחֲשָׁבוֹת שֶׁלִּבִּי מוֹרִישַׁנִי, שֶׁהָיָה לִבִּי אוֹמֵר לִי לִירַשׁ טוֹבָה לְפִי דַרְכִּי:",3,0],[17,12,"לַיְלָה לְיוֹם יָשִׂימוּ. הַתּוֹלִים אֵלֶּה הוֹפְכִים לִי לַיְלָה לְיוֹם, כִּי מִצָּרַת הַתּוֹלִים לֹא אִישַׁן בַּלַּיְלָה:",1,0],[17,12,"אוֹר קָרוֹב. וְקָצַר לִי, מִפְּנֵי צָרוֹת חֹשֶׁךְ לַיְלָה. אוֹר קָרוֹב – כַּאֲשֶׁר יָבֹא הַשֶּׁמֶשׁ נִרְאֶה לִי שֶׁעַתָּה מִקָּרוֹב הֵאִיר הַיּוֹם, וְנִקְצַר וְחָלַף לוֹ; כְּמוֹ ״הָעִיר הַזֹּאת קְרֹבָה״ (בראשית יט:כ) – נִתְיַשְּׁבָה מִקָּרוֹב מֵחָדָשׁ; וּכְמוֹ ״כִּי רִנְנַת רְשָׁעִים מִקָּרֹב״ (איוב כ:ה), וּכְמוֹ ״חֲדָשִׁים מִקָּרֹב בָּאוּ״ (דברים לב:יז):",2,0],[17,13,"אִם אֲקַוֶּה שְׁאוֹל. כְּמוֹ ״אִם חֲרוּצִים יָמָיו״ (איוב יד:ה), כְּלוֹמַר: מֵאַחַר שֶׁאֲנִי מְקַוֶּה שְׁאוֹל בֵּיתִי:",1,0],[17,13,"וּבַּחֹשֶׁךְ רִפַּדְתִּי. שִׁטַּחְתִּי יְצוּעָי בַּקֶּבֶר:",2,0],[17,14,"לַשַּׁחַת קָרָאתִי אָבִי אָתָּה. לְהִתְלוֹנֵן בּוֹ יָמִים רַבִּים, כְּאִלּוּ הוּא אָבִי, מֵאַחַר שֶׁתִּקְוָתִי זֹאת הִיא:",1,0],[17,15,"וְאַיֵּה אֵפוֹ תִקְוָתִי. וְאַתְּ, לָמָּה נִמְשַׁכְתְּ? וּמִי יְשׁוּרֶנָּה לְהָרִיצָהּ עָדַי?",1,0],[17,16,"בַּדֵּי שְׁאוֹל תֵּרַדְנָה. אוֹתָם אֵבָרִים שֶׁסּוֹפָן לֵירֵד שְׁאוֹל, שֶׁתְּהֵא יַחַד עַל עָפָר נָחַת:",1,0],[17,16,"נָחַת. מְלוֹנָן, לְשׁוֹן ״וַתָּנַח עֲלֵיהֶם הָרוּחַ״ (במדבר יא:כו):",2,0],[18,2,"(מענה בלדד):קִנְצֵי. סוֹף:",1,0],[18,2,"תָּבִינוּ. תִּשְׁתְּקוּ לְהָבִין וְלִשְׁמֹעַ אֶת אֲשֶׁר נְדַבֵּר:",2,0],[18,3,"נִטְמִינוּ בְעֵינֵיכֶם. נֶחְשַׁבְנוּ בְעֵינֵיכֶם טְמוּנִין. וְאֵין יְסוֹד בַּתֵּיבָה זוֹ זוּלָתִי טי״ת מ״ם, כְּמוֹ ״טְמוֹנִין פְּלִשְׁתָּאֵי״, תַּרְגּוּם שֶׁל ״סִתְּמוּם פְּלִשְׁתִּים״ (בראשית כו:טו). יֵשׁ מְפָרְשִׁים לְשׁוֹן טְמִינָה, וְטָעוּת הוּא בְּיָדָם, שֶׁאִם כֵּן צְרִיכָה הַתֵּיבָה שְׁנֵי נוּנִי״ן, אֶחָד בַּיְּסוֹד וְאֶחָד בְּשִׁמּוּשׁ שֶׁל רַבִּים:",1,0],[18,4,"טוֹרֵף נַפְשׁוֹ. חוֹזֵר עַל אִיּוֹב. לְךָ אֲנִי אוֹמֵר, הַטּוֹרֵף וּמְחַבֵּל נַפְשׁוֹ בְּאַפּוֹ וּבְכַעֲסוֹ:",1,0],[18,4,"הֲלְמַעַנְךָ. הַלְמַעַן צִדְקָתְךָ תֵּעָזֵב הָאָרֶץ מִמִּשְׁפַּט מִדָּתָהּ?",2,0],[18,4,"וְיֶעְתַּק צוּר. הַיּוֹצֵר (מִמְּקוֹמוֹ) מִדַּעְתּוֹ וּמִמִּדָּתוֹ:",3,0],[18,5,"גַּם. עַתָּה, לְפִי צַעֲקָתְךָ, זֹאת תִּנְהַג לְדוֹרוֹת:",1,0],[18,5,"אוֹר רְשָׁעִים יִדְעָךְ. יִקְפֹּץ מִמְּקוֹמוֹ. שְׁבִיב. אֶשְׁטַנְצִיל״אָ:",2,0],[18,7,"יֵצְרוּ. יִהְיוּ קְצָרִים צַעֲדֵי כֹּחוֹ:",1,0],[18,7,"וְתַשְׁלִיכֵהוּ. מֵעָלָיו עֲצָתוֹ שֶׁיָּעַץ, אֲשֶׁר לֹא יִתְקַיֵּם:",2,0],[18,8,"כִּי וְגוֹ׳. סוֹפוֹ אֲשֶׁר שֻׁלַּח בְּרֶשֶׁת רַגְלָיו, (שֻׁלְּחוּ) לִצְעוֹד עַל הָרֶשֶׁת וְלִיתָּפֵשׂ:",1,0],[18,8,"וְעַל שְׂבָכָה יִתְהַלָּךְ. הִיא רֶשֶׁת; כָּל שְׂבָכָה עֲשׂוּיָה כְּמוֹ רֶשֶׁת, וְהוּא קֵייפָ״א שֶׁבְּרָאשֵׁי הַנָּשִׁים:",2,0],[18,9,"יֹאחֵז. יֹאחֲזֶנּוּ בְּעָקֵב פַּח:",1,0],[18,10,"טָמוּן בָּאָרֶץ. תַּחַת רַגְלָיו:",1,0],[18,10,"חַבְלוֹ. חֶבֶל מְצוּדָתוֹ אֲשֶׁר יִלָּכֵד בָּהּ:",2,0],[18,10,"וּמַלְכֻּדְתּוֹ. טָמוּן עֲלֵי נְתִיבוֹ, כְּשֵׁם שֶׁטּוֹמְנִין חֶבֶל מַלְכֹּדֶת לָעוֹפוֹת:",3,0],[18,11,"בַּלָּהוֹת. שֵׁדִים:",1,0],[18,11,"וֶהֱפִיצֻהוּ לְרַגְלָיו. (יִנְפְּצֵהוּ) יַחְבְּטוּהוּ עַל הָאָרֶץ:",2,0],[18,12,"אוֹנוֹ. בְּנוֹ (בראשית מט:ג):",1,0],[18,12,"לְצַלְעוֹ. אִשְׁתּוֹ (בראשית ב:כא):",2,0],[18,13,"יֹאכַל בַּדֵּי עוֹרוֹ. וְיֹאכַל כָּל שְׁאָר בַּדָּיו – בָּנָיו וּבְנוֹתָיו:",1,0],[18,13,"בְּכוֹר מָוֶת. שַׂר הַמָּוֶת, כְּמוֹ ״אָנִי בְּכוֹר אֶתְּנֵהוּ״ (תהלים פט:כח):",2,0],[18,14,"יִנָּתֵק מֵאָהֳלוֹ. מֵאִשְׁתּוֹ:",1,0],[18,14,"מִבְטַחוֹ. שֶׁהִיא בְּטוּחָה בּוֹ, (מִבְטַחוֹ) מִבְטַחַת שֶׁלּוֹ, שֶׁהִיא בּוֹטַחַת עָלָיו:",2,0],[18,14,"וְתַצְעִידֵהוּ. וְהִיא תַּצְעִידֵהוּ וְתִשְׁלָחֵהוּ (מֵעָלֶיהָ) לַקֶּבֶר לְמֶלֶךְ הַשֵּׁדִים:",3,0],[18,15,"תִּשְׁכּוֹן בְּאָהֳלוֹ אַלְמָנָה:",1,0],[18,15,"מִבְּלִי לוֹ. (שֶׁלֹּא תְּהֵא שֶׁלּוֹ) שֶׁהֲרֵי מֵת, וְסוֹף יְזֹרֶה עַל נָוֵהוּ גָּפְרִית:",2,0],[18,18,"יֶהְדְּפֻהוּ. מִן הַשָּׁמַיִם:",1,0],[18,19,"נֶכֶד. בֶּן הַבֵּן:",1,0],[18,20,"נָשַׁמּוּ אַחֲרוֹנִים. תָּמְהוּ בְּשָׁמְעָם עַל אֵיד אֲשֶׁר בָּא לוֹ:",1,0],[18,20,"שָׂעַר. לֹא יִתָּכֵן לִהְיוֹת מִגִּזְרַת שֵׂעָר, שֶׁאֵין טַעַם שֵׂעָר בְּשִׁי״ן אֶלָּא בְּעַיִן, וְאֵינוֹ נֶהְפָּךְ לְקָמַץ בְּאַתְנַחְתָּא וְסוֹף פָּסוּק. לֹא שָׁמַעְתִּי:",2,0],[18,21,"אֵלֶּה מִשְׁכְּנוֹת עַוָּל. זֶה אַחֲרִיתָם:",1,0],[19,2,"(מענה איוב): תּוֹגְיוּן. לְשׁוֹן ״תּוּגָה״ (משלי יד:יג):",1,0],[19,3,"עֶשֶׂר פְּעָמִים. עֶשֶׂר פָּרָשִׁיּוֹת יֵשׁ עַד כָּאן:",1,0],[19,3,"תַּהְכְּרוּ לִי. תִּתְנַכְּרוּ לִי:",2,0],[19,4,"אִתִּי תָּלִין. אֲנִי הוּא הַלּוֹקֵחַ מַכּוֹת עַל מְשׁוּגָתִי:",1,0],[19,5,"אִם אָמְנָם. אַתֶּם נוֹסָפִים עָלַי לְצָרָתִי, וְתוֹכִיחוּ עָלַי חֶרְפָּתִי מַרְאִים וּמוֹכִיחִים חֶרְפָּתִי עַל פָּנַי:",1,0],[19,7,"אֶצְעַק. עַל חָמָס וְלֹא אֵעָנֶה:",1,0],[19,10,"וַיַּסַּע. לְשׁוֹן עֲקִירָה:",1,0],[19,12,"וַיָּסֹלּוּ. לְשׁוֹן ״מְסִלָּה״ (ישעיה יא:טז):",1,0],[19,13,"אַךְ זָרוּ. לְשׁוֹן ״אַכְזָר״ (איוב ל:כא):",1,0],[19,17,"לִבְנֵי בִטְנִי. לְאוֹתָם שֶׁגִּדַּלְתִּי בְּבֵיתִי, כְּאִלּוּ הֵם בָּנַי:",1,0],[19,18,"עֲוִילִים מָאֲסוּ בִי. נִבְזֶה אֲנִי בְּעֵינֵי נְעָרִים, וְכָל שֶׁכֵּן בְּעֵינֵי שָׂרִים:",1,0],[19,20,"דָּבְקָה עַצְמִי. שֶׁאֲנִי כָּחוּשׁ מֵעֹבִי בְּשָׂרִי:",1,0],[19,20,"בְּעוֹר שִׁנָּי. כָּל בְּשָׂרִי הָיָה לָקוּי בִּשְׁחִין וּבְתוֹלָעִים, חוּץ מֵחֲנִיכֵי שִׁנָּיו:",2,0],[19,24,"בְּעֵט בַּרְזֶל. יֵחָצְבוּן בַּצּוּר, וְאַחַר כָּךְ מַעֲבִירִין אֶת הָעוֹפֶרֶת עֲלֵיהֶם, לָתֵת לָאוֹתִיּוֹת מַרְאֵה שַׁחֲרוּרִית, לְהַכִּירָם; וְכֵן דֶּרֶךְ חוֹקֵק אֶבֶן. וְלֹא יִתָּכֵן לְפָרֵשׁ עֵט שֶׁל עוֹפֶרֶת, שֶׁהֲרֵי רַךְ הוּא אֵצֶל הָאֶבֶן:",1,0],[19,25,"וַאֲנִי יָדַעְתִּי גֹּאֲלִי חָי. וָא״ו זֶה חוֹזֵר לְמַעְלָה: אַתֶּם תִּרְדְּפוּנִי, וַאֲנִי יָדַעְתִּי גּוֹאֲלִי חַי – לִיפָּרַע, וְהוּא יִתְקַיֵּם וְיַעֲמֹד:",1,0],[19,25,"וְאַחֲרוֹן עַל עָפָר יָקוּם. לְאַחַר שֶׁיִּכְלוּ כָּל שׁוֹכְנֵי עָפָר, הוּא אַחֲרוֹן יַעֲמֹד:",2,0],[19,25,"יָקוּם. יִתְקַיֵּם:",3,0],[19,26,"וְאַחַר עוֹרִי נִקְּפוּ זֹאת. וְהֵם אֵינָם נוֹתְנִים לֵב לְגוֹאֲלִי, אֶלָּא אַחַר מַכַּת עוֹרִי נִקְּפוּ וְנִקְּרוּ הַקְּנִיטָה וְהָרְדִיפָה הַזֹּאת שֶׁאָמַרְתִּי, שֶׁהִיא לִי כְּנוֹקֵף וְחוֹתֵךְ בְּעוֹרִי. כְּמוֹ ״וְנִקַּף סִבְכֵי הַיַּעַר״ (ישעיהו י:לד):",1,0],[19,26,"וּמִבְּשָׂרִי. אֲנִי רוֹאֶה מִשְׁפָּטִים:",2,0],[19,26,"אֱלוֹהַּ. לְשׁוֹן מִשְׁפָּט וְיִסּוּרִין:",3,0],[19,28,"כִּי תֹאמְרוּ מַה נִּרְדָּף לוֹ. כְּמוֹ ״כִּי תֹאמַר בִּלְבָבְךָ״ (דברים ז:יז), שֶׁהוּא מְשַׁמֵּשׁ לְשׁוֹן דִּילְמָא. כְּלוֹמַר: וְשֶׁתִּהְיוּ נוֹתְנִים לִבְּכֶם לַחְמֹל, וְלוֹמַר: לָמָּה נִרְדְּפֶנּוּ?",1,0],[19,28,"וְשֹׁרֶשׁ דָּבָר. הַנִּמְצָא בּוֹ מַה הִיא? לְעוֹלָם לֹא תַעֲלֶה בִלְבַבְכֶם הַטּוֹבָה הַזֹּאת! שֹׁרֶשׁ דָּבָר עַל מָה הוּא עוֹמֵד?",2,0],[19,29,"כִּי חֵמָה. שֶׁאַתֶּם מַגְדִּילִים עָוֹן הַמֵּבִיא לִידֵי חֶרֶב:",1,0],[19,29,"לְמַעַן תֵּדְעוּן. וְתָבִינוּ סוֹד הַפּוּרְעָנוּת הַבָּא עַל הָרְשָׁעִים. וְיֵשׁ אֵם לַמָּסֹרֶת: שַׁדִּין כְּתִיב – כְּמוֹ שֶׁיֵּשׁ דִּין בָּעוֹלָם, כְּמוֹ ״שַׁקַּמְתִּי דְּבוֹרָה״ (שופטים ה:ז). כֵּן רָאִיתִי בְּתַנְחוּמָא (תנחומא, משפטים ג):",2,0],[20,2,"(מענה צופר):שְׂעִפַּי יְשִׁיבוּנִי. מַחְשְׁבוֹתַי יְשִׁיבוּנִי מַעֲנֶה לְפִי, וּבַעֲבוּר שֶׁאֲנִי חָשׁ וְשׁוֹתֵק וְשַׂמְתִּי בִי שְׁתִיקוֹתַי יְשִׁיבוּנִי סְעִיפַי לַעֲנוֹת. אֲנִי שׁוֹמֵעַ מִמְּךָ יִסּוּרֵי כְלִמָּתִי, שֶׁאַתָּה תַכְלִימֵנִי, וְעַל כֵּן דְּבַר רוּחַ יַעֲנֵנִי מִבִּינָתִי לַהֲשִׁיבְךָ:",1,0],[20,2,"חוּשִׁי. שְׁתִיקוּתִי, כְּמוֹ ״עֵת לַחֲשׁוֹת״ (קהלת ג:ז):",2,0],[20,4,"הֲזֹאת. תֵּימַהּ: הֲיוֹדֵעַ אַתָּה מִדָּה הַמְהַלֶּכֶת עַל פְּנֵי כָּל הַדּוֹרוֹת מִנִּי עַד?",1,0],[20,5,"כִּי רִנְנַת רְשָׁעִים. כָּל יְמֵי הֱיוֹתָהּ, מִקָּרוֹב בָּאָה וְלֹא לְאֹרֶךְ יָמִים עוֹמֶדֶת:",1,0],[20,5,"וְשִׂמְחַת חָנֵף עֲדֵי רָגַע. בִּזְמַן מוּעָט תִּכְלֶה:",2,0],[20,6,"שִׂיאוֹ. גָּבְהוֹ:",1,0],[20,7,"כְּגֶלְלוֹ. גָּלָל שֶׁל רְעִי:",1,0],[20,8,"וְלֹא יִמְצָאוּהוּ. יוֹדְעָיו:",1,0],[20,9,"שְׁזָפַתּוּ. רָאֲתָהוּ:",1,0],[20,10,"בָּנָיו יְרַצּוּ דַלִּים. עַל אַנְשֵׁי סְדוֹם נֶאֱמַר מַעֲנֶה זוֹ, שֶׁהָיוּ גַּזְלָנִים וְאַכְזָרִים עַל עֲנִיִּים:",1,0],[20,10,"וְיָדָיו תָּשֵׁבְנָה. חֲמַס כַּפָּיו:",2,0],[20,10,"אוֹנוֹ. כֹּחַ אָנְסוֹ:",3,0],[20,11,"עַצְמוֹתָיו מָלְאוּ עֲלוּמָיו. כֹּחַ נַעֲרוּתָיו:",1,0],[20,11,"וְעִמּוֹ עַל עָפָר תִּשְׁכָּב. כִּי יָמוּת פִּתְאוֹם עִם כֹּחוֹ:",2,0],[20,12,"אִם תַּמְתִּיק. כָּךְ וֶסְתּוֹ שֶׁל רָשָׁע: אִם תַּמְתִּיק בְּפִיו רָעָה וְאֵינוֹ רוֹאֶה לָהּ עַתָּה שָׁעָה שֶׁתָּחוּל, יַכְחִידֶנָּה תַּחַת לְשׁוֹנוֹ, עַד בֹּא הָעֵת שֶׁתַּצְלִיחַ:",1,0],[20,14,"לַחְמוֹ בְּמֵעָיו. בְּיוֹם אֵידוֹ נֶהְפַּךְ לִמְרוֹרוֹת פְּתָנִים:",1,0],[20,15,"חַיִל. מָמוֹן:",1,0],[20,16,"אֶפְעֶה. נָחָשׁ שָׂרָף:",1,0],[20,17,"בִּפְלַגּוֹת נַהֲרֵי נַחֲלֵי. גַּן עֵדֶן הַמְּתוּקִין כִּדְבַשׁ וְחֶמְאָה:",1,0],[20,18,"מֵשִׁיב יָגָע. הַגֶּזֶל שֶׁגָּזַל:",1,0],[20,18,"כְּחֵיל תְּמוּרָתוֹ. כַּאֲשֶׁר תִּהְיֶה תְּמוּרָתוֹ לְ״חֵיל״, נְכָסִים גְּדוֹלִים, אָז יְבִיאֵהוּ חִסָּרוֹן:",2,0],[20,18,"וְלֹא יַעֲלֹס. בּוֹ, וְכֵן ״יַעֲלֹז״ (תהלים צו:יב) וְכֵן ״יַעֲלֹץ״ (דברי הימים א טז:לב) שְׁלָשְׁתָּן מִתְחַלְּפוֹת:",3,0],[20,19,"כִּי רִצַּץ עָזַב דַּלִּים. לְאַחַר שֶׁרִצַּץ אֶת דַּלִּים, עָזַב הַדַּלִּים וְנִטְרַד מִן הָעוֹלָם וְהָלַךְ לוֹ, וְהֵם חוֹזְרִים וְגוֹבִים מִמֶּנּוּ גְּזֵלוֹתָיו:",1,0],[20,19,"כִּי רִצַּץ. כְּשֶׁרִצַּץ; כְּמוֹ ״כִּי יִהְיֶה לָהֶם דָּבָר בָּא אֵלַי״ (שמות יח:טז) – כְּשֶׁיִּהְיֶה לָהֶם:",2,0],[20,20,"כִּי לֹא יָדַע. אֶת בִּטְנוֹ מֵעוֹלָם שָׁלֵיו, בִּטְנוֹ אוֹמֵר לוֹ תָּמִיד: גְּזוֹל וְהָבֵא לְמַלְּאֵנִי! וְעַל כֵּן בַּחֲמוּדוֹ. בִּבְשַׂר יוֹפִי חֶמְדָּתוֹ:",1,0],[20,20,"לֹא יְמַלֵּט. כִּי יְהֵא פּוֹחֵת וְהוֹלֵךְ, וְדוֹמֶה לוֹ ״וַתֶּמֶס כָּעָשׁ חֲמוּדוֹ״ (תהילים לט:יב):",2,0],[20,21,"אֵין שָׂרִיד לְאָכְלוֹ. לֹא שִׁיֵּר מִמַּאֲכָלוֹ לְחַלֵּק לַעֲנִיִּים:",1,0],[20,21,"עַל כֵּן לֹא יָחִיל טוּבוֹ. לֹא יַצְלִיחַ, כְּמוֹ ״יָחִילוּ דְרָכָיו״ (תהלים י:ה). וּבְאַנְשֵׁי סְדוֹם מְדַבֵּר, שֶׁהָיָה עֵינֵיהֶם צָרָה בָּאוֹרְחִים, כִּי כֵּן הֵעִיד עַל סְדוֹם ״גָּאוֹן שִׂבְעַת לֶחֶם וְגוֹ׳ וְיַד עָנִי וְאֶבְיוֹן לֹא הֶחֱזִיקָה״ (יחזקאל טז:מט). וְרַבּוֹתֵינוּ פֵּרְשׁוּ (סנהדרין צב.): אֵין שָׂרִיד לְאָכְלוֹ. לֹא הִשְׁרָה תַּלְמִידֵי חֲכָמִים עַל שֻׁלְחָנוֹ, כְּמוֹ ״וּבַשְּׂרִידִים אֲשֶׁר ה׳ קוֹרֵא״ (יואל ג:ה):",2,0],[20,22,"בִּמְלֹאות שִׂפְקוֹ. בְּהִתְמַלְּאוֹת תַּאֲוַת לִבּוֹ דַּי, אָז יֵצֶר לוֹ. תָּבֹא עָלָיו צָרָה:",1,0],[20,22,"סִפְקוֹ. לְשׁוֹן דֵּי, כְּדִמְתַרְגְּמִינָן: ״כַּד סְפִיקוּ גַמְלַיָּא״ (אונקלוס בראשית כד:כב), ״וּמָצָא לָהֶם״ (במדבר יא:כב): ״הֲיִסְפְּקוּן״ (תרגום אונקלוס):",2,0],[20,22,"כָּל־יַד עָמֵל תְּבוֹאֶנּוּ. תֶּחֱזַק עָלָיו וְתָצַר יַד עֲנִיִּים:",3,0],[20,23,"יְהִי לְמַלֵּא בִטְנוֹ יְשַׁלַּח בּוֹ חֲרוֹן אַפּוֹ. שְׁלִיחוּת חֲרוֹן אַפּוֹ יְהִי לְמַלֵּא בִטְנוֹ. וְאֵין זֶה לְשׁוֹן קְלָלָה אֶלָּא לְשׁוֹן נְבוּאָה וְעָתִיד:",1,0],[20,23,"וְיַמְטֵר עָלֵימוֹ. הַקָּדוֹשׁ בָּרוּךְ הוּא:",2,0],[20,23,"בִּלְחוּמוֹ. בְּזַעַף מִלְחַמְתּוֹ פַּחִים אֵשׁ וְגָפְרִית (תהלים יא:ו), כְּעִנְיָן שֶׁנֶּאֱמַר: ״וַה׳ הִמְטִיר עַל סְדֹם וְגוֹ׳״ (בראשית יט:כד):",3,0],[20,24,"תַּחְלְפֵהוּ. חִצִּים שֶׁתִּזְרוֹק הַקֶּשֶׁת יַחְלְפוּ אֶת גּוּפוֹ לַעֲבוֹר מֵעֵבֶר אֶל עֵבֶר. לָשׁוֹן אַחֵר: תַּחְלְפֵהוּ, כְּמוֹ תַּחֲלִיפֵהוּ (תְּקַדְּמֵהוּ) קֶשֶׁת נְחוּשָׁה:",1,0],[20,25,"שָׁלַף. הַשּׁוֹלֵף עָלָיו אֶת הַנֶּשֶׁק:",1,0],[20,25,"וַיֵּצֵא. הַנֶּשֶׁק:",2,0],[20,25,"מִגֵּוָה. מִתּוֹךְ תַּעְרָהּ:",3,0],[20,25,"וּבָרָק. פְּלַנְדוֹרְ״שׁ בְּלַעַ״ז, כְּמוֹ ״וּלְמַעַן הֱיוֹת לָהּ בָּרָק״ (יחזקאל כא:טו) – פוֹרְבִּי״ר:",4,0],[20,25,"מִמְּרוֹרָתוֹ יַהֲלֹךְ. מִמְּרוֹרָתוֹ שֶׁל נֶשֶׁק יַהֲלֹךְ, וּמִשָּׁם יִהְיוּ אֵמִים וָפַחַד עַל הָרָשָׁע:",5,0],[20,26,"לִצְפּוּנָיו. לְצֹרֶךְ מַצְפּוּנֵי גְנוּזִים הַצְּפוּנִים לוֹ:",1,0],[20,26,"אֵשׁ לֹא נֻפָּח. אֵשׁ שֶׁל גֵּיהִנֹּם:",2,0],[20,26,"יֵרַע שָׂרִיד בְּאָהֳלוֹ. תָּבֹא רָעָה לַשָּׂרִיד שֶׁיִּשָּׁאֵר בְּאָהֳלוֹ. כָּל הַפָּרָשָׁה כֻּלָּהּ בְּאַנְשֵׁי סְדוֹם (בראשית יט:א-כט):",3,0],[20,26,"יֵרַע שָׂרִיד בְּאָהֳלוֹ. אֲפִלּוּ לוֹט הַנִּמְלָט מֵהֶם בָּאָה רָעָה לְאָהֳלוֹ; זוֹ אִשְׁתּוֹ, שֶׁהָיְתָה נְצִיב מֶלַח (בראשית יט:כו). כֵּן מָצָאתִי בְּמִדְרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, וירא ז):",4,0],[20,27,"מִתְקוֹמָמָה. לְשׁוֹן אוֹיֵב הַקָּם כְּנֶגְדּוֹ:",1,0],[20,28,"יִגֶל. לְשׁוֹן גָּלוּת:",1,0],[20,28,"נִגָּרוֹת. יִהְיוּ אוֹצְרוֹתָיו נְתוּנוֹת לִמְשִׁיסָה וּלְבַז, כְּמוֹ ״כַּמַּיִם הַמֻּגָּרִים אָרְצָה״ (מיכה א:ד):",2,0],[20,29,"אִמְרוֹ מֵאֵל. הָאָמוּר עָלָיו מִלִּפְנֵי הַמָּקוֹם. אִמְרוֹ לְשׁוֹן זָכָר, מִגִּזְרַת ״אֲמָרַי הַאֲזִינָה״ (תהלים ה:ב); ״אִמְרָתוֹ״ (תהלים קמז:טו) – לְשׁוֹן נְקֵבָה, מִגִּזְרַת ״אֲמָרוֹת טְהוֹרוֹת״ (תהלים יב:ז):",1,0],[21,2,"(מענה איוב): וּתְהִי זֹאת תַּנְחוּמוֹתֵיכֶם. אֶת אֲשֶׁר תַּחֲרִישׁוּ וְתִשְׁמְעוּ אֵלַי, זֹאת תְּהִי לִי תַּנְחוּם מֵאִתְּכֶם:",1,0],[21,3,"שָׂאוּנִי. סִבְלוּנִי:",1,0],[21,4,"הֶאָנֹכִי לְאָדָם שִׂיחִי. לָמָּה תַּעַמְדוּ עַל צַעֲקָתִי? וְכִי אֲנִי לְאָדָם כָּמוֹנִי מֵשִׂיחַ, שֶׁיִּשְׁמַע קוֹלִי? וְאִם מַדּוּעַ לֹא תִקְצַר רוּחִי, לִצְעוֹק מִצָּרָה לִי?",1,0],[21,5,"פְּנוּ אֵלַי. לִשְׁמֹעַ:",1,0],[21,5,"וְהָשַׁמּוּ. הִתְּמְהוּ לִדְבָרַי:",2,0],[21,5,"וְשִׂימוּ יָד עַל פֶּה. שֶׁלֹּא תֵדְעוּ לְהָשִׁיב:",3,0],[21,6,"וְאִם זָכַרְתִּי. דָּבָר שֶׁאֲנִי רוֹצֶה לוֹמַר מַדּוּעַ רְשָׁעִים יִחְיוּ?!",1,0],[21,6,"וְנִבְהָלְתִּי. שֶׁאֲנִי רוֹאֶה רִשְׁעֵי דּוֹר הַמַּבּוּל עָתְקוּ גַּם גָּבְרוּ חַיִל (בראשית ו:א-ד):",2,0],[21,9,"שָׁלוֹם מִפָּחַד. שֶׁלֹּא הָיוּ מַזִּיקִין שׁוֹלְטִין בָּהֶן:",1,0],[21,10,"שׁוֹרוֹ עִבַּר. אֶת הַנְּקֵבָה:",1,0],[21,10,"וְלֹא יַגְעִל. לֹא יוֹרֶה בָּהּ זֶרַע פְּסֹלֶת, שֶׁיְּהֵא חוֹזֵר וְנִפְלָט מִגּוּפָהּ בְּלֹא הֵרָיוֹן. כָּל לְשׁוֹן הַגְעָלָה – פְּלִיטָה הוּא; וְכֵן בִּלְשׁוֹן מִשְׁנָה: מַגְעִילָן בְּרוֹתְחִין (עבודה זרה עה.); וְכֵן ״כִּי שָׁם נִגְעַל מָגֵן גִּבּוֹרִים״ (שמואל ב א:כא) – נִפְלַט מְשִׁיחָתוֹ, וְהָיָה כְּאִלּוּ לֹא נִמְשַׁח בְּשֶׁמֶן; שֶׁהָיוּ רְגִילִין לִמְשֹׁחַ מָגִנֵּי עוֹר, כְּדֵי שֶׁיְּהֵא חָלָק וּמַחֲלִיק אֶת הָרֹמַח וְהַחֲנִית הַמַּכֶּה בּוֹ; וְהוּא כְּמוֹ ״שָׂרִים מָשְׁחוּ מָגֵן״ (ישעיה כא:ה):",2,0],[21,10,"תְּפַלֵּט פָּרָתוֹ. בָּעֵת תֵּלֵד אֶת וְלָדָהּ:",3,0],[21,10,"וְלֹא תְשַׁכֵּל. בְּלֹא עֵת:",4,0],[21,11,"יְשַׁלְּחוּ כַצֹּאן עֲוִילֵיהֶם וְגוֹ׳. בְּעֵת לֵידָתוֹ, הָיָה הוֹלֵךְ וּמְרַקֵּד מִיָּד; וְאִם פּוֹגֵעַ בְּמַזִּיק, נִלְחָם בּוֹ. וְהָיְתָה אוֹמֶרֶת לוֹ אִמּוֹ: הָבֵא לִי מִסְפָּרַיִם, וַאֲחַתּוֹךְ שָׁרְךָ! (הגדת בראשית) לֵךְ וְהַדְלֵיק לִי אֶת הַנֵּר! (בראשית רבה לו:א):",1,0],[21,12,"יִשְׂאוּ. הָיוּ נוֹשְׂאִין קוֹל בְּשִׁיר בְּתֹף וְכִנּוֹר. עוּגָב אֵינוֹ אֶלָּא לְשׁוֹן שְׂחוֹק, עַל שֵׁם הָעֲגָבוֹת; אשביימנ״ט בְּלַעַ״ז. כָּךְ שָׁמַעְתִּי:",1,0],[21,13,"וּבְרֶגַע שְׁאוֹל יֵחָתּוּ. כְּשֶׁמַּגִּיעַ יוֹם מוֹתוֹ, הָיָה מֵת לְפִי שָׁעָה, בְּנַחַת בְּלֹא יִסּוּרִין:",1,0],[21,13,"יֵחָתּוּ. יֵרְדוּ, וּבְתַרְגּוּם: ״נְחִיתוּ״:",2,0],[21,15,"וּמַה נּוֹעִיל. מַה הֲנָאָה יֵשׁ לָנוּ כִּי נִפְגַּע בּוֹ? אֵין אָנוּ צְרִיכִין לוֹ אֲפִלּוּ לְטִפַּת גְּשָׁמִים, כִּי ״אֵד יַעֲלֶה מִן הָאָרֶץ״ (בראשית ב:ו):",1,0],[21,16,"הֵן לֹא בְיָדָם טוּבָם. בִּתְמִיהַּ: וְכִי אֵין כָּל טוּבָם בְּיָדָם?",1,0],[21,16,"וַעֲצַת רְשָׁעִים רָחֲקָה מֶנִּי. אִיּוֹב הָיָה מְשַׁבֵּחַ בְּעַצְמוֹ, שֶׁרָאָה אוֹתָם וְלֹא נִמְנָה עִמָּהֶם:",2,0],[21,17,"כַּמָּה נֵר רְשָׁעִים יִדְעָךְ. לְמַעְלָה הוּא חוֹזֵר לָמָּה רְשָׁעִים יִחְיוּ, כַּמָּה תַּאֲרִיךְ זְמַן זֶה? וְחָזַר וּמְקַלְלָם: נֵר רְשָׁעִים יִדְעָךְ וְגוֹ׳:",1,0],[21,17,"חֲבָלִים. גּוֹרָל הָרָאוּי לָהֶם:",2,0],[21,19,"אֱלוֹהַּ יִצְפֹּן לְבָנָיו אוֹנוֹ. בִּתְמִיהַּ: וְכִי מִדָּה הִיא? שֶׁכֵּן זֶה הִרְשִׁיעַ כָּל יָמָיו, וִיהֵא בְּשָׁלוֹם וְיָמוּת בְּשָׁלוֹם, וְאוֹנוֹ – וְרִשְׁעוֹ יִצְפֹּן הַקָּדוֹשׁ בָּרוּךְ הוּא לְבָנָיו, לִלְקוֹת לָהֶם?!",1,0],[21,19,"יְשַׁלֵּם אֵלָיו וְיֵדָע. שֶׁבַח הוּא לְהַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁיְּשַׁלֵּם לָרָשָׁע עַצְמוֹ גְּמוּלוֹ, וְיָבִין שֶׁהִרְשִׁיעַ לַעֲשׂוֹת:",2,0],[21,20,"יִרְאוּ עֵינָיו כִּידוֹ. שִׁבְרוֹ, וְאֵינִי יָכוֹל לִמְצוֹא לוֹ דִּמְיוֹן בַּתּוֹרָה, כִּי אִם לְפִי עִנְיַן הַפָּסוּק נִרְאֶה שֶׁבֶר, וְכֵן הָרַב לֹא מָצָא לוֹ דִּמְיוֹן. (כִּידוֹ. לְשׁוֹן אֵידוֹ, אָלֶ״ף מִתְחַלֵּף בְּכָ״ף):",1,0],[21,21,"כִּי מַה חֶפְצוֹ בְּבֵיתוֹ אַחֲרָיו וּמִסְפַּר חֳדָשָׁיו חֻצָּצוּ. כִּי מַה הוּא חוֹשֵׁשׁ, שקלירי״ר בְּלַעַ״ז, וְחָפֵץ בְּבֵיתוֹ לְאַחַר מוֹתוֹ, לִדְאֹג בְּחַיָּיו בְּפֻרְעָנוּת הָעֲתִידָה לָבֹא עֲלֵיהֶם, אַחֲרֵי שֶׁמִּסְפַּר חֳדָשָׁיו נִקְבְּצוּ וְיִכְלוּ לִפְנֵי הָרָעָה שֶׁהִבְטִיחָם הַמָּקוֹם ״וְהָיוּ יָמָיו מֵאָה וְעֶשְׂרִים שָׁנָה: (בראשית ו:ג)? זֹאת הִיא שֶׁאָמַרְתִּי לָכֶם: ״פְּנוּ אֵלַי וְהָשַׁמּוּ״ (איוב כא:ה):",1,0],[21,22,"הֲלָאֵל יְלַמֶּד דָּעַת. הֲיֵשׁ אֶחָד מִכֶּם אֲשֶׁר הוּא תַּחַת הָאֵל, שֶׁיְּלַמֵּד דַּעַת, מַה הִיא הַמִּדָּה הַזֹּאת?",1,0],[21,22,"וְהוּא רָמִים יִשְׁפּוֹט. כְּגוֹן אֲנִי וְהַצַּדִּיקִים וְהַחֲשׁוּבִים הוּא מְיַסֵּר וְדָן וְנִפְרָע מֵהֶם, כְּמוֹ ״וְלֹא יִפְנֶה דֶּרֶךְ כְּרָמִים״ (איוב כד:יח) הָאָמוּר בְּנֹחַ וּבִמְתוּשֶׁלַח בְּאַגָּדַת חֵלֶק (סנהדרין קח.-קח:). לָשׁוֹן אַחֵר: הַלְאֵל יְלַמֶּד דָּעַת, כְּלוֹמַר: הַאֲנִי צָרִיךְ לְלַמְּדוֹ דַּעַת לִשְׁפּוֹט אֱמֶת? הוּא עַצְמוֹ יוֹדֵעַ שֶׁכֵּן! אֲבָל הוּא יִשְׁפּוֹט דִּינִים רָמִים בְּגָבְהוֹ וּבְגָדְלוֹ, וְאֵינוֹ חָשׁ לְדַקְדֵּק. זֶה שָׁמַעְתִּי, וְלֹא הָרִאשׁוֹן:",2,0],[21,23,"זֶה. הָרָשָׁע:",1,0],[21,23,"יָמוּת. נֶעֱנַשׁ בְּעֶצֶם תֻּמּוֹ, בְּמַרְאֵה שְׁלֵימוּתוֹ, לֹא חָסֵר:",2,0],[21,23,"שַׁלְאֲנַן. כְּמוֹ ״שַׁאֲנָן״ (ירמיהו מח:יא):",3,0],[21,24,"עֲטִינָיו מָלְאוּ חָלָב. לְשׁוֹן מִשְׁנָה הוּא (מנחות פו.): ״עוֹטְנוֹ בְּבֵית הַבַּד״ – צוֹבְרִים הַזֵּיתִים יַחַד וְשׁוּמָנָן מִתְעַגֵּל וּמִתְאַסֵּף לְתוֹכוֹ, כְּדֵי שֶׁיְּהֵא מוּכָן כְּשֶׁעוֹצְרוֹ בְּבֵית הַבַּד; וְאוֹתוֹ כְּלִי שֶׁצּוֹבְרִין אוֹתוֹ כְּדֵי לְהֵאָסֵף שַׁמְנוֹ לְתוֹכוֹ, נִקְרָא ״מַעֲטָן״. אַף כָּאן: חֶלְבּוֹ וְלַחְלוּחוֹ וְשׁוּמָנוֹ נִקְרָא עֲטִינָיו:",1,0],[21,25,"וְזֶה יָמוּת בְּנֶפֶשׁ מָרָה. הָרָמִים וְהַקְּדוֹשִׁים אֵלָיו, יִפְרַע מִיָּד מֵהֶם:",1,0],[21,26,"יַחַד עַל עָפָר יִשְׁכָּבוּ. וּלְאַחַר מוֹתָן אֵין נִכָּר לַבְּרִיּוֹת, מִי הָרַע מִי הַטּוֹב, כִּי כָזֶה כֵּן זֶה יַחַד עַל עָפָר יִשְׁכָּבוּ:",1,0],[21,27,"הֵן יָדַעְתִּי מַחְשְׁבוֹתֵיכֶם. וְהַמְּזִמּוֹת אֲשֶׁר עָלַי תַּחְמֹסוּ – תָּרֵיעוּ לַחְשֹׁב חָמָס:",1,0],[21,28,"כִּי תֹאמְרוּ וְגוֹ׳. בִּשְׁבִיל הָרָעָה אֲשֶׁר בָּאַתְנִי אַתֶּם אוֹמְרִים: רְאוּ, אַיֵּה בֵיתוֹ שֶׁל זֶה, שֶׁהָיָה נָדִיב, וְאַיֵּה אֹהֶל וּמִשְׁכְּנוֹת שְׁאָר רְשָׁעִים? כְּלוֹמַר: כָּמוֹהוּ כָּמוֹהֶם, בְּרִשְׁעוֹ אָבַד בֵּיתוֹ (וְלָמָּה אַתֶּם בּוֹטְחִים בְּשַׁלְוַתְכֶם):",1,0],[21,29,"הֲלֹא שְׁאֶלְתֶּם וְגוֹ׳. כָּל זֶה אַתֶּם מוֹשְׁלִים עָלַי מְשָׁלוֹת:",1,0],[21,29,"וְאֹתֹתָם. אֲשֶׁר הוֹדִיעוּ אֶתְכֶם, לֹא תְנַכְּרוּם מִשּׂוּם עַל לֵב, כְּמוֹ ״וַיִּתְנַכֵּר אֲלֵיהֶם״ (בראשית מב:ז):",2,0],[21,30,"כִּי לְיוֹם. אָמְרוּ לָכֶם, אֲשֶׁר לְיוֹם אֵיד יֵחָשֶׂךְ רָע, הָרָשָׁע מוֹנֵעַ וְנֶחְשָׂךְ מֵרָעָה, וְשָׁמוּר לְיוֹם הַקָּבוּעַ לְאֵידוֹ. כְּמוֹ ״אֲשֶׁר חָשַׂכְתִּי לְעֵת צָר״ (איוב לח:כג) – הִצְנַעְתִּים וַחֲשַׂכְתִּים לְהוֹדִיעָם עַד יוֹם קְרָב וּמִלְחָמָה:",1,0],[21,31,"מִי יַגִּיד עַל פָּנָיו דַּרְכּוֹ. מִי הוּא הַמֶּלֶךְ הַגָּדוֹל אֲשֶׁר יַגִּיד עַל פָּנָיו דַּרְכּוֹ? וְלֹא יִרְאוּ מִמֶּנּוּ, כַּמָּה הוּא נִשְׂגָּב זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁעָשָׂה!",1,0],[21,31,"וּמִי יְשַׁלֶּם לוֹ. וּגְמוּל רִשְׁעוֹ מִי יְשַׁלֶּם לוֹ?",2,0],[21,32,"וְהוּא לִקְבָרוֹת יוּבָל. סוֹפוֹ יוּבַל לַקֶּבֶר:",1,0],[21,32,"וְעַל גָּדִישׁ יִשְׁקוֹד. כְּשֶׁהוּא נִקְבָּר בַּשָּׂדוֹת אֵצֶל הַגְּדִישִׁים. (וְעַל גָּדִישׁ יִשְׁקוֹד. יָדוּנוּ אוֹתוֹ עַל שֶׁלֹּא קִיֵּם הַמִּצְווֹת הַשַּׁיָּכִים בַּשָּׂדֶה, לֶקֶט שִׁכְחָה וּפֵאָה, וּשְׁאָר מִצְווֹת הַנּוֹהֲגִים בָּעֹמֶר וּבַגָּדִישׁ; וְלָכֵן שָׁקְדוּ וִימַהֲרוּ עָלָיו הַפֻּרְעָנוּת הג״ה מר״ע):",2,0],[21,33,"רִגְבֵי. בְּלַשְׁטְ״ז בְּלַעַ״ז:",1,0],[21,33,"וּלְפָנָיו אֵין מִסְפָּר. לַנִּמְשָׁכִים לְאוֹתוֹ דֶּרֶךְ. כָּל אֵלֶּה מְזִמּוֹת תַּחְמְסוּ עָלַי (איוב כא:כז):",2,0],[21,34,"וְאֵיךְ תְּנַחֲמוּנִי הָבֶל. מֵאַחַר שֶׁתְּשׁוּבוֹתֵיכֶם נִשְׁאַר מָעַל, נִשְׁכְּחָה וְאָבְדָה מִכֶּם תְּשׁוּבוֹת הַחָכְמָה; וּתְשׁוּבוֹתֵיכֶם לֹא נִשְׁאֲרָה בְּיֶדְכֶם אֶלָּא תְּשׁוּבַת מָעַל. מָעַל. שֵׁם דָּבָר הוּא, לְכָךְ נִנְקַד כֻּלּוֹ קָמַץ, וְטַעֲמוֹ מִלְּעֵיל. כָּךְ שָׁמַעְתִּי:",1,0],[22,2,"(מענה אליפז):הַלְאֵל יִסְכָּן גָּבֶר. הַלְצֹרֶךְ וּלְהַנָּאַת הַיּוֹצֵר יוֹעִיל גֶּבֶר וְיֵהָנֶה, כַּאֲשֶׁר יְלַמֵּד דַּעַת אֶל הַבְּרִיּוֹת, וְחָכְמָה? יִסְכָּן הָרִאשׁוֹן – לְשׁוֹן הֲנָיָה, כְּמוֹ ״וַתְּהִי לוֹ סֹכֶנֶת״ (מלכים א א:ב); וְהַשֵּׁנִי – לְשׁוֹן לִמּוּד, כְּמוֹ ״הַהַסְכֵּן הִסְכַּנְתִּי״ (במדבר כב:ל). וְגַם הָרִאשׁוֹן יִתָּכֵן לִהְיוֹת נִפְתָּר לְשׁוֹן לִמּוּד: הַלְטוֹבַת הַיּוֹצֵר וּלְצָרְכּוֹ יִלְמַד גֶּבֶר כַּאֲשֶׁר יִלְמַד הַשְׂכֵּל?",1,0],[22,3,"הַחֵפֶץ לְשַׁדַּי. כְּמוֹ ״כִּי מַה חֶפְצוֹ בְּבֵיתוֹ אַחֲרָיו״ (איוב כא:כא)? הַהֲנָאָה וַחֲשָׁשׁ לוֹ, אִם תַּצְדִּיק מַעֲשֶׂיךָ בְּהִתְוַכֵּחַ לְפָנָיו, שֶׁיָּבֹא עִמְּךָ לְהִתְוַכֵּחַ בִּדְבָרֶיךָ?",1,0],[22,3,"וְאִם בֶּצַע. מָמוֹן לוֹ, אִם תַּתֵּם דְּרָכֶיךָ?",2,0],[22,4,"הֲמִיִּרְאָתְךָ יוֹכִיחֶךָ. אוֹ אִם מִיִּרְאָה שֶׁיִּירָא מִפָּנֶיךָ יָבֹא וְיִתְוַכַּח עִמְּךָ?",1,0],[22,5,"הֲלֹא. יוֹדֵעַ הוּא כִּי רָעָתְךָ רַבָּה:",1,0],[22,8,"וְאִישׁ זְרוֹעַ לוֹ הָאָרֶץ. בִּתְמִיהַּ וְכִי מֵחֲמַת שֶׁהָיִיתָ גָּדוֹל תִּירַשׁ אֶת הָאָרֶץ? כְּלוּם הוּא רָאוּי לְהִתְקַיֵּם?",1,0],[22,8,"יֵשֶׁב בָּהּ. יַאֲרִיךְ בָּהּ, כְּמוֹ ״וַתֵּשְׁבוּ בְקָדֵשׁ״ (דברים א:מו):",2,0],[22,11,"אוֹ חֹשֶׁךְ לֹא תִרְאֶה. כְּלוֹמַר: לֹא תִתֵּן עֵינֶיךָ וּבִטְחוֹנְךָ בַּכֹּחַ, לֵאמֹר:",1,0],[22,12,"הֲלֹא אֱלוֹהַּ גֹּבַהּ שָׁמָיִם. וְלֹא יַשְׁפִּיל לִרְאוֹת:",1,0],[22,12,"וּרְאֵה רֹאשׁ כּוֹכָבִים כִּי רָמּוּ. כְּמוֹ ״וּרְאֵה עָנְיִי״ שֶׁבְּסוֹף מַעֲנֶה הַחֲמִישִׁי (איוב י:טו), כְּלוֹמַר: וְנוֹתֵן אַתָּה עַיִן בְּרֹאשׁ כּוֹכָבִים כִּי רָמּוּ. וּבִשְׁבִיל כָּךְ אָמַרְתָּ:",2,0],[22,13,"מַה יָּדַע אֵל. בְּמַעֲשֵׂה הַחֹשֶׁךְ?",1,0],[22,13,"הֲבְעַד עֲרָפֶל יִשְׁפּוֹט. הַכְּנֶגֶד הַחֹשֶׁךְ הַזֶּה יִרְאֶה וְיִשְׁפּוֹט? הִנֵּה:",2,0],[22,14,"עָבִים סֵתֶר. לְפָנָיו וְלֹא יוּכַל לִרְאוֹת:",1,0],[22,14,"וְחוּג שָׁמַיִם יִתְהַלָּךְ. וְלֹא יֵדַע אֶת אֲשֶׁר בָּאָרֶץ:",2,0],[22,14,"חוּג. עוֹגֶל מְחוּגַת שָׁמַיִם, כְּמוֹ ״וּבַמְּחוּגָה יְתָאֳרֵהוּ״ (ישעיהו מד:יג). קוֹמְפָּ״שׁ בְּלַעַ״ז:",3,0],[22,15,"הָאֹרַח עוֹלָם. הַדֶּרֶךְ הָרִאשׁוֹנִים אֲשֶׁר מֵאָז:",1,0],[22,15,"תִּשְׁמֹר. שָׁמַרְתָּ בְּלִבְּךָ, לִזְכּוֹר מַה נִּהְיְיתָה בָּהֶם?",2,0],[22,16,"קֻמְּטוּ וְלֹא עֵת. נִגְזְרוּ בְּלֹא עִתָּם:",1,0],[22,16,"נָהָר וְגוֹ׳. וְנָהָר שֶׁל מַבּוּל אוֹ גָּפְרִית וָאֵשׁ שֶׁל סְדוֹם (בראשית יט:כד), הוּצַק בִּיסוֹדָם:",2,0],[22,20,"אִם לֹא נִכְחַד קִימָנוּ. הֲתִשְׁמֹר וְרָאִיתָ אִם לֹא נִכְחַד יְקוּמָם?",1,0],[22,20,"קִימָנוּ. כְּמוֹ קוֹמָתוֹ שֶׁל אוֹתוֹ הַדּוֹר, כְּמוֹ ״בֵּית אֵל יִמְצָאֶנּוּ וְשָׁם יְדַבֵּר עִמָּנוּ״ (הושע יב:ה) – כְּמוֹ ׳עִמּוֹ׳:",2,0],[22,20,"וְיִתְרָם. גַּאֲוָתָם:",3,0],[22,20,"אָכְלָה אֵשׁ. בְּרוֹתְחִין נִדּוֹנוּ. רַבִּי תַּנְחוּמָא דָּרַשׁ (תנחומא, נח י), שֶׁהָיוּ בַּעֲלֵי קוֹמָה, וְלֹא מֵתוּ בַּתְּהוֹמוֹת, וּבָאוּ עֲלֵיהֶם רוֹתְחִין מִלְמַעְלָה; וְזֶה יִתְרָם – קִימָה יְתֵרָה שֶׁלָּהֶם, כָּךְ שָׁמַעְתִּי:",4,0],[22,21,"הַסְכֶּן. לְמוֹד לִהְיוֹת עִמּוֹ שָׁלֵם:",1,0],[22,21,"וּשְׁלָם. וְתִהְיֶה שָׁלֵם וְלֹא תֶחְסַר בָּהֶם בַּדְּבָרִים הָאֵלֶּה:",2,0],[22,21,"תְּבוֹאַתְךָ טוֹבָה. תְּבוֹאֲךָ טוֹבָה:",3,0],[22,24,"וְשִׁית עַל עָפָר בָּצֶר. עַל אֲשֶׁר תָּשׁוּב אֵלָיו, תָּשִׁית עַל הָאָרֶץ חֹסֶן וּמִבְצָרִים:",1,0],[22,24,"וּבְצוּר נְחָלִים. הַסְּלָעִים גְּבוֹהִים שֶׁבַּנְּחָלִים עֲמוּקִים יִהְיֶה לְךָ אֹסֶף צְבִירַת אוֹפִיר – הִיא סְגֻלַּת מְלָכִים, שֶׁהָיוּ מְסַגְּלִים וְאוֹצְרִים זָהָב הַבָּא מֵאוֹפִיר:",2,0],[22,25,"וְהָיָה שַׁדַּי בְּצָרֶיךָ. אִם שַׁדַּי זֶה קֹדֶשׁ תָּמַהְתִּי עַל פִּתְרוֹנוֹ, שֶׁמַּשְׁמָעוֹ קְלָלָה שֶׁיִּמָּנֶה עִם אוֹיְבָיו כְּמוֹ ״וְאַתְּ הָיִית בְּעֹכְרָי״ (שופטים יא:לה) עִם עוֹכְרָי. וְעַל יְדֵי צֹרֶךְ נְדוּנֶנּוּ מִן הַמִּקְרָאוֹת חֲסֵרִים (כְּמוֹ וְהָיָה שַׁדַּי שׁוֹפֵט בְּצָרִיךְ, וְאִם נוּכַל לְאָמְרוֹ חוֹל לְשׁוֹן דַּיָּן וְחֹסֶן זֶה פִּתְרוֹנוֹ) וְהָיָה חֹסֶן מִבְצָרֶיךָ כְּמוֹ וְשִׁית עַל עָפָר בָּצֶר כְּלוֹמַר הוֹן עָתֵק תִּהְיֶה נִבְצָר. וּלְפִי הָעִנְיָן כֵּן פִּתְרוֹנוֹ שֶׁהֲרֵי סוֹפוֹ מוֹכִיחוֹ וְכֶסֶף תּוֹעָפוֹת לָךְ לְשׁוֹן חֹסֶן כְּמוֹ ״וְתוֹעֲפֹת רְאֵם לוֹ״ (במדבר כג:כב):",1,0],[22,26,"וְתִשָּׂא אֶל אֱלוֹהַּ פָּנֶיךָ. לֹא תָבֹא לְהָרִים פָּנֶיךָ אֶלָּא לִשְׁאוֹל צְרָכֶיךָ הֵימֶנּוּ:",1,0],[22,27,"וּנְדָרֶיךָ תְשַׁלֵּם. מֻבְטָח אַתָּה, שֶׁיֵּרָצוּ קָרְבְּנוֹת תַּשְׁלוּמֵי נְדָרֶיךָ:",1,0],[22,28,"וְיָקָם לָךְ. כְּמוֹ וְיָקוּם לָךְ:",1,0],[22,29,"כִּי הִשְׁפִּילוּ וַתֹּאמֶר גֵּוָה. וְאִם רוֹאֲךָ דּוֹרֵךְ שָׁפָל, תֹּאמַר בְּהַבְטָחָה לְהַגְבִּיהוֹ, וְיִגְבַּהּ:",1,0],[22,29,"וְשַׁח עֵינַיִם. בַּצָּרָה הַבָּאָה (אֵלָיו) בַּעֲוֹנוֹ:",2,0],[22,29,"יוֹשִׁעַ. אוֹתוֹ אֱלוֹהַּ בְּיָדְךָ וּבִתְפִלָּתְךָ:",3,0],[22,30,"יְמַלֵּט אִי נָקִי. אֵין נָקִי, כְּמוֹ ״אִי כָבוֹד״ (שמואל א ד:כא) – אֵין כָּבוֹד, וְכֵן ״וּלְרוֹזְנִים אֵי שֵׁכָר״ (משלי לא:ד) – אֵין שֵׁכָר, אֵין נָאֶה לָהֶם שִׁכְרוּת. שְׁלָשְׁתָּן חִבְּרָם מְנַחֵם בְּמַחֲלֹקֶת אַחַת. וְאַף עַל פִּי שֶׁהֵן שְׁתֵּי תֵיבוֹת, מְפָרְשִׁין כֵּן: וְנִמְלַט אֶת אִי נָקִי בְּבֹר כַּפֶּיךָ, וְכֵן שָׁמַעְתִּי. לָשׁוֹן אַחֵר שָׁמַעְתִּי, שֶׁהָיוּ אוֹמְרִים מִפִּי רַבִּי יַעֲקֹב, שֶׁהוּא לְשׁוֹן אָדָם הַשָּׁרוּי בְּצַעַר וּבַאֲנָקָה, וְהַיּוֹ״ד יְתֵרָה בַּתֵּיבָה, כְּמוֹ ״הַיֹּשְׁבִי בַשָּׁמָיִם״ (תהלים קכג:א). אֲבָל לֹא שָׁמַעְתִּי מִפִּי הָרַב:",1,0],[23,2,"(מענה איוב): גַּם הַיּוֹם. אַחַר כָּל תַּנְחוּמִין הַלָּלוּ:",1,0],[23,2,"מְרִי שִׂיחִי. בִּמְקוֹמוֹ עוֹמֵד, כִּי אֵין תַּנְחוּם בְּדִבְרֵיכֶם:",2,0],[23,2,"יָדִי כָּבְדָה. מַכַּת נִגְעִי תַּקִּיפָה יוֹתֵר מֵאַנְחָתִי; שֶׁאֵינִי קוֹבֵל וְצוֹעֵק לְפִי מַכָּתִי:",3,0],[23,3,"וְאֶמְצָאֵהוּ. לְשׁוֹפְטִי:",1,0],[23,3,"תְּכוּנָתוֹ. מְכוֹן כִּסְאוֹ:",2,0],[23,4,"מִשְׁפָּט. הוֹכָחַת דְּבָרִים:",1,0],[23,5,"(אֵדְעָה מִלִּים יַעֲנֵנִי. וְגַם אִם יִסְתֹּם אוֹתִי מִלְּדַבֵּר לְפָנָיו, שֶׁמָּא יְדַבֵּר הוּא עִמִּי, וְאֵדְעָה מִלִּים יַעֲנֵנִי רַבִּי תַּנְחוּמָא (תנחומא, בראשית יג)):",1,0],[23,6,"הַבְּרָב כֹּחַ. דְּבָרִים וְתוֹכָחוֹת שֶׁל חֲטָאָיו יָרִיב עִמָּדִי:",1,0],[23,6,"לֹא אַךְ. מַכָּה וּכְפִיָּה. לֹא יָשִׂים בִּי אָכְפּוֹ וְאֵימָתוֹ. (וְעוֹד יִפָּתֵר:) לֹא אַךְ הוּא יָשִׂים בִּי, כִּי לֹא יָשִׂים בִּי אַךְ הָרִיב שֶׁל תּוֹכַחַת פְּשָׁעַי, וְלֹא תְשׂוּמוֹת עֲלִילוֹת:",2,0],[23,7,"שָׁם. בִּמְקוֹם רִיבֵנוּ:",1,0],[23,7,"יָשָׁר. כֹּשֶׁר מִפְעֲלוֹתַי יְהֵא נוֹכָח וְנִגְלֶה וְנִרְאֶה עִמּוֹ, לְפָנָיו:",2,0],[23,7,"נוֹכָח. מוּכָח, וְשָׁם אֲפַלְּטָה לָנֶצַח – כִּי לֹא יִמְצָא בִי עָוֹן:",3,0],[23,8,"הֵן קֶדֶם. לְמַעְלָה הוּא חוֹזֵר, לְמִי יִתֵּן יָדַעְתִּי וְגוֹ׳:",1,0],[23,8,"קֶדֶם. מִזְרָח, שֶׁנֶּאֱמַר ״קֵדְמָה מִזְרָחָה״ (שמות כז:יג):",2,0],[23,8,"אָחוֹר. מַעֲרָב. הוֹאִיל וְהַמִּזְרָח – קִדְמַת עוֹלָם, נִמְצָא הַמַּעֲרָב – אֲחוֹרָיו שֶׁל עוֹלָם:",3,0],[23,9,"שְׂמֹאל. צָפוֹן:",1,0],[23,9,"בַּעֲשׂוֹתוֹ. כְּשֶׁבְּרָאוֹ, לֹא עָשָׂה מְקוֹם כִּסְאוֹ שָׁם שֶׁאֶרְאֶנּוּ שָׁם:",2,0],[23,9,"אָחַז. תַּרְגּוּם שֶׁל ״אֶרְאֶה״ (בראשית כא:טז). וְתֵדַע, שֶׁהַטַּעַם תַּחַת הָאָלֶ״ף; וְאִם לְשׁוֹן אֲחִיזָה הוּא, הָיָה טַעֲמוֹ מִלְּרַע, תַּחַת הַחֵי״ת:",3,0],[23,9,"יַעְטֹף יָמִין. כִּסָּה פְּנֵי הַדָּרוֹם בְּפָנָיו, לְמַעַן לֹא אֶרְאֶנּוּ:",4,0],[23,10,"כִּי יָדַע דֶּרֶךְ וְגוֹ׳. אֲשֶׁר עִמָּדִי מַהוּ, לְפִיכָךְ אֵינוֹ בָּא לָרִיב עִמָּדִי:",1,0],[23,10,"בְּחָנַנִי וְגוֹ׳. אֲשֶׁר כַּזָּהָב אֵצֵא אִם יָרִיב עִמָּדִי:",2,0],[23,11,"בְּאֲשׁוּרוֹ. בְּמַעְגָּלוֹ, כְּמוֹ ״אִם תִּטֶּה אֲשׁוּרִי״ (איוב לא:ז), ״כּוֹנֵן אֲשׁוּרָיו״ (תהלים מ:ג):",1,0],[23,11,"וְלֹא אָט. אֵינִי רָגִיל לִנְטוֹת:",2,0],[23,12,"מֵחֻקִּי צָפַנְתִּי אִמְרֵי פִיו. יוֹתֵר מֵחֻקֵּי מְזוֹנוֹתַי הָיִיתִי זָרִיז לִצְפֹּן אִמְרֵי פִיו, כְּמוֹ ״לֶחֶם חֻקִּי״ (משלי ל:ח) – מְזוֹנוֹתַי:",1,0],[23,13,"וְהוּא. לְפִי שֶׁהוּא יָחִיד בָּעוֹלָם, וְיוֹדֵעַ דַּעְתָּן וּמַחֲשַׁבְתָּן שֶׁל בְּרִיּוֹת וּמַה יֵּשׁ לָהֶם לְדַבֵּר לְפָנָיו, לְפִיכָךְ תְּשׁוּבוֹת מוּכָנוֹת לְפָנָיו:",1,0],[23,13,"וּמִי יְשִׁיבֶנּוּ. לְפִיכָךְ נַפְשׁוֹ אִוְּתָה וַיָּעַשׂ:",2,0],[23,14,"כִּי יַשְׁלִים חֻקִּי. יָדַעְתִּי כִּי לֹא יָשִׁיב יָדוֹ עַד אֲשֶׁר יַשְׁלִים חֹק גְּזֵרוֹתָיו – פֻּרְעָנִיּוֹת אֲשֶׁר גָּזַר עָלַי:",1,0],[23,14,"וְכָהֵנָּה רַבּוֹת עִמּוֹ. כִּי כָהֵנָּה רַבּוֹת עָשָׂה:",2,0],[23,15,"עַל כֵּן. שֶׁאֵינוֹ גּוֹמֵל לָאָדָם כְּפִי דְרָכָיו:",1,0],[23,15,"מִפָּנָיו אֶבָּהֵל. וּכְשֶׁאֶתְבּוֹנֵן בִּדְרָכָיו, אֶפְחַד מִמֶּנּוּ:",2,0],[23,17,"כִּי לֹא נִצְמַתִּי מִפְּנֵי חֹשֶׁךְ. בָּזֹאת אֲנִי נִבְהָל, כִּי לֹא נִצְמַתִּי לַחֲלוּטִין וּצְמִיתוּת קֶבֶר מִפְּנֵי הַחֹשֶׁךְ הַזֶּה הַבָּא עָלַי; וְכֵן לֹא כִסָּה מִפָּנַי אֶת הָאֹפֶל הַזֶּה עַד מוֹתִי:",1,0],[23,17,"וּמִפָּנַי כִּסָּה אֹפֶל. עַל כִּי לֹא שֶׁבְּרֹאשׁ הַפָּסוּק, חוֹזֵר:",2,0],[24,1,"מַדּוּעַ מִשַּׁדַּי לֹא נִצְפְּנוּ עִתִּים. קַבָּלָה הוּא זֶה: לָמָּה לֹא נִצְפְּנוּ עִתֵּי יְמֵי הָאָדָם מִן הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁלֹּא יֵדַע יוֹם מוֹת הָאָדָם? שֶׁמָּא לֹא יְמַהֵר פֻּרְעָנוּת, וִיקַדְּמֶנּוּ יוֹם הַמִּיתָה:",1,0],[24,1,"וְיוֹדְעָיו לֹא חָזוּ יָמָיו. מִיּוֹם הָאָדָם, כְּמוֹ ״חֹדֶשׁ יָמִים״ (בראשית כט:יד). (ומְתַּרְגְּמִינָן ״עִדַן בְּעִדַן״ (סא״א)). דָּבָר אַחֵר: מַדּוּעַ יוֹדְעָיו וְאוֹהֲבָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינָן יְכוֹלִין לִרְאוֹת סוֹף דְּרָכָיו וּמִדּוֹתָיו?",2,0],[24,1,"יָמָיו. זוֹ הִיא דֶּרֶךְ שֶׁנָּהַג בְּיָמָיו, כְּמוֹ ״לֹא יֶחֱרַף לְבָבִי מִיָּמָי״ (איוב כז:ו). וּמָה הֵן הַמִּדּוֹת הַתְּמוּהוֹת?",3,0],[24,2,"גְּבוּלוֹת יַשִּׂיגוּ. אוֹתָן שֶׁדַּרְכָּן לְהַסִּיג גְּבוּלוֹת, שֶׁהֵן קוֹנִין שָׂדוֹת כְּנֶגֶד שָׂדוֹת אֲחֵרִים, וּבַלַּיְלָה הֵם מַרְבִּים גְּבוּלֵיהֶם, שֶׁהָיוּ עוֹשִׂים גְּדֵרֵיהֶם בַּלַּיְלָה בְּתוֹךְ תְּחוּם שְׁכֵינֵיהֶם. (וְזֶהוּ מַשִּׂיג דִּמְתַּרְגְּמִינָן ״מִשְׁגֶּה״ שֶׁהָיוּ מַשְׁגִּים הַגְּבוּל סא״א):",1,0],[24,2,"עֵדֶר גָּזְלוּ וַיִּרְעוּ. לְעַצְמָן:",2,0],[24,3,"חֲמוֹר יְתוֹמִים יִנְהָגוּ. וְעוֹשִׂין כָּל רָעוֹת הָאֲמוּרוֹת בָּעִנְיָן. סוֹף דָּבָר: וֵאלוֹהַּ לֹא יָשִׂים תִּפְלָה – לְהוֹדִיעָם עֲוֹנָם וּלְהַמְצִיאָם גְּמוּלָם:",1,0],[24,4,"יַחַד חֻבְּאוּ. עֲנִיֵּי אֶרֶץ מִפְּנֵי שֶׁיְּרֵאִים מֵהֶם:",1,0],[24,5,"הֵן פְּרָאִים. הַפְּרָאִים שֶׁהֵם לִמּוּדֵי מִדְבָּר (ירמיהו ב:כד), לֶאֱרֹב אֶת הָעוֹבְרִים:",1,0],[24,5,"יָצְאוּ בְּפָעֳלָם. יָצְאוּ לִמְלַאכְתָּן, וּמַה הִיא הַפְּעֻלָּה? מְשַׁחֲרֵי לַטָּרֶף. מְבַקְּשִׁים לִטְרוֹף:",2,0],[24,5,"עֲרָבָה לוֹ לֶחֶם לַנְּעָרִים. לִמְשָׁרְתָיו וּנְעָרָיו שֶׁל רָשָׁע, הָעֲרָבָה וְהַמִּדְבָּר הָוֶה לוֹ לֶחֶם לְצָרְכָּם, שֶׁמִּשָּׁם הוּא חוֹטֵף וְאוֹכֵל וְגוֹזֵל מַה שֶּׁהֵם אוֹכְלִים:",3,0],[24,5,"לַנְּעָרִים. הֵם הַהוֹלְכִים אִתּוֹ לִגְזוֹל, כְּמוֹ ״רַק אֲשֶׁר אָכְלוּ הַנְּעָרִים״ (בראשית יד:כד):",4,0],[24,6,"בַּשָּׂדֶה. שֶׁל אֲחֵרִים:",1,0],[24,6,"בְּלִילוֹ. יְבוּלוֹ:",2,0],[24,6,"יִקְצוֹרוּ. לִגְזוֹל:",3,0],[24,6,"וְכֶרֶם רָשָׁע יְלַקֵּשׁוּ. וּכְרָמִים שֶׁל אֲחֵרִים הָרְשָׁעִים הָאֵלּוּ נוֹטְלִים פִּרְיָם, יְלַקֵּשׁוּ אשפריימנ״ט נוֹטְלִים לֶקֶשׁ שֶׁלָּהֶם, לֶקֶשׁ לְשׁוֹן צֶמַח פְּרִי כְּמוֹ ״בִּתְחִלַּת עֲלוֹת הַלֶּקֶשׁ״ (עמוס ז:א) תִּרְגֵּם יוֹנָתָן צִימוּחַ וְכֵן יָסַד רַבִּי אֶלְעָזָר (בהושענא אדמה מארר) לֶקֶשׁ מֵאַרְבֶּה. (דָּבָר אַחֵר וְכֶרֶם רָשָׁע יְלַקֵּשׁוּ, יְלַקְּשׁוּ אוֹתָהּ מֵהַשְּׁחִיתָהּ, כִּי אֶת שֶׁל הָעֲנִיִּים וִיתוֹמִים הֵם אוֹכְלִים. יְלַקֵּשׁוּ כְּמוֹ ״וּפִיהֶם פָּעֲרוּ לְמַלְקוֹשׁ״ (איוב כט:כג) זְמַן אָרוֹךְ וּכְמוֹ ״לְקִישָׁיָּא לְלָבָן״ (אונקלוס בראשית ל:מב)):",4,0],[24,7,"עָרוֹם יָלִינוּ. הֵם מְלִינִים אֶת הָעֲנִיִּים:",1,0],[24,7,"מִבְּלִי לְבוּשׁ. שֶׁנָּטְלוּ כְּסוּיִן:",2,0],[24,8,"מִזֶּרֶם. הַיּוֹרֵד מִן הֶהָרִים יִרְטָבוּ וְיִתְלַחְלְחוּ אוֹתָן הָעֲרוּמִים, לְפִי שֶׁמִבְּלִי כִסּוּי אֵין מַחְסֶה לְהֵחָסוֹת בּוֹ:",1,0],[24,8,"חִבְּקוּ צוּר. נֶחְבָּאִים בִּנְקִיקֵי הַסְּלָעִים, וְגַם שָׁם הַזֶּרֶם יוֹרֵד וּמְקַלֵּחַ עֲלֵיהֶם וְרוֹטְבָם. רָטוֹב – תַּרְגּוּם שֶׁל ״לַח״ (בראשית ל:לז); וְכָל מִי שֶׁאֵינוֹ מְנֻגָּב קָרוּי ׳לַח׳:",2,0],[24,8,"יִרְטָבוּ. מוֹיִישְׁטָ״א בְּלַעַ״ז:",3,0],[24,9,"מִשֹּׁד יָתוֹם. יְנִיקַת הַיָּתוֹם, מְקוֹם מוֹצָא מַאֲכָלוֹ וּמְזוֹנוֹתָיו. כְּמוֹ ״וְשֹׁד מְלָכִים תִּינָקִי״ (ישעיהו ס:טז):",1,0],[24,9,"יַחְבֹּלוּ. לְשׁוֹן ״אִם חָבֹל תַּחְבֹּל״ (שמות כב:כה), וּכְמוֹ ״חֲבֹל לֹא יַחֲבֹל״ (יחזקאל יח:טז):",2,0],[24,10,"הָלְכוּ. הֵם הִלְּכוּהוּ בְּלִי לְבוּשׁ:",1,0],[24,10,"וּרְעֵבִים נָשְׂאוּ עֹמֶר. וּמֵרְעֵבִים נָטְלוּ הָעֳמָרִים שֶׁל לֶקֶט. וְעוֹד יִפָּתֵר וּרְעֵבִים – אוֹתָם שֶׁהָיוּ נוֹשְׂאִים עֹמֶר, לְפִי שֶׁאֵלּוּ גּוֹזְלִים אוֹתָם מֵהֶם, וְהָיוּ נִשְׁאָרִים רְעֵבִים:",2,0],[24,11,"בֵּין שׁוּרוֹתָם יַצְהִירוּ. וְיַעֲשׂוּ שֶׁמֶן, בַּעֲלֵי זֵיתִים:",1,0],[24,11,"וְיְקָבִים דָּרְכוּ. בַּעֲלֵי כְּרָמִים:",2,0],[24,11,"וַיִּצְמָאוּ. לְאַחַר זְמַן; לְפִי שֶׁאֵלּוּ הָרְשָׁעִים גּוֹזְלִים אוֹתָם מֵהֶם:",3,0],[24,11,"בֵּין שׁוּרוֹתָם. כִּמְדֻמֶּה לִי שֶׁעוֹשִׂין הַזֵּיתִים שׁוּרוֹת שׁוּרוֹת בְּבֵית הַבַּד, וְהַיִּצְהָר זָב בֵּינֵיהֶם:",4,0],[24,12,"מֵעִיר מְתִים יִנְאָקוּ. מְתֵיהָ וְטוֹבֵיהָ שֶׁל עִיר יִנָּאֲקוּ מֵחֲמַת אוֹתָן הָאוֹנְסִין:",1,0],[24,12,"לֹא יָשִׂים תִּפְלָה. לְהַקְפִּיד עֲלֵיהֶם וְלִיקַּח נְקָמָה:",2,0],[24,13,"הֵמָּה. הָרְשָׁעִים הָאֵלֶּה, הֵם דּוֹר הַמַּבּוּל שֶׁמָּרְדוּ בָּאוֹר, בִּשְׁבִיל הַמָּטָר שֶׁהָיָה עוֹלֶה מִן הָאָרֶץ (בראשית ב:ו), וְלֹא הָיוּ צְרִיכִים לִכְלוּם:",1,0],[24,14,"לָאוֹר יָקוּם. אִם הָיוּ עוֹמְדִים בַּיּוֹם, הָיוּ הוֹרְגִים עוֹבְרֵי דְרָכִים:",1,0],[24,14,"וּבַלַּיְלָה יְהִי כַגַּנָּב. לַחְתּוֹר בָּתִּים:",2,0],[24,15,"וְעֵין נוֹאֵף. וְהַנּוֹאֵף שֶׁבָּהֶם הָיָה שׁוֹמֵר וּמַמְתִּין עַד נֶשֶׁף, לֵאמֹר וְגוֹ׳:",1,0],[24,15,"וְסֵתֶר. וּבַסֵּתֶר יָשִׂים פָּנָיו לַעֲבוֹר עֲבֵירָה, שֶׁעַל כָּל אֵלֶּה הָיוּ חֲשׁוּדִין דּוֹר הַמַּבּוּל: עַל הַגֶּזֶל, שֶׁנֶּאֱמַר ״וַתִּמָּלֵא הָאָרֶץ חָמָס״ (בראשית ו:יא), וְעַל הָעֲרָיוֹת, שֶׁנֶּאֱמַר ״כִּי הִשְׁחִית כָּל בָּשָׂר״ (בראשית ו:יב):",2,0],[24,16,"יוֹמָם חִתְּמוּ לָמוֹ. אוֹתָם שֶׁהָיוּ חַלָּשִׁים מֵהֶם מֵעֲשׂוֹת לִסְטִיּוּת בַּיּוֹם, הָיוּ חוֹתְרִים בַּבָּתִּים בַּלַּיְלָה, וּבַיּוֹם הָיוּ חֲתוּמִים וּמְסֻגָּרִים בְּבָתֵּיהֶם:",1,0],[24,16,"לֹא יָדְעוּ אוֹר. לֹא הָיוּ מַכִּירִין אֶת הָאוֹר, וְלֹא הָיָה עֵת מַהֲלָכָם:",2,0],[24,17,"כִּי יַחְדָּו בֹּקֶר לָמוֹ צַלְמָוֶת. שֶׁבַּיּוֹם הָיוּ נִסְגָּרִים, וּבַלַּיְלָה הָיוּ הוֹלְכִים לְמַחְתַּרְתָּם, וְלֹא הָיוּ יְרֵאִים מִן הַמַּזִּיקִים כְּלָל:",1,0],[24,17,"כִּי יַכִּיר בַּלְהוֹת צַלְמָוֶת. מַכִּיר הָיָה כָּל אֶחָד שֵׁדִים הַמַּבְהִילִים, וְלֹא הָיָה יָרֵא מֵהֶם. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (סנהדרין קט.): יוֹמָם חָתְמוּ לָמוֹ – בַּיּוֹם הָיוּ עוֹשִׂים סִימָנִים, הֵיכָן מַרְתֵּפוֹ שֶׁל בַּיִת וְהֵיכָן גְּנָזָיו שֶׁל עָשִׁיר; שֶׁהָיוּ מַפְקִידִין אֲפַרְסְמוֹן אֵצֶל בַּעֲלֵי בָתִּים עֲשִׁירִים, וְיוֹדְעִים הֵם שֶׁיַּנִּיחֶנּוּ בְּבֵית גְּנָזָיו, וּבַלַּיְלָה מְרִיחִין וְהוֹלְכִים שָׁם וְחוֹתְרִים שָׁם:",2,0],[24,18,"קַל הוּא עַל פְּנֵי מַיִם. כְּשֶׁהָיוּ הַצַּדִּיקִים נֹחַ וּמְתוּשֶׁלַח מוֹכִיחִים אוֹתָם, וְאוֹמְרִים לָהֶם שֶׁעָתִיד הַמַּבּוּל לָבֹא עֲלֵיהֶם, הָיוּ אוֹמְרִים: קַלִּים אָנוּ לָשׁוּט עַל הַמַּיִם, וְיֵשׁ לָנוּ גֹּמֶא וּדְבָרִים קַלִּים, לַעֲשׂוֹת מֵהֶם אֳנִיּוֹת וְלָשׁוּט:",1,0],[24,18,"תְּקֻלַּל חֶלְקָתָם בָּאָרֶץ לֹא יִפְנֶה דֶּרֶךְ כְּרָמִים. הָיוּ מְקַלְּלִים אֶת חֶלְקָם בָּאָרֶץ לֵאמֹר לֹא יִפְנֶה דֶּרֶךְ הַטּוֹב בְּדַרְכֵי הַצַּדִּיקִים הָרָמִים וְשׁוֹכְנִים בְּרוּמוֹ שֶׁל עוֹלָם. לָשׁוֹן אַחֵר כְּרָמִים הֵם הַצַּדִּיקִים וּפַרְנְסֵי הַדּוֹר, כְּמוֹ ״וְנָתַתִּי לָהּ אֶת כְּרָמֶיהָ מִשָּׁם״ (הושע ב:יז) תִּרְגֵּם יוֹנָתָן ״יַת פַּרְנָסָהָא״, הָיוּ מְקַלְּלִים אֶת חֶלְקָם בָּאָרֶץ לֵאמֹר לֹא יִפְנוּ דֶּרֶךְ הַטּוֹב נִשְׁבָּעִים שֶׁלֹּא יִפְנוּ אֶת דַּרְכָּם. לָשׁוֹן אַחֵר תְּקֻלַּל חֶלְקָתָם מִתְקַלְקֶלֶת הָיְתָה חֶלְקָתָם שֶׁהָיוּ מַשְׁחִיתִים זַרְעָם לְבַטָּלָה, כְּמוֹ ״כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ״ (בראשית ו:יב), תְּקֻלַּל לְשׁוֹן קִלְקוּל, כְּמוֹ ״בַּעֲוֹן אֲשֶׁר יָדַע כִּי מְקַלְלִים לָהֶם בָּנָיו״ (שמואל א ג:יג). לָשׁוֹן אַחֵר תְּקֻלַּל חֶלְקָתָם הַדּוֹרוֹת שֶׁאַחֲרֵיהֶם מְקַלְּלִים בָּהֶם מִי שֶׁפָּרַע מִדּוֹר הַמַּבּוּל, כָּךְ שָׁמַעְתִּי. לָשׁוֹן אַחֵר תְּקֻלַּל חֶלְקָתָם לֹא יִפְנֶה דֶּרֶךְ כְּרָמִים, לֹא הָיוּ מְקַבְּלִים תּוֹכָחָה מִן הַטּוֹבִים. לָשׁוֹן אַחֵר הָיוּ קַלִּים לָשׁוּט בִּסְפִינוֹת לַהֲרֹג וְלַחְמֹס מָמוֹן וְדֶרֶךְ יִשּׁוּב בְּנֵי אָדָם וּנְטִיעַת כְּרָמִים אֵין חוֹשֵׁשׁ לֵילֵךְ:",2,0],[24,19,"צִיָּה גַם חֹם יִגְזְלוּ. מִפְּנֵי רָעָתָם גָּרְמוּ לָהֶם שָׁנָה אַחַת לְהִשְׁתַּנּוֹת עוֹלָם מִשִּׁשָּׁה סְדָרָיו: ״זֶרַע וְקָצִיר וְקֹר וָחֹם וְקַיִץ וָחֹרֶף״ (בראשית ח:כב):",1,0],[24,19,"מִימֵי שֶׁלֶג. כְּמוֹ ׳וּמִימֵי שֶׁלֶג׳, גַּם אוֹתָם גָּזְלוּ מִן הָעוֹלָם, לְפִי שֶׁשְּׁאוֹל חָטָאוּ. יֵשׁ תֵּיבוֹת חֲסֵרוֹת וָוִי״ן, כְּמוֹ ״וַאֲנִי כְּכֶבֶשׂ אַלּוּף״ (ירמיהו יא:יט), וְהוּא נִפְתָּר ׳כְּכֶבֶשׂ וְאַלּוּף׳. עוֹד הַרְבֵּה בְּמַחְבֶּרֶת מְנַחֵם בֶּן סָרוּק:",2,0],[24,20,"יִשְׁכָּחֵהוּ רֶחֶם. אִמּוֹ. דָּרַשׁ רַבִּי תַּנְחוּם (תנחומא, נח ז), שֶׁהָיוּ דּוֹר הַמַּבּוּל נוֹטְלִים אֶת בְּנֵיהֶם וְנוֹתְנִים אוֹתָם תַּחְתֵּיהֶם, לִסְתֹּם אֲרֻבּוֹת הַתְּהוֹם; וַאֲפִלּוּ אִמּוֹ לֹא הָיְתָה מְרַחֶמֶת עָלָיו:",1,0],[24,20,"מְתָקוֹ רִמָּה. לָמוּת וְלֶאֱכוֹל רִמָּה בְּשָׂרָם:",2,0],[24,20,"עוֹד לֹא יִזָּכֵר. בְּשָׁנָה אַחַת נֶעֶקְרוּ. וְעַל אַרְכָּא שֶׁנִּיתַּן לָהֶם מִתְּחִילָּה, הָיָה אִיּוֹב קוֹבֵל; שֶׁהַרְבֵּה מֵתוּ וְלֹא רָאוּ בְּפוּרְעָנוּת זֶה:",3,0],[24,21,"רוֹעֶה עֲקָרָה לֹא תֵלֵד. כָּךְ הָיָה מִנְהָגָם: נוֹשֵׂא שְׁתֵּי נָשִׁים, אַחַת לְתַשְׁמִישׁ וְאַחַת לְבָנִים. זוֹ שֶׁעוֹמֶדֶת לְתַשְׁמִישׁ, מַשְׁקֶה כּוֹס עִקָּרִין כְּדֵי שֶׁלֹּא תֵלֵד עוֹלָמִית, וּמַאֲכִילָהּ תַּפְנוּקִים וּמַרְחִיצָהּ וּמְקַשְּׁטָהּ, כְּדֵי שֶׁתְּהֵא נָאָה. וְזוֹ הָעוֹמֶדֶת לְבָנִים, מַלְבִּישָׁהּ בִּגְדֵי אַלְמָנוֹת וּמַרְעִיבָהּ. וְזֶהוּ שֶׁאוֹמֵר: הָעֲקָרָה שֶׁלֹּא תֵלֵד הָיָה רוֹעֶה וּמֵטִיב, וְאֶת הָאַלְמָנָה שֶׁעוֹמֶדֶת לְבָנִים לֹא יְיֵטִיב:",1,0],[24,22,"וּמָשַׁךְ. הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָן אַבִּירִים בְּכֹחוֹ לְפוּרְעָנוּת וּלְמִחְיָה, מִתּוֹךְ אַרְכָּא שֶׁהֶאֱרִיךְ לָהֶם:",1,0],[24,22,"יָקוּם. יוֹם אֶחָד:",2,0],[24,22,"וְלֹא יַאֲמִין בַּחַיִּין. כְּמוֹ בַּחַיִּים: ״בַּיּוֹם הַזֶּה נִבְקְעוּ כָּל וְגוֹ׳״ (בראשית ז:יא):",3,0],[24,23,"יִתֶּן לוֹ לָבֶטַח. עַד יוֹם אֵידָם, וְנִשְׁעָנוּ:",1,0],[24,24,"רוֹמּוּ מְעַט. נִסְתַּלְּקוּ מִן הָעוֹלָם כִּמְעַט רֶגַע:",1,0],[24,24,"וְהֻמְּכוּ. נִדְכְּאוּ וְנִתְמַסְכְּנוּ:",2,0],[24,24,"כְּכֹל יִקָּפְצוּן. כִּשְׁאָר כָּל הַנִּקְפָּצִים וְנִמְלָטִים בְּעֵת קָצִיר וּבָצִיר וּמָסִיק, שֶׁנִּקְפָּצִים יַחַד, כֵּן תַּמּוּ כְרֶגַע:",3,0],[24,25,"וְאִם לֹא אֵפוֹ. כַּאֲשֶׁר אָמַרְתִּי, יָבֹא אֶחָד מִכֶּם וְיַכְזִיבֵנִי:",1,0],[24,25,"וְיָשֵׂם לְאַל מִלָּתִי. שֶׁאֲנִי מְהַרְהֵר אַחֲרָיו לָדַעַת מִדּוֹתָיו, שֶׁמַּאֲרִיךְ אַף לָרְשָׁעִים. וְאֶת אוֹהֲבָיו, כְּמוֹנִי הוּא מְיַסֵּר וְאֵינוֹ מְמִיתָן; כְּמוֹ שֶׁקּוֹבֵל ״כִּי לֹא נִצְמַתִּי מִפְּנֵי חֹשֶׁךְ״ (איוב כג:יז). וְאֵלּוּ שֶׁ״גְּבוּלוֹת יַשִּׂיגוּ״ (איוב כד:ב), וְכָל אֵלֶּה עָשׂוּ, לֹא הֻכּוּ בְּיִסּוּרִין:",2,0],[25,2,"(מענה בלדד): הַמְשֵׁל וָפַחַד עִמּוֹ. כְּלַפֵּי שֶׁאָמַר אִיּוֹב ״אֶעֶרְכָה לְפָנָיו מִשְׁפָּט״ (איוב כג:ד), אָמַר לוֹ: הַמְשֵׁל וָפַחַד עִמּוֹ, הַמְשֵׁל זֶה מִיכָאֵל, וָפַחַד זֶה גַּבְרִיאֵל. כְּלוּם אַתָּה יָכוֹל לְהָשִׁיב אֶת אֶחָד מֵהֶם?",1,0],[25,2,"עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. כְּשֶׁהַמַּזָּלוֹת עוֹלִים, כָּל אֶחָד סוֹבֵר: אֲנִי עוֹלֶה רִאשׁוֹן; לְפִי שֶׁאֵינוֹ רוֹאֶה מַה שֶּׁלְּפָנָיו, לְפִיכָךְ אֵינוֹ מִתְקַנֵּא. כָּךְ שָׁמַעְתִּי (תנחומא בובר, איוב). לָשׁוֹן אַחֵר: עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. אֵשׁ וּמַיִם בְּלוּלִין, וְאֵין מַיִם מְכַבִּין אֶת הָאֵשׁ. כָּךְ שָׁמַעְתִּי:",2,0],[25,4,"וּמַה יִּצְדַּק וְגוֹ׳. יְלוּד אִשָּׁה שֶׁאָמַרְתָּ: ״בְּחָנֵנִי כַּזָּהָב אֵצֵא״ (איוב כג:י):",1,0],[25,5,"עַד יָרֵחַ. כְּמוֹ ״וְלֹא עָדָה עָלָיו שָׁחַל״ (איוב כח:ח):",1,0],[25,5,"וְלֹא יַאֲהִיל. כְּמוֹ ״לֹא יָהֵלּוּ אוֹרָם״ (ישעיהו יג:י), וְאָלֶ״ף זוֹ בָּאָה כְּמוֹ ״וְלַאֲדִיב אֶת נַפְשֶׁךָ״ (שמואל א ב:לג) – אָלֶ״ף יְתֵרָה. לָשׁוֹן אַחֵר: לֹא יַאֲהִיל – לֹא יִהְיֶה לוֹ צֵל, כְּשֶׁאֵינוֹ מֵאִיר אֵין לוֹ צֵל. וְהָרִאשׁוֹן נִרְאֶה, וּשְׁנֵיהֶם שָׁמַעְתִּי:",2,0],[26,4,"(מענה איוב): וְנִשְׁמַת מִי יָצְאָה מִמֶּךָּ. מִי שָׂם בְּךָ הָרוּחַ הַזֶּה שֶׁיָּצָא מִפִּיךָ? מִי לֹא יָדַע זֹאת?",1,0],[26,5,"הָרְפָאִים. גֵּיהִנֹּם הַמְּרַפֶּה אֶת הַבְּרִיּוֹת:",1,0],[26,5,"יְחוֹלָלוּ. שִׁבְעָה חֲלָלִים שֶׁלּוֹ:",2,0],[26,5,"מִתַּחַת מַיִם וְשֹׁכְנֵיהֶם: בְּעִמְקֵי עֲמָקִים, וְגַם הוּא:",3,0],[26,6,"עָרוֹם שְׁאוֹל נֶגְדּוֹ. לָדַעַת וְלִרְאוֹת אֶת כָּל מַה שֶּׁבְּתוֹכוֹ:",1,0],[26,7,"עַל בְּלִימָה. אֵין כְּלוּם בַּיְּסוֹד, כִּי הֵם עוֹמְדִים בָּאֲוִיר עַל חֹזֶק זְרוֹעוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְדוּנַשׁ פֵּרֵשׁ בְּלִימָה – מִישׁוֹר; כְּמוֹ ״בְּמֶתֶג וָרֶסֶן עֶדְיוֹ לִבְלוֹם״ (תהלים לב:ט). (כָּךְ רָאִיתִי סא״א.)",1,0],[26,8,"וְלֹא נִבְקַע עָנָן. מֵעוֹלָם, שֶׁיִּפְּלוּ מֵימָיו בְּיַחַד:",1,0],[26,8,"תַּחְתָּם. תַּחַת הַמַּיִם:",2,0],[26,9,"מְאַחֵז. בִּמְחִיצוֹת פְּנֵי כִסֵּא הַכָּבוֹד כֻּלּוֹ, כְּגוֹן ״יָשֶׁת חֹשֶׁךְ סִתְרוֹ״ (תהלים יח:יב):",1,0],[26,9,"וּפַּרְשֵׁז. עַל הַכִּסֵּא עֲנָנוֹ, כְּמוֹ וּדְמוּת עַל רָאשֵׁי הַחַיּוֹת רָקִיעַ (יחזקאל א:כב):",2,0],[26,10,"חוֹק חָג. קוֹמְפָּ״שׁ בְּלַעַ״ז, לְשׁוֹן ״וּבַמְּחוּגָה יְתָאֲרֵהוּ״ (ישעיהו מד:יג). סִבְּבוֹ בְּחוֹל, לִהְיוֹת לוֹ (הַחוֹל) חֹק – גְּבוּל עוֹלָם. וְלֹא יַעֲבֹר הַיָּם אוֹתוֹ חוּג, עַד שֶׁיִּכְלֶה אוֹר וְחֹשֶׁךְ:",1,0],[26,11,"יְרוֹפָפוּ. כְּשֶׁבְּרָאָם וְהִקְרִישָׁם הָיוּ רוֹפְפִים, וְגָעַר בָּהֶם וְעָמְדוּ בְּיֹבֶשׁ וּבְחֹזֶק:",1,0],[26,11,"וְיִתְמְהוּ. תּוֹהֶה וְעוֹלֶה (ס״א: כְּאָדָם תּוֹהֶה וְעוֹמֵד) בְּמָקוֹם אֶחָד:",2,0],[26,12,"רָגַע הַיָּם. כְּמוֹ ״עוֹרִי רָגַע״ (איוב ז:ה), נִקְמַט; קְמָטִים קְמָטִים נַעֲשׂוּ, (כָּךְ כְּשֶׁאָמַר ״יִקָּווּ הַמַּיִם״ נֶאֶסְפוּ מִפְּשִׁיטָתָן וְנִקְמְטוּ קְמָטִים קְמָטִים) עַד שֶׁנִּקְווּ לְמָקוֹם אֶחָד הַמּוּכָן לָהֶם (בראשית א:ט):",1,0],[26,12,"מָחַץ רָהַב. מִצְרַיִם קְרוּיִין רְהָבִים (ישעיהו ל:ז):",2,0],[26,13,"בְּרוּחוֹ שָׁמַיִם שִׁפְרָה. בִּדְבָרָיו וּבְרוּחַ פִּיו אִיהֵל, כְּמוֹ ״וְנָטָה אֹהֶל שַׁפְרִירוֹ״ (ירמיה מג:י):",1,0],[26,13,"חוֹלְלָה יָדוֹ. אֶת פַּרְעֹה הַנִּקְרָא ״נָחָשׁ בָּרִיחַ״ (ישעיהו כז:א). לְשׁוֹן חִיל וְצָרָה. וְכֵן בְּמָקוֹם אַחֵר ״הֲלֹא זֹאת הִיא הַמַּחְצֶבֶת רַהַב מְחוֹלֶלֶת תַּנִּין״ (ישעיהו נא:ט). לָשׁוֹן אַחֵר: יִסְּדָה יָדוֹ אֶת לִוְיָתָן, כְּמוֹ ״גְּבָעוֹת חוֹלָלְתִּי״ (משלי ח:כה):",2,0],[26,14,"קְצוֹת דְּרָכָיו. קַלּוֹת וּמוּעָטוֹת, לְפִי שְׁאָר גְּדוֹלוֹת שֶׁבּוֹ:",1,0],[26,14,"וּמַה שֵּׁמֶץ דָּבָר נִשְׁמַע בּוֹ. מָה רֶמֶז דָּבָר אָדָם יָכוֹל לְהָבִין מִפְּעֻלּוֹתָיו. דָּבָר אַחֵר: שֵׁמֶץ כְּמוֹ ״לְשִׁמְצָה״ (שמות לב:כה), לִגְנוּת:",2,0],[27,1,"וַיֹּסֶף. עָמְדוּ רֵיעָיו מֵעֲנוֹת, כַּאֲשֶׁר הוֹכִיחָם אֱלִיהוּא ״כִּי עָמְדוּ וְלֹא עָנוּ עוֹד״ (איוב לב:טז):",1,0],[27,2,"חַי אֵל. שְׁבוּעָה הִיא, כִּי בֶּאֱמֶת הֵסִיר אֶת מִשְׁפָּטִי. וּמִכָּאן דָּרַשׁ רַבִּי יְהוֹשֻׁעַ (סוטה כז:), שֶׁמֵּאַהֲבָה עָבַד אִיּוֹב אֶת הַמָּקוֹם: אֵין אָדָם נוֹדֵר בְּחַיֵּי הַמֶּלֶךְ אֶלָּא אִם כֵּן אוֹהֵב אֶת הַמֶּלֶךְ:",1,0],[27,5,"אִם אַצְדִּיק אֶתְכֶם. אִם אוֹמַר: הַדִּין עִמָּכֶם לְחַיְּבֵנִי:",1,0],[27,5,"לֹא אָסִיר תֻּמָּתִי. לֹא אוֹדֶה לְדִבְרֵיכֶם, לוֹמַר שֶׁאֵינִי תָּם:",2,0],[27,6,"בְּצִדְקָתִי הֶחֱזַקְתִּי. לוֹמַר שֶׁאֲנִי צַדִּיק:",1,0],[27,6,"לֹא יֶחֱרַף לְבָבִי. אוֹתִי מִיָּמַי – מִכָּל דֶּרֶךְ וּמִדָּה שֶׁנָּהַגְתִּי בְּיָמַי, וְעַל כָּרְחוֹ יְהִי כְּרָשָׁע אוֹיְבִי:",2,0],[27,8,"כִּי מַה תִּקְוַת חָנֵף. כִּי לָמָּה אֶהְיֶה רָשָׁע וְגַזְלָן? מַה סוֹפוֹ שֶׁל רָשָׁע הַגּוֹזֵל מָמוֹן?",1,0],[27,8,"כִּי יֵשֶׁל. כִּי יַשְׁלִיךְ הַמָּקוֹם אֶת נַפְשׁוֹ מֵעָלָיו, לְשׁוֹן ״שַׁל נַעַלְךָ״ (שמות ג:ה) ״וְנָשַׁל הַבַּרְזֶל״ (דברים יט:ה):",2,0],[27,10,"אִם עַל שַׁדַּי יִתְעַנָּג. כֶּפֶל הַתְּמִיהָה הִיא, כְּכָל הַתְּמִיהוֹת הַכְּפוּלוֹת; שֶׁכֵּן דֶּרֶךְ הָרִאשׁוֹנָה בְּה״א וְהַשְּׁנִיָּה בְּאִם, כְּמוֹ ״הֲיְרֻצוּן בַּסֶּלַע סוּסִים אִם יַחֲרוֹשׁ בַּבְּקָרִים״ (עמוס ו:יב), ״הֲיֵשׁ בִּלְשׁוֹנִי עַוְלָה וְאִם חִכִּי לֹא יָבִין הַוּוֹת״ (איוב ו:ל). אַף כָּאן: הַצַּעֲקָתוֹ יִשְׁמַע אֵל אִם עַל שַׁדַּי יִתְעַנָּג?! שֶׁמָּא, אוֹ מִי שֶׁהוּא רָשָׁע חָנֵף, יָכוֹל הוּא לְהִתְעַנֵּג וְלִסְמֹךְ עַל יְשׁוּעַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלִקְרֹא אֵלָיו בְּעֵת צָרָתוֹ?! בִּתְמִיהָה:",1,0],[27,11,"אוֹרֶה אֶתְכֶם. מָה הַמִּדָּה שֶׁבְּיַד אֵל, וְדֶרֶךְ אֲשֶׁר עִם שַׁדַּי לֹא אֲכַחֵד. כְּמוֹ ״כִּי יָדַע דֶּרֶךְ עִמָּדִי״ (איוב כג:י):",1,0],[27,12,"כֻּלְּכֶם חֲזִיתֶם. שֶׁזֶּה חֵלֶק אָדָם רָשָׁע:",1,0],[27,12,"וְלָמָּה זֶּה הֶבֶל תֶּהְבָּלוּ. לִהְיוֹת רְשָׁעִים וַחֲנֵפִים:",2,0],[27,14,"אִם יִרְבּוּ בָנָיו לְמוֹ חָרֶב. יִרְבּוּ וְיָמוּתוּ בְּיִסּוּרִים וְתַחֲלוּאִים, עַד כִּי יִשְׂמְחוּ אַלְמְנוֹתָיו בְּמִיתָתָן, וְלֹא תִבְכֶּינָה:",1,0],[27,17,"(וְכֶסֶף נָקִי. כַּסְפּוֹ שֶׁל רָשָׁע לְנָקִי יְחַלְּקֶנּוּ הַקָּדוֹשׁ בָּרוּךְ הוּא):",1,0],[27,18,"בָּנָה כְעָשׁ. כְּתוֹלַע הַבּוֹנֶה חוֹר שֶׁאֵינוֹ מִתְקַיֵּם, וּכְסֻכָּה שֶׁעָשָׂה נוֹצֵר הַתְּאֵנָה (משלי כז:יח) וְהַכֶּרֶם, שֶׁאֵינָהּ שֶׁל קַיָּמָא. (עִנְיָן אַחֵר: נוֹצֵר הַכֶּרֶם – שֶׁאֵינוֹ שׁוֹמְרָהּ בְּכָל עֵת. זֶה שָׁמַעְתִּי (סא״א).)",1,0],[27,19,"עָשִׁיר יִשְׁכַּב. יָמוּת בְּעָשְׁרוֹ, וּפְעָמִים שֶׁלֹּא יֵאָסֵף לִקְבוּרָה:",1,0],[27,20,"בַּלָּהוֹת. שֵׁדִים:",1,0],[27,20,"גְּנָבַתּוּ סוּפָה. וְתַשְׁלִיכֵהוּ לִדְרָאוֹנִים:",2,0],[27,22,"וְיַשְׁלֵךְ עָלָיו. הַמַּשְׁלִיךְ עָלָיו רָעָה, וְלֹא יַחְמֹל:",1,0],[27,22,"מִיָּדוֹ. שֶׁל רָשָׁע וּמִכֹּחוֹ וּמִמְּקוֹמוֹ:",2,0],[27,22,"בָּרוֹחַ יִבְרָח. בֶּן עֲצָתוֹ שֶׁהָיָה מְסַיְּעוֹ בַּתְּחִלָּה, יִבְרַח מֵעֲזוֹר יָדוֹ בִּשְׁעַת כִּשְׁלוֹנוֹ. כְּמוֹ שֶׁעָשָׂה חַרְבוֹנָה לְהָמָן (מגילה טז.):",3,0],[27,23,"יִשְׂפֹּק עָלֵימוֹ כַפֵּימוֹ. הַיּוֹדְעִים (אוֹתוֹ) לְפָנִים, וְעַתָּה רוֹאִים בְּשִׁבְרוֹ:",1,0],[28,1,"כִּי יֵשׁ לַכֶּסֶף מוֹצָא. גַּם זֶה טַעַם אַחֵר לִדְבָרוֹ הָרִאשׁוֹן, שֶׁאָמַר ״בְּצִדְקָתִי הֶחֱזַקְתִּי״ (איוב כז:ו): כִּי לָמָּה אֶהְיֶה רָשָׁע, אִם בִּשְׁבִיל כֶּסֶף וְזָהָב – לַכֹּל יֵשׁ מוֹצָא וְסוֹף, אֲבָל הַחָכְמָה מֵאַיִן תָּבוֹא – זֶה סוֹף הַפָּרָשָׁה – הִיא יְקָרָה מִכֹּל. עַל כֵּן כָּל יָמַי נָתַתִּי לִבִּי עָלֶיהָ לִלְמֹד:",1,0],[28,1,"וּמָקוֹם. יֵשׁ לַזָּהָב, שֶׁמִּשָּׁם יָזוֹקּוּ וְיַתִּיכוּ אוֹתוֹ:",2,0],[28,2,"וְאֶבֶן יָצוּק נְחוּשָׁה. מִן הָהָר יָצַק הָאוּמָּן אֶת הַנְּחוּשָׁה; הֲרֵי תְּחִלָּה וָסוֹף יֵשׁ לְכָל דָּבָר, שֶׁכָּל הָעוֹלָם יִכְלֶה, וְכָל אֲשֶׁר בּוֹ:",1,0],[28,3,"קֵץ שָׂם. הַמָּקוֹם מָתַי תִּהְיֶה הַחֹשֶׁךְ, שֶׁהַשָּׁמַיִם נִמְלָחוּ וְהָאָרֶץ תִּבְלֶה (ישעיהו נא:ו), וּלְכָל תַּכְלִית דָּבָר – הוּא חוֹקֵר לוֹ:",1,0],[28,3,"אֶבֶן. אֲשֶׁר מִשָּׁם יָצָא לוֹ חֹשֶׁךְ וְצַלְמָוֶת. אֶבֶן מְקוֹם מוֹצָא פּוּרְעָנוּת. לָכֵן נִקְרָא אֶבֶן בִּמְקוֹם פּוּרְעָנוּת, כְּאָדָם הַנּוֹגֵף אֶת רַגְלָיו בָּאֶבֶן, שֶׁיֵּשׁ לוֹ צַעַר. כָּךְ שָׁמַעְתִּי. כְּמוֹ ״קַו תֹּהוּ וְאַבְנֵי בֹהוּ״ (ישעיהו לד:יא), ״דְּמִן טוּרָא אִתְגְּזֶרֶת אֶבֶן וְגוֹמֵר״ (דניאל ב:מה):",2,0],[28,4,"פָּרַץ נַחַל. עַל סְדוֹם וַעֲמוֹרָה נַחֲלֵי אֵשׁ וְגָפְרִית (בראשית יט:כד):",1,0],[28,4,"מֵעִם גָּר. מִמָּקוֹם שֶׁהוּא נוֹבֵעַ וְנוֹגֵר:",2,0],[28,4,"הַנִּשְׁכָּחִים מִנִּי רָגֶל. אֵלּוּ אַנְשֵׁי סְדוֹם, שֶׁשִּׁכְּחוּ תּוֹרַת רַגְלֵי אוֹרְחִים מֵאַרְצָם. שֶׁהָיוּ מַשְׁכִּיבִים הָאוֹרֵחַ בְּמִטָּה; אִם הָיָה אָרוֹךְ יוֹתֵר, מְקַטְּעִין רַגְלָיו, וְאִם הָיָה קָצָר, מַאֲרִיכִין אוֹתוֹ. כָּךְ מְפֹרָשׁ בָּאַגָּדָה (סנהדרין קט:):",3,0],[28,4,"דַּלּוּ. עַל יְדֵי פְּרִיצַת נַחַל זֶה, וּמֵאֱנוֹשׁ נָעוּ:",4,0],[28,5,"אֶרֶץ. אֲשֶׁר מִמֶּנָּה יֵצֵא לֶחֶם נֶהְפַּךְ מְקוֹמָהּ כְּמוֹ אֵשׁ:",1,0],[28,6,"מְקוֹם סַפִּיר. הָיוּ אֲבָנֶיהָ:",1,0],[28,7,"לֹא יְדָעוֹ עָיִט. לֹא עָבַר עֲלֵיהֶן חַיִל שֶׁל לִיסְטִין:",1,0],[28,7,"וְלֹא שְׁזָפַתּוּ עֵין אַיָּה. לְפִי שֶׁהִיא רוֹאָה יוֹתֵר מִשְּׁאָר עוֹפוֹת, וּלְכָךְ נִקְרְאָה רָאָה (דברים יד:יג), שֶׁהִיא עוֹמֶדֶת בְּבָבֶל וְרוֹאָה נְבֵלוֹת בְּאֶרֶץ יִשְׂרָאֵל. כָּךְ מְפֹרָשׁ בְּאַגָּדַת (חולין סג.). כְּלוֹמַר: לֹא חֲפָרוּהָ מְרַגְּלִים:",2,0],[28,8,"לֹא עָדָה עָלָיו. עָבַר, כְּדִמְתַרְגְּמִינָן ״אֲשֶׁר עָבַר בֵּין הַבְּתָרִים״ (בראשית טו:יז): ״דַּעֲדָא״ (תרגום אונקלוס):",1,0],[28,8,"שַׁחַץ וְשָׁחַל. מִשִּׁבְעָה שֵׁמוֹת הָאַרְיֵה הֵם (סנהדרין צה.). שִׁשָּׁה שֵׁמוֹת יֵשׁ לָאַרְיֵה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מָה עָשָׂה:",2,0],[28,9,"בַּחַלָּמִישׁ שָׁלַח יָדוֹ. וְהָפַךְ שָׁרְשֵׁי הֶהָרִים מִלְמַעְלָה לְמַטָּה:",1,0],[28,10,"בַּצּוּרוֹת יְאֹרִים בִּקֵּעַ. חוֹזֵר לִתְחִלַּת עִנְיָנוֹ שֶׁאָמַר כִּי לְכָל דָּבָר יֵשׁ מוֹצָא, וּבַצּוּרוֹת בִּקֵּעַ לְמוֹצָא הַיְאוֹרִים וְכֵן כָּל יְקָר רָאֲתָה עֵינוֹ. מֵהֵיכָן יָצָא לַבְּרִיּוֹת (כְּמוֹ שֶׁעָשָׂה לְיִשְׂרָאֵל ״הִכָּה צוּר וַיָּזוּבוּ מַיִם״ (תהלים עח:כ)):",1,0],[28,11,"מִבְּכִי נְהָרוֹת חִבֵּשׁ. בִּבְרִיאַת הָעוֹלָם, כְּשֶׁבָּכוּ מַיִם הַתַּחְתּוֹנִים. בְּכִי כְּמוֹ ״נִבְכֵי יָם״ (איוב לח:טז):",1,0],[28,11,"חִבֵּשׁ. כְּמוֹ ״וַיַּחֲבֹשׁ אֶת־חֲמֹרוֹ״ (בראשית כב:ג). כָּךְ שָׁמַעְתִּי. [ס״א: מִבְּכִי וְגוֹ׳. מִפְּנֵי בְּכִיָּתָן שֶׁל יִשְׂרָאֵל, שֶׁהָיוּ בוֹכִין ״לֵאמֹר מַה נִּשְׁתֶּה״ (שמות טו:כד), חָבַשׁ וְתִקֵּן לָהֶם נַהֲרֵי מַיִם מִן הַסֶּלַע; ״וַיַּחֲבֹשׁ לָהֶם״ (ויקרא ח:יג) – מְתַרְגֵּם: ״וְאַתְקֵין״ (תרגום אונקלוס).]",2,0],[28,11,"וְתַעֲלֻמָהּ יוֹצִיא אוֹר. חַלּוֹן יֵשׁ בָּרָקִיעַ וּשְׁמוֹ תַּעֲלוּמָה, מִשָּׁם תּוֹלְדוֹת הַשֶּׁמֶשׁ לִתְקוּפָתוֹ (פרקי רבי אליעזר ו). כְּלוֹמַר: לְכָל דָּבָר יֵשׁ מוֹצָא וְסוֹף, רַק לַחָכְמָה – לֹא מוֹצָא לָהּ, אֶלָּא מִפִּיו, וְלֹא סוֹף עוֹלָמוֹת:",3,0],[28,12,"וְהַחָכְמָה. הַתּוֹרָה:",1,0],[28,13,"וְלֹא תִמָּצֵא בְּאֶרֶץ הַחַיִּים. בְּמִי שֶׁמְּחַיֶּה, אֶלָּא בְּמִי שֶׁמֵּמִית עַצְמוֹ עָלֶיהָ בִּיגִיעָה וּבְרָעָבוֹן:",1,0],[28,14,"תְּהוֹם אָמַר לֹא בִי הִיא. אִם תִּשְׁאָלֶנָּה לְיוֹרְדֵי תְהוֹם הָעוֹסְקִים בְּמוֹצָא מַרְגָּלִיּוֹת וּבְמוֹצָא זָהָב וָכֶסֶף מִמְּקוֹם תְּהוֹמוֹת הָאָרֶץ, יֹאמְרוּ לְךָ: לֹא בִי הִיא. אֵינִי בָּקִי בְּהוֹרָאָה (שבת פט.. עיין שם היטב וצריך עיון):",1,0],[28,14,"וְיָם אָמַר. וְיוֹרְדֵי הַיָּם לִסְחוֹרָה יֹאמְרוּ לְךָ לֹא עִמָּדִי חָכְמָה. לָמָּה? לְפִי שֶׁאֵינָם יְכוֹלִים לִקְנוֹתָהּ כִּשְׁאָר פְּרַקְמַטְיָא, לָתֵת מֵעָשְׁרָם בְּדָמֶיהָ. וּבָאַגָּדָה הוּא אוֹמֵר (שבת פט.), שֶׁבִּשְׁעַת מַתַּן תּוֹרָה בָּא הַשָּׂטָן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר לוֹ: הֵיכָן תּוֹרָה? אָמַר לוֹ: אֵצֶל בֶּן עַמְרָם. בָּא לוֹ אֵצֶל מֹשֶׁה, אָמַר לוֹ: הֵיכָן תּוֹרָה? אֵצֶל יָם. בָּא לוֹ אֵצֶל יָם, אָמַר לוֹ: הֵיכָן תּוֹרָה? לֹא בִי הִיא; לֵךְ אֵצֶל בֶּן עַמְרָם. בָּא לוֹ אֵצֶל בֶּן עַמְרָם, אָמַר לוֹ: הֵיכָן תּוֹרָה? אֵצֶל תְּהוֹם. בָּא לוֹ אֵצֶל תְּהוֹם, אָמַר לוֹ: הֵיכָן תּוֹרָה? אָמַר לוֹ: אֵין עִמָּדִי; לֵךְ אֵצֶל בֶּן עַמְרָם. בָּא לוֹ אֵצֶל בֶּן עַמְרָם, אָמַר לוֹ: הֵיכָן תּוֹרָה? אֵצֶל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְזֶהוּ שֶׁאָמַר: תְּהוֹם אָמַר לֹא בִי הִיא וְיָם אָמַר אֵין עִמָּדִי:",2,0],[28,15,"לֹא יֻתַּן סְגוֹר. ״זָהָב סָגוּר״ (מלכים א ו:כ) זֶהוּ זָהָב טוֹב, שֶׁבְּשָׁעָה שֶׁנִּפְתָּח, כָּל חֲנֻיּוֹת שֶׁל זָהָב נִסְגָּרוֹת:",1,0],[28,16,"לֹא תְסֻלֶּה. לֹא תִשְׁתַּבַּח, לְשׁוֹן ״סֹלּוּ לָרֹכֵב בָּעֲרָבוֹת״ (תהלים סח:ה). הַמְשַׁבְּחָהּ לוֹמַר: חֲשׁוּבָה הִיא כְּכֶתֶם אוֹפִיר וּכְשֹׁהַם יָקָר – לֹא שֶׁבַח הוּא לָהּ, וְכֵן ״הַמְסֻלָּאִים בַּפָּז״ (איכה ד:ב):",1,0],[28,17,"זָהָב. טָהוֹר, מַנְהִיר כְּמַרְגָּלִית:",1,0],[28,17,"וּתְמוּרָתָהּ וְגוֹ׳. וּתְמוּרָתָהּ לֹא בִּכְלִי פָז:",2,0],[28,18,"רָאמוֹת וְגָבִישׁ. שֵׁמוֹת אֲבָנִים טוֹבוֹת שֶׁבַּיָּם הֵם:",1,0],[28,18,"לֹא יִזָּכֵר. אֶצְלָהּ:",2,0],[28,19,"פִּטְדַת כּוּשׁ. אֶבֶן טוֹבָה הִיא, כְּמוֹ ״אֹדֶם פִּטְדָה״ (שמות כח:יז). כֶּתֶם הִיא קְבוּצַת עֲדִי לְתַכְשִׁיטֵי נָשִׁים, וְנִקְרֵאת הַקְּבוּצָה כֶּתֶם בִּלְשׁוֹן עִבְרִי, וּבִלְשׁוֹן עֲרָבִי אַלְחַלוּ, וְהוּא ״נֶזֶם זָהָב וַחֲלִי כָתֶם״ (משלי כה:יב). וְכֵן ״וַתַּעַד נִזְמָהּ וְחֶלְיָתָהּ״ (הושע ב:טו). וְיֵשׁ פּוֹתְרִים כֶּתֶם – כֶּתֶר, וְלֹא נָכוֹן. כִּי לֹא מָצִינוּ פְּעֻלָּה בְּלָשׁוֹן זֶה, כַּאֲשֶׁר מָצִינוּ בִּלְשׁוֹן כֶּתֶר: מַכְתִּיר, כּוֹתָרוֹת:",1,0],[28,21,"וּמֵעוֹף הַשָּׁמַיִם. מַלְאָכִים הַמְעוֹפְפִים:",1,0],[28,22,"אֲבַדּוֹן וָמָוֶת אָמְרוּ. הַמְּאַבְּדִין וּמְמִיתִין עַצְמָן עָלֶיהָ אָמְרוּ: בְּאָזְנֵינוּ שָׁמַעְנוּ שִׁמְעָהּ, שֶׁהַמִּיגֵּעַ בָּהּ, מִתְקַיֶּמֶת בּוֹ. וְיֵשׁ אוֹמְרִים, כַּאֲשֶׁר בָּאַגָּדָה אֲשֶׁר פֵּרַשְׁתִּי לְמַעְלָה, שֶׁבָּא הַשָּׂטָן לִפְנֵי הַמָּקוֹם, אָמַר לוֹ: הֵיכָן תּוֹרָה? אָמַר לוֹ וְכוּ׳. וְהַיְינוּ דִּכְתִיב: אֲבַדּוֹן וָמָוֶת אָמְרוּ בְּאָזְנֵינוּ שָׁמַעְנוּ שִׁמְעָהּ. כְּשֶׁנִּתְּנָה לְיִשְׂרָאֵל. אֲבָל:",1,0],[28,23,"אֱלֹהִים הֵבִין דַּרְכָּהּ וְהוּא יָדַע אֶת מְקוֹמָהּ. שֶׁיּוֹדֵעַ הוּא הֵיכָן שׁוֹרָה. וְגַם יְשַׁבְּחוּהָ וְיֹאמְרוּ לָהּ, כִּי אֱלֹהִים הֵבִין דַּרְכָּהּ. נִסְתַּכֵּל בָּהּ וּבָרָא אֶת הָעוֹלָם, בְּאוֹתִיּוֹתֶיהָ כְּסִדְרָם וּמִשְׁקָלָן יָצַר כָּל הַיְּצוּרִים; כַּאֲשֶׁר כָּתוּב בְּסוֹד סֵפֶר יְצִירָה:",1,0],[28,24,"כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט. בָּהּ הֵיאַךְ יִבְנֵם וְיִבְרָאֵם, וְתַחַת כָּל הַשָּׁמַיִם צָרְכֵי בְּרִיָּתָן רָאָה בָּהּ:",1,0],[28,25,"לַעֲשׂוֹת וְגוֹ׳. בָּהּ מִשְׁקָל לָרוּחַ, לְכָל אֶרֶץ לְפִי כֹּחָהּ. וְכֵן הַמַּיִם לְפִי הַמִּדָּה, לְפִי מַה שֶּׁהָיְתָה אֶרֶץ צְרִיכָה לְהַשְׁקוֹתָהּ. יֵשׁ אֶרֶץ נְגוּבָה, וּצְרִיכָה הַרְבֵּה גְּשָׁמִים, וְיֵשׁ אֶרֶץ שֶׁאֵינָהּ צְרִיכָה כָּל כָּךְ:",1,0],[28,26,"חֹק. גְּזֵרָה קְצוּבָה לְפִי כָּל אֲרָצוֹת, וּמַעְיָן וּפֶלֶג לְהַשְׁקוֹת כָּל אֶרֶץ וָאֶרֶץ. וּבַעֲשׂוֹתוֹ דֶּרֶךְ לְכָל הַחֲזִיזִים, שֶׁלֹּא יֵצְאוּ שְׁנֵי קוֹלוֹת דֶּרֶךְ נֶקֶב אֶחָד, פֶּן יַחֲרִיב אֶת הָעוֹלָם:",1,0],[28,27,"אָז רָאָה. רָאָה אוֹתָהּ, נִסְתַּכֵּל בָּהּ, וּבַעֲצָתָהּ יַעֲשֶׂה הַכֹּל:",1,0],[28,27,"וַיְסַפְּרָהּ. סִפֵּר אוֹתִיּוֹתֶיהָ: כְּפוּלוֹת וּפְשׁוּטוֹת; רִאשׁוֹנָה וְאֶמְצָעִית וְאַחֲרוֹנִית – הִיא ׳אֱמֶת׳, חוֹתָמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא; וְכֵן בִּשְׁאָר סְדָרִים בָּרָא כָּל דָּבָר וְדָבָר בָּאוֹתִיּוֹת הַלָּלוּ. וְהַכֹּל מְפֹרָשׁ בְּסוֹד סֵפֶר ׳יְצִירָה׳:",2,0],[28,27,"הֱכִינָהּ. זִמְּנָהּ לִיצִירָה:",3,0],[28,28,"הֵן יִרְאַת אֲדֹנָי הִיא חָכְמָה. זוֹ צְרִיכָה לָזוֹ, וְאֵין חָכְמָה יָפָה בְּלֹא יִרְאָה:",1,0],[29,2,"(מענה איוב):מִי יִתְּנֵנִי כְיַרְחֵי קֶדֶם. כְּיָמִים קַדְמוֹנִים, שֶׁהָיִיתִי בִּגְדֻלָּתִי:",1,0],[29,3,"בְּהִלּוֹ נֵרוֹ. לְשׁוֹן אוֹר וְשִׂמְחָה:",1,0],[29,3,"לְאוֹרוֹ. הָיִיתִי הוֹלֵךְ; בְּכָל חֹשֶׁךְ וְצָרָה שֶׁהָיְתָה בָּאָה לָעוֹלָם, לִי הָיָה אוֹר:",2,0],[29,4,"בִּימֵי חָרְפִּי. בִּימֵי קַדְמוּתִי, לָשׁוֹן אֲרַמִּי הוּא: ״חַרְפֵּי וְאַפְּלֵי״ (נידה סה:):",1,0],[29,4,"בְּסוֹד אֱלוֹהַּ עֲלֵי אָהֳלִי. כְּשֶׁהָיוּ כְּשֵׁרֵי הַדּוֹר בָּאִים לְאָהֳלִי לְהִוָּסֵד בְּדִבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּתּוֹרָה וּבְ׳גֶדֶר סְיָג לְשָׁעָה׳:",2,0],[29,5,"נְעָרָי. מְשָׁרְתַי:",1,0],[29,6,"הֲלִיכַי. רַגְלַי:",1,0],[29,6,"בְּחֵמָה. כְּמוֹ בְּחֶמְאָה:",2,0],[29,6,"וְצוּר יָצוּק עִמָּדִי פַּלְגֵי שָׁמֶן. כְּלוֹמַר: נַחַת רוּחַ וְכָל תַּאֲוַת לֵב, הַנּוֹחִים כְּנַחֲלֵי שֶׁמֶן:",3,0],[29,6,"יָצוּק. כְּמוֹ ״וְיָצַקְתָּ״ (שמות כה:יב):",4,0],[29,7,"קָרֶת. תִּקְרָה גְּבוֹהָה מוּכֶנֶת כְּכִסֵּא, לָשֶׁבֶת לְזִקְנֵי הָעִיר:",1,0],[29,7,"בָּרְחוֹב וְגוֹ׳. וְכַאֲשֶׁר בָּרְחוֹב הָיִיתִי מֵכִין מוֹשָׁבִי:",2,0],[29,8,"הָיוּ נְעָרִים רוֹאִים אוֹתִי וְנֶחְבָּאִים, וִישִׁישִׁים עָמְדוּ מִפָּנַי:",1,0],[29,9,"שָׂרִים עָצְרוּ בְמִלִּים. וּמְצַפִּים שֶׁאֶפְתַּח אֲנִי תְּחִלָּה:",1,0],[29,11,"כִּי אֹזֶן. אֲשֶׁר שָׁמְעָה מִלָּתִי וַתְּאַשְּׁרֵנִי:",1,0],[29,11,"וְעַיִן רָאֲתָה. בְּכָל מָקוֹם בְּגָדְלִי וְכֹשֶׁר מִדָּתִי:",2,0],[29,13,"בִּרְכַּת אוֹבֵד. אָדָם מֵת בַּעֲוֹנוֹ וְנִטְרַד:",1,0],[29,13,"עָלַי תָּבֹא. כִּי הָיִיתִי זָן אֶת בָּנָיו וְאֶת אִשְׁתּוֹ. וְרַבּוֹתֵינוּ אָמְרוּ (בבא בתרא טז.), שֶׁהָיָה גּוֹזֵל שְׂדֵה יְתוֹמִים וּמַשְׁבִּיחָהּ וּמַחֲזִירָהּ לָהֶם. וּפְשָׁטֵיהּ דִּקְרָא אֵינוֹ נִרְאֶה כָּךְ, שֶׁאֵין קָרוּי אוֹבֵד – אֶלָּא דָּבָר שֶׁהוּא עַצְמוֹ אוֹבֵד; כְּמוֹ ״כִּכְלִי אֹבֵד״ (תהלים לא:יג), וְכֵן ״תָּעִיתִי כְּשֶׂה אֹבֵד״ (תהלים קיט:קעו); ״צֹאן אֹבְדוֹת״ (ירמיה נ:ו):",2,0],[29,13,"וְלֵב אַלְמָנָה אַרְנִין. שֶׁהָיָה מַטִּיל שְׁמוֹ עַל אַלְמָנוֹת, לֵאמֹר: קְרוֹבָתִי הִיא; אוֹ: אֲנִי אַשִּׂיאֶנָּה! כְּדֵי שֶׁיִּקְפְּצוּ עָלֶיהָ תּוֹבְעִים:",3,0],[29,14,"צֶדֶק לָבַשְׁתִּי וַיִּלְבָּשֵׁנִי. רָדַפְתִּי אַחֲרֵי הַצֶּדֶק וְהוּא נִמְצָא לִי כִּמְעִיל וְצָנִיף, שֶׁהֵם תַּכְשִׁיטִים נָאִים; כֵּן הָיָה מִשְׁפָּטִי נָאֶה וְטָהוֹר:",1,0],[29,18,"וָאֹמַר עִם קִנִּי אֶגְוָע. בִּשְׁבִיל כֹּשֶׁר מִדָּתִי, הָיִיתִי אוֹמֵר בְּלִבִּי: כְּשֶׁאָמוּת יִהְיֶה קִנִּי וּבֵיתִי נָכוֹן עִמִּי:",1,0],[29,18,"וְכַחוֹל אַרְבֶּה יָמִים. עוֹף וּשְׁמוֹ חוֹל. וְלֹא נִקְנְסָה עָלָיו מִיתָה, שֶׁלֹּא טָעַם מֵעֵץ הַדַּעַת; וּלְבַסּוֹף אֶלֶף שָׁנָה מִתְחַדֵּשׁ וְחוֹזֵר לְנַעֲרוּתוֹ:",2,0],[29,19,"שָׁרְשִׁי פָתוּחַ וְגוֹ׳. כָּל זֶה הָיִיתִי אוֹמֵר בְּלִבִּי, שֶׁלֹּא יִיבַשׁ שָׁרְשִׁי וְלֹא יָמוּת קְצִירִי; כְּמוֹ ״וְעָשָׂה קָצִיר״ (איוב יד:ט) – וְהֵן יוֹנְקוֹת עֲנָפִים רַכִּים שֶׁל אִילָן. וְאָמַרְתִּי:",1,0],[29,20,"שֶׁכְּבוֹדִי. יִתְחַדֵּשׁ עִמָּדִי תָּמִיד:",1,0],[29,20,"וְקַשְׁתִּי. וְאֵיתָנִי תַּחֲלִיף תָּמִיד לְטוֹבָה:",2,0],[29,21,"לִי שָׁמְעוּ וְיִחֵלּוּ. הַשּׁוֹמְעִים דְּבָרַי הָיוּ מְיַחֲלִים שֶׁיִּתְקַיְּמוּ, וְהָיוּ מִתְקַיְּמוֹת. כִּי מָסֹרֶת חָכְמָה הָיָה בְּיָדִי:",1,0],[29,22,"תִּטֹּף מִלָּתִי. לְשׁוֹן נְבוּאָה, וְכֵן ״לֹא תַטִּיף עַל בֵּית יִשְׂחָק״ (עמוס ז:טז). כְּלוֹמַר: כִּנְבוּאָה הָיָה דְבָרִי:",1,0],[29,23,"לְמַלְקוֹשׁ. לִזְמַן אָרוֹךְ הָיוּ מְדַבְּרִים, כִּי רוֹב שְׁעוֹתֵיהֶם שְׁתִיקָה, שֶׁהָיוּ תְּאֵבִים לִשְׁמוֹעַ דְּבָרַי:",1,0],[29,24,"לֹא יַאֲמִינוּ. שֶׁאֲנִי מְשַׂחֵק עִמָּהֶם, מִפְּנֵי חֲשִׁיבוּתִי:",1,0],[29,24,"וְאוֹר פָּנַי לֹא יַפִּילוּן. הָיוּ יְרֵאִים לְהִתְקָרֵב אֵלַי וּלְהָגִיס לִבָּם בִּי:",2,0],[29,25,"אֶבְחַר דַּרְכָּם. כָּל דַּרְכֵיהֶם וַעֲצָתָם אֲנִי הָיִיתִי בּוֹחֵר לָהֶם, שֶׁהָיוּ שׁוֹאֲלִים לִי: אֵיזֶה דֶּרֶךְ נֵלֵךְ? וּמַה נַּעֲשֶׂה?",1,0],[29,25,"וְאֵשֵׁב רֹאשׁ. אִם הָיוּ מְסֻבִּים, אֲנִי הָיִיתִי מֵסֵב בְּרֹאשׁ הַמְּסֻבִּים:",2,0],[30,2,"גַּם כֹּחַ יְדֵיהֶם לָמָּה. הָיָה לִי בְּאוֹתָן הַיָּמִים רְשָׁעִים הָיוּ, וְלֹא תּוֹעֶלֶת בָּהֶם; כִּי פֻּרְעָנוּת בָּא עַל יָדָם:",1,0],[30,2,"עָלֵימוֹ אָבַד כָּלַח. זִקְנָה:",2,0],[30,3,"בְּחֶסֶר וּבְכָפָן. הָיוּ גַּלְמוּד:",1,0],[30,3,"הָעוֹרְקִים צִיָּה. שֶׁמַּבְרִיחִין אוֹתָן בְּיָמָיו מִקֶּרֶב בְּנֵי אָדָם, לֵילֵךְ בַּחֹשֶׁךְ:",2,0],[30,3,"אֶמֶשׁ שׁוֹאָה וּמְשׁוֹאָה. בְּרוּאִינָ״א בְּלַעַ״ז:",3,0],[30,4,"הַקּוֹטְפִים מַלּוּחַ עֲלֵי שִׂיחַ. בִּהְיוֹתָם בַּמִּדְבָּרוֹת הָיוּ קוֹטְפִים לָהֶם מְלוּחִים עַל אִילָנוֹת הַיְּעָרִים וְאוֹכְלִים. מַלּוּחַ שֵׁם עֵשֶׂב הוּא, וּבִלְשׁוֹן אֲרַמִּי נִקְרָא קָקוּלִין (ירושלמי פאה ד), וּבִלְשׁוֹן מִשְׁנָה מְלוּחִים, מַצוֹ״שׁ בְּלַעַ״ז, כְּאוֹתָהּ שֶׁשָּׁנִינוּ (קדושין סו.): הֶעֱלוּ מְלוּחִים עַל שֻׁלְחָנוֹת שֶׁל זָהָב:",1,0],[30,4,"שִׂיחַ. אִילָן, כְּמוֹ ״אַחַד הַשִּׂיחִים״ (בראשית כא:טו):",2,0],[30,5,"מִן גֵּו. מִן קֶרֶב עִיר הָיוּ נִגְרָשִׁין:",1,0],[30,6,"בַּעֲרוּץ נְחָלִים. יֵשׁ אֶרֶץ מְלוּחָה, מִתְבַּקַּעַת, שֶׁשָּׁם הָיוּ שׁוֹכְבִים בְּחוֹרֵי הֶעָפָר וְחוֹרֵי נְקִיקֵי הַסְּלָעִים:",1,0],[30,6,"וְכֵפִים. תַּרְגּוּם שֶׁל ״סְלָעִים״ (מלכים א יט:יא). דָּבָר אַחֵר: בַּעֲרוּץ נְחָלִים. הוּא הַנְּקִיק שֶׁעוֹשֶׂה הַנַּחַל סְבִיבוֹתָיו:",2,0],[30,7,"חָרוּל יְסֻפָּחוּ. אוֹרְשִׁיאַ״שׁ בְּלַעַ״ז. הָיוּ נֶאֱסָפִים, כְּמוֹ ״וְנִסְפְּחוּ עַל בֵּית יַעֲקֹב״ (ישעיהו יד:א):",1,0],[30,8,"נִכְאוּ. בְּיָמַי מִן הָאָרֶץ, שֶׁהָיִיתִי מַשְׁפִּילָם; לְשׁוֹן ״נְכֵה רוּחַ״ (ישעיה סו:ב):",1,0],[30,11,"כִּי יִתְרִי פִּתַּח. יֶתֶר קַשְׁתִּי פִּתַּח (כְּמוֹ שֶׁאָמַרְתִּי לְמַעְלָה וְקַשְׁתִּי תַּחְלִיף), כְּלוֹמַר: כֹּחִי הֵתִישׁ מִי שֶׁבְּיָדוֹ לַעֲשׂוֹת:",1,0],[30,11,"וְרֶסֶן מִפָּנַי שִׁלֵּחוּ. רִסְנִי שֶׁהָיוּ מְרֻסָּנִים בּוֹ, שִׁלְּחוּהוּ מִפָּנַי, כִּי אֵינָם יְרֵאִים מֵעַתָּה מִמֶּנִּי:",2,0],[30,12,"עַל יָמִין. עַל יְמִינִי עוֹמְדִים פִּרְחָחִים קְטַנִּים, כִּשְׁאָר הֶדְיוֹטִים; שֶׁאֵינִי חָשׁוּב בְּעֵינֵיהֶם לְהִכָּנַע מִפָּנַי:",1,0],[30,12,"רַגְלַי שִׁלֵּחוּ. אִם הַמָּקוֹם צַר לָהֶם, דּוֹחֲפִים אוֹתִי הָלְאָה:",2,0],[30,12,"וַיָּסֹלּוּ עָלַי אָרְחוֹת אֵידָם. כָּל דֶּרֶךְ נְבָלָה שֶׁיֵּשׁ לָהֶם לַעֲשׂוֹת, עוֹשִׂים מְסִלָּתָן לְפָנַי וְאֶצְלִי, וְלֹא יִירָאוּ:",3,0],[30,13,"נָתְסוּ נְתִיבָתִי. הַטּוֹבָה וְאֵין חוֹשְׁשִׁין לָהּ, נָתְסוּ כְּמוֹ ״נָתְצוּ״ (מלכים ב כה:י) וְסָמֶ״ךְ מִתְחַלֶּפֶת בְּצָדִ״י:",1,0],[30,13,"לְהַוָּתִי יוֹעִילוּ. לְהַקְנִיטֵנִי מוֹסִיפִין:",2,0],[30,14,"כְּפֶרֶץ רָחָב. שֶׁבַּגָּדֵר שֶׁהַכֹּל בָּאִים וְעוֹבְרִים שָׁם, כֵּן יֶאֱתָיוּ יַחַד עָלַי לְהַכְלִימֵנִי:",1,0],[30,14,"תַּחַת שׁוֹאָה הִתְגַּלְגָּלוּ. כְּלוֹמַר: מִתְגַּלְגְּלִים וּבָאִין בְּסֵתֶר, עַד שֶׁמַּגִּיעִין אֶצְלִי לְהַקְנִיטֵנִי, כְּדֵי שֶׁלֹּא אֶשָּׁמֵט מֵהֶם:",2,0],[30,15,"הָהְפַּךְ עָלַי. נֶהְפַּךְ עָלַי:",1,0],[30,15,"בַּלָּהוֹת. שֵׁדִים:",2,0],[30,15,"תִּרְדֹּף כָּרוּחַ. רָעָה:",3,0],[30,15,"אֶת נְדִיבָתִי. רוּחַ נְדִיבָה שֶׁהָיָה שׁוֹרָה עָלַי מִתְּחִלָּה:",4,0],[30,16,"וְעַתָּה. אֶל הַצָּרָה הַזֹּאת תִּשְׁתַּפֵּךְ נַפְשִׁי, כְּאָדָם שֶׁתִּתְפַּעֵם רוּחוֹ; כִּי יֹאחֲזוּנִי, וְכוֹפִין אוֹתִי לְהִשְׁתַּפֵּל נַפְשִׁי:",1,0],[30,16,"יְמֵי עֹנִי. שֶׁאֲנִי בָּהֶם:",2,0],[30,17,"נִקַּר. כְּמוֹ ״הַעֵינֵי הָאֲנָשִׁים הָהֵם תְּנַקֵּר״ (במדבר טז:יד). נִקַּר. פוֹרִיי״ר בְּלַעַ״ז; הַתּוֹלָעִים מְנַקְּרִין בְּשָׂרִי מֵעַל עַצְמִי:",1,0],[30,17,"וְעֹרְקַי. גִּידַי, אֵין לָהֶם מְנוּחָה. ׳גִּיד׳ בִּלְשׁוֹן עֲרָבִי ׳עוֹרֶק׳; כָּךְ פֵּירֵשׁ דּוּנַשׁ. לָשׁוֹן אַחֵר: עֹרְקַי. רוֹדְפַי, הַמַּבְרִיחִין אוֹתִי:",2,0],[30,18,"יִתְחַפֵּשׂ לְבוּשִׁי. מִשְׁתַּנֶּה לְבוּשִׁי, גֶּלֶד אַחַר גֶּלֶד; כְּשֶׁאָדָם פּוֹשֵׁט אֶת בְּגָדָיו וְלוֹבֵשׁ בְּגָדִים אֲחֵרִים, מְשֻׁנִּים מֵרִאשׁוֹנִים, קוֹרֵא אוֹתָם ׳בִּגְדֵי חֹפֶשׂ׳; כְּמוֹ ״הִתְחַפֵּשׂ וָבֹא בַמִּלְחָמָה״ (מלכים א כב:ל), וּמְתֻרְגָּם: ״אִשְׁתַּנִּי״ (תרגום יונתן):",1,0],[30,18,"כְּפִי כֻתָּנְתִּי יַאַזְרֵנִי. שֶׁאוֹזֵר וּמַעֲנִיק צַוָּארִי, כֵּן יַאַזְרֵנִי אוֹתִי לְבוּשִׁי כָּל סְבִיבִי:",2,0],[30,19,"הוֹרָנִי לַחֹמֶר. הוֹרָנִי יְלַמְּדֵנִי הַשְּׁחִין הַזֶּה לֵישֵׁב כְּמוֹ בַחֹמֶר, כְּמוֹ שֶׁאָמַרְנוּ ״וְהוּא יוֹשֵׁב בְּתוֹךְ הָאֵפֶר״ (איוב ב:ח). דָּבָר אַחֵר: הוֹרָנִי לַחֹמֶר פֵּירוּשׁוֹ: הִשְׁלִיכַנִי, לְשׁוֹן ״יָרָה בַיָּם״ (שמות טו:ד):",1,0],[30,19,"וָאֶתְמַשֵּׁל. נִדְמֵיתִי. וּבְמִדְרַשׁ רַבִּי תַּנְחוּמָא (תנחומא בובר, וישלח ח): אָמַר רַבִּי בֶּרֶכְיָה: סָרֵס אֶת הַמִּקְרָא: אֲנִי נִמְשַׁלְתִּי לְאַבְרָהָם בְּצִדְקָתִי שֶׁקָּרָא עַצְמוֹ ״עָפָר וָאֵפֶר״ (בראשית יח:כז), וְהוּא דָּנַנִּי כְּרִשְׁעֵי דּוֹר הַפְּלַגָּה (שֶׁמָּרְדוּ בּוֹ בְּבִנְיַן הַמִּגְדָּל) שֶׁכָּתוּב בָּהֶם ״וְהַחֵמָר הָיָה לָהֶם לַחֹמֶר״ (בראשית יא:ג):",2,0],[30,20,"עָמַדְתִּי. לִרְאוֹת, לִשְׁתּוֹק וּלְהָבִין; כְּמוֹ ״וּבְפִתְחוֹ עָמְדוּ כָל הָעָם״ (נחמיה ח:ה), וְ״לֹא עָנוּ עוֹד״ (איוב לב:טו):",1,0],[30,20,"וַתִּתְבֹּנֶן בִּי. מְחַשֵּׁב עָלַי לִשְׁנוֹת אֶת נְגָעַי:",2,0],[30,22,"תִּשָּׂאֵנִי אֶל רוּחַ. שֵׁדִים:",1,0],[30,22,"תַּרְכִּיבֵנִי וּתְמֹגְגֵנִי תּוּשִׁיָּה. חַלָּשׁוּת וְתַשּׁוּת כֹּחַ הָיָה מְמוֹגְגֵנִי:",2,0],[30,22,"וּתְמוֹגְגֵנִי תּוּשִׁיָּה. לְשׁוֹן נְקֵבָה, וְעַל תּוּשִׁיָּה עוֹמֵד. וְאֵין תָּי״ו זוֹ כְּתָי״ו שֶׁל תִּשָּׂאֵנִי:",3,0],[30,23,"כִּי יָדַעְתִּי. כִּי יוֹדֵעַ הָיִיתִי אֲשֶׁר לַמָּוֶת תְּשִׁיבֵנִי, מָקוֹם שֶׁהוּא מוֹעֵד לְכָל חָי. בַּקֶּבֶר:",1,0],[30,24,"אַךְ לֹא בְעִי. וּבַהַשְׁחָתָה הָיָה רָגִיל הַשּׁוֹפֵט לִשְׁלֹחַ יָד, כְּמוֹ ״לְעִי הַשָּׂדֶה״ (מיכה א:ו):",1,0],[30,24,"אִם בְּפִידוֹ. אִם הָיָה שׁוֹלֵחַ פִּיד, שֶׁהוּא שֶׁבֶר, עַל בְּרִיּוֹתָיו:",2,0],[30,24,"לָהֶן שׁוּעַ. הָיָה מְשַׁעֲשְׁעָן תַּנְחוּמִין בְּמִקְצָת. וְכֵן פֵּרְשׁוּ רַבּוֹתֵינוּ (ילקוט שמעוני איוב תתקיח): אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מַכֶּה אוּמָּה וּמוֹשִׁיבָהּ צָדוּ, אֶלָּא מֵבִיא פִּיד לָזוֹ וּמְשַׁעֲשְׁעָהּ בַּחֲבֶרְתָּהּ שֶׁלָּקְתָה כְּבָר, וּמִתְנַחֶמֶת בָּהּ. הֵבִיא פִּיד לְאַשּׁוּר וְשִׁעֲשֵׁעַ בְּמִצְרַיִם, שֶׁנֶּאֱמַר ״הֲתֵיטְבִי מִנֹּא אָמוֹן״ (נחום ג:ח); הֵבִיא פִּיד לְמִצְרַיִם וְשִׁעֲשֵׁעַ בְּאַשּׁוּר, שֶׁנֶּאֱמַר ״הִנֵּה אַשּׁוּר… בַּלְּבָנוֹן״ (יחזקאל לא:ג). וְעוֹד יִפָּתֵר לָהֶן שׁוּעַ. תְּפִלָּה וּתְחִנָּה מוֹעֶלֶת בָּהֶם:",3,0],[30,25,"אִם לֹא בָכִיתִי לִקְשֵׁה יוֹם. יוֹדֵעַ וּמַכִּיר, אִם לֹא הָיִיתִי רַחֲמָנִי וּבוֹכֶה עַל עֲנִיִּים קְשֵׁי יוֹם, וְעָגְמָה נַפְשִׁי לָאֶבְיוֹנִים. כִּי עַל כָּל אֵלֶּה בָּאַתְנִי זֹאת:",1,0],[30,26,"כִּי טוֹב קִוִּיתִי וְגוֹ׳. כְּלוֹמַר: כִּי הַגְּמוּל הַזֶּה רָאוּי לִי:",1,0],[30,27,"וְלֹא דָמּוּ. אֵין יְכוֹלִין לִדּוֹם וּלְהַחֲרִישׁ:",1,0],[30,28,"בְּלֹא חַמָּה. לֹא שְׁזָפַתְנִי הַשֶּׁמֶשׁ, וְהִנְנִי קוֹדֵר:",1,0],[30,29,"אָח הָיִיתִי לְתַנִּים וְגוֹ׳. תַּנִּים וּבְנוֹת יַעֲנָה עֲסוּקִים בִּבְכִי כָּל יְמֵיהֶם:",1,0],[30,30,"חָרָה. לְשׁוֹן דָּבָר הַנִּחְרָה וּמִתְיַיבֵּשׁ מִפְּנֵי חוֹם הָאֵשׁ, כְּמוֹ ״נָחַר מַפֻּחַ״ (ירמיהו ו:כט), ״וְתוֹכוֹ נִחָר״ (יחזקאל טו:ד):",1,0],[31,1,"בְּרִית כָּרַתִּי לְעֵינָי. שֶׁלֹּא לְהִסְתַּכֵּל בְּאֵשֶׁת אִישׁ:",1,0],[31,1,"וּמָה אֶתְבּוֹנֵן עַל בְּתוּלָה. מָה לִּי לְהִתְבּוֹנֵן בָּהּ? כָּךְ הָיְתָה חֲסִידוּתִי, שֶׁלֹּא לָתֵת עַיִן אֲפִלּוּ בִּפְנוּיָה; שֶׁמָּא לְאַחַר יָמִים תִּנָּשֵׂא, וְנִמְצֵאתִי כָּרוּךְ אַחֲרֶיהָ. כָּךְ מְפֹרָשׁ בְּאָבוֹת דְּרַבִּי נָתָן (אבות דרבי נתן):",2,0],[31,2,"וּמֶה חֵלֶק וְגוֹ׳. שֶׁגְּמָלַנִי כָּךְ?",1,0],[31,3,"הֲלֹא אֵיד לְעַוָּל. לוֹ רָאוּי, וְלֹא לִי:",1,0],[31,3,"וְנֵכֶר. דּוּגְמַת ״וְאַל תֵּרֶא בְיוֹם אָחִיךָ בְּיוֹם נָכְרוֹ״ (עובדיה א:יב):",2,0],[31,4,"וְכָל צְעָדַי יִסְפּוֹר. וְרוֹאֶה אִם הָלַכְתִּי עִם שָׁוְא:",1,0],[31,5,"וַתַּחַשׁ. וַתְּמַהֵר, כְּמוֹ ״אֲחִישֶׁנָּה״ (ישעיה ס:כב); ״כִּי גָז חִישׁ״ (תהלים צ:י):",1,0],[31,7,"מָאוּם. הוּא מוּם, דְּבַר שֶׁמֶץ. וְאָלֶ״ף זוֹ כְּתוּבָה וְלֹא קְרִיָא בַּמָּסֹרֶת הַגְּדוֹלָה, וְהוּא מִגִּזְרַת לֹא תֹאסִפוּן (שמות ה:ז). אִם זוֹ עָשִׂיתִי, הָיִיתִי רָאוּי לָבֹא עָלַי קְלָלָה זוֹ:",1,0],[31,8,"אֶזְרְעָה וְאַחֵר יֹאכֵל וְצֶאֱצָאַי יְשֹׁרָשׁוּ. יֵעָקְרוּ הַשָּׁרָשִׁין:",1,0],[31,9,"וְעַל פֶּתַח רֵעִי אָרָבְתִּי. לְאִשְׁתּוֹ – יָשִׁיב לִי גְּמוּלִי:",1,0],[31,10,"תִּטְחַן לְאַחֵר אִשְׁתִּי. רַבּוֹתֵינוּ פֵּרְשׁוּהוּ (במדבר רבה ט:כד) לְשׁוֹן תַּשְׁמִישׁ, כְּמוֹ ״וַיְהִי טוֹחֵן בְּבֵית הָאֲסוּרִין״ (שופטים טז:כא):",1,0],[31,11,"כִּי הִיא זִמָּה. וְיָרֵא הָיִיתִי אִם עָשִׂיתִי, שֶׁהוּא עָוֺן פְּלִילִי, עָוֹן שֶׁמִּשְׁפַּט יִסּוּרִין רְאוּיִין לָבֹא עַל יָדוֹ:",1,0],[31,12,"וּבְכָל תְּבוּאָתִי תְשָׁרֵשׁ. הָאֵשׁ הַזֹּאת, לָכֵן נִמְנַעְתִּי מֵעֲשׂוֹת. כְּשֶׁהוּא מְדַבֵּר בִּלְשׁוֹן עִקּוּר, אוֹמֵר תְּשָׁרֵשׁ; וּבִלְשׁוֹן שֹׁרֶשׁ אוֹמֵר ״תַּשְׁרֵשׁ״ (תהלים פ:י). וְכֵן ״יְשֹׁרָשׁוּ״ (איוב לא:ח) – לְשׁוֹן עִקּוּר; ״יַשְׁרֵשׁ״ (ישעיהו כז:ו) – לְשׁוֹן שֹׁרֶשׁ:",1,0],[31,14,"וּמָה אֶעֱשֶׂה וְגוֹ׳. זֹאת נָתַתִּי אֶל לִבִּי, וְכִי יִפְקֹד אֶת דְּרָכַי, מָה אֲשִׁיבֶנּוּ?",1,0],[31,15,"וַיְכֻנֶנּוּ בָרֶחֶם. אֲנִי בְּבֶטֶן אִמִּי, וְהוּא בְּבֶטֶן אִמּוֹ, הֱכִינָנוּ יוֹצֵר אֶחָד:",1,0],[31,16,"אֲכַלֶּה. שֶׁלֹּא מִלֵּאתִי תַּאֲוָתָהּ, שֶׁהוּא כִּלְיוֹן עֵינַיִם. הַמִּתְאַוֶּה וְאֵינוֹ מַגִּיעַ, קָרוּי ״כִּלְיוֹן עֵינַיִם״ (דברים כח:סה):",1,0],[31,18,"כִּי מִנְּעוּרַי גְּדֵלַנִי. הַכִּשָּׁרוֹן הַזֶּה כְּאָב הַמְגַדְּלֵנִי וְהַמְלַמְּדֵנִי, כֵּן לִמְּדַנִי יֹשֶׁר לִבִּי מִנְּעוּרַי:",1,0],[31,18,"וּמִבֶּטֶן אִמִּי אַנְחֶנָּה. לְמִדָּה זוֹ:",2,0],[31,22,"מִשִּׁכְמָה. הוּא רֹחַב הַכָּתֵף:",1,0],[31,22,"מִקָּנָה. הוּא עֶצֶם הָעֶלְיוֹן, הֶעָגֹל כְּקָנֶה; וְעַל שֶׁהוּא עָגֹל כְּקָנֶה, קוֹרֵא אוֹתוֹ כֵּן:",2,0],[31,23,"כִּי פַחַד אֵלַי וְגוֹ׳. פַּחַד הָיָה בְּעֵינַי אֵידוֹ, שֶׁהוּא מֵבִיא עַל הָרְשָׁעִים; לָכֵן חָדַלְתִּי מֵעֲשׂוֹת:",1,0],[31,23,"וּמִשְּׂאֵתוֹ. וּמִכְּבוֹדוֹ:",2,0],[31,24,"כִּסְלִי. כְּמוֹ ״אֲשֶׁר יָקוֹט כִּסְלוֹ״ (איוב ח:יד) – תִּקְוָתִי וּמַחֲשַׁבְתִּי. וְעַל יְדֵי שֶׁכְּלָיוֹת עַל הַכְּסָלִים הֵם (ויקרא ג:ד), וְהַכְּלָיוֹת יוֹעֲצוֹת (תהלים טז:ז), נִקְרֵאת הַמַּחֲשָׁבָה ׳כֶּסֶל׳:",1,0],[31,24,"וְלַכֶּתֶם. קְבוּצוֹת זָהָב וְאוֹצָרוֹת:",2,0],[31,24,"אָמַרְתִּי מִבְטַחִי. לְהִתְחַזֵּק בָּהֶם עַל הָעֲנִיִּים:",3,0],[31,25,"אִם אֶשְׂמַח כִּי רַב חֵילִי. לֹא הָיִיתִי נוֹהֵג שִׂמְחָה בִּפְנֵי הָעֲנִיִּים בְּעָשְׁרִי, שֶׁלֹּא לְהַקְנִיאָם בִּי:",1,0],[31,26,"אִם אֶרְאֶה אוֹר כִּי יָהֵל. חַמָּה בִּתְקוּפַת גְּבוּרָתָהּ וְהִילָּה:",1,0],[31,26,"וְיָרֵחַ יָקָר הוֹלֵךְ. מַגִּיהַּ וְהוֹלֵךְ, כְּמוֹ ״אוֹר יְקָרוֹת״ (זכריה יד:ו), ״כִּיקַר כָּרִים״ (תהלים לז:כ):",2,0],[31,27,"וַיִּפְתְּ בַּסֵּתֶר לִבִּי. לַשֶּׁמֶשׁ וְלַיָּרֵחַ לֵאמֹר: אֱלוֹהוּת הֵם, כִּקְצָת עוֹבְדֵי כוֹכָבִים הַנִּדָּחִים (וְעוֹבְדִים) לְכָל צְבָא הַשָּׁמַיִם:",1,0],[31,30,"וְלֹא נָתַתִּי לַחֲטֹא חִכִּי. לְהַקְנִיט שׂוֹנְאִי וְלִתְבֹּעוֹ מָמוֹן שֶׁאֵין לִי עָלָיו, כְּדֵי לְהַשְׁבִּיעוֹ, וְלִשְׁאֹל בְּאָלָה נַפְשׁוֹ שֶׁל שׂוֹנְאִי:",1,0],[31,31,"לֹא נִשְׂבָּע. מִתּוֹךְ שִׂנְאָה שֶׁהָיוּ שׂוֹנְאִים אוֹתִי, עַל שֶׁהָיִיתִי מַטְרִיחָם בְּהַכְנָסַת אוֹרְחִים:",1,0],[31,32,"לָאֹרַח. לֹא הָיוּ דַּלְתוֹת בֵּיתִי פְּנִימִיִּים וּמוּקָּפִין בֵּית שַׁעַר מִבַּחוּץ, אוֹ מוּסָּבִין בְּקַרְנֵי זָוִית, לְהַשְׁבִּית אֶת הָאוֹרְחִים מִלָּבוֹא, אֶלָּא פְּתוּחִין לְאֵם דֶּרֶךְ, לָבוֹא כָּל הַבָּא:",1,0],[31,33,"בְּחֻבִּי. בְּמַחֲבוֹאִי:",1,0],[31,34,"כִּי אֶעֱרוֹץ. מִתְּחִלָּה הָיִיתִי מַכְנִיעַ הָמוֹן רַבָּה שֶׁל רְשָׁעִים, וְעַתָּה אַף בֵּין כַּשְׂדִּיִים, ״זֶה הָעָם לֹא הָיָה״ (ישעיהו כג:יג):",1,0],[31,34,"יְחִתֵּנִי. יְיָרְאֵנִי:",2,0],[31,35,"הֵן תָּוִי שַׁדַּי יַעֲנֵנִי. וּלְוַאי שֶׁיָּעִיד עָלַי הַמָּקוֹם בַּדִּין, כְּמוֹ שֶׁאָמַר עָלַי: ״כִּי אֵין כָּמוֹהוּ בָּאָרֶץ… תָּם וְיָשָׁר וִירֵא אֱלֹהִים״ (איוב א:ח). גַּם מֹשֶׁה שֶׁכָּתַב סִפְרוֹ וְסִפְרִי יָעִיד עָלַי. כֵּן הָיָה אִיּוֹב אוֹמֵר: תְּנָה לְתַוּוֹת אוֹתִי וְאֶת כּוֹשְׁרִי:",1,0],[31,35,"שַׁדַּי יַעֲנֵנִי. לְבַקָּשָׁה זֹאת:",2,0],[31,35,"וְסֵפֶר כָּתַב אִישׁ רִיבִי. יִכְתֹּב גַּם הוּא סִפְרוֹ, לְהִתְוַכֵּחַ עִמִּי:",3,0],[31,36,"אֶשָּׂאֶנּוּ. לִכְתּוֹב אֶת סְפָרִי:",1,0],[31,36,"אֶעֶנְדֶנּוּ. אֶקְשְׁרֶנּוּ לְסֵפֶר עֲטָרוֹת לִי:",2,0],[31,37,"מִסְפַּר צְעָדַי אַגִּידֶנּוּ. לְאוֹתוֹ הָאִישׁ:",1,0],[31,38,"אִם עָלַי אַדְמָתִי תִזְעָק. עַל לֶקֶט שִׁכְחָה וּפֵאָה וּמַעַשְׂרוֹת, שֶׁלֹּא הוֹצֵאתִי מַעַשְׂרוֹת כָּרָאוּי:",1,0],[31,38,"וְיַחַד תְּלָמֶיהָ יִבְכָּיוּן. שֶׁחָרַשְׁתִּי בְּשׁוֹר וּבַחֲמוֹר יַחְדָּיו (דברים כב:י):",2,0],[31,39,"בְּלִי כָסֶף. לִשְׂכֹּר שְׂכִירִים וּלְעָשְׁקָם. דָּבָר אַחֵר: זֶה מַעֲשֵׂר שֵׁנִי, דִּכְתִיב ״וְצַרְתָּ הַכֶּסֶף בְּיָדְךָ״ (דברים יד:כה):",1,0],[31,39,"וְנֶפֶשׁ בְּעָלֶיהָ. אָרִיס הָעוֹבֵד בָּהּ:",2,0],[31,40,"בָּאְשָׁה. (דָּבָר מַבְאִישׁ) כְּמוֹ ״בְּאוּשִׁים״ (ישעיה ה:ב). וְאִם לֹא עָשִׂיתִי כֵּן תַּחַת חִטָּה יֵצֵא חוֹחַ. תָּנָא רַבִּי אוֹשַׁעְיָא: לִמֶּדְתְךָ תּוֹרָה דֶּרֶךְ אֶרֶץ: שָׂדֶה שֶׁמַּעֲלָה חוֹחִים, יָפֶה לְזוֹרְעָהּ חִטִּים, שֶׁמַּעֲלָה בְּאוּשִׁים יָפֶה לְזוֹרְעָהּ שְׂעוֹרִים. כָּךְ הוּא בַּיַּלְקוּט (ילקוט שמעוני איוב תתקיח). וּמַה טַּעַם? תַּחַת חִטָּה יֵצֵא חוֹחַ:",1,0],[31,40,"תַּמּוּ וְגוֹ׳. עַד כָּאן הוּא חוֹזֵר וּמִתְנַבֵּא כַּמָּה נְבוּאוֹת, וְאַתְּ אוֹמֵר תַּמּוּ דִּבְרֵי אִיּוֹב? אֶלָּא כָּךְ אוֹמֵר אִיּוֹב: אִם לֹא עָשִׂיתִי כֵן, יִתַּמּוּ דִּבְרֵי אִיּוֹב, וְאַל יְהִי פִּתְחוֹן פֶּה לוֹמַר לְפָנֶיךָ ״בִּעַרְתִּי הַקֹּדֶשׁ״ (דברים כו:יג). כָּךְ רָאִיתִי בַּפְּסִיקְתָּא בְּפָרָשַׁת ׳עַשֵּׂר תְּעַשֵּׂר׳ (דברים יד:כב) מְפֹרָשׁ כֵּן, מִן הַפְּסוּקִים הָאֵלּוּ:",2,0],[32,2,"(מענה אליהוא:) מִמִּשְׁפַּחַת רָם. אַבְרָהָם, שֶׁנֶּאֱמַר ״הָאָדָם הַגָּדוֹל בָּעֲנָקִים״ (יהושע יד:טו) – זֶה אַבְרָהָם:",1,0],[32,2,"מֵאֱלֹהִים. יוֹתֵר מִן הַמָּקוֹם:",2,0],[32,3,"וַיַּרְשִׁיעוּ אֶת אִיּוֹב. זֶה אֶחָד מִן הַמִּקְרָאוֹת שֶׁתִּקְּנוּ סוֹפְרִים אֶת לְשׁוֹן הַכָּתוּב: ״וַיַּרְשִׁיעוּ כְּלַפֵּי הַמָּקוֹם בִּשְׁתִיקוֹתָם״ הָיָה לוֹ לִכְתֹּב, אֶלָּא שֶׁכִּנָּה הַכָּתוּב. וְכֵן ״וַיָּמִירוּ אֶת כְּבוֹדָם בְּתַבְנִית שׁוֹר״ (תהלים קו:כ) – ״כְּבוֹדִי״ הָיָה לוֹ לִכְתֹּב, אֶלָּא שֶׁכִּנָּה הַכָּתוּב. וְכֵן ״וְאַל אֶרְאֶה בְּרָעָתִי״ (במדבר יא:טו) – ״בְּרָעָתָם״ הָיָה לוֹ לִכְתֹּב, אֶלָּא שֶׁכִּנָּה הַכָּתוּב. וְכֵן הַרְבֵּה מְקוֹמוֹת (ספרי במדבר פד) וּבַמָּסֹרֶת הַגְּדוֹלָה:",1,0],[32,4,"חִכָּה. הִמְתִּין:",1,0],[32,4,"כִּי זְקֵנִים הֵמָּה מִמֶּנּוּ לְיָמִים. הָאֲחֵרִים, לָכֵן חָדַל לוֹ עַד שֶׁשָּׁתְקוּ הֵם:",2,0],[32,6,"זָחַלְתִּי. יָרֵאתִי:",1,0],[32,8,"אָכֵן רוּחַ הִיא בֶאֱנוֹשׁ. הַחָכְמָה, וְלֹא עַל יְדֵי יָמִים וְזִקְנָה, אֶלָּא רוּחַ הַמָּקוֹם הוּא:",1,0],[32,12,"וְעָדֵיכֶם אֶתְבּוֹנָן. הִתְבּוֹנַנְתִּי בָּכֶם וְרָאִיתִי, כִּי אֵין מוֹכִיחַ לְאִיּוֹב:",1,0],[32,13,"פֶּן תֹּאמְרוּ מָצָאנוּ חָכְמָה. בִּשְׁתִיקוּתֵינוּ, שֶׁלֹּא לְהַקְנִיטוֹ עוֹד, כִּי אֵל יִדְּפֶנּוּ וְלֹא אִישׁ. לֹא הָיָה לָכֶם לְמַעֵט כְּבוֹד הַמָּקוֹם בְּכָךְ:",1,0],[32,14,"וְלֹא עָרַךְ אֵלַי מִלִּין. קַבָּלָה הִיא, אוֹ שֶׁלֹּא עָרַךְ אֵלַי מִלִּין:",1,0],[32,14,"וּבְאִמְרֵיכֶם לֹא אֲשִׁיבֶנּוּ. לֹא בְּאוֹתָן אֲמָרִים שֶׁהֲשִׁיבוֹתֶם לוֹ, הָיִיתִי מְשִׁיבוֹ:",2,0],[32,15,"הֶעְתִּיקוּ. סָרוּ מֵהֶן מִלִּין:",1,0],[32,19,"הִנֵּה בִטְנִי. מָלֵא רוּחַ, דְּבָרִים לְהָשִׁיב בְּתַאֲוָה:",1,0],[32,19,"כְּיַיִן לֹא יִפָּתֵחַ. כְּיַיִן חָדָשׁ שֶׁאֵינוֹ נִפְתָּח, וְהוּא נוֹפֵחַ, וְאַף בְּתוֹךְ אוֹבוֹת חֲדָשִׁים, וּמְבַקְּעָם:",2,0],[32,19,"אוֹבוֹת. נוֹדוֹת עֲשׂוּיִין כְּקוֹמַת אָדָם, גְּבוֹהִים:",3,0],[32,21,"לֹא אֲכַנֶּה. לֹא אֲשַׁנֶּה דְבָרַי לְהַחֲלִיפוֹ לִכְבוֹדוֹ, כְּמוֹ שֶׁאָמַרְתִּי לְמַעְלָה ״וַיַּרְשִׁיעוּ אֶת אִיּוֹב״ (איוב לב:ג) – זֶהוּ ׳כִּנּוּי׳, שֶׁמְּשַׁנֶּה אֶת הַדִּבּוּר בִּשְׁבִיל כְּבוֹדוֹ. וְאַף זֹאת לֹא אֶעֱשֶׂה, כִּי בְּפֶה מָלֵא אוֹכִיחֶנּוּ:",1,0],[32,22,"כִּמְעַט יִשָּׂאֵנִי. יְסַלְּקֵנִי מִן הָעוֹלָם. וְיֵשׁ פּוֹתְרִים יִשָּׂאֵנִי כְּמוֹ ״וַתִּשָּׂא הָאָרֶץ מִפָּנָיו״ (נחום א:ה):",1,0],[33,4,"רוּחַ אֵל עָשָׂתְנִי. וְאֵינִי חָזָק יוֹתֵר מִמְּךָ:",1,0],[33,6,"הֵן אֲנִי כְפִיךָ לָאֵל. כְּמוֹ שֶׁשָּׁאַל פִּיךָ לְהִתְוַכֵּחַ לְמִי שֶׁלֹּא יְבַעֲתֶךָ (איוב יג:כא), הֵן אֲנִי בִּמְקוֹמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּבִשְׁבִילוֹ, לְדַבֵּר דְּבָרָיו:",1,0],[33,7,"וְאַכְפִּי. כְּפִיָּתִי, כְּמוֹ ״אָכַף עָלָיו פִּיהוּ״ (משלי טז:כו):",1,0],[33,9,"חַף. טָהוֹר וּמְשֻׁפְשָׁף, כְּמוֹ (ביצה לה:) ״נָזִיר לֹא יָחוֹף רֹאשׁוֹ״, וּכְמוֹ (שבת נ.) ״בַּכֹּל חָפִין אֶת הַכֵּלִים״:",1,0],[33,10,"תְּנוּאוֹת. עֲלִילוֹת, לְשׁוֹן ״תּוֹאֲנָה״ (שופטים יד:ד) – לָשׁוּב מִן הַמָּקוֹם:",1,0],[33,12,"כִּי יִרְבֶּה אֱלוֹהַּ מֵאֱנוֹשׁ. אֵין הַמָּקוֹם צָרִיךְ כָּל כָּךְ לְדַקְדֵּק אַחַר הָאָדָם, כִּי הַרְבֵּה יֵשׁ לְהַקָּדוֹשׁ בָּרוּךְ הוּא צְדָקוֹת יוֹתֵר מֵאֱנוֹשׁ:",1,0],[33,16,"אָז יִגְלֶה אֹזֶן אֲנָשִׁים. כְּמוֹ שֶׁעָשָׂה לַאֲבִימֶלֶךְ בַּחֲלוֹם הַלַּיְלָה (בראשית כ:ג):",1,0],[33,16,"וּבְמוֹסָרָם יַחְתֹּם. חוֹתְמָן וְאוֹסְרָן בְּיִסּוּרִין עַל עֲוֹנָם:",2,0],[33,17,"לְהָסִיר אָדָם. בְּחָלְיוֹ:",1,0],[33,17,"מַעֲשֶׂה. שֶׁהָיָה בְדַעְתּוֹ לַעֲשׂוֹת:",2,0],[33,17,"וְגֵוָה מִגֶּבֶר יְכַסֶּה. בְּיִסּוּרָיו, לְמַעַן הַכְנִיעוֹ וּלְהַשְׁפִּילוֹ לָשׁוּב, כְּדֵי שֶׁיֶּחְשַׂךְ נַפְשׁוֹ מִמִּיתָה גְּמוּרָה:",3,0],[33,17,"גֵּוָה. כְּמוֹ גַּאֲוָה:",4,0],[33,18,"וְחַיָּתוֹ מֵעֲבֹר בַּשָּׁלַח. בְּשִׁלְחוֹ וְחַרְבּוֹ שֶׁל מַלְאַךְ הַמָּוֶת, כְּלוֹמַר: לְטוֹבָתְךָ הֵבִיא עָלֶיךָ יִסּוּרִין:",1,0],[33,18,"שֶׁלַח. כְּלִי זַיִן, וְכֵן ״יָדוֹ אַחַת מַחֲזֶקֶת הַשֶּׁלַח״ (נחמיה ד:יא):",2,0],[33,19,"וְהוּכַח. לְשׁוֹן תּוֹכָחָה, שֶׁיָּשׁוּב מֵעֲוֹנוֹ:",1,0],[33,19,"וְרוֹב עֲצָמָיו. שֶׁהוּא אֵיתָן, מוֹכִיחָן בְּמַכְאוֹב:",2,0],[33,20,"וְזִהֲמַתּוּ חַיָּתוֹ לָחֶם. מְמַאֶסֶת נַפְשׁוֹ וְחַיָּתוֹ שֶׁל חוֹלֶה כָּל מַאֲכָל:",1,0],[33,20,"וְנַפְשׁוֹ. מְזַהֶמֶת כָּל מַאֲכַל תַּאֲוָה:",2,0],[33,21,"יִכֶל בְּשָׂרוֹ מֵרֹאִי. יֶחְשַׁךְ בְּשָׂרוֹ מִמַּרְאֶה, כְּמוֹ ״כָּלוּ בַדְּמָעוֹת עֵינַי״ (איכה ב:יא), ״מְכַלּוֹת עֵינַיִם״ (ויקרא כו:טז):",1,0],[33,21,"וְשֻׁפּוּ עַצְמוֹתָיו. מִתְנַתְּקִין מִמְּקוֹמוֹ, וְשֻׁפּוּ כְּמוֹ דְּשָׁף מִדּוּכְתֵּיהּ (חולין מב:):",2,0],[33,21,"לֹא רֻאּוּ. אֵין לָהֶם מַרְאֶה וְתֹאַר:",3,0],[33,23,"אֶחָד מִנִּי אָלֶף. בְּמַגִּידֵי פִּשְׁעוֹ, וְהוּא יָלִיץ יָשְׁרוֹ:",1,0],[33,24,"וַיְחֻנֶּנּוּ. הַמָּקוֹם:",1,0],[33,24,"פְּדָעֵהוּ. כְּמוֹ פְּדָאֵהוּ, אָלֶ״ף מִתְחַלֶּפֶת בְּעַיִ״ן. וְהָעִנְיָן מוֹכִיחַ: מָצָאתִי כֹפֶר, וְהוּא ״פִּדְיוֹן״ (שמות כא:ל):",2,0],[33,25,"רֻטְפַשׁ בְּשָׂרוֹ. רוֹטְפַשׁ אֶשְׁקוֹשָׁ״א בְּלַעַ״ז:",1,0],[33,25,"מִנֹּעַר. נִתְעוֹרֵר בְּשָׂרוֹ מִן הַנּוֹעַר, שֶׁהוּא מְנוֹעָר וּמְשֻׁנָּק בְּיִסּוּרֵי חָלְיוֹ. וְאֵין לַתֵּיבָה זוֹ דִּמְיוֹן בַּמִּקְרָא, וּלְפִי הָעִנְיָנִים הֻצְרַכְנוּ לְפָרְשׁוֹ כְּמַשְׁמָעוּת הָעִנְיָן. וְהַפּוֹתְרוֹ בִּלְשׁוֹן ׳רֶפֶשׁ׳, וְאוֹמֵר הַטֵּי״ת נִתּוֹסְפָה בּוֹ, כְּמוֹ ״נִצְטַדָּק״ (בראשית מד:טז) – טוֹעֶה הוּא מְאֹד. כִּי אֵין טֵי״ת מִתּוֹסֶפֶת בַּתֵּיבָה, כִּי אִם בִּלְשׁוֹן ׳מִתְפַּעֵל׳ אוֹ ׳נִתְפַּעֵל׳, וּבַתֵּיבָה שֶׁיְּסוֹדָהּ צַדִּ״י; וְלֹא בִּשְׁאָר תֵּיבוֹת. כְּמוֹ ״צֶדֶק״ (איוב ח:ג) וְ״נִצְטַדָּק״ (בראשית מד:טז); וּכְמוֹ ״צָרוּעַ״ (ויקרא יג:מד) – ׳נִצְטָרַע׳; ״צִיר נֶאֱמָן״ (משלי כה:יג) – ״וַיֵּלְכוּ וַיִּצְטַיָּרוּ״ (יהושע ט:ד); ״צֵדָה״ – ״הִצְטַיַּדְנוּ״ (יהושע ט:יב):",2,0],[33,25,"יָשׁוּב. בְּכֹחוֹ וּבִרְפוּאָה לִימֵי בַּחֲרוּתוֹ:",3,0],[33,26,"בִּתְרוּעָה. בִּתְפִלָּה:",1,0],[33,27,"יָשֹׁר עַל אֲנָשִׁים. יַעֲשֶׂה שׁוּרוֹת שֶׁל אֲנָשִׁים כְּשֶׁנִּצּוֹל מֵחָלְיוֹ, וְיִתְוַדֶּה לְיוֹצְרוֹ:",1,0],[33,27,"וְלֹא שָׁוָה לִי. לֹא נִהְיָה לִי שָׂכָר בִּדְבָרָיו:",2,0],[33,29,"פַּעֲמַיִם שָׁלוֹשׁ. מְיַסְּרוֹ עַל עֲוֹנוֹתָיו בְּחָלְיוֹ, שֶׁלֹּא לְהַשְׁחִיתוֹ; וְאִם יוֹתֵר יַכְעִיס לְפָנָיו, יִדְאַג מִן גֵּיהִנֹּם וּמִן הַמִּיתָה; שֶׁנֶּאֱמַר ״וְעַל אַרְבָּעָה לֹא אֲשִׁיבֶנּוּ״ (עמוס א:ג):",1,0],[34,3,"(מענה אליהו): כִּי אֹזֶן מִלִּין תִּבְחָן. כַּאֲשֶׁר הַחֵיךְ יִטְעַם הָאֹכֶל:",1,0],[34,5,"מִשְׁפָּטִי. הוֹכָחַת דְּבָרִים:",1,0],[34,6,"אֲכַזֵּב. אֲכַזִּיב שׁוֹפְטִי, שֶׁלֹּא דָנַנִּי אֱמֶת:",1,0],[34,6,"אָנוּשׁ. חוֹלֶה מַכָּתִי, כְּמוֹ ״וַיֵּאָנַשׁ״ (שמואל ב יב:טו):",2,0],[34,6,"חִצִּי. נִגְעִי:",3,0],[34,9,"לֹא יִסְכָּן גָּבֶר. לֹא יֵהָנֶה אָדָם, אִם מַתְמִים דְּרָכָיו:",1,0],[34,13,"מִי פָקַד עָלָיו אָרְצָה. מִי מוֹשֵׁל בּוֹ, לֵאמֹר: לָמָּה כֵּן עָשִׂיתָ וְלֹא צִוִּיתִיךָ כֵּן? כִּי מִי צִוָּהוּ בְּמֶמְשַׁלְתּוֹ, וְלָמָּה יִמְצָא תּוֹאֲנוֹת לַבְּרִיּוֹת? אֵינוֹ צָרִיךְ לְהָשִׁיב דָּבָר לְמוֹשֵׁל בּוֹ, לֵאמֹר: בִּשְׁבִיל זֹאת הֲרֵעוֹתִי לוֹ:",1,0],[34,14,"אִם יָשִׂים אֵלָיו לִבּוֹ. עַל אָדָם, לְהַשְׁחִיתוֹ, לָמָּה יָבֹא בַּעֲלִילָה עָלָיו? הֲרֵי מִיָּד יֶאֱסֹף אֵלָיו רוּחוֹ וְנִשְׁמָתוֹ. רוּחַ וּנְשָׁמָה שֶׁלּוֹ שֶׁהִיא נְפוּחָה בּוֹ, וְאֵין מוֹחֶה בְּיָדוֹ, וְיִגְוַע כָּל בָּשָׂר יָחַד:",1,0],[34,16,"וְאִם בִּינָה. וְאִם אַתָּה רוֹצֶה הָבִין, שִׁמְעָה זֹאת. בִּינָה זוֹ אֵינָהּ שֵׁם דָּבָר, אֶלָּא לְשׁוֹן צִוּוּי, כְּמוֹ ״בִּינָה הֲגִיגִי״ (תהלים ה:ב). לְפִיכָךְ שְׁתַּיִם אֵלּוּ טַעֲמָן לְמַעְלָה, בַּבֵּי״ת, וְכָל שְׁאָר בִּינָה טַעֲמָן לְמַטָּה, בַּנּוּ״ן:",1,0],[34,17,"הַאַף שׂוֹנֵא מִשְׁפָּט. מִשְׁפָּטוֹ שֶׁל שׁוֹפֵט צֶדֶק יַחֲבוֹשׁ הַמָּקוֹם? וְאִם תֹּאמַר: אֵינוֹ מִשְׁפָּט, כִּי לֹא כַדִּין עָשָׂה, אֶפְשָׁר זֹאת מִי שֶׁהוּא צַדִּיק מְאֹד תַּרְשִׁיעַ?",1,0],[34,17,"כַּבִּיר. לְשׁוֹן מְאֹד:",2,0],[34,18,"הַאֲמֹר לְמֶלֶךְ בְּלִיָּעַל. וְכִי הָגוּן וְרָאוּי לֹאמַר לְמֶלֶךְ: בְּלִיָּעַל, וְלֹאמַר רָשָׁע אֶל נְדִיבִים?!",1,0],[34,19,"אֲשֶׁר לֹא נָשָׂא פְּנֵי שָׂרִים. כְּלוֹמַר: לְמֶלֶךְ עוֹלָם, אֲשֶׁר אֵין מַשּׂוֹא פָנִים לְפָנָיו:",1,0],[34,19,"שׁוֹעַ. שַׂר, כְּמוֹ ״וְלַכִּילַי לֹא יֵאָמֵר שׁוֹעַ״ (ישעיהו לב:ה):",2,0],[34,20,"רֶגַע יָמוּתוּ. כְּשֶׁיִּרְצֶה:",1,0],[34,20,"וַחֲצוֹת לָיְלָה. כְּמוֹ שֶׁעָשָׂה לְמִצְרַיִם (שמות יא:ד-ח):",2,0],[34,20,"יְגֹעֲשׁוּ עָם. כְּלוֹמַר: בְּרֶגַע יַעַבְרוּ:",3,0],[34,20,"וְיָסִירוּ אַבִּיר. כֹּחַ שֶׁלָּהֶם:",4,0],[34,20,"לֹא בְיָד. לֹא יִשְׁנוּ בְיָדָם וְאֵין לָהֶם כֹּחַ:",5,0],[34,23,"כִּי לֹא עַל אִישׁ יָשִׂים עוֹד. כְּלוֹמַר: אָמַרְתָּ: ״לֹא אַךְ יָשִׂים בִּי״ (איוב כג:ו), רַק חֲטָאַי לְבַדִּי; וַאֲנִי מְשִׁיבְךָ: לֹא יָשִׂים הַקָּדוֹשׁ בָּרוּךְ הוּא עַל בְּרִיּוֹתָיו עֲלִילוֹת תּוֹסֶפֶת עַל פִּשְׁעָם. עוֹד לְשׁוֹן תּוֹסֶפֶת:",1,0],[34,23,"לָהֲלֹךְ אֶל אֵל בַּמִּשְׁפָּט. כְּשֶׁהוּא בָּא עַל בְּרִיּוֹתָיו לְהִתְוַכֵּחַ עִמָּהֶם:",2,0],[34,24,"יָרֹעַ. יְרוֹצֵץ, כְּמוֹ ״רֹעַ הִתְרוֹעֲעָה״ (ישעיה כד:יט):",1,0],[34,24,"וַיַּעֲמֵד אֲחֵרִים. בִּמְקוֹמָם:",2,0],[34,25,"לָכֵן יַכִּיר מַעְבָּדֵיהֶם. לְפִי שֶׁהוּא מַכִּיר מַעְבָּדֵיהֶם הַטּוֹב וְהָרַע, וְאֵין צֹרֶךְ לוֹ לְהִתְוַכֵּחַ:",1,0],[34,25,"וְהָפַךְ לַיְלָה. עֵת חֹשֶׁךְ וְצָרָה לָהֶם, וְיִדַּכָּאוּ:",2,0],[34,26,"תַּחַת רְשָׁעִים. בִּמְקוֹמָם:",1,0],[34,26,"סְפָקָם. לְאַנְשֵׁי סְדוֹם (בראשית יט:א-כט):",2,0],[34,26,"בִּמְקוֹם רוֹאִים. לְעֵין כֹּל:",3,0],[34,27,"אֲשֶׁר עַל כֵּן סָרוּ מֵאַחֲרָיו. כְּמוֹ ״עַל כֵּן יָדַעְתָּ חֲנֹתֵנוּ בַּמִּדְבָּר״ (במדבר י:לא). כְּמוֹ: מִפְּנֵי אֲשֶׁר סָרוּ מֵאַחֲרָיו וְהֵבִיאוּ לְפָנָיו וְעָלָיו צַעֲקַת דַּלִּים:",1,0],[34,29,"וְהוּא יַשְׁקִיט. מַשְׁקִיט אֶת הַדַּלִּים מֵאוֹתָן הָעוֹשְׁקִים, וּמִי יַרְשִׁיעַ עוֹד? וּבְעוֹד שֶׁהִסְתִּיר פָּנִים, מִי יְשׁוּרֶנּוּ?",1,0],[34,29,"וְעַל גּוֹי וְעַל אָדָם יָחַד. כִּיחִידִים כִּמְרֻבִּים שָׁוֶה לְפָנָיו, לְהַשְׁקִיט וּלְהַסְתִּיר פָּנִים:",2,0],[34,30,"מִמְּלֹךְ אָדָם חָנֵף מִמֹּקְשֵׁי עָם. עַל דַּלִּים שֶׁמָּלַךְ:",1,0],[34,30,"מִמּוֹקְשֵׁי עָם. עָוֹן, וְלֵאלוֹהַּ כָּזֶה לֹא הָיָה לְךָ לוֹמַר ״בְּלִיַּעַל״ וְ״רָשָׁע״ (איוב לד:יח):",2,0],[34,31,"כִּי אֶל אֵל הֶאָמַר. לְהֵאָמֵר אֵלָיו. נָכוֹן וְרָאוּי מֵאֵת כָּל סוֹבְלֵי יִסּוּרִים לְהֵאָמֵר: נָשָׂאתִי, וּמְקַבֵּל וְסוֹבֵל אֲנִי מִשְׁפָּטֶיךָ, וְלֹא אֶחְבֹּל בְּעַצְמִי. וְעוֹד צָרִיךְ הַנִּדּוֹן לוֹמַר:",1,0],[34,32,"בִּלְעֲדֵי אֶחֱזֶה. לְבַד מַה שֶּׁאֲנִי יוֹדֵעַ לִרְאוֹת וּלְהָבִין בִּדְבָרֶיךָ, אַתָּה הוֹרֵנִי, וְאִם אָוֶן פָּעַלְתִּי, לֹא אוֹסִיף:",1,0],[34,33,"הַמֵעִמְּךָ יְשַׁלְּמֶנָּהּ כִּי מָאַסְתָּ וְגוֹ׳. כָּךְ אָמַר אֱלִיהוּ לְאִיּוֹב: הַמֵעִמְּךָ הָיָה לוֹ לְהַקָּדוֹשׁ בָּרוּךְ הוּא לְהִמָּלֵךְ בְּפֵרָעוֹן תַּשְׁלוּמִין מִמְּךָ?",1,0],[34,33,"כִּי מָאַסְתָּ. לֵאמֹר: ״מָאַסְתִּי לֹא לְעוֹלָם אֶחְיֶה״ (איוב ז:טז), ״יַתֵּר יָדוֹ וִיבַצְּעֵנִי״ (איוב ו:ט)?! סָבוּר אַתָּה שֶׁיִּגְבֶּה מִמְּךָ לְפִי דַעְתְּךָ וּרְצוֹנְךָ, וְאַתָּה תִבְחַר הַתַּשְׁלוּמִין, וְלֹא אֲנִי? בִּמְקוֹם הַקָּדוֹשׁ בָּרוּךְ הוּא דִּבֵּר אֱלִיהוּ, בִּתְמִיהַּ:",2,0],[34,34,"אַנְשֵׁי לֵבָב יֹאמְרוּ לִי. כִּי אִיּוֹב לֹא בְדַעַת יְדַבֵּר:",1,0],[34,36,"אָבִי יִבָּחֵן. אָבִי. אַתָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אָב לַכֹּל, הַלְוַאי יִבָּחֵן אִיּוֹב עַד נֶצַח, לְמַעַן תִּהְיֶה תְּשׁוּבָה לְאַנְשֵׁי אָוֶן. וְאַף לִבְנֵי אָדָם דִּבֵּר הַכָּתוּב כֵּן, כְּמוֹ ״אָבִי דָּבָר גָּדוֹל וְגוֹ׳״ (מלכים ב ה:יג). (דָּבָר אַחֵר: אָבִי. כְּמוֹ ״וְתָפֵר הָאֲבִיּוֹנָה״ (קהלת יב:ה), לְשׁוֹן רָצוֹן. כָּךְ חִבְּרוֹ מְנַחֵם. וְכֵן פִּתְרוֹנוֹ: אָבִי יִבָּחֵן אִיּוֹב עַד נֶצַח. רְצוֹנִי וּמְאַוְּיִי שֶׁיִּבָּחֵן אִיּוֹב עַד נֶצַח סא״א).",1,0],[34,37,"יִסְפּוֹק. לְשׁוֹן רוֹב דְּבָרִים וַהֲרָמַת קוֹל:",1,0],[34,37,"בֵּינֵינוּ יִסְפּוֹק. הוּא אוֹמֵר: מַה לָּנוּ וּלְדִבְרֵי אִיּוֹב? ״אַף אָמְנָם שָׁגִיתִי אִתִּי תָּלִין״ (איוב יט:ד)! וְאֵינוֹ יוֹדֵעַ שֶׁאָנוּ נֶעֱנָשִׁים, וּמַסְפִּיק לָנוּ עֲוֹנוֹת, עַל שֶׁאָנוּ שׁוֹמְעִים. כָּךְ מְפֹרָשׁ בְּוַיִּקְרָא רַבָּה (ויקרא רבה ד:ו):",2,0],[35,2,"(מענה אליהוא): הֲזֹאת חָשַׁבְתָּ לְמִשְׁפָּט. שֶׁהוּא מִשְׁפַּט הַבְּרִיּוֹת כְּנֶגֶד יוֹצְרָם, אֲשֶׁר אָמַרְתָּ צִדְקִי מִשֶּׁל הַבּוֹרֵא:",1,0],[35,3,"כִּי תֹאמַר מַה יִּסְכָּן לָךְ. דַּרְכֵי יֹשֶׁר:",1,0],[35,3,"מָה אוֹעִיל. בְּצִדְקָתִי יוֹתֵר מֵחַטָּאתִי:",2,0],[35,4,"וְאֶת רֵעֶיךָ עִמָּךְ. שֶׁשָּׁתְקוּ עַל דְּבָרֶיךָ:",1,0],[35,5,"הַבֵּט שָׁמַיִם. וְאַחֲרֵי שֶׁהוּא גָּבוֹהַּ וְאַתָּה נָמוּךְ, וְאֵין לוֹ תּוֹעֶלֶת בְּרִשְׁעֲךָ וְצִדְקְךָ, לָמָּה תִּתְפָּאֵר אֵלָיו בְּצִדְקְךָ?",1,0],[35,8,"לְאִישׁ. אֲשֶׁר כָּמוֹךָ יוּכַל וְיוֹעִיל רִשְׁעֲךָ וְצִדְקָתֶךָ, רְאֵה רְשָׁעִים רַבִּים אֲשֶׁר:",1,0],[35,9,"מֵרֹב עֲשׁוּקִים. שֶׁהֵם עוֹשְׁקִים, יַזְעִיקוּ אֶת הַבְּרִיּוֹת לְפָנָיו, וִישַׁוְּעוּ עֲנִיִּים מִזְּרוֹעַ רַבִּים הָעוֹשְׁקִים אוֹתָם:",1,0],[35,10,"וְלֹא אָמַר. הָרָשָׁע:",1,0],[35,10,"אַיֵּה אֱלוֹהַּ עֹשָׂי. לִירָא מִפָּנָיו:",2,0],[35,10,"נוֹתֵן זְמִירוֹת. כְּמוֹ ״כַּרְמְךָ לֹא תִזְמֹר״ (ויקרא כה:ד), שֶׁמַּכְרִית אֶת הָרְשָׁעִים בַּלַּיְלָה. כְּגוֹן אַמְרָפֶל וַחֲבֵירָיו (בראשית יד:טו), וּמִצְרַיִם (שמות יב:כט), וְסַנְחֵרִיב (מלכים ב יט:לה):",3,0],[35,11,"מַלְּפֵנוּ. מְלַמְּדֵנוּ חָכְמָה יוֹתֵר מִבְּהֵמוֹת, כְּלוֹמַר: חֲשָׁבָנוּ וְגִדְּלָנוּ מִבַּהֲמוֹת וּמֵעוֹף:",1,0],[35,12,"שָׁם יִצְעֲקוּ. וּרְאֵה, אֲשֶׁר שָׁם צוֹעֲקִים הָעֲנִיִּים מִפְּנֵי גְּאוֹן הָעוֹשְׁקִים אוֹתָם, וְהוּא אֵינוֹ עוֹנֶה.",1,0],[35,13,"אַךְ שָׁוְא לֹא יִשְׁמַע. מִיָּד:",1,0],[35,13,"וְשַׁדַּי לֹא יְשׁוּרֶנָּה. לְהִנָּקֵם מִיָּד, אֶלָּא מַאֲרִיךְ אַפּוֹ:",2,0],[35,14,"אַף כִּי תֹאמַר. כָּל שֶׁכֵּן אַתָּה, שֶׁאֵין צַעֲקָתְךָ בָּאָה כִּי אִם עַל יָדוֹ, וְאַתָּה תֹּאמַר וְתִזְעַק עַל אֲשֶׁר לֹא תְשׁוּרֶנּוּ לְהִתְוַכֵּחַ עִמּוֹ; כְּלוֹמַר: אוֹתָם הַקּוֹבְלִים וְצוֹעֲקִים אֵינוֹ מְמַהֵר לַעֲנוֹתָם, וְאַתָּה תִּצְעַק שֶׁלֹּא תְשׁוּרֶנּוּ?",1,0],[35,14,"דִּין לְפָנָיו. (דְּבָרְךָ סס״א) בְּכָל מָקוֹם שֶׁהוּא:",2,0],[35,14,"וּתְחוֹלֵל. וְקַוֵּה לְתַנְחוּמִין:",3,0],[35,15,"וְעַתָּה. דַּע לְךָ, כִּי אַיִן הִיא פְּקִידַת (אַפּוֹ) זֹאת עָלֶיךָ; אֵינָהּ כְּלוּם לְפִי רוֹב עֲווֹנוֹתֶיךָ:",1,0],[35,15,"וְלֹא יָדַע בַּפַּשׁ מְאֹד. בְּרוֹב חֲטָאֲךָ הִתְנַהֵג הַבּוֹרֵא כְּאִלּוּ לֹא יְדָעָם:",2,0],[35,15,"בַּפַּשׁ. לְשׁוֹן רוֹב, כְּמוֹ ״וּפִשְׁתֶּם״ (מלאכי ג:כ), וּכְמוֹ ״כִּי תָפוּשׁוּ וְגוֹ׳״ (ירמיה נ:יא); ״כִּי פָשָׂה הַנֶּגַע״ (ויקרא יג:נא):",3,0],[35,16,"יַכְבִּיר. לְשׁוֹן מְאֹד:",1,0],[36,1,"וַיֹּסֶף אֱלִיהוּא. רָאִיתִי בְּטַעֲמֵי רַבִּי מֹשֶׁה הַדַּרְשָׁן, שֶׁלְּפִיכָךְ אָמַר שְׁלֹשָׁה מַעֲנוֹת, כְּנֶגֶד שְׁלֹשֶׁת רֵיעֵי אִיּוֹב. וְזֶה רְבִיעִי, לְפִיכָךְ נִקְרָא תּוֹסֶפֶת:",1,0],[36,2,"כַּתַּר לִי זְעֵיר וַאֲחַוֶּךָּ. כֻּלּוֹ לְשׁוֹן אֲרַמִּי הוּא: הוֹחֵל לִי מְעַט וַאֲגִידְךָ. כַּתַּר לְשׁוֹן הוֹחֵל, כַּאֲשֶׁר תִּרְגֵּם יוֹנָתָן ״וּלְתוֹרָתוֹ אִיִּים יְיַחֵלוּ״ (ישעיהו מב:ד): ״יְכַתְּרוּן״:",1,0],[36,2,"לֶאֱלוֹהַּ. לַבָּאִים בִּמְקוֹמוֹ:",2,0],[36,4,"תְּמִים דֵּעוֹת עִמָּךְ. הִנֵּה אַתְחִיל עַתָּה לְדַבֵּר עִמָּךְ, שֶׁאַתָּה סָבוּר שֶׁדַּעְתְּךָ שְׁלֵמָה:",1,0],[36,5,"הֵן אֵל כַּבִּיר. בְּחָכְמָה וּבְרַחֲמִים:",1,0],[36,5,"וְלֹא יִמְאָס. עָנִי:",2,0],[36,5,"כַּבִּיר כֹּחַ לֵב. הוּא לְהִתְנַקֵּם, לְפִיכָךְ לֹא יְחַיֶּה רָשָׁע:",3,0],[36,7,"לֹא יִגְרַע מִצַּדִּיק עֵינָיו. עַד אֲשֶׁר עִם מְלָכִים יוֹשִׁיבֵם:",1,0],[36,8,"וְאִם אֲסוּרִים. וְאִם תִּרְאֶה צַדִּיקִים שֶׁיִּהְיוּ אֲסוּרִים בַּזִּיקִים שֶׁל יִסּוּרִין וָחֳלָיִים, אוֹ יִלָּכְדוּ בְּחַבְלֵי עֹנִי. בִּלְשׁוֹן גּוֹרָל וּמֵיתָרִים נִקְרָא חַבְלֵי, וּבִלְשׁוֹן דְּאָגָה נִקְרָא ״חֶבְלֵי יוֹלֵדָה״ (הושע יג:יג). בְּחַבְלֵי עֹנִי. קוֹדְרֵ״שׁ בְּלַעַ״ז. אֵינוֹ אֶלָּא שֶׁחָטְאוּ לְפָנָיו, וּבָא לִיפָּרַע מֵהֶם לְטוֹבָתָם, לְנַקּוֹתָם, וּלְהַזְהִירָם לָשׁוּב אֵלָיו:",1,0],[36,9,"וַיַּגֵּד לָהֶם פָּעֳלָם. בַּיִּסּוּרִין הַלָּלוּ מוֹדִיעָם שֶׁחָטְאוּ לְפָנָיו. וְכָל דִּבְרֵי אֱלִיהוּא תַּנְחוּמִין שְׁלֵמִים הָיוּ, וְלֹא קִנְתּוּרִין; כְּלוֹמַר: אַל תִּדְאַג עַל יִסּוּרִין, אִם צָדַקְתָּ, כִּי לְטוֹבָה הֵן לְךָ:",1,0],[36,10,"וַיֹּאמֶר. כִּי בְּיִסּוּרִין יְשׁוּבוּן מֵאָוֶן:",1,0],[36,11,"אִם יִשְׁמְעוּ. וְיַעַבְדוּהוּ:",1,0],[36,13,"וְחַנְפֵי לֵב. שֶׁהֵם רְשָׁעִים, הֵם יָשִׂימוּ אָף – בְּבֹא יִסּוּרִין עֲלֵיהֶם, מְחָרְפִים וּמְגַדְּפִים:",1,0],[36,13,"וְלֹא יְשַׁוְּעוּ. לְפָנָיו בִּתְחִנָּה:",2,0],[36,13,"כִּי אֲסָרָם. כְּשֶׁהוּא אוֹסְרָן בְּיִסּוּרִין, לְפִיכָךְ לֹא יִרְפָּאֵם:",3,0],[36,14,"תָּמֹת בַּנֹּעַר. וּבְשִׁנּוּק שֶׁעֲלֵיהֶם נַפְשָׁם:",1,0],[36,15,"יְחַלֵּץ עָנִי. אֶת הֶעָנִי, הַשָּׂם עַצְמוֹ רָשׁ בִּדְבַר תַּחֲנוּנִים, יְחַלֵּץ מִגֵּיהִנֹּם בִּשְׁבִיל עָנְיוֹ שֶׁהֵבִיא עָלָיו:",1,0],[36,15,"וְיִגֶל בַּלַּחַץ אָזְנָם. בַּלַּחַץ שֶׁהֵבִיא עָלָיו, מְגַלֶּה אֶת אָזְנוֹ, לֵאמֹר: שׁוּב אֵלַי!",2,0],[36,16,"וְאַף. זֹאת עוֹד גְּדוֹלָה עָשָׂה לְךָ בְּיִסּוּרִין הַלָּלוּ: הֲסִיתְךָ וְהִדִּיחֲךָ מִגֵּיהִנֹּם, שֶׁפִּיהָ צַר וְתַחְתֶּיהָ רָחָב:",1,0],[36,16,"לֹא מוּצָק. כְּדֵי שֶׁיְּהֵא עֲשָׁנָהּ צָבוּר לְתוֹכָהּ. וְלֹא עוֹד, אֶלָּא שֶׁתִּזְכֶּה לָעוֹלָם הַבָּא, וְנַחַת שֻׁלְחָנְךָ מָלֵא דָשֶׁן:",2,0],[36,17,"וְדִין רָשָׁע מָלֵאתָ. וְאִם נִתְמַלֵּאתָ בְּיִסּוּרֵי הָרְשָׁעִים, הַדִּין וְהַמִּשְׁפָּט הֵם הַיִּסּוּרִין; הֵם יִתְמֹכוּ לְךָ לֶעָתִיד מִגֵּיהִנֹּם, וְיֵשׁ לְךָ לְקַבְּלָם בְּאַהֲבָה:",1,0],[36,18,"כִּי חֵמָה. גְּדוֹלָה תִּהְיֶה:",1,0],[36,18,"פֶּן יְסִיתְךָ. יִצְרְךָ לְדַבֵּר דְּבָרִים:",2,0],[36,18,"בְּשָׂפֶק. בְּשָׂפֶק זֶה אֲשֶׁר תִּשְׂפֹּק, וְתֶרֶב אֲמָרֶיךָ לָאֵל. וּמֵאַחַר שֶׁתַּעֲלֶה הַחֵמָה, רָב מָמוֹן אַל יַטֶּךָּ מִמֶּנָּה:",3,0],[36,19,"הֲיַעֲרֹךְ שׁוּעֲךָ לֹא בְצָר. וְכִי בָּאתָה לַעֲרֹךְ צְעָקָה, שֶׁלֹּא תְּבוֹאֲךָ שׁוּם צָרָה וְשׁוּם מַאֲמַצֵּי כֹחַ לְאוֹנְסְךָ, אִם כֵּן בַּמֶּה יִגְבֶּה אֶת חוֹבוֹ?",1,0],[36,20,"אַל תִּשְׁאַף הַלָּיְלָה. כְּלוֹמַר: וְאֵין לְךָ לִבְחֹר בְּיִסּוּרִים אֲחֵרִים; אַל תִּשְׁאַף וְתִתְאַוֶּה הַלַּיְלָה שֶׁבָּא לְאַמְרָפֶל, לְמִצְרַיִם וּלְסַנְחֵרִיב, לְסַלֵּק עַמִּים מִן הָעוֹלָם, כְּשֶׁהֵם תַּחְתָּם – בִּמְקוֹמָם, בְּשַׁלְוָה; כִּי הֵם אָבְדוּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא:",1,0],[36,20,"לַעֲלוֹת. כְּמוֹ ״אַל תַּעֲלֵנִי בַּחֲצִי יָמָי״ (תהילים קב:כה), ״כַּעֲלוֹת גָּדִישׁ בְּעִתּוֹ״ (איוב ה:כו):",2,0],[36,21,"הִשָּׁמֶר אַל תֵּפֶן אֶל אָוֶן. לָדוּן וְלוֹמַר: הָיָה לוֹ לְשָׁפְטֵנִי בְּיִסּוּרֵי עֲנִיּוּת:",1,0],[36,21,"כִּי עַל זֶה בָּחַרְתָּ מֵעֹנִי. כִּי עַל הַיִּסּוּרִין הַלָּלוּ יֵשׁ לִבְחֹר יוֹתֵר מֵעֲנִיּוּת אָדָם שֶׁנָּהֲגוּ בּוֹ כָּבוֹד, וְלָמוּד בְּעֹשֶׁר כָּל יָמָיו, וְיַעֲמֹד עַל הַמֶּקַח וְאֵין לוֹ דָּמִים, וּבוֹשׁ וְשָׁב לְבֵיתוֹ בְּפַחֵי נֶפֶשׁ. וְאִם תֹּאמַר: אִיּוֹב עָנִי הָיָה עִם הַיִּסּוּרִין? לֹא מָצִינוּ שֶׁאִבֵּד, אֶלָּא בְּהֵמוֹתָיו, אֲבָל לֹא כֶּסֶף וְזָהָב. וַאֲפִלּוּ אִבֵּד בְּהֵמוֹתָיו עִם כֶּסֶף וְזָהָב, טוֹב לוֹ לִהְיוֹת עָנִי וְחוֹלֶה, מִהְיוֹת תָּמִים וְהוֹלֵךְ בַּשְּׁוָקִים וְאֵין בְּיָדוֹ כְּלוּם. וְכֵן מְפֹרָשׁ בְּמִדְרַשׁ רַבִּי תַּנְחוּמָא מִן הַמִּקְרָא הַזֶּה (תנחומא, משפטים יא), כִּי נוֹחִין הָיוּ יִסּוּרֵי אִיּוֹב מִיִּסּוּרֵי עֲנִיּוּת. וְכֵן בְּאַגָּדוֹת הַגְּמָרָא (בבא בתרא קטז.):",2,0],[36,22,"הֵן אֵל יַשְׂגִּיב בְּכֹחוֹ. מִתּוֹךְ שֶׁכֹּחוֹ גָּדוֹל וְאֵין לְהִנָּצֵל מִפָּנָיו, לְפִיכָךְ אֵין כָּמוֹהוּ מוֹרֶה. כְּשֶׁמּוֹרֶה לַחוֹטֵא לָשׁוּב אֵלָיו, מַתְרֶה קוֹדֶם מַכָּה, לְפִי שֶׁהוּא יוֹדֵעַ שֶׁאֵין יָכוֹל לְהִשָּׁמֵר מִמַּכָּתוֹ; כְּמוֹ שֶׁהָיָה מַתְרֶה בְּפַרְעֹה עַל כָּל מַכָּה וּמַכָּה: ״הִנְנִי מַמְטִיר כָּעֵת מָחָר בָּרָד״ (שמות ט:יח), וְ״הִנְנִי מֵבִיא מָחָר אַרְבֶּה״ (שמות י:ד); וְכֵן כֻּלָּם. וּבָשָׂר וָדָם, כְּשֶׁרוֹצֶה לְהִנָּקֵם מֵאוֹיְבָיו, בָּא עָלָיו פִּתְאוֹם; שֶׁאִם יַתְרֶה בּוֹ, יַחֲזֹר וְיִנָּצֵל מִמֶּנּוּ:",1,0],[36,23,"מִי פָקַד עָלָיו דַּרְכּוֹ. יְצַוֶּה עָלָיו מֵעוֹלָם: אֶת הַדֶּרֶךְ הַזֶּה תֵּלֵךְ:",1,0],[36,24,"זְכֹר. דְּרָכָיו, וּבְהַזְכִּירְךָ תַּשְׂגִּיא מֵאֵלֶיךָ שֶׁבַח פֹּעַל מִדּוֹתָיו:",1,0],[36,24,"אֲשֶׁר שֹׁרְרוּ אֲנָשִׁים. אֲשֶׁר רָאוּ אֲנָשִׁים, כְּמוֹ ״אֲשׁוּרֶנּוּ וְלֹא קָרוֹב״ (במדבר כד:יז):",2,0],[36,25,"חָזוּ בוֹ. בְּפָעֳלוֹ:",1,0],[36,25,"מֵרָחוֹק. מִיְּצִירַת עוֹלָם עַד עַכְשָׁיו:",2,0],[36,26,"מִסְפַּר שָׁנָיו וְלֹא חֵקֶר. לְפִיכָךְ צָרִיךְ לֶאֱנוֹשׁ לְהַבִּיט מֵרָחוֹק, לִשְׁאוֹל מַה שֶּׁאֵרַע בָּרִאשׁוֹנִים, וְיִלְמַד מֵהֶם:",1,0],[36,27,"כִּי יְגָרַע. כִּי יַרְבֶּה, כְּמוֹ ״וְתִגְרַע שִׂיחָה״ (איוב טו:ד). וְיֵשׁ פּוֹתְרִים: יִגְרָעֵם מִן הַשָּׁמַיִם, לְהוֹרִידָם אָרֶץ:",1,0],[36,27,"וְיָזֹקּוּ. הָרְקִיעִים אֶת הַמָּטָר:",2,0],[36,27,"לְאֵדוֹ. לַעֲנָנוֹ:",3,0],[36,29,"אַף אִם יָבִין. אוֹ אִם יָבִין אָדָם מַה יֵּשׁ בְּמִפְרְשֵׂי עָב, בִּתְמִיהַּ:",1,0],[36,29,"תְּשֻׁאוֹת. לְשׁוֹן עֲרָפֶל סֻכָּתוֹ:",2,0],[36,30,"הֵן פָּרַשׂ. עַל הֶעָב אֶת אוֹרוֹ, וְשָׁרְשֵׁי הַיָּם כִּסָּה בּוֹ:",1,0],[36,31,"כִּי בָם. בֶּעָבִים יָדִין עַמִּים – יְיַסְּרֵם בַּעֲצִירַת גְּשָׁמִים, בָּרָעָב וְכָל מַכָּה. חָטְאוּ דּוֹר הַמַּבּוּל – ״וַאֲרֻבֹּת הַשָּׁמַיִם נִפְתָּחוּ״ (בראשית ז:יא), אַנְשֵׁי סְדוֹם – ״גָּפְרִית וָמֶלַח שְׂרֵפָה כָל אַרְצָהּ״ (דברים כט:כב), סִיסְרָא – ״מִן הַשָּׁמַיִם נִלְחֲמוּ עִם סִיסְרָא״ (שופטים ה:כ):",1,0],[36,31,"יִתֶּן אֹכֶל לְמַכְבִּיר. מִשָּׁם בָּאִים מְזוֹנוֹת: ״הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם״ (שמות טז:ד). מָשָׁל לְנַחְתּוֹם הָעוֹמֵד לִפְנֵי הַכִּבְשָׁן – נִכְנַס שׂוֹנְאוֹ, חוֹתֶה גֶּחָלִים וְזוֹרֵק בּוֹ; נִכְנַס אוֹהֲבוֹ, מוֹצִיא פַּת חַמָּה וְנוֹתֵן לוֹ:",2,0],[36,31,"לְמַכְבִּיר. לְמִי שֶׁטְּפָלָיו מְרֻבִּים וְכַבִּירִים, וְצָרִיךְ לִמְזוֹנוֹת:",3,0],[36,32,"עַל כַּפַּיִם. עַל הֶעָנָנִים, וְכֵן ״נִשָּׂא לְבָבֵנוּ אֶל כַּפָּיִם״ (איכה ג:מא), עַל שֵׁם ״עָב קְטַנָּה כְּכַף אִישׁ״ (מלכים א יח:מד). וְרַבּוֹתֵינוּ אָמְרוּ (תענית ז:): עַל חָמָס וְעָוֹן כַּפַּיִם כִּסָּה אוֹר, הַמָּטָר נֶעֱצָר:",1,0],[36,32,"וַיְצַו עָלֶיהָ. לָבוֹא עַל יְדֵי מַפְגִּיעַ בִּתְפִלָּה, אוֹהֲבוֹ שֶׁל דּוֹר וְגָדוֹל וְחָכָם שֶׁבּוֹ, יַגִּיד עָלָיו לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא צָרַת הַדּוֹר וּצְרָכָיו:",2,0],[36,33,"יַגִּיד עָלָיו רֵעוֹ. יִדְרֹשׁ לָהֶם לִבְדֹּק לָהֶם בְּמַעֲשֵׂיהֶם וְלָשׁוּב אֵלָיו:",1,0],[36,33,"מִקְנֶה. וְזֶהוּ קִנְיָן שֶׁנִּקְנִין בּוֹ הַגְּשָׁמִים:",2,0],[36,33,"אַף עַל עוֹלֶה. גַּם לְמַעְלָה לְמַעְלָה, כְּמוֹ ״יָשׁוּבוּ אֶל עָל״ (הושע ז:טז), אוֹ ״הֻקַם עָל״ (שמואל ב כג:א). וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ (תענית ח.): קִנְיַן אַף וְחֵמָה עַל הַמֵּגִיס דַּעְתּוֹ. אֲבָל הַנִּקּוּד, שֶׁנִּקַּד מִקְנֶה – פַּתָּח, מוֹכִיחַ, שֶׁהוּא אֵינוֹ דָבוּק לְאַף; שֶׁאִלּוּ הָיָה דָבוּק, הָיָה נָקוּד קָמַץ, וְלֹא הָיָה בּוֹ פִּסּוּק הַטַּעַם, שֶׁהוּא נִטְעָם בִּ׳רְבִיעִי׳:",3,0],[37,1,"וְיִתַּר. וְיִקְפֹּץ, כְּמוֹ ״לְנַתֵּר בָּהֶם עַל הָאָרֶץ״ (ויקרא יא:כא). וְזוֹ הִיא שֶׁלִּבּוֹ תּוֹהֶה:",1,0],[37,2,"שִׁמְעוּ שָׁמוֹעַ בְּרֹגֶז קוֹלוֹ. הָרְעָמִים שֶׁהוּא מַרְעִים בָּרָקִיעַ, כְּהֶגֶה הַיּוֹצֵא מִפִּיו:",1,0],[37,3,"תַּחַת כָּל הַשָּׁמַיִם יִשְׁרֵהוּ. רְאִיתִיו, כְּמוֹ ״אֲשׁוּרֶנּוּ״ (במדבר כד:יז). וְהֵם אוֹתָם אוֹרוֹת שֶׁהַבְּרָקִים מְאִירִים:",1,0],[37,4,"אַחֲרָיו. שֶׁל אוֹתוֹ אוֹר, יִשְׁאַג הָרַעַם וּמַרְעִים בְּקוֹל גְּאוֹנוֹ, וְהֵם בְּרָקִים וּרְעָמִים הַמְּבִיאִים אֶת הַמָּטָר:",1,0],[37,4,"וְלֹא יְעַקְּבֵם. הַמָּקוֹם:",2,0],[37,4,"כִּי יִשָּׁמַע. לְפָנָיו קוֹלוֹ שֶׁל מַפְגִּיעַ (איוב לו:לב):",3,0],[37,4,"יְעַקְּבֵם. יַכְרִיתֵם, וּלְשׁוֹן מִשְׁנָה שָׁנִינוּ (סוטה טז.): בְּשָׁלֹשׁ מְקוֹמוֹת הֲלָכָה עוֹקֶבֶת מִקְרָא:",4,0],[37,6,"כִּי לַשֶּׁלֶג יֹאמַר. עַל יְדֵי הַקּוֹלוֹת הַלָּלוּ:",1,0],[37,6,"הֱוֵא אָרֶץ וְגֶשֶׁם מָטָר וְגֶשֶׁם מִטְרוֹת עֻזּוֹ. כְּלוֹמַר מֵאַרְבַּע רוּחוֹת יָבֹא:",2,0],[37,7,"בְּיַד כָּל אָדָם יַחְתּוֹם. כְּשֶׁאָדָם חוֹטֵא לְפָנָיו, הָאָדָם עַצְמוֹ חוֹתֵם כְּתַב יָדוֹ בְּיוֹם מוֹתוֹ עַל עֲבֵירוֹת שֶׁעָבַר, הַכְּתוּבוֹת לְפָנָיו:",1,0],[37,7,"לָדַעַת כָּל אַנְשֵׁי מַעֲשֵׂהוּ. לְהוֹדִיעַ עַל מָה הוּא נִידּוֹן:",2,0],[37,8,"וַתָּבֹא חַיָּה בְמוֹ אָרֶב. כְּלוֹמַר: וְעוֹד שְׁלוּחִים הַרְבֵּה יֵשׁ לַמָּקוֹם לִיפָּרַע פּוּרְעָנוּתָיו, שִׁלּוּחַ חַיּוֹת רָעוֹת וְסוּפָה וְקָרָה:",1,0],[37,9,"וּמִמְּזָרִים. אוֹצָר יֵשׁ וּשְׁמוֹ מְזָרִים:",1,0],[37,10,"מִנִּשְׁמַת. מֵרוּחוֹ:",1,0],[37,10,"וְרֹחַב מַיִם בְּמוּצָק. בִּיצִיקָה לְפֻרְעָנוּת:",2,0],[37,11,"אַף בְּרִי. שֵׁם מַלְאָךְ הַמְמֻנֶּה עַל הָעֲנָנִים, וְהוּא יָפִיץ עֲנַן מְטָרוֹ שֶׁל הַמָּקוֹם:",1,0],[37,11,"עֲנַן אוֹרוֹ. עֲנַן מְטָרוֹ:",2,0],[37,12,"וְהוּא. הַמְּמֻנֶּה:",1,0],[37,12,"מְסִבּוֹת מִתְהַפֵּךְ בְּתַחְבּוּלוֹתָיו. שֶׁל מָקוֹם:",2,0],[37,12,"לְפָעֳלָם. שֶׁל גְּשָׁמִים. לְפֹעַל הַמּוּטָּל עֲלֵיהֶם לַעֲשׂוֹת, אִם טוֹב וְאִם רַע, מִתְהַפֵּךְ בִּמְסִבּוֹת הַרְבֵּה. כְּאוֹתוֹ שֶׁשָּׁנִינוּ (ראש השנה יז:): הֲרֵי שֶׁהָיוּ יִשְׂרָאֵל צַדִּיקִים גְּמוּרִים בְּרֹאשׁ הַשָּׁנָה, וּפָסְקוּ לָהֶם גְּשָׁמִים; לְסוֹף סָרְחוּ – לִפְחוֹת מֵהֶם אִי אֶפְשָׁר, שֶׁכְּבָר נִגְזְרָה גְּזֵרָה; אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹרִידָם שֶׁלֹּא בִזְמַנָּם, וְעַל אֶרֶץ שֶׁאֵינָהּ צְרִיכָה לָהֶם. וְעִתִּים לְטוֹבָה; כֵּיצַד? וְכוּ׳:",3,0],[37,12,"כָּל אֲשֶׁר יְצַוֵּם. לְאוֹתָן גְּשָׁמִים לַעֲשׂוֹת לָאָרֶץ. דָּבָר אַחֵר: וְהוּא מְסִבּוֹת מִתְהַפֵּךְ בְּתַחְבּוּלוֹתָיו. מַקִּיף עֲנָנִים וְרוּחוֹת סְבִיבוֹת הֶהָרִים, שֶׁיִּהְיוּ שׁוֹתִים מִכָּל רוּחוֹתֵיהֶם. בְּאַגָּדַת ׳וְהָיָה עֵקֶב׳ (ספרי דברים לט):",4,0],[37,13,"אִם לְשֵׁבֶט. אִם לְפוּרְעָנוּת בְּנֵי אָדָם, מוֹרִידָם בֶּהָרִים וּגְבָעוֹת, שֶׁאֵין מְקוֹם זְרִיעָה:",1,0],[37,13,"אִם לְאַרְצוֹ. לְהוֹרִידָם כַּאֲשֶׁר נִגְזַר בִּתְחִלַּת דִּין, לֹא לְשֵׁבֶט וְלֹא לִפְנִים מִן הַשּׁוּרָה, אֶלָּא בְּבֵינוֹנִית:",2,0],[37,13,"אִם לְחֶסֶד. שֶׁנַּעֲשׂוּ הַדּוֹר עַכְשָׁיו יוֹתֵר צַדִּיקִים מִשֶּׁהָיוּ בְּרֹאשׁ הַשָּׁנָה, וְאוֹתָן גְּשָׁמִים שֶׁנִּגְזְרוּ בְּבֵינוֹנִית, מִתְהַפֵּךְ בְּתַחְבּוּלוֹת מְסִבּוֹתֵיהֶם, לֵירֵד בְּחֶסֶד בִּזְמַנָּם, וְעַל הָאָרֶץ הַצְּרִיכָה לָהֶם; שֶׁלֹּא תֵּרֵד הַטִּפָּה מֵהֶם לְאִבּוּד:",3,0],[37,13,"יַמְצִיאֵהוּ. לַמָּטָר, לְאַחַת מִן הַמִּדּוֹת הַלָּלוּ:",4,0],[37,15,"בְּשׂוּם אֱלוֹהַּ. חֹק בְּרִית עֲלֵיהֶם, הֵיאַךְ תְּלוּיִים בְּמַאֲמָר:",1,0],[37,16,"מִפְלְשֵׂי עָב. גִּילּוּי עָב, לְשׁוֹן מָבוֹי מְפוּלָּשׁ. כְּלוֹמַר: לְאָרְכָּן וּלְרָחְבָּן שֶׁל עָבִים:",1,0],[37,16,"הֲתֵדַע. עֲלֵיהֶם מִפְלְאוֹת תְּמִים דֵּעִים:",2,0],[37,17,"אֲשֶׁר בְּגָדֶיךָ חַמִּים. בַּמֶּה בְּגָדֶיךָ חַמִּים? בְּהַשְׁקִיטִי אֶרֶץ מֵרוּחַ דְּרוֹמִית, שֶׁאֵינָהּ הוֹרֶגֶת אֶת הָעוֹלָם בְּקָרָה; שֶׁרוּחַ מִזְרָחִית מְחַמֶּמֶת, שֶׁנֶּאֱמַר ״רוּחַ קָדִים חֲרִישִׁית״ (יונה ד:ח) – שֶׁמַּשְׁתֶּקֶת כָּל הָרוּחוֹת מִפָּנֶיהָ:",1,0],[37,18,"חֲזָקִים. הָרְקִיעִים:",1,0],[37,18,"כִּרְאִי מוּצָק. כִּרְאִי שֶׁהַנָּשִׁים רוֹאוֹת בּוֹ, (מוּצָק טְרִישְׁטְיֵי״ר וְהוּא חָזָק בְּיוֹתֵר):",2,0],[37,19,"הוֹדִיעֵנוּ מַה נֹּאמַר לוֹ. לְהַקָּדוֹשׁ בָּרוּךְ הוּא, בְּרִיבֵנוּ עִמּוֹ. לֹא נוּכַל לַעֲרֹךְ אֵלָיו מִפְּנֵי חֹשֶׁךְ. אֲשֶׁר סִתְרוֹ וּסְבִיבוֹתָיו (תהלים יח:יב):",1,0],[37,20,"הֲיְסֻפַּר לוֹ כִּי אֲדַבֵּר. וְכִי כְּמִדַּת הַבְּרִיּוֹת הוּא, שֶׁצָּרִיךְ שֶׁיְּסַפְּרוּ אֵלָיו דְּבָרִים הַיּוֹצְאִים מִפִּינוּ?",1,0],[37,20,"אִם אָמַר אִישׁ. אוֹמֵר מִפִּיו:",2,0],[37,20,"כִּי יְבֻלָּע. יְגֻלֶּה אֵלָיו מִיָּד, כְּמוֹ ״פֶּן יְבֻלַּע לַמֶּלֶךְ״ (שמואל ב יז:טז) יִגָּלֶה. וְרַבּוֹתֵינוּ פֵּרְשׁוּ (מגילה יח.) הַיְסֻפַּר כָּל שִׁבְחוֹ לוֹ כִּי אֲדַבֵּר. כִּי נְדַבֵּר בּוֹ וּבִגְבוּרָתוֹ, אִם אָמַר אִישׁ, לְסַפְּרָם כֻּלָּם כִּי יְבֻלָּע. מִמְּקוֹמוֹ:",3,0],[37,21,"וְעַתָּה לֹא רָאוּ אוֹר. בְּסוֹף דְּבָרָיו אֶל אֱלִיהוּא חָזַר לְקַנְתֵּר אוֹתָן שְׁלֹשֶׁת רֵיעֵי אִיּוֹב עַל לֹא מָצְאוּ מַעֲנֶה (איוב לב:א-ג), וְאָמַר: וְעַתָּה, שְׁלֹשֶׁת רֵיעֶיךָ אֵלֶּה, שֶׁהָיָה לָהֶם לַהֲשִׁיבְךָ כָּל דְּבָרִים אֵלּוּ שֶׁאָמַרְתִּי לְךָ, לֹא רָאוּ אוֹר. נַעֲשׂוּ הֵמָּה כִּנְפָלִים אֲשֶׁר לֹא רָאוּ חָכְמָה (איוב ג:טז):",1,0],[37,21,"בָּהִיר הוּא בַּשְּׁחָקִים. דּוֹמֶה לַבְּהִירִים הַנִּרְאִים בַּשְּׁחָקִים, לְהוֹרִיד גֶּשֶׁם:",2,0],[37,21,"וְרוּחַ עָבְרָה. וְרוּחַ בָּא וּמְטַהֲרָתָן וּמַעֲבִירָתָן, וְאֵין מָטָר יוֹרֵד. כָּךְ הוּא דֻּגְמָא שֶׁלָּהֶם: הִתְחִילוּ לַהֲשִׁיבְךָ, וְסוֹף עָמְדוּ וְלֹא עָנוּ (איוב לב:טז):",3,0],[37,22,"מִצָּפוֹן זָהָב יֶאֱתֶה. הֲרֵי הוּא כְּחוֹזֵר עַל הָרִאשׁוֹנוֹת. דָּבָר אַחֵר: מִדְרַשׁ חֲכָמִים (תענית ז:): כְּשֶׁהָרָקִיעַ מָלֵא בֶּהָרוֹת עֲנָנִים עֲנָנִים לְהוֹרִיד גֶּשֶׁם, רוּחַ עָבְרָה וַתְּטַהֲרֵם, וְאֵין גֶּשֶׁם יוֹרֵד. זֶה מִדְרַשׁ חֲכָמִים, וְאֵינָהּ מִתְיַשֶּׁבֶת עַל סֵדֶר הַמִּקְרָאוֹת:",1,0],[37,22,"מִצָּפוֹן זָהָב יֶאֱתֶה. מְנַשֵּׁב רוּחַ צְפוֹנִית וּמַעֲבִיר הַגֶּשֶׁם, וְהַחַמָּה זוֹרַחַת; כְּמוֹ ״הַמְּרִיקִים מֵעֲלֵיהֶם הַזָּהָב״ (זכריה ד:יב):",2,0],[37,22,"עַל אֱלוֹהַּ. מִלְּפָנָיו:",3,0],[37,22,"מִצָּפוֹן זָהָב יֶאֱתֶה. נִצְפַּן הַזָּהָב הַטּוֹב לְאוֹתָן שֶׁיֵּאָתִיּוּ אֶת עַצְמָן לְמִצְווֹת הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמַאֲמִינִים בֵּאלוֹהַּ הַנּוֹרָא מְאֹד:",4,0],[37,23,"שַׁדַּי לֹא מְצָאנוּהוּ שַׂגִּיא כֹחַ. לְעוֹרֵר מִשְׁפָּטָיו עַל הַבְּרִיּוֹת בְּגֹדֶל כֹּחוֹ, כִּי אִם בְּרַחֲמִים. וְכַפָּרַת הַבְּרִיּוֹת שָׂם בְּדָבָר מוּעָט לְפִי הַיְּכֹלֶת: קֹמֶץ מִנְחָה, מַחֲצִית הַשֶּׁקֶל, תּוֹרִים וּבְנֵי יוֹנָה, בָּקָר וְצֹאן; וְלֹא טָרַח לְבַקֵּשׁ רְאֵם וְיַחְמוּר:",1,0],[37,23,"וּמִשְׁפָּט. יִסּוּרִין:",2,0],[37,23,"לֹא יְעַנֶּה. הַבְּרִיּוֹת יוֹתֵר מִדַּאי, וְכֵן לֹא יְעַנֶּה הַצַּדִּיק יוֹתֵר מִדַּאי בְּמַה שֶׁאִי אֶפְשָׁר, כִּי אִם ״אִישׁ כְּמַתְּנַת יָדוֹ״ (דברים טז:יז):",3,0],[37,24,"לָכֵן יְרֵאוּהוּ אֲנָשִׁים. מִלְּהִתְוַכֵּחַ אֵלָיו, (כִּי) לֹא יִרְאֶה כָּל חַכְמֵי לֵב. הַמִּתְחַכְּמִים אֵלָיו, כִּי אֵין חָכְמָתָם בְּעֵינָיו כְּלוּם. וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ עַל אִיּוֹב (ראש השנה יז.), שֶׁאָמַר לוֹ אֱלִיהוּא: לְפִי שֶׁהָיִיתָ מֵטִיל אֵימָה יְתֵרָה עַל דּוֹרְךָ חִנָּם, לְפִיכָךְ לֹא זָכִיתָ לְהִתְקַיֵּם לְךָ בָּנִים חַכְמֵי לֵב:",1,0],[38,1,"(מענה מן הסערה): מִן הַסְּעָרָה: מְנֵה שְׂעָרוֹת שֶׁלְּךָ, וַאֲשִׁיבְךָ דְּבָרִים כְּנֶגְדָּן. מִן הַסְּעָרָה שֶׁחֵרַפְתַּנִי ״אֲשֶׁר בַּסְּעָרָה יְשׁוּפֵנִי״ (איוב ט:יז) – מִמֶּנָּה אָשִׁיב לְךָ, כַּאֲשֶׁר תִּשְׁמַע בְּסוֹף הָעִנְיָן: ״מִי פִלַּג לַשֶּׁטֶף תְּעָלָה״ (איוב לח:כה) – גּוּמָא לְכָל שֵׂעָר. דָּבָר אַחֵר: בַּסְּעָרָה הִכָּהוּ, בַּסְּעָרָה רִפְּאָהוּ. כִּדְמְפָרֵשׁ בְּסִפְרֵי (ילקוט שמעוני תורה רלה):",1,0],[38,2,"מַחְשִׁיךְ עֵצָה. עֵצָה חֲשֵׁכָה וּסְכָלָה. דָּבָר אַחֵר: מִי זֶה מַחְשִׁיךְ עֵצָה… בְּלִי דָעַת. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מִי זֶה הוּא מַחְשִׁיךְ עֵצָה – מְקַלְקֵל בְּמִלִּים וּבְרֹב דְּבָרִים? שֶׁכָּתַבְתִּי ״אִישׁ תָּם וְיָשָׁר״ בִּתְחִלַּת הַסֵּפֶר (איוב א:א), כְּדֵי לָחוּל שְׁמִי עָלָיו; וְהוּא בָּא וְהֶחְשִׁיךְ וְקִלְקֵל מַה שֶּׁיָּעַצְתִּי בְּרֹב דְּבָרָיו! וְאִיּוֹב עָנָהוּ: ״מִי זֶה מַעְלִים עֵצָה״ (איוב מב:ג) – אִלּוּ הָיִיתִי יוֹדֵעַ עֲצָתְךָ, לֹא הָיִיתִי מַרְבֶּה בִדְבָרִים. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֱשִׁיבוֹ: וַהֲלֹא אַבְרָהָם לֹא הָיָה יוֹדֵעַ, וְעָמַד בְּעֶשֶׂר! כָּךְ מָצָאתִי:",1,0],[38,3,"אֱזָר נָא כְגֶבֶר חֲלָצֶיךָ. רֶמֶז לוֹ שֶׁיִּתְעוֹרֵר מִן חָלְיוֹ וְיִסּוּרָיו:",1,0],[38,4,"אֵיפֹה. אֵי פֹּה:",1,0],[38,5,"מְמַדֶּיהָ. מִדּוֹתֶיהָ:",1,0],[38,6,"יָרָה אֶבֶן פִּנָּתָהּ. בְּאֶמְצַע הַיָּם, וּמִשָּׁם נִשְׁתַּת כָּל הָעוֹלָם:",1,0],[38,7,"בְּרָן יַחַד. מִתְּחִלָּה כּוֹכְבֵי אוֹר:",1,0],[38,8,"בִּדְלָתַיִם יָם. חוֹל גְּבוּל לוֹ:",1,0],[38,8,"בְּגִיחוֹ. בְּהַמְשָׁכָתוֹ יוֹצֵא מִן הַתְּהוֹם, כְּמוֹ ״גֹּחִי מִבָּטֶן״ (תהלים כב:י) – מוֹשְׁכִי:",2,0],[38,9,"בְּשׂוּמִי עָנָן. סְבִיבוֹת יָם אוֹקְיָינוֹס, שֶׁהוּא הֶיקֵּף הָעוֹלָם; וַעֲנָנִים סוֹבְבִים לוֹ כִּלְבוּשׁ:",1,0],[38,9,"חֲתֻלָּתוֹ. תַּכְרִיכוֹ, כְּמוֹ ״וְהָחְתֵּל לֹא חֻתָּלְתְּ״ (יחזקאל טז:ד):",2,0],[38,10,"וָאֶשְׁבֹּר. עָשִׂיתִי לוֹ שְׁבָרִים סָבִיב, לְעַכְּבוֹ בְּתוֹכָם. וְהֵם לוֹ חֹק אֲשֶׁר לֹא יַעַבְרֵם (ירמיה ה:כב), כְּמוֹ ״וַיִּרְדְּפוּם לִפְנֵי הַשַּׁעַר עַד הַשְּׁבָרִים״ (יהושע ז:ה) – וְהֵם תְּעָלוֹת סָבִיב לָעִיר:",1,0],[38,12,"הֲמִיָּמֶיךָ. מִיּוֹם שֶׁנּוֹלַדְתָּ:",1,0],[38,13,"לֶאֱחֹז בְּכַנְפוֹת הָאָרֶץ. וְעוֹד הֲמִיָּמֶיךָ צִוִּיתָ לֶאֱחֹז בְּכַנְפֵי הָאָרֶץ כְּאָדָם שֶׁאוֹחֵז בְּכַנְפֵי הַטַּלִּית וּמְנַעֲרָהּ? כֵּן אֲנִי עָתִיד לֶאֱחֹז בְּכַנְפוֹתֶיהָ וּלְנַעֵר אֶת הָרְשָׁעִים. וְכֵן הוּא אוֹמֵר ״וַה׳ יַטֶּה אֶת יָדוֹ וְכָשַׁל עוֹזֵר״ (ישעיהו לא:ג) כְּאָדָם הָאוֹחֵז בְּיָדוֹ דָּבָר, וּמַטֶּה יָדוֹ, וְהוּא נוֹפֵל:",1,0],[38,14,"תִּתְהַפֵּךְ. בְּצִיּוּרִין:",1,0],[38,14,"כְּחֹמֶר חוֹתָם. מִטֶּבַע צוּרַת הָאָדָם בְּמוֹתָן, וּבִתְחִיַּת הַמֵּתִים יִחְיוּ וְיַעַמְדוּ בִּלְבוּשֵׁיהֶם:",2,0],[38,15,"וְיִמָּנַע. אָז מֵרְשָׁעִים אוֹרָם. וְכֵן הוּא אוֹמֵר: וּזְרוֹעַ רָמָה תִּשָּׁבֵר:",1,0],[38,16,"נִבְכֵי יָם. מַסְגְּרֵי יָם, כְּמוֹ ״נְבֻכִים הֵם בָּאָרֶץ״ (שמות יד:ג):",1,0],[38,17,"שַׁעֲרֵי מָוֶת. זֶה גֵּיהִנֹּם:",1,0],[38,21,"יָדַעְתָּ. כָּל זֹאת:",1,0],[38,21,"כִּי אָז תִּוָּלֵד. כְּשֶׁבְּרָאתִים:",2,0],[38,23,"אֲשֶׁר חָשַׂכְתִּי. הִמְנַעְתִּי:",1,0],[38,23,"לְעֶת צָר. לַחֲמֵשֶׁת מְלָכִים בְּגִבְעוֹן (יהושע י:טז-כז):",2,0],[38,23,"לְיוֹם קְרָב. מִלְחֶמֶת גּוֹג וּמָגוֹג (יחזקאל לח-לט):",3,0],[38,24,"יֵחָלֶק אוֹר. תִּימוֹר שֶׁל חַמָּה מַפְצִיעַ לְכָאן וּלְכָאן כְּקַרְנֵי אַיָּל:",1,0],[38,24,"קָדִים. שֶׁמֶשׁ הַמִּזְרָח:",2,0],[38,25,"מִי פִלַּג לַשֶּׁטֶף תְּעָלָה. בַּעֲרַבְיָא קוֹרִין לְשַׂעֲרָה שִׁיטְפָא: כָּל שֵׂעָר וְשֵׂעָר שֶׁבָּרֹאשׁ פִּלַּגְתִּי לוֹ תְּעָלָה, גּוּמָא, לִינֹק מִמֶּנָּה; שֶׁאִלּוּ שְׁנַיִם יוֹנְקוֹת מִגּוּמָא אַחַת, מַחְשִׁיכוֹת מְאוֹר עֵינָיו שֶׁל אָדָם. וְהֵם לֹא נִתְחַלְּפוּ לִי, בֵּין אִיּוֹב לְאוֹיֵב נִתְחַלֵּף לִי?! וְזֶהוּ ״מִן הַסְּעָרָה״ (איוב לח:א). דָּבָר אַחֵר: לַשֶּׁטֶף. טִפַּת גֶּשֶׁם שׁוֹטֵף: פִּלַּגְתִּי לְכָל טִפָּה גּוּמָא בֶּעָבִים; שֶׁאִלּוּ יוֹרְדוֹת שְׁתֵּי טִפּוֹת מִגּוּמָא אַחַת, מְטַשְׁטְשׁוֹת אֶת הָאָרֶץ, וְנַעֲשֵׂית טִיט:",1,0],[38,25,"וְדֶרֶךְ לַחֲזִיז קוֹלוֹת. מִי פִלַּג? כָּל קוֹל וָקוֹל יֵשׁ לוֹ שְׁבִיל, וְאִם שְׁנַיִם הוֹלְכִים בִּשְׁבִיל אֶחָד, אֵין הַבְּרִיּוֹת סוֹבְלוֹת אֶת הַקּוֹל:",2,0],[38,27,"שׁוֹאָה. אֶרֶץ שֶׁהִיא חֲשֵׁכָה בְּרָעָב:",1,0],[38,28,"אֶגְלֵי טָל. גַּלֵּי טָל, וְהָאָלֶ״ף יְתֵרָה; כְּמוֹ ״וַאֲחַוֶּה דַעְתִּי בְאָזְנֵיכֶם״ (איוב יג:יז) – אָלֶ״ף יְתֵרָה בְּרֹאשׁ הַתֵּיבָה, לִהְיוֹתוֹ שֵׁם דָּבָר; וְכֵן ״אַבְחַת חֶרֶב״ (יחזקאל כא:כ) – כְּמוֹ נִבּוּחַ חֶרֶב, צַעֲקַת חֶרֶב. לָשׁוֹן אַחֵר: אֶגְלֵי. כְּמוֹ אַגְנֵי טָל, כְּמִין אֲגָנוֹת – פְּלָגִים, שֶׁהַטַּל נָתוּן בָּהֶם. לָמֶ״ד מִתְחַלֵּף בְּנוּ״ן; וְכֵן בְּסֵפֶר נְחֶמְיָה: ״נִשְׁכָּה״ (נחמיה יג:ז) כְּמוֹ ״לִשְׁכָּה״ (נחמיה יג:ה):",1,0],[38,29,"כְּפוֹר. גְּרִיסָ״א:",1,0],[38,30,"כָּאֶבֶן מַיִם יִתְחַבָּאוּ. עַל יְדֵי הַקֶּרַח שֶׁמַּגְלִיד טִפָּה שֶׁעַל פְּנֵיהֶם:",1,0],[38,30,"וּפְנֵי תְהוֹם יִתְלַכָּדוּ. בּוֹ, וְיִתְאַחֲזוּ כְּאֶחָד:",2,0],[38,31,"מַעֲדַנּוֹת כִּימָה. קִשּׁוּר כִּימָה, שֶׁלֹּא תֵצֵא כָּל קוֹרוֹתָיו, וְיַחֲרִיב אֶת הָעוֹלָם בְּצִנָּה:",1,0],[38,31,"אוֹ מוֹשְׁכוֹת כְּסִיל תְּפַתֵּחַ. לְהוֹצִיא חַמָּה, לְהָפִיג צִנָּתָהּ שֶׁל כִּימָה:",2,0],[38,32,"מַזָּרוֹת. כָּל שְׁאָר מַזָּלוֹת:",1,0],[38,32,"וְעַיִשׁ. כּוֹכָב גָּדוֹל שֶׁבַּכִּימָה, וְהַרְבֵּה כּוֹכָבִים קְבוּעִים בּוֹ; וְנָטַל שְׁנֵי כוֹכָבִים מִמֶּנָּה, לִפְתֹּחַ אֲרֻבּוֹת הַמַּבּוּל, וְנִבְקְעוּ בְּמַזַּל טָלֶה; וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲזִירָם לָהּ (תנחומא):",2,0],[38,33,"מִשְׁטָרוֹ. שְׁטִירַת הַמַּזָּלוֹת הַמְּמֻנִּים לְהָבִיא עַל הָאָרֶץ ״קֹר וָחֹם קַיִץ וָחֹרֶף״ (בראשית ח:כב):",1,0],[38,34,"הֲתָרִים לָעָב קוֹלֶךָ. לְצַוּוֹת עָלָיו לְהִתְקַשֵּׁר בְּחֶשְׁכַת מַיִם לִהְיוֹת שִׁפְעַת מַיִם מְתְכַסֶּךָ, וְהוּא קַדְרוּת הֶעָבִים, כְּמוֹ ״אוֹ חֹשֶׁךְ לֹא תִרְאֶה״ (איוב כב:יא). אוֹ שִׁפְעַת מַיִם. עַל פִּיךָ יְכַסֶּךָּ מִן הַשָּׁמַיִם:",1,0],[38,35,"וְיֹאמְרוּ לְךָ. בַּמָּקוֹם שֶׁנִּשְׁתַּלְּחוּ שָׁם הִנֵּנוּ, עָשִׂינוּ שְׁלִיחוּתְךָ! שֶׁאֵין צְרִיכִין לַחֲזֹר לִמְקוֹמָן, וּלְהָשִׁיב שׁלוּחָן, שֶׁהַשְּׁכִינָה בְּכָל מָקוֹם:",1,0],[38,36,"בַּטֻּחוֹת. אֵלּוּ הַכְּלָיוֹת:",1,0],[38,36,"לַשֶּׂכְוִי. זֶה תַּרְנְגוֹל; לְשׁוֹן חֲכָמִים (ראש השנה כו.). וְיֵשׁ אוֹמְרִים: זֶה הַלֵּב, שֶׁהוּא שׂוֹכֶה וְצוֹפֶה וּמְחַשֵּׁב אֶת הַנּוֹלָדוֹת:",2,0],[38,37,"יְסַפֵּר. יְדַבֵּר וְיַזְהִיר תַּפְקִידָם:",1,0],[38,37,"וְנִבְלֵי. עֲשׂוּיִין כְּנוֹדוֹת, וְהַגְּשָׁמִים כְּנוּסִים בּוֹ שָׁם, כְּמוֹ נֵבֶל יָיִן (שמואל א י:ג):",2,0],[38,38,"בְּצֶקֶת עָפָר. בְּיוֹם שֶׁיָּצַקְתִּי עָפָר:",1,0],[38,38,"לַמּוּצָק. לַיְּסוֹד עוֹלָם בְּאֶמְצָעִיתוֹ:",2,0],[38,38,"וּרְגָבִים יְדֻבָּקוּ. סְבִיבוֹתָיו לַצְּדָדִין, עַד כִּי נִתְמַלֵּא אָרְכּוֹ וְרָחְבּוֹ:",3,0],[38,40,"יָשׁוֹחוּ. עוֹמְדִים צְפוּפִים:",1,0],[38,40,"לְמוֹ אָרֶב. לֶאֱרוֹב. כֵּן דֶּרֶךְ הָאוֹרְבִים, לָשׁוּחַ וְלָכוֹף עַצְמָן, כְּדֵי שֶׁלֹּא יַכִּירוּ בָּהֶם:",2,0],[38,41,"יִתְעוּ לִבְלִי אֹכֶל. שֶׁאֲבִיהֶם שׂוֹנְאָם. הַקָּדוֹשׁ בָּרוּךְ הוּא מְזַמֵּן לָהֶם יַתּוּשִׁין, נִבְרָאִים מִצּוֹאָתָן, וְנִכְנָסִין לְתוֹךְ פִּיהֶם:",1,0],[39,1,"יַעֲלֵי סָלַע. אֶשְׁטַנְבּוֹ״ק, וְשׂוֹנְאָה אֶת וְלָדָהּ; וְעוֹלָה לְרֹאשׁ סֶלַע גָּבוֹהַּ כְּשֶׁכּוֹרַעַת לֵילֵד, כְּדֵי שֶׁיִּפּוֹל לָאָרֶץ וְיָמוּת. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְזַמֵּן לוֹ נֶשֶׁר וּמְקַבְּלוֹ בִּכְנָפָיו:",1,0],[39,1,"חוֹלֵל אַיָּלוֹת תִּשְׁמֹר. לְשׁוֹן ״חִיל יוֹלֵדָה״ (ירמיהו ו:כד). הָאַיָּלָה – רַחְמָהּ צַר, וְאֵין הַוָּלָד יָכוֹל לָצֵאת; וּבִשְׁעַת לֵידָתָהּ אֲנִי מְזַמֵּן לָהּ דְּרָקוֹן, וּמַכִּישָׁהּ בְּרַחְמָהּ, וְנִפְתָּח. וְאִם מַקְדִּים וּמְאַחֵר רֶגַע, מִיָּד מֵתָה. וּבֵין אוֹתָם רְגָעִים אֵינִי מַחֲלִיף, וּבֵין ׳אִיּוֹב׳ לְ׳אוֹיֵב׳ נִתְחַלֵּף לִי?!",2,0],[39,3,"תְּפַלַּחְנָה. מִתְבַּקֵּעַ רֶחֶם שֶׁלָּהֶם, וּמוֹצִיא הַוְּלָדוֹת, וְחֶבְלֵי לֵידָה שֶׁלָּהֶם:",1,0],[39,3,"תְּשַׁלַּחְנָה. מֵעֲלֵיהֶם בְּלִדְתָּן, לְרֶגַע שֶׁאֲנִי מַזְמִין לָהֶם:",2,0],[39,4,"יַחְלְמוּ. יֶחֱזְקוּ:",1,0],[39,4,"וְלֹא שָׁבוּ לָמוֹ. מִשֶּׁיִּרְבּוּ קְצָת, יִגְדְּלוּ בַּבָּר, בַּזְּרָעִים וּבַדְּשָׁאִים, וְאֵינָם צְרִיכִים לְגִדּוּל אֲבִיהֶם וְאִמָּם:",2,0],[39,5,"חָפְשִׁי. שֶׁאֵין אָדָם יָכוֹל לְגַדֵּל פֶּרֶא, לְלַמְּדוֹ עֲבוֹדַת בְּהֵמוֹת:",1,0],[39,5,"עָרוֹד. חֲמוֹר הַבָּר:",2,0],[39,5,"מִי פִתֵּחַ. מוֹסְרוֹתָיו, שֶׁאֵין עָלָיו עֹל אָדָם:",3,0],[39,8,"יְתוּר הָרִים מִרְעֵהוּ. הוּא עַצְמוֹ תָּר לוֹ מְקוֹם מִרְעֶה:",1,0],[39,9,"רֵים. כְּמוֹ ״רְאֵם״ (במדבר כג:כב):",1,0],[39,9,"עָבְדֶּךָ. לְעָבְדְּךָ:",2,0],[39,10,"בְּתֶלֶם עֲבֹתוֹ. (אוֹ קָשַׁרְתָּ רְאֵם בַּעֲבוּר תֶּלֶם שֶׁל שׁוֹרְךָ?) עֲבֹת. חֶבֶל שֶׁקּוֹשְׁרִין (שְׁוָורִים) לְתַלְמֵי הַמַּחֲרֵשָׁה:",1,0],[39,10,"יְשַׂדֵּד. יְתַקֵּן הַשָּׂדֶה:",2,0],[39,11,"הֲתִבְטַח בּוֹ. לֶאֱסֹף תְּבוּאָתְךָ, בִּשְׁבִיל שֶׁכֹּחוֹ רַב, וְיָכוֹל לִסְבֹּל הַרְבֵּה?",1,0],[39,11,"וְתַעֲזֹב אֵלָיו יְגִיעֶךָ. לֶאֱסֹף אֶל הַבַּיִת:",2,0],[39,13,"כְּנַף רְנָנִים נֶעֱלָסָה. כֵּן שֵׁם עוֹף גָּדוֹל רְנָנִים, וּלְשׁוֹן מִשְׁנָה קָרוּי בַּר יוֹכְנִי (בכורות נז:):",1,0],[39,13,"אֶבְרָה. כָּל עוֹף קָרוּי אֶבְרָה, עַל שֵׁם שֶׁפּוֹרֵחַ. כְּלוֹמַר: אוֹ עוֹף שֶׁשְּׁמוֹ חֲסִידָה, וְעוֹף שֶׁשְּׁמוֹ נֹצָה. רְאֵה מָה מִנְהָגָהּ:",2,0],[39,14,"תַּעֲזֹב לָאָרֶץ בֵּיצֶיהָ. וְהוֹלֶכֶת וּמִתְחַמֶּמֶת לְמֵרָחוֹק עַל עָפָר:",1,0],[39,15,"וַתִּשְׁכַּח כִּי רֶגֶל תְּזוּרֶהָ. לְבֵיצָתָהּ תְּבַקְּעֶנָּה:",1,0],[39,16,"הִקְשִׁיחַ. הִקְשָׁה בָּנֶיהָ מִלִּבָּהּ, כְּאִלּוּ אֵינָם שֶׁלָּהּ:",1,0],[39,16,"לְרִיק יְגִיעָהּ. וְאֵינָהּ יְרֵאָה שֶׁתְּאַבְּדֵם:",2,0],[39,18,"כָּעֵת בַּמָּרוֹם תַּמְרִיא. כָּל לְשׁוֹן הַמְרָאָה כְּאָדָם שֶׁזּוֹנֶה לִבּוֹ לָצֵאת מִמִּדָּתוֹ וּמִגִּדּוּלוֹ וּמֵאַרְצוֹ, לְשׁוֹטֵט לוֹ בָּאֲרָצוֹת, וּלְנַסּוֹת לוֹ מִדּוֹת אֲחֵרוֹת. וְכֵן ״בֵּן סוֹרֵר וּמוֹרֶה״ (דברים כא:יח). וּבִלְשׁוֹן גְּמָרָא: אִימְרָאִי כַּלְּתֵיהּ דְּרַב זְבִיד, אִימְרָאִי וְנָפְקָא (כתובות סג: ושם איתא אימרדא ועיין ברש״י בחולין נח ומציעא עו ד״ה ואימרו):",1,0],[39,19,"רַעְמָה. לְשׁוֹן רַעַם וּבְעָתָה, כְּמוֹ ״רָעֲמוּ פָנִים״ (יחזקאל כז:לה):",1,0],[39,20,"כָּאַרְבֶּה. מְדַלֵּג וּמְקַפֵּץ כָּאַרְבֶּה וּמַרְעִישׁ סְבִיבָיו:",1,0],[39,20,"נַחְרוֹ. כְּשֶׁהוּא נוֹפֵחַ בִּנְחִירָיו בְּקוֹל אֵימָה הוּא:",2,0],[39,21,"יַחְפְּרוּ בָעֵמֶק. כְּמוֹ ״וְיַחְפְּרוּ לָנוּ אֶת הָאָרֶץ״ (דברים א:כב), שֶׁדֶּרֶךְ הַפָּרָשִׁים אוֹרְבִים בָּעֲמָקִים וּבַנְּחָלִים:",1,0],[39,21,"וְיָשִׂישׂ בְּכֹחַ. וְהַסּוּס שָׂמֵחַ וְיוֹצֵא לִקְרַאת נָשֶׁק:",2,0],[39,22,"וְלֹא יֵחָת. וְלֹא יִירָא:",1,0],[39,23,"תִּרְנֶה אַשְׁפָּה. מְלֵאָה חִצִּים, וּמְקַשְׁקְשׁוֹת זוֹ בְּזוֹ וְנִשְׁמַע קוֹלָם:",1,0],[39,23,"לַהַב חֲנִית. כְּלִי שֶׁל בַּרְזֶל (וַחֲנִית שֶׁל בַּרְזֶל) קָרוּי לַהַב, כְּמוֹ ״וַיָּבֹא גַם הַנִּצָּב אַחַר הַלַּהַב״ (שופטים ג:כב):",2,0],[39,24,"יְגַמֶּא אָרֶץ. עוֹשֶׂה גֻּמּוֹת בְּרַגְלָיו. עִנְיָן אַחֵר: יְגַמֶּא כְּמוֹ ״הַגְמִיאִינִי נָא״ (בראשית כד:יז):",1,0],[39,24,"וְלֹא יַאֲמִין. מֵרוֹב שִׂמְחָה, שֶׁהוּא מִתְאַוֶּה לַמִּלְחָמָה:",2,0],[39,24,"כִּי קוֹל שׁוֹפָר. שֶׁל מִלְחָמָה:",3,0],[39,25,"בְּדֵי שׁוֹפָר. לְשׁוֹן ״דֵּי הָשִׁיב לוֹ״ (ויקרא כה:כח) – בְּהַרְבֵּה שׁוֹפָר:",1,0],[39,25,"יֹאמַר הֶאָח. לָשׁוֹן שֶׁאוֹמְרִים (הָעוֹבְרִים) כְּשֶׁהֵן שְׂמֵחִין, כְּמוֹ שֶׁאוֹמְרִים ״אֲהָהּ״ (יהושע ז:ז) מֵחֲמַת צַעַר:",2,0],[39,26,"יַאֲבֶר נֵץ. יִגְדַּל הַנֵּץ כָּנָף. וּמַלְאָךְ הוּא דּוֹמֶה לִדְמוּת נֵץ, וּמַעֲמִיד קֹשִׁי הָרוּחַ דְּרוֹמִית בִּפְרִישׂוּת כְּנָפָיו, שֶׁלֹּא תַּחֲרִיב אֶת הָעוֹלָם:",1,0],[39,27,"אִם עַל פִּיךָ יַגְבִּיהַּ נָשֶׁר. הַשְּׁכִינָה, שֶׁנֶּאֱמַר: ״כְּנֶשֶׁר יָעִיר קִנּוֹ״ (דברים לב:יא) – הָיָה מְסַלֵּק פָּמַלְיָא שֶׁלּוֹ, שֶׁלֹּא יַזִּיקוּ לְאַהֲרֹן בְּבוֹאוֹ אֶל הַקֹּדֶשׁ בְּיוֹם הַכִּפּוּרִים:",1,0],[39,28,"סֶלַע יִשְׁכֹּן וְיִתְלוֹנָן. בָּטוּחַ הָיָה אַהֲרֹן בְּמַחְתַּת הַקְּטֹרֶת, כְּשֶׁנְּתָנָהּ עַל אֶבֶן שְׁתִיָּה (יומא נג:):",1,0],[39,29,"מִשָּׁם חָפַר אֹכֶל. מִתְפַּלֵּל עַל צָרְכֵי כָּל הַשָּׁנָה. וְאַחַר כָּל הַכָּבוֹד הַזֶּה רָאָה בְּמִיתַת שְׁנֵי אֶפְרוֹחָיו נָדָב וַאֲבִיהוּא, שֶׁמֵּתוּ לְהִתְקַדֵּשׁ שְׁמִי בָּהֶם (ויקרא י:א-ב), שֶׁנָּפְלָה אֵימָתִי עַל הַשְּׁאָר:",1,0],[39,30,"יְעַלְעוּ. וְאֵינָן אֶלָּא כְּפִי מִדַּת בָּלְעוֹ דָּם וּמַיִם, וְנִרְאֶה כְּבוֹלֵעַ הַרְבֵּה, כְּאוֹמֵר ״עַל עַל״. וְכֵן בִּלְשׁוֹן חֲכָמִים בְּהַשְׁקָאַת סוֹטָה (סוטה כ.): מְעַרְעֲרִין אוֹתָהּ וּמַשְׁקִין אוֹתָהּ עַל כָּרְחָהּ. וְכֵן ״זַעֲקַת שֶׁבֶר יְעֹעֵרוּ״ (ישעיהו טו:ה) – לְשׁוֹן קְרִיאַת גָּרוֹן דּוֹמֶה לְכָךְ. וּלְפִי הַדֶּרֶךְ דִּבֵּר הַנָּבִיא:",1,0],[39,30,"וּבַאֲשֶׁר חֲלָלִים שָׁם הוּא. לֶאֱכוֹל. וְרַבּוֹתֵינוּ דִּמּוּ כָּל עִנְיָן זֶה בְּאַהֲרֹן, בִּפְסִיקְתָּא דְּ׳אַחֲרֵי מוֹת׳ (פסיקתא רבתי):",2,0],[40,2,"(מענה ה׳):הֲרֹב עִם שַׁדַּי יִסּוֹר. הַאִם שַׁדַּי – אָדָם יִשְׂתָּרֵר?",1,0],[40,2,"מוֹכִיחַ אֱלוֹהַּ יַעֲנֶנָּה. הַבָּא לְהִתְוַכֵּחַ, יַעֲנֶה דְּבָרָיו?",2,0],[40,5,"(מענה איוב): אַחַת דִּבַּרְתִּי. כְּלוֹמַר: מְעַט אָמַרְתִּי וְלֹא אוֹסִיף עוֹד. וְיֵשׁ פּוֹתְרִים: אַחַת דִּבַּרְתִּי, אֲשֶׁר אָמַרְתִּי (איוב ט:כב) ״תָּם וְרָשָׁע הוּא מְכַלֶּה״, לֹא אֶעֱנֶה עוֹד:",1,0],[40,5,"וּשְׁתַּיִם. שֶׁאָמַרְתִּי: ״אַל תַּעַשׂ עִמָּדִי״ (איוב יג:כ), לֹא אוֹסִיף:",2,0],[40,8,"(מענה ה׳ מן הסערה): הַאַף תָּפֵר מִשְׁפָּטִי. הַאַף תּוֹכִיחַ שֶׁדְּבָרֶיךָ לְהָפֵר מִשְׁפָּטִי, וּלְהַרְאוֹת שֶׁהוּא מְעֻקָּל?",1,0],[40,10,"עֲדֵה. לְשׁוֹן עֲדִי וְתַכְשִׁיט:",1,0],[40,12,"וְהָדוֹךְ. לְשׁוֹן ״דָּכוּ בַמְּדוֹכָה״ (במדבר יא:ח):",1,0],[40,15,"בְּהֵמוֹת. מוּכָן לֶעָתִיד:",1,0],[40,16,"כֹּחוֹ בְמָתְנָיו. בֵּיצָיו מְעוּכִים וְנִסְתָּרִים, וְלֹא נִתְּקוּ לְגַמְרֵי:",1,0],[40,16,"בִּשְׁרִירֵי. כְּמוֹ ״שָׁרְרֵךְ״ (שיר השירים ז:ג):",2,0],[40,17,"יַחְפֹּץ. כְּמוֹ יַחְפֹּז (להלך כג) – מִתְקַשֶּׁה. וְכֵן בִּלְשׁוֹן חֲכָמִים ׳דַּחֲפִיזָא כִּי אוּפְתָּא׳ (חולין מז:) – קָשֶׁה כָּעֵץ:",1,0],[40,17,"פַּחֲדָיו. בֵּיצָיו:",2,0],[40,17,"יְשֹׂרָגוּ. גְּדִילִים כְּמוֹ ״וַיִּשְׂתָּרְגוּ״ (איכה א:יד), אוֹ שְׂרִיגֵי מִטָּה בִּלְשׁוֹן מִשְׁנָה (כלים כד:ח), וְהוּא לְשׁוֹן גָּדִיל:",3,0],[40,18,"אֲפִיקֵי. חוֹזֶק:",1,0],[40,18,"גְּרָמָיו. עֲצָמָיו:",2,0],[40,18,"כְּמַטִּיל. כְּמַשָּׂאוֹי שֶׁל בַּרְזֶל:",3,0],[40,19,"רֵאשִׁית דַּרְכֵי אֵל. מִבְּרֵאשִׁית נִבְרָא רֹאשׁ לַבְּהֵמוֹת:",1,0],[40,19,"הָעֹשׂוֹ. הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעַצְמוֹ יִשְׁחֲטֶנּוּ:",2,0],[40,20,"כִּי בוּל הָרִים יִשְׂאוּ לוֹ. וּבְסֵפֶר תְּהִלִּים כָּתוּב ״בְּהֵמוֹת בְּהַרְרֵי אָלֶף״ (תהלים נ:י), אֶלֶף הָרִים נָשְׂאוּ לוֹ יְבוּל וּבְכָל יוֹם רוֹעֶה אֶת כֻּלָּם. (עד כאן יסד רש״י מכאן ואילך אינו לשון רש״י):",1,0],[40,21,"צֶאֱלִים. צֵל אִילָנוֹת:",1,0],[40,22,"יְסֻכֻּהוּ צֶאֱלִים צִלְלוֹ. אוֹתוֹ צֵל שֶׁל סֵתֶר קָנֶה וּבִצָּה מְסֻבָּךְ וּמְסֻכָּךְ בְּאִילָנוֹת הַרְבֵּה:",1,0],[40,23,"הֵן יַעֲשֹׁק נָהָר וְלֹא יַחְפּוֹז. פְּרָת, שֶׁמֵּימָיו פָּרִים וְרָבִים, וְהוּא נָהָר גָּדוֹל – עוֹשְׁקוֹ וְגוֹזְלוֹ מִן הַבְּרִיּוֹת בִּשְׁתוֹתוֹ:",1,0],[40,23,"וְלֹא יַחְפּוֹז. לֹא מִתְקַשֶּׁה בִּטְנוֹ עַל שְׁתִיָּתוֹ, כְּמוֹ יַחְפֹּץ זְנָבוֹ:",2,0],[40,23,"יִבְטַח כִּי יָגִיחַ יַרְדֵּן. בָּטוּחַ הוּא לִמְשֹׁךְ כָּל הַיַּרְדֵּן לְפִיהוּ, אִלּוּ הָיָה שׁוֹתֶה שָׁם. כְּמוֹ ״גֹּחִי מִבָּטֶן״ (תהלים כב:י):",3,0],[40,24,"בְּעֵינָיו יִקָּחֶנּוּ. הַמָּקוֹם יִקָּחֶנּוּ בְּהַבִּיטוֹ בּוֹ, וְנִרְעָד מֵאֵימָתוֹ:",1,0],[40,24,"בְּמוֹקְשִׁים. כְּלֵי אוּמָּנוּת שֶׁל צַיָּדִים, שֶׁשּׁוֹלִים בָּהֶם דָּגִים:",2,0],[40,25,"תִּמְשֹׁךְ לִוְיָתָן וְגוֹ׳. כַּאֲשֶׁר תִּמְשְׁכֶנּוּ בְּחַכָּה וְתָשִׂים אַגְמוֹן בְּאַפּוֹ, הֲיְדַבֵּר אֵלֶיךָ תַּחֲנוּנִים? כְּלוֹמַר: לֹא תוּכַל (לְהִתְקָרֵב אֵלָיו) בִּכְלִי מְצוּדָה:",1,0],[40,25,"תַּשְׁקִיעַ לְשׁוֹנוֹ. תַּשְׁקִיעַ חֶבֶל בִּלְשׁוֹנוֹ, לְהוֹצִיאוֹ מִמְּקוֹמוֹ:",2,0],[40,26,"אַגְמוֹן. הוּא כָּפוּף, כְּמוֹ ״כִּפָּה וְאַגְמוֹן״ (ישעיה ט:יג); וְעָשׂוּי שֶׁל בַּרְזֶל, לָצוּד בּוֹ דָּגִים:",1,0],[40,26,"הֲתָשִׂים. אִם תָּשִׂים אַגְמוֹן בְּאַפּוֹ לְהוֹצִיאוֹ מִן הַיָּם?",2,0],[40,26,"וּבְחוֹחַ. כְּלִי שֶׁל צַיָּדֵי דָּגִים:",3,0],[40,26,"תִּקּוֹב. כְּמוֹ תִּנְקֹב:",4,0],[40,27,"הֲיַרְבֶּה אֵלֶיךָ תַּחֲנוּנִים. אִם יַרְבֶּה לְךָ תַּחֲנוּנִים וִיבַקֵּשׁ עַל נַפְשׁוֹ, שֶׁתַּנִּיחֵהוּ?",1,0],[40,27,"אִם יְדַבֵּר. כֶּפֶל מִלָּה:",2,0],[40,27,"רַכּוֹת. דְּבָרִים שֶׁל תַּחֲנוּנִים:",3,0],[40,28,"הֲיִכְרוֹת בְּרִית עִמָּךְ. אִם יִכְרוֹת בְּרִית לְעָבְדְךָ, שֶׁתִּקָּחֶנּוּ לִהְיוֹת לְךָ עֶבֶד עוֹלָם?",1,0],[40,29,"הַתְשַׂחֶק. אִם תְּשַׂחֵק וּתְטַיֵּל בּוֹ, כְּאִלּוּ הוּא צִפּוֹר קָטָן?",1,0],[40,29,"וְאִם תִּקְשְׁרֶנּוּ לְצַוָּארֵי (ס״א לְצֹרֶךְ) נְעָרֶיךָ הַקְּטַנִּים, שֶׁיְּטַיְּלוּ בּוֹ; כְּצִפֳּרִים קְטַנִּים שֶׁנּוֹתְנִין לְתִינוֹקוֹת, לְטַיֵּל וּלְפַיְּסוֹ:",2,0],[40,30,"יִכְרוּ עָלָיו חַבָּרִים. אִם יִכְרוּ וְיַחְכְּמוּ עָלָיו חֲבֵרִים וּמְכַשְּׁפִים, לָצוּד אוֹתוֹ לְהוֹצִיאוֹ מִן הַיָּם עַל יְדֵי מְכַשְּׁפוֹת, שֶׁיֶּחֱצוּהוּ וִיחַלְּקוּהוּ בֵּין תַּגָּרִים; כְּעִנְיָן שֶׁעוֹשִׂים צַיָּדֵי הַיָּם, שֶׁצָּדִין דָּגִים גְּדוֹלִים בְּחָכְמָתָם, וּבָאִים הַתַּגָּרִים וְקוֹנִים מֵהֶם:",1,0],[40,30,"יִכְרוּ. לְשׁוֹן ״כּוֹרֶה שׁוּחָה״ (ירמיה יח:כב):",2,0],[40,30,"חַבָּרִים. לְשׁוֹן ״וְחֹבֵר חָבֶר״ (דברים יח:יא):",3,0],[40,30,"כְּנַעֲנִים. תַּגָּרִים:",4,0],[40,31,"הֲתְמַלֵּא. אִם תְּמַלֵּא תַּאֲוָתְךָ, וְתַעֲשֶׂה סֻכּוֹת מֵעוֹרוֹ:",1,0],[40,31,"וּבְצִלְצַל דָּגִים רֹאשׁוֹ. וְאִם תַּעֲשֶׂה מֵרֹאשׁוֹ צִלְצַל דָּגִים? כֶּפֶל לָשׁוֹן:",2,0],[40,31,"צִלְצַל. סֻכַּת דָּגִים. וְלַסֻּכָּה עֲשׂוּיָה מֵרֹאשׁוֹ קוֹרֵא אוֹתָהּ צִלְצַל דָּגִים, לְפִי שֶׁעֲשׂוּיָה מִמֶּנּוּ:",3,0],[40,31,"צִלְצַל. אַמְבּוֹרִיץ בְּלַעַ״ז, לְשׁוֹן צֵל הוּא, וְהוּא מִתֵּיבוֹת כְּפוּלוֹת, כְּמוֹ ״יְרַקְרַק אֲדַמְדַּם״ (ויקרא יג:מט), ״פְּתַלְתֹּל״ (דברים לב:ה), ״קַעֲקַע״ (ויקרא יט:כח):",4,0],[40,32,"שִׂים עָלָיו כַּפֶּךָ. הִתְגַּבֵּר לַעֲרֹךְ לְפָנָיו, שֶׁתָּשִׂים עָלָיו כַּפֶּיךָ לְהַכּוֹתוֹ:",1,0],[40,32,"זְכֹר מִלְחָמָה אַל תּוֹסַף. וְאַל תּוֹסִיף זְכֹר גְּבוּרָתְךָ, לְהִלָּחֵם בּוֹ בַּמִּלְחָמָה:",2,0],[40,32,"אַל תּוֹסַף. מִן יָסַף, כְּמוֹ ״וְלֹא יָסַף עוֹד לְדַעְתָּהּ״ (בראשית לח:כו); וּבְלַעַ״ז רֶקְרֵייטְרַ״שׁ. אַל תּוֹסַף. סָמֶ״ךְ נִפְתַּחַת, מִפְּנֵי סוֹף פָּסוּק; כְּמוֹ ״אַל תּוֹתַר״ (בראשית מט:ד); ״וַתֹּתַר״ (רות ב:יד); וְכֵן הַרְבֵּה כָּמוֹהוּ:",3,0],[41,1,"הֵן תּוֹחַלְתּוֹ נִכְזָבָה. הֵן אִם תּוֹחַלְתּוֹ נִכְזָבָה, שֶׁלֹּא יְהֵא בּוֹ כֹּחַ לְהִלָּחֵם וְלָזוּז מִמְּקוֹמוֹ:",1,0],[41,1,"הֲגַם אֶל מַרְאָיו יֻטָּל. אִם גַּם אֶל מַרְאִית פָּנָיו יֻטַּל וְיֻשְׁלַךְ אָדָם, לַעֲמֹד לְפָנָיו לְהִסְתַּכֵּל בּוֹ, מִפְּנֵי אֵימָתוֹ:",2,0],[41,2,"לֹא אַכְזָר כִּי יְעוּרֶנּוּ. אֵין אַכְזָר גִּבּוֹר וְעָרִיץ, אֲשֶׁר יְעִירֶנּוּ מִשְּׁנָתוֹ, וִיעוֹרְרֶנּוּ מִמְּקוֹמוֹ לַהֲקִימוֹ:",1,0],[41,2,"וּמִי הוּא וְגוֹ׳. אֲשֶׁר יִתְיַצֵּב וְיַעֲמֹד לְפָנַי, אֲשֶׁר אֲנִי עוֹשֶׂה אֶת כָּל אֵלֶּה:",2,0],[41,3,"מִי הִקְדִּימַנִי. וּמִי הוּא אֲשֶׁר הִקְדִּים פָּנַי בְּהַקְבָּלָתוֹ, לְעָבְדֵנִי וְלִשְׁמֹר מִצְוֹתַי, וַאֲשַׁלֵּם לוֹ שְׂכָרוֹ?",1,0],[41,3,"תַּחַת כָּל הַשָּׁמַיִם לִי הוּא. כָּל אֲשֶׁר בַּשָּׁמַיִם לִי הוּא, וּבְיָדִי לִפְרֹעַ לוֹ שְׂכָרוֹ וּפְעֻלָּתוֹ וּמַעֲבָדוֹ:",2,0],[41,4,"לֹא אַחֲרִישׁ בַּדָּיו. לֹא אַחֲרִישׁ עַל בָּנָיו שֶׁל צַדִּיק, שֶׁהָלַךְ לְפָנַי בְּתָמִים, וּלְבָנָיו יִשְׁתַּלְּמוּ שְׂכַר טוֹב אֲבִיהֶם, וְיִמְצְאוּ טוֹבָה בִּזְכוּתוֹ:",1,0],[41,4,"וּדְבַר גְּבוּרוֹת וְחִין עֶרְכּוֹ. וּדְבַר גְּבוּרוֹתָיו אֲשֶׁר נִתְגַּבֵּר לַעֲשׂוֹת הַטּוֹב וְהַיָּשָׁר, וּתְחִנַּת סִדּוּרוֹ שֶׁל צַדִּיק אֲשַׁלֵּם שְׂכָרוֹ גַּם לְבָנָיו אַחֲרָיו:",2,0],[41,4,"בַּדָּיו. עֲנָפָיו, וְהֵם בָּנָיו, כְּמוֹ ״וַתַּעַשׂ בַּדִּים וַתִּשְׁלַח פֹּארוֹת״ (יחזקאל יז:ו):",3,0],[41,5,"מִי גִלָּה פְּנֵי לְבוּשׁוֹ. חוֹזֵר עַל הָרִאשׁוֹנוֹת, לְדַבֵּר עַל לִוְיָתָן. מִי יוּכַל לְגַלּוֹת קַשְׂקַשּׂוֹת שֶׁהֵן בְּכֶפֶל רִסְנוֹ, בְּכֶפֶל שְׂפָתָיו כְּשֶׁהֵן פְּתוּחוֹת מִי הוּא אֲשֶׁר יִכָּנֵס שָׁם. בְּכֶפֶל הֵן הַשְּׂפָתַיִם, שֶׁהֵן כְּפוּלוֹת: אַחַת לְמַעְלָה וְאַחַת לְמַטָּה, שֶׁאֵין בְּרִיָּה רַשָּׁאָה לִיכָּנֵס שָׁם מִפְּנֵי אֵימָתוֹ:",1,0],[41,6,"דַּלְתֵי פָנָיו. הֵן הַשְּׂפָתַיִם; כְּשֶׁהוּא סוֹגֵר פִּיו, מִי יוּכַל לְפָתְחָן?",1,0],[41,6,"סְבִיבוֹת שִׁנָּיו אֵימָה. אֲשֶׁר מִפְּנֵי פַּחְדּוֹ וְאֵימָתוֹ אֵין בְּרִיָּה יְכוֹלָה לְהִתְקָרֵב לְשִׁנָּיו:",2,0],[41,7,"גַּאֲוָה אֲפִיקֵי מָגִנִּים. גַּאֲוָה גְּדוֹלָה יֵשׁ לוֹ בְּחֹזֶק מָגִנָּיו, הֵן קַשְׂקַשִּׂים שֶׁעָלָיו, הַמְּגִנִּין עָלָיו כְּמָגֵן:",1,0],[41,7,"סָגוּר. הוּא חוֹתַם שִׁרְיוֹנוֹ, שֶׁהוּא צַר וְסָגוּר וְעָצוּם; שֶׁכָּל קַשְׂקֶשֶׂת וְקַשְׂקֶשֶׂת דְּבוּקָה בּוֹ וַאֲדוּקָה לַחֲבֶרְתָּהּ, שֶׁאֵין בְּרִיָּה יְכוֹלָה לְהַכּוֹתוֹ בֵּין הַדְּבָקִים (מלכים א כב:לד). וְזֶהוּ שֶׁנֶּאֱמַר: אֶחָד בְּאֶחָד יִגַּשׁוּ. שֶׁכֻּלָּן מֻגָּשׁוֹת וּתְכוּפוֹת זוֹ לָזוֹ:",2,0],[41,9,"יִתְלַכְּדוּ וְלֹא יִתְפָּרָדוּ. עֲדַיִן כּוֹפֵל לְשׁוֹנוֹ, שֶׁנִּלְכָּדוֹת וְנֶאֱחָדוֹת כָּל אַחַת וְאַחַת בַּחֲבֶרְתָּהּ, שֶׁלֹּא תִּהְיֶינָה מִתְפָּרְדוֹת זוֹ מִזּוֹ:",1,0],[41,10,"עֲטִישֹׁתָיו תָּהֶל אוֹר. בְּכָל עֲטִישָׁה וַעֲטִישָׁה שֶׁהוּא מִתְעַטֵּשׁ, יָהֶל וְתִזְרַח אוֹר:",1,0],[41,10,"תָּהֶל. כְּמוֹ ״בְּהִלּוֹ נֵרוֹ״ (איוב כט:ג):",2,0],[41,10,"וְעֵינָיו כְּעַפְעַפֵּי שָׁחַר. עֵינָיו זוֹרְחוֹת וּמְאִירוֹת כְּדִמְדּוּמֵי חַמָּה, כְּמוֹ לְעֵת בֹּקֶר שֶׁהַשֶּׁמֶשׁ מִתְאַדֶּמֶת:",3,0],[41,11,"מִפִּיו. מִלַּהֶבֶת הַיּוֹצֵאת מִמֶּנּוּ:",1,0],[41,11,"מִפִּיו לַפִּידִים יַהֲלֹכוּ. לַפִּידִים יוֹצְאוֹת מִפִּיו:",2,0],[41,11,"כִּידוֹדֵי אֵשׁ. כְּמוֹ לַפִּידִים:",3,0],[41,11,"יִתְמַלָּטוּ. פִּתְרוֹנוֹ לְפִי עִנְיָנוֹ שוינ״ט אישקמוצי״ר בְּלַעַ״ז:",4,0],[41,12,"מִנְּחִירָיו יֵצֵא עָשָׁן. כְּסִיר נָפוּחַ עַל הָאֵשׁ, שֶׁמַּעֲלֶה עָשָׁן:",1,0],[41,12,"וְאַגְמוֹן. פִּתְרוֹנוֹ לְפִי עִנְיָנוֹ, לְשׁוֹן כְּלִי חֶרֶשׂ הוּא, כְּמוֹ דּוּד נָפוּחַ; כְּעִנְיָן שֶׁנֶּאֱמַר ״סִיר נָפוּחַ אֲנִי רֹאֶה״ (ירמיהו א:יג):",2,0],[41,13,"נַפְשׁוֹ גֶּחָלִים תְּלַהֵט. גֶּחָלִים בּוֹעֲרוֹת וְלוֹהֲטוֹת, וְלַהֲבוֹת דּוֹלְקוֹת יוֹצְאוֹת מִפִּיו:",1,0],[41,14,"בְּצַוָּארוֹ יָלִין עֹז. גְּבוּרָה:",1,0],[41,14,"וּלְפָנָיו תָּדוּץ דְּאָבָה. שֶׁאֵין דַּאֲבוֹן וְעִצָּבוֹן לְפָנָיו, שֶׁאֵינוֹ מִתְיָרֵא מִשּׁוּם בְּרִיָּה. תָּדוּץ לְשׁוֹן דִּיצָה וְשִׂמְחָה:",2,0],[41,15,"מַפְּלֵי בְשָׂרוֹ דָבֵקוּ. נִדְבָּקוֹת וּתְכוּפוֹת זוֹ בָּזוֹ, שֶׁהַדָּגִים הֵן נַעֲשִׂין חֲתִיכוֹת חֲתִיכוֹת בִּבְשָׂרוֹ, וּמְדֻבָּקוֹת זוֹ בָּזוֹ. וּבְדָג גָּדוֹל כְּשֶׁהוּא מְבֻשָּׁל, נִרְאוֹת חֲתִיכוֹת כְּשֶׁהֵן שׁוֹכְבוֹת זוֹ עַל זוֹ וְזוֹ אֵצֶל זוֹ. וְכֵן הוֹלֵךְ סִדּוּר הַמִּלָּה: תְּחִלָּה דִּבֵּר בְּקַשְׂקַשּׂוֹתָיו שֶׁל לִוְיָתָן וְאַחַר כֵּן בַּחֲתִיכוֹת בְּשָׂרוֹ וְחֹזֶק לִבּוֹ:",1,0],[41,15,"מַפְּלֵי. לְשׁוֹן כְּפִילוּת חֲתִיכוֹת. וְיֵשׁ לוֹמַר כְּמוֹ פְּלָאֵי פְּלוּיֵי שֶׁבִּלְשׁוֹן גְּמָרָא (נדה כא:) לְשׁוֹן בִּקּוּעַ בִּקּוּעֵי חֲתִיכוֹתָיו:",2,0],[41,15,"דָבֵקוּ. בֵּי״ת קְמוּצָה בְּקָמַץ קָטָן, כְּמוֹ ״וּלְשׁוֹנָם לְחִכָּם דָּבֵקָה״ (איוב כט:י), וְכֵן הַרְבֵּה בְּאֶתְנַחְתָּא וְסוֹף פָּסוּק:",3,0],[41,15,"יָצוּק עָלָיו. כָּל מַפָּל וּמַפָּל יָצוּק זֶה עַל זֶה אֲשֶׁר לֹא יִמּוֹט וְלֹא יִתְפָּרֵד זֶה מֵעַל זֶה. יָצוּק לְשׁוֹן ״מוּצָק״ (איוב לז:יח), וְהוּא לְשׁוֹן עָשׂוּי, כְּמוֹ יָרוּד מִן יָרַד, יָצוּק מִן יָצַק, ״יָדוּעַ״ (ישעיה נג:ג) מִן יָדַע:",4,0],[41,16,"לִבּוֹ יָצוּק כְּמוֹ אָבֶן. לִבּוֹ בְּקִרְבּוֹ חָזָק וּמְיֻסָּד כְּאֶבֶן הַקְּבוּעָה וּנְתוּנָה בִּיסוֹד הַבִּנְיָן בְּחֹזֶק:",1,0],[41,16,"יָצוּק כְּפֶלַח תַּחְתִּית. כּוֹפֵל מִלָּתוֹ, שֶׁמְּיֻסָּד לִבּוֹ וְקָבוּעַ כְּפֶלַח שֶׁל רֵחַיִם, שֶׁנָּתוּן בְּתַחְתִּיתוֹ שֶׁל פֶּלַח רֶכֶב. שֶׁפֶּלַח רֶכֶב שֶׁלְּמַעְלָה – הוּא סוֹבֵב וּמִתְגַּלְגֵּל וְטוֹחֵן, וְשֶׁל מַטָּה – אֵינוֹ זָז מִמְּקוֹמוֹ כִּי קָבוּעַ הוּא בִּמְקוֹמוֹ, אֲשֶׁר לֹא יִמּוֹט (ישעיהו מ:כ). הוּא נִקְרָא ׳פֶּלַח׳, שֶׁנֶּאֱמַר ״וַתַּשְׁלֵךְ אִשָּׁה אַחַת פֶּלַח רֶכֶב עַל רֹאשׁ אֲבִימֶלֶךְ״ (שופטים ט:נג), וְאֶת שֶׁלְּמַטָּה קָרוּי פֶּלַח תַּחְתִּית:",2,0],[41,17,"מִשֵּׂתוֹ יָגוּרוּ אֵלִים. מִפַּחְדּוֹ מִתְיָרְאִים גִּבּוֹרִים וַחֲזָקִים, בֵּין דָּגִים בֵּין שְׁאָר בְּרִיּוֹת:",1,0],[41,17,"מִשְּׁבָרִים יִתְחַטָּאוּ. גַּלֵּי הַיָּם, שֶׁקְּרוּיִין מִשְׁבָּרִים, הֵן חֲסֵרִין לְפָנָיו; שֶׁהוּא שׁוֹבְרָן בִּפְרִיחָתוֹ, כַּאֲשֶׁר הוּא פּוֹרֵחַ וְצָף בְּגַלֵּי הַיָּם:",2,0],[41,17,"יִתְחַטָּאוּ. לְשׁוֹן חִסָּרוֹן, כְּמוֹ ״וְהָיִיתִי אֲנִי וּבְנִי שְׁלֹמֹה חַטָּאִים״ (מלכים א א:כא):",3,0],[41,18,"מַשִּׂיגֵהוּ חֶרֶב בְּלִי תָקוּם. גִּבּוֹר הַמַּשִּׂיגֵהוּ לְהִלָּחֵם בְּחֶרֶב – לֹא יִתְקַיֵּם חַרְבּוֹ, כִּי הוּא יִשְׁבְּרֶנָּה:",1,0],[41,18,"חֲנִית מַסָּע וְשִׁרְיָה. וְכֵן כָּל כְּלֵי מִלְחָמָה הַלָּלוּ שֶׁבְּיַד הַמַּשִּׂיג, לֹא יִתְקַיְּמוּ וְלֹא יַעַמְדוּ לְפָנָיו שֶׁל לִוְיָתָן. מַסָּע. יֵשׁ לוֹמַר שֶׁהוּא אֶחָד מִכְּלֵי מִלְחָמָה, כְּמוֹ חֶרֶב וַחֲנִית וְשִׁרְיָה. וְיֵשׁ לוֹמַר מַסָּע דּוּגְמַת ״אֶבֶן שְׁלֵמָה מַסָּע וְגוֹ׳״ (מלכים א ו:ז). וְזֶהוּ פִּתְרוֹנוֹ: חֲנִית מַסָּע שֶׁהוּא גָּדוֹל וְאֵינוֹ נוֹחַ לְטַלְטֵל כָּל כָּךְ, מִפְּנֵי שֶׁהוּא גָּדוֹל וְחָזָק מְאֹד; כְּעִנְיָן שֶׁנֶּאֱמַר בְּגָלְיַת הַפְּלִשְׁתִּי ״וְחֵץ חֲנִיתוֹ כִּמְנוֹר אֹרְגִים וְלַהֶבֶת חֲנִיתוֹ שֵׁשׁ מֵאוֹת וְגוֹ׳״ (שמואל א יז:ז):",2,0],[41,18,"וְשִׁרְיָה. שִׁרְיוֹן:",3,0],[41,19,"יַחְשֹׁב לְתֶבֶן בַּרְזֶל. כְּלֵי זַיִן שֶׁל בַּרְזֶל חֲשׁוּבִים לְפָנָיו כְּתֶבֶן, וּכְלֵי זַיִן שֶׁל נְחֹשֶׁת הֵם לְפָנָיו כִּרְקֵבוּת עֵץ.",1,0],[41,20,"לֹא יַבְרִיחֶנּוּ בֶן קָשֶׁת. לֹא יִבְרַח מִפְּנֵי בַּעַל קֶשֶׁת וְחִצִּים, וְאַבְנֵי בַּלִּיסְטְרָאוֹת הֲרֵי הֵן לְפָנָיו כְּקַשׁ:",1,0],[41,21,"תּוֹתָח. הוּא כְּלִי זַיִן, וּפִתְרוֹנוֹ לְפִי עִנְיָנוֹ:",1,0],[41,21,"וְיִשְׂחַק לְרַעַשׁ כִּידוֹן. לְרַעַשׁ מְהוּמַת בַּעֲלֵי מִלְחָמוֹת נוֹטְלֵי כִּידוֹן, הוּא מְשַׂחֵק וּמְטַיֵּל; שֶׁאֵינוֹ מִתְיָרֵא מִפְּנֵיהֶם:",2,0],[41,22,"תַּחְתָּיו חַדּוּדֵי חָרֶשׂ. בִּמְקוֹם חֲנִיָּתוֹ יֵשׁ זָהֳרוּרֵי שֶׁמֶשׁ, כִּי סְנַפִּירִים שֶׁלּוֹ, אֲשֶׁר תַּחְתָּיו – בְּבִטְנוֹ, מְאִירוֹת וּמַזְרִיחוֹת כַּשֶּׁמֶשׁ:",1,0],[41,22,"חַדּוּדֵי. כְּמוֹ ״חֶרֶב חַדָּה״ (יחזקאל ה:א), שֶׁהִיא שְׁנוּנָה, צַחָה וּמְלֻבָּנָה; וְעַל שֵׁם כָּךְ קוֹרֵא לְזַהֲרוּרֵי – חַדּוּדֵי:",2,0],[41,22,"חָרֶשׂ. שֶׁמֶשׁ, כְּמוֹ ״הָאוֹמֵר לַחֶרֶס לֹא יִזְרָח וְגוֹ׳״ (איוב ט:ז), ״בְּטֶרֶם תָּבֹא הַחַרְסָה״ (שופטים יד:יח):",3,0],[41,22,"יִרְפַּד חָרוּץ עֲלֵי טִיט. מִלָּה כְּפוּלָה, יִרְפַּד חָרוּץ מוּסָב עַל חִדּוּדֵי חֶרֶס, עֲלֵי טִיט מוּסָב עַל תַּחְתִּיתוֹ, בִּמְקוֹם שֶׁהוּא שָׂם עַל הַחוֹל, זֶה טִיט רִפּוּדוֹ מַזְרִיחַ כְּזָהָב חָרוּץ, כְּעִנְיָן שֶׁנֶּאֱמַר ״רְפִידָתוֹ זָהָב״ (שיר השירים ג:י), חָרוּץ מִין זָהָב, כְּעִנְיָן שֶׁנֶּאֱמַר ״מֵחָרוּץ תְּבוּאָתָהּ״ (משלי ג:יד), ״טוֹב פִּרְיָהּ מֵחָרוּץ וּמִפָּז״ (משלי ח:יט). יִרְפַּד לְשׁוֹן מַצָּע וּמִשְׁכָּב כְּמוֹ ״רְפִידָתוֹ זָהָב״ (שיר ג:י):",4,0],[41,23,"יַרְתִּיחַ כַּסִּיר מְצוּלָה. כְּסִיר קָטָן נָפוּחַ, שֶׁמַּעֲלֶה מְהֵרָה רְתִיחוֹת תְּכוּפוֹת וּרְצוּפוֹת, כֵּן הוּא מַרְתִּיחַ אֶת הַמְּצוּלָה שֶׁהִיא גְּדוֹלָה וַעֲמֻקָּה:",1,0],[41,23,"יָם יָשִׂים כַּמֶּרְקָחָה. כְּמִרְקַחַת רִקּוּחַ בְּשָׂמִים, שֶׁהִיא מְעוֹרָה וּמְעֹרֶבֶת, כְּמוֹ כֵן יָשִׂים וִיעָרֵב אֶת הַיָּם כְּשֶׁהוּא זָז מִמְּקוֹמוֹ:",2,0],[41,24,"אַחֲרָיו יָאִיר נָתִיב. כְּשֶׁהוּא פּוֹרֵחַ וְשָׁט בַּיָּם, אַחֲרָיו מֵאִיר נָתִיב הַתְּהוֹם; שֶׁלְּפִי שָׁעָה שֶׁהוּא פּוֹרֵחַ, וְאֵין שָׁם מַיִם מֵחֲמַת מְרוּצַת פְּרִיחָתוֹ:",1,0],[41,24,"יַחְשֹׁב תְּהוֹם לְשֵׂיבָה. תְּהוֹם חָשׁוּב לְפָנָיו בְּחַלָּשׁוּת וְתַשּׁוּת:",2,0],[41,24,"לְשֵׂיבָה. לְחַלְשׁוּת שֶׁל זִקְנָה וְשֵׂיבָה:",3,0],[41,25,"אֵין עַל עָפָר מָשְׁלוֹ. מֵ״ם חֲטַף קָמַץ, וּפִתְרוֹנוֹ: מֶמְשַׁלְתּוֹ – שֶׁאֵין בְּרִיָּה מוֹשֶׁלֶת עָלָיו. וְהוּא שֵׁם דָּבָר: מוֹשֵׁל וְשִׁלְטוֹן, וְעַל כֵּן הַמֵּ״ם מְנֻקֶּדֶת בַּחֲטַף קָמַץ:",1,0],[41,25,"הֶעָשׂוּ. כְּמוֹ ״הֶעָשׂוּי״ (שמות ג:טז), וְלֹא יָדַעְתִּי לוֹ רֵיעַ. וּפִתְרוֹנוֹ: הֶעָשׂוּי בְּלִי פַּחַד וּמְחִתָּה, שֶׁאֵינוֹ מִתְיָרֵא מִן הַבְּרִיּוֹת; כְּמוֹ שֶׁנֶּאֱמַר בַּסּוּס ״יִשְׂחַק לְפַחַד וְלֹא יֵחָת״ (איוב לט:כב):",2,0],[41,26,"אֵת כָּל גָּבֹהַּ יִרְאֶה. כָּל הַגְּבוֹהִים שֶׁבָּעוֹלָם הוּא רוֹאֶה תַּחְתָּיו, וְכֵן הוּא מִנְהַג הָעוֹלָם, אֲשֶׁר אוֹתוֹ הָעוֹמֵד לְמַעְלָה רוֹאֶה אֶת הַתַּחְתּוֹן יוֹתֵר מִמַּה שֶּׁרוֹאֶה הַתַּחְתּוֹן, וְאֵין לַתַּחְתּוֹן גְּבוּרָה וְנִצָּחוֹן נֶגֶד הָעֶלְיוֹן. וְלִוְיָתָן זֶה רוֹאֶה אֶת כָּל הַגִּבּוֹרִים, לוֹמַר שֶׁאֵין לָהֶם גְּבוּרָה כְּנֶגְדּוֹ:",1,0],[41,26,"הוּא מֶלֶךְ עַל כָּל בְּנֵי שָׁחַץ. מִלָּה כְּפוּלָה: עַל כָּל גַּאֲוָה יִרְאֶה, וְהוּא מֶלֶךְ עַל כָּל בְּנֵי שָׁחַץ – בְּנֵי גַּסּוּת הָרוּחַ שֶׁבָּרָאתִי בְּעוֹלָמִי, שֶׁאֵין לָהֶם כְּנֶגְדּוֹ מֶמְשָׁלָה וּשְׂרָרָה. וְהָאֵיךְ נְשָׂאֲךָ לִבְּךָ לָשֵׂאת רֹאשׁ לְפָנַי, לְהִתְוַכֵּחַ נֶגְדִּי – כִּי הִנְנִי עוֹשֶׂה אֶת כָּל הַנִּפְלָאוֹת הָאֵלֶּה?!",2,0],[42,2,"(מענה איוב): יָדַעְתִּי כִּי כֹל תּוּכָל. כִּי הַכֹּל תּוּכַל לַעֲשׂוֹת, כַּאֲשֶׁר יָשָׁר בְּעֵינֶיךָ:",1,0],[42,2,"וְלֹא יִבָּצֵר מִמְּךָ מְזִמָּה. כּוֹפֵל מִלָּתוֹ: שֶׁאֵין מְזִמָּה וּמַחֲשָׁבָה נִבְצֶרֶת וְנִסְתֶּרֶת מִמְּךָ, אֲשֶׁר כָּל מַחֲשְׁבוֹתֶיךָ תּוּכַל לִגְמֹר וּלְמַלְּאוֹת; כִּי בְיָדְךָ כֹּחַ וּגְבוּרָה וּבְיָדְךָ לַעֲשׂוֹת כָּל הַטּוֹב בְּעֵינֶיךָ (דברי הימים א כט:יב). וּמִקְרָא זֶה דּוּגְמַת ״וְעַתָּה לֹא יִבָּצֵר מֵהֶם כֹּל אֲשֶׁר יָזְמוּ לַעֲשׂוֹת״ (בראשית יא:ו):",2,0],[42,3,"מִי זֶה מַעְלִים. אֲשֶׁר הֶעֱלִים וְכִסָּה עֲצָתוֹ וְנִפְלְאוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בִּבְלִי דַעַת? יָדַעְתִּי כִּי הַכֹּל בְּיָדְךָ לַעֲשׂוֹת, וְעַל כֵּן הִגַּדְתִּי קְצָת מִגְּבוּרוֹתָיו כַּאֲשֶׁר הָיוּ עִם לְבָבִי, כַּאֲשֶׁר יָדַעְתִּי:",1,0],[42,3,"וְלֹא אָבִין. אֲבָל לֹא הֵבַנְתִּי כָּל כָּךְ, כַּאֲשֶׁר הוֹדַעְתַּנִי; כִּי כַּמָּה נִפְלָאוֹת נִסְתָּרוֹת וְנֶעֱלָמוֹת מִמֶּנִּי, אֲשֶׁר אֵינֶנִּי יוֹדֵעַ:",2,0],[42,5,"לְשֵׁמַע אֹזֶן שְׁמַעְתִּיךָ. כַּמָּה וְכַמָּה פְּעָמִים שָׁמַעְתִּי שִׁמְעֲךָ, וְעַתָּה עֵינִי רָאֲתָה אֶת שְׁכִינָתְךָ:",1,0],[42,6,"עַל כֵּן. אֲשֶׁר זָכִיתִי לַחֲזוֹת שְׁכִינָתְךָ, מוֹאֵס אֲנִי בְּחַיַּי; וְאֶהְיֶה מִתְנַחֵם, אִלּוּ הָיִיתִי שׁוֹכֵן בַּקֶּבֶר, לָשׁוּב לְעָפָר וָאֵפֶר אֲשֶׁר לֻקַּחְתִּי מִשָּׁם:",1,0],[42,7,"וּבִשְׁנֵי רֵעֶיךָ. בִּלְדַּד הַשּׁוּחִי וְצוֹפַר הַנַּעֲמָתִי:",1,0],[42,7,"כִּי לֹא דִבַּרְתֶּם. שֶׁהֲרֵי לֹא דִבַּרְתֶּם אֵלַי טַעֲנָה נְכוֹנָה כְּעַבְדִּי אִיּוֹב; שֶׁהֲרֵי הוּא לֹא פָּשַׁע בִּי, כִּי אִם עַל אֲשֶׁר אָמַר ״תָּם וְרָשָׁע הוּא מְכַלֶּה״ (איוב ט:כב), וְעַל יְדֵי הַשָּׂטָן הַמְקַטְרֵג אֶת הָעוֹלָם, שֶׁנֶּאֱמַר ״אִם שׁוֹט יָמִית פִּתְאוֹם וְגוֹ׳״ (איוב ט:כג). וְאִם הוֹסִיף לְדַבֵּר – מִפְּנֵי קֹשִׁי יִסּוּרִין אֲשֶׁר כָּבְדוּ וְחָזְקוּ עָלָיו דִּבֵּר. אֲבָל אַתֶּם פְּשַׁעְתֶּם, עַל אֲשֶׁר הִרְשַׁעְתֶּם אוֹתוֹ, לֵאמֹר ״הֲלֹא יִרְאָתְךָ כִּסְלָתֶךָ״ (איוב ד:ו), וְהֶחֱזַקְתֶּם אוֹתוֹ בְּחֶזְקַת רָשָׁע. וּלְבַסּוֹף הֱיִיתֶם מְשֻׁתָּקִים וּמְנֻצָּחִים לְפָנָיו; וְהָיָה לָכֶם לְנַחֲמוֹ, כַּאֲשֶׁר עָשָׂה אֱלִיהוּא. וְלֹא דַי לְאִיּוֹב בְּצָרָתוֹ וְיִסּוּרָיו, כִּי גַם הוֹסַפְתֶּם עַל חַטֹּאתֵיכֶם פֶּשַׁע לְהַקְנִיטוֹ:",2,0],[42,8,"וְהַעֲלִיתֶם עוֹלָה בַּעַדְכֶם. לְמַעַן שֶׁתִּתְרַצּוּ וְתִתְפַּיְּסוּ לְפָנַי, וּבִלְבַד אֲשֶׁר עַבְדִּי אִיּוֹב יִתְפַּלֵּל עֲלֵיכֶם אֲשֶׁר אֶסְלַח לְחַטֹּאתֵיכֶם, וְלִפְשָׁעֵיכֶם לֹא אֶזְכֹּר עוֹד:",1,0],[42,8,"כִּי אִם פָּנָיו אֶשָּׂא. שֶׁהֲרֵי פָנָיו אֶשָּׂא לְקַבֵּל תְּפִלָּתוֹ. הֲרֵי אִם כְּמוֹ אֲשֶׁר, וְכֵן ״עַד אִם כִּלּוּ לִשְׁתּוֹת״ (בראשית כד:יט), ״אִם כֹּפֶר יוּשַׁת עָלָיו״ (שמות כא:ל), וְכֵן הַרְבֵּה:",2,0],[42,8,"כִּי לֹא. שֶׁהֲרֵי לֹא:",3,0],[42,9,"וַיִּשָּׂא ה׳ אֶת פְּנֵי אִיּוֹב. וַיִּשָּׂא כְּמוֹ ״נָשָׂאתִי פָנֶיךָ גַּם לַדָּבָר הַזֶּה״ (בראשית יט:כא), שֶׁקִּבֵּל תְּפִלָּתוֹ וְהִסְבִּיר לוֹ פָּנִים:",1,0],[42,10,"שָׁב אֶת שְׁבוּת אִיּוֹב בְּהִתְפַּלְלוֹ. שָׁב נוֹפֵל לוֹמַר בְּעִנְיָן זֶה, וַהֲרֵי הוּא כְּאִלּוּ כְּתִיב וְהֵשִׁיב אֶת שְׁבוּת אִיּוֹב:",1,0],[42,10,"בְּהִתְפַּלְלוֹ בְּעַד רֵעֵהוּ. בִּזְכוּת שֶׁהִתְפַּלֵּל עַל כָּל רֵיעַ וְרֵיעַ שֶׁלּוֹ:",2,0],[42,10,"לְמִשְׁנֶה. עַל אֶחָד שְׁנַיִם (נראה דקאי גם על מה שכתב למעלה שהיה לו לומר להשיב מהר״ז), וְלֹא דִקְדֵּק הַמִּקְרָא בְּמִלָּתוֹ:",3,0],[42,11,"לְפָנִים. כָּל אֲשֶׁר הָיוּ אוֹהֲבָיו וּמַכִּירָיו בְּטֶרֶם הִגִּיעוּ אֵלָיו הַיִּסּוּרִים:",1,0],[42,11,"וַיָּנֻדוּ לוֹ. לְשׁוֹן קוֹנְפְּלֵיְינְטָ״א בְּלַעַ״ז:",2,0],[42,11,"קְשִׂיטָה. מָעָה:",3,0],[42,11,"וְאִישׁ. וְכָל אֶחָד וְאֶחָד (רוצה לומר שלא תאמר שהכונה שיש שנתנו לו קשיטה ויש שנתן לו נזם לכך כתב רש״י ואיש פירושו כל אחד ואחד מהר״ז):",4,0],[42,12,"מֵרֵאשִׁיתוֹ. יוֹתֵר מֵרֵאשִׁית עָשְׁרוֹ:",1,0],[42,13,"שִׁבְעָנָה. הֵם פַּעֲמַיִם שֶׁבַע, שְׁתֵּי שְׁבִיעִיּוֹת; כְּמוֹ ״שְׁבֻעַיִם״ (ויקרא יב:ה), שֶׁהֵם שְׁתֵּי שָׁבוּעוֹת:",1,0],[42,14,"וַיִּקְרָא שֵׁם הָאַחַת יְמִימָה. עַל שֵׁם יָפְיָתָן נִקְרְאוּ שְׁמוֹתֵיהֶן:",1,0],[42,14,"יְמִימָה. צַחָה וּמְלֻבָּנָה כַּיּוֹם:",2,0],[42,14,"קְצִיעָה. רֵיחָהּ נוֹדֵף עָרֵב וּמְבֻשָּׂם, כִּקְצִיעָה שֶׁל בֹּשֶׂם:",3,0],[42,14,"קֶרֶן הַפּוּךְ. עַל שֵׁם הַקֶּרֶן שֶׁנּוֹתְנִין בּוֹ כְּחוֹל וּבוֹרִית, שֶׁנֶּאֱמַר ״וְתִקְרְעִי בַפּוּךְ עֵינַיִךְ״ (ירמיהו ד:ל):",4,0],[42,15,"וְלֹא נִמְצָא נָשִׁים יָפוֹת כִּבְנוֹת אִיּוֹב וְגוֹ׳. וְלֹא נִמְצָא מַעֲשֶׂה שֶׁל נָשִׁים יָפוֹת, כְּמַעֲשֵׂה יֹפִי שֶׁל בְּנוֹת אִיּוֹב; וּמִקְרָא זֶה דּוּגְמַת ״וַיְהִי אֲנָשִׁים אֲשֶׁר הָיוּ טְמֵאִים״ (במדבר ט:ו); וְכֵן הַרְבֵּה:",1,0],[42,15,"וַיִּתֵּן לָהֶם אֲבִיהֶם נַחֲלָה בְּתוֹךְ אֲחֵיהֶם. מִתּוֹךְ חֲשִׁיבוּתָן וְיָפְיָן, נָתַן לָהֶם נַחֲלָה עִם הָאַחִים:",2,0],[42,17,"וּשְׂבַע יָמִים. מִן שָׂבֵעַ יֹאמַר שְׂבַע בִּדְבֵקוּת:",1,0]]);
